#[derive(Debug, Error)]
pub enum CliError {
    #[error("{0}")]
    Input(String),
    #[error("I/O failed for {path}: {source}")]
    Io {
        path: String,
        source: std::io::Error,
    },
    #[error(transparent)]
    Storage(#[from] cfctl_storage::StorageError),
    #[error(transparent)]
    Catalog(#[from] cfctl_catalog::CatalogError),
    #[error(transparent)]
    Auth(#[from] cfctl_auth::AuthError),
    #[error(transparent)]
    Core(#[from] cfctl_core::CoreError),
    #[error(transparent)]
    Cloudflare(#[from] cfctl_cloudflare::CloudflareError),
    #[error(transparent)]
    Workspace(#[from] cfctl_workspace::WorkspaceError),
    #[error(transparent)]
    Registry(#[from] cfctl_registry::RegistryError),
    #[error(transparent)]
    Agent(#[from] cfctl_agent::AgentError),
    #[error(transparent)]
    Json(#[from] serde_json::Error),
    #[error("HTTP client construction failed: {0}")]
    Http(#[from] reqwest::Error),
    #[error("subprocess `{0}` exceeded the 120-second governed timeout")]
    SubprocessTimeout(String),
    /// A CLI-level blocker that carries its own stable code and a specific,
    /// copy-pasteable next command for the agent. Prefer this over
    /// `Input(String)` whenever the failure has a knowable recovery step.
    #[error("{message}")]
    Guided {
        code: &'static str,
        message: String,
        next_step: String,
    },
}

impl CliError {
    /// Build a guided blocker: a stable code, a human message, and the exact
    /// next command an agent should run to recover.
    pub fn guided(
        code: &'static str,
        message: impl Into<String>,
        next_step: impl Into<String>,
    ) -> Self {
        Self::Guided {
            code,
            message: message.into(),
            next_step: next_step.into(),
        }
    }

    /// Stable machine-readable code for the failure envelope. Defaults to
    /// `CFCTL_ERROR` when the category is not specifically recognized.
    #[must_use]
    pub fn code(&self) -> &'static str {
        self.guidance().map_or("CFCTL_ERROR", |(code, _)| code)
    }

    /// A specific, copy-pasteable next command for the agent, when the error
    /// category makes one knowable. `None` lets the caller fall back to the
    /// generic doctor guidance.
    #[must_use]
    pub fn next_step(&self) -> Option<String> {
        self.guidance().map(|(_, step)| step)
    }

    fn guidance(&self) -> Option<(&'static str, String)> {
        match self {
            Self::Guided {
                code, next_step, ..
            } => Some((code, next_step.clone())),
            Self::Cloudflare(inner) => cloudflare_guidance(inner),
            Self::Core(inner) => core_guidance(inner),
            Self::Storage(inner) => storage_guidance(inner),
            Self::Auth(inner) => auth_guidance(inner),
            Self::Workspace(_) => Some((
                "CFCTL_WORKSPACE",
                "Run `cfctl workspace audit --json` to inspect registered roots and drift."
                    .to_owned(),
            )),
            Self::Registry(_) => Some((
                "CFCTL_REGISTRY",
                "Run `cfctl registry status --json` and `cfctl registry coverage --json` to inspect projection health and blockers."
                    .to_owned(),
            )),
            _ => None,
        }
    }
}

fn cloudflare_guidance(
    error: &cfctl_cloudflare::CloudflareError,
) -> Option<(&'static str, String)> {
    use cfctl_cloudflare::CloudflareError as E;
    let (code, step): (&'static str, &str) = match error {
        E::MissingSelector(_)
        | E::MissingHeaderSelector(_)
        | E::InvalidSelector(_)
        | E::InvalidSelectorObject
        | E::InvalidSelectorSchema { .. } => (
            "CFCTL_REQUEST_CONTRACT",
            "Run `cfctl guide <capability-id> --json` for the required selectors, then re-run `cfctl call` with each `--selector name=value`.",
        ),
        E::UndeclaredSelector(_) | E::InvalidQueryObject | E::UndeclaredQuerySelector(_) => (
            "CFCTL_REQUEST_CONTRACT",
            "Run `cfctl catalog show <capability-id> --json` to see the declared selectors and query controls, then drop or rename the undeclared input.",
        ),
        E::MissingQuerySelector(_)
        | E::InvalidQuerySelector { .. }
        | E::InvalidQuerySelectorSchema { .. }
        | E::UnsupportedQuerySerialization { .. } => (
            "CFCTL_REQUEST_CONTRACT",
            "Run `cfctl guide <capability-id>` and add each required `--query name=value`.",
        ),
        E::MissingRequestBody(_) | E::InvalidRequestBody(_) => (
            "CFCTL_REQUEST_CONTRACT",
            "Run `cfctl guide <capability-id>` for the body schema, then pass `--body-json '{…}'` (or `--body-stdin`).",
        ),
        E::ApprovedPlanRequired(_) => (
            "CFCTL_PLAN_REQUIRED",
            "This capability mutates state: draft, approve, then run. `cfctl call <capability-id> …` prints an operation id; then `cfctl plans approve <operation-id> --yes` and `cfctl plans run <operation-id>`.",
        ),
        E::CatalogDrift { .. } => (
            "CFCTL_CATALOG_DRIFT",
            "The catalog moved since the plan was drafted. Run `cfctl catalog sync`, then re-draft with `cfctl call <capability-id> …`.",
        ),
        E::Plan(core) => return core_guidance(core),
        _ => return None,
    };
    Some((code, step.to_owned()))
}

fn core_guidance(error: &cfctl_core::CoreError) -> Option<(&'static str, String)> {
    use cfctl_core::CoreError as E;
    const CODE: &str = "CFCTL_PLAN_LIFECYCLE";
    let step = match error {
        E::ExplicitApprovalRequired => {
            "Re-run with the explicit approval flag: `cfctl plans approve <operation-id> --yes`."
                .to_owned()
        }
        E::CostCeilingRequired(operation_id) => format!(
            "This plan needs an explicit cost ceiling: `cfctl plans approve {operation_id} --yes --max-cost USD:<amount>`."
        ),
        E::CostCeilingTooLow {
            operation_id,
            required_currency,
            required_amount,
        } => format!(
            "Raise the ceiling to at least the declared maximum: `cfctl plans approve {operation_id} --yes --max-cost {required_currency}:{required_amount}`."
        ),
        E::InvalidCostCeiling { .. } => {
            "Format the ceiling as CURRENCY:AMOUNT, for example `--max-cost USD:5`.".to_owned()
        }
        E::InvalidPlanState {
            operation_id,
            actual,
            expected,
        } => plan_state_next_step(operation_id, *actual, expected),
        E::PlanExpired { .. } => {
            "The plan expired. Re-draft with `cfctl call <capability-id> …`, then approve and run promptly."
                .to_owned()
        }
        E::PlanDrifted(_) => {
            "Approval no longer matches the plan content. Re-draft and re-approve: `cfctl call <capability-id> …`."
                .to_owned()
        }
        E::InvalidTransactionJournal { operation_id, .. } => {
            format!("Reconcile the plan's journal: `cfctl plans rectify {operation_id}`.")
        }
        _ => return None,
    };
    Some((CODE, step))
}

/// Recovery guidance for a rejected plan transition. Keys on the plan's ACTUAL
/// state — not the `expected` string — so a completed plan is never told to
/// re-approve/re-run, and a genuine run-before-approve is told to approve.
fn plan_state_next_step(
    operation_id: &str,
    actual: cfctl_core::PlanStatus,
    expected: &str,
) -> String {
    use cfctl_core::PlanStatus as S;
    match actual {
        S::Consumed | S::Running | S::Verified => format!(
            "This plan already ran (state: {}); do not re-approve or re-run it. Inspect `cfctl plans status {operation_id}`, or draft a new plan with `cfctl call <capability-id> …` to repeat the change.",
            plan_status_label(actual)
        ),
        S::Failed | S::RectificationRequired => {
            format!("The plan did not complete and needs recovery: `cfctl plans rectify {operation_id}`.")
        }
        S::Rectified => {
            format!("The plan was already rectified; inspect `cfctl plans status {operation_id}`.")
        }
        S::Expired => {
            "The plan expired. Re-draft with `cfctl call <capability-id> …`, then approve and run promptly."
                .to_owned()
        }
        S::Cancelled => {
            "The plan was cancelled and its authority retired. If the change is still wanted, draft a new plan with `cfctl call <capability-id> …`."
                .to_owned()
        }
        S::Approved => {
            format!("The plan is already approved; run it: `cfctl plans run {operation_id}`.")
        }
        S::Draft => {
            if expected.contains("unchanged") || expected.contains("hash") {
                "The plan changed since it was drafted. Re-draft and re-approve: `cfctl call <capability-id> …`."
                    .to_owned()
            } else if expected.contains("unapproved") {
                format!(
                    "This draft is consumed under a standing policy, not approved by hand. Inspect it with `cfctl plans status {operation_id}`."
                )
            } else {
                format!(
                    "Approval is required before running. Approve it: `cfctl plans approve {operation_id} --yes`, then `cfctl plans run {operation_id}`."
                )
            }
        }
    }
}

fn plan_status_label(status: cfctl_core::PlanStatus) -> &'static str {
    use cfctl_core::PlanStatus as S;
    match status {
        S::Draft => "draft",
        S::Approved => "approved",
        S::Running => "running",
        S::Consumed => "consumed",
        S::Verified => "verified",
        S::Failed => "failed",
        S::RectificationRequired => "rectification_required",
        S::Rectified => "rectified",
        S::Expired => "expired",
        S::Cancelled => "cancelled",
    }
}

fn storage_guidance(error: &cfctl_storage::StorageError) -> Option<(&'static str, String)> {
    use cfctl_storage::StorageError as E;
    let (code, step) = match error {
        E::PlanNotFound(id) => (
            "CFCTL_PLAN_LIFECYCLE",
            format!(
                "No plan with that id. Confirm it with `cfctl plans show {id}`; the operation id is printed by the `cfctl call` that drafted the plan."
            ),
        ),
        E::PlanLocked(id) => (
            "CFCTL_PLAN_LIFECYCLE",
            format!(
                "Another `cfctl plans` run holds the lock. Check `cfctl plans status {id}` and retry once it finishes."
            ),
        ),
        E::InvalidPlanId(_) | E::InvalidAuthorityId(_) => (
            "CFCTL_PLAN_LIFECYCLE",
            "Pass the operation id exactly as printed by `cfctl call` (a lowercase hyphenated UUID)."
                .to_owned(),
        ),
        E::WriteDurabilityUnknown { .. } => (
            "CFCTL_PLAN_LIFECYCLE",
            "The write is not durably confirmed. Reload with `cfctl plans status <operation-id>` before retrying."
                .to_owned(),
        ),
        E::InvalidPlan(core) => return core_guidance(core),
        _ => return None,
    };
    Some((code, step))
}

fn auth_guidance(error: &cfctl_auth::AuthError) -> Option<(&'static str, String)> {
    use cfctl_auth::AuthError as E;
    const CODE: &str = "CFCTL_AUTH";
    let step = match error {
        E::CredentialUnavailable { profile_id, .. } => {
            return Some((
                "CFCTL_CREDENTIAL_UNAVAILABLE",
                format!(
                    "Re-import the credential for the selected profile `{profile_id}`. If the only valid copy is intentionally in Keychain, run `cfctl auth repair-keychain-access {profile_id}` and review its warning before continuing."
                ),
            ));
        }
        E::MissingCredential(_) => {
            "The profile has no stored credential. Re-import it: `printf '%s' \"$TOKEN\" | cfctl auth import-api-token --account <account-id> --stdin`."
                .to_owned()
        }
        E::NoAccounts | E::AmbiguousAccount { .. } | E::AccountNotFound(_) => {
            "Pass `--account <account-id>` explicitly (list available accounts with `cfctl auth status --json`)."
                .to_owned()
        }
        E::UnsupportedLegacyWranglerSession(id) => format!(
            "Remove the legacy profile and re-authenticate: `cfctl auth logout {id}` then `cfctl auth login --profile {id}`."
        ),
        E::SecretStore(_) => {
            "The secret backend is unavailable. Run `cfctl doctor --json` to inspect the credential store."
                .to_owned()
        }
        _ => return None,
    };
    Some((CODE, step))
}

/// Map a non-2xx live Cloudflare read status to a stable code and a specific
/// next command. Authorization failures point at the token scope; input
/// failures point at the selector/zone contract; the rest fall back to doctor.
fn live_read_failure_guidance(status: u16) -> (&'static str, String) {
    match status {
        401 | 403 => (
            "CFCTL_LIVE_UNAUTHORIZED",
            "The token lacks scope for this read. Confirm its permissions with `cfctl keys permissions --json`, or select a scoped profile with `--profile <id>`."
                .to_owned(),
        ),
        400 | 404 | 422 => (
            "CFCTL_LIVE_BAD_REQUEST",
            "Cloudflare rejected the inputs. Run `cfctl guide <capability-id>` to check required selectors — zone selectors need the 32-hex zone id, not a domain (resolve it with a `/zones` read filtered by `--query name=<domain>`)."
                .to_owned(),
        ),
        429 => (
            "CFCTL_LIVE_RATE_LIMITED",
            "Cloudflare rate-limited the request. Wait and retry the same `cfctl call`.".to_owned(),
        ),
        500..=599 => (
            "CFCTL_LIVE_UPSTREAM",
            "Cloudflare reported a server-side error. Retry shortly; if it persists, run `cfctl doctor --json`."
                .to_owned(),
        ),
        _ => (
            "CFCTL_LIVE_ERROR",
            "The live read failed. Inspect the returned Cloudflare errors and run `cfctl doctor --json`."
                .to_owned(),
        ),
    }
}

fn live_read_availability(capability: &CapabilityV1, response: &CloudflareResponseV1) -> Value {
    let permission_owner =
        if capability.path.starts_with("/user") || capability.account_scope == "user" {
            "user_owned"
        } else {
            "account_owned"
        };
    let analytics_rows = capability.analytics_query.as_ref().and_then(|_| {
        response
            .result_info
            .as_ref()
            .and_then(|info| info.pointer("/output/rows"))
            .and_then(Value::as_u64)
    });
    let (state, data_state, distinction_proven, next_action) = if response.success {
        if analytics_rows == Some(0) {
            (
                "available",
                "no_data_in_bounded_query_window",
                true,
                "Widen the governed time window within the capability limit or verify dataset freshness and retention; cfctl does not reinterpret an empty result as an authorization failure.",
            )
        } else {
            (
                "available",
                "data_returned_or_not_applicable",
                true,
                "Inspect the content-addressed live-read receipt and any freshness, sampling, pagination, or truncation metadata.",
            )
        }
    } else if capability.entitlement.available == Some(false) {
        (
            "unavailable_current_plan",
            "not_observed",
            true,
            "Review the capability entitlement source and use an eligible account or plan; do not retry as a permission workaround.",
        )
    } else if matches!(response.status, 401 | 403) {
        (
            "authorization_or_entitlement_unresolved",
            "not_observed",
            false,
            "Compare the active token against required_permissions. If those permissions are present, inspect the capability entitlement source or a governed product-specific entitlement read; cfctl does not guess which boundary Cloudflare rejected.",
        )
    } else if response.status == 404 {
        (
            "resource_or_configuration_absent",
            "not_observed",
            true,
            "Verify the exact account, zone, and resource selectors. A 404 is not treated as an empty analytics result.",
        )
    } else {
        (
            "upstream_error",
            "not_observed",
            true,
            "Inspect the redacted Cloudflare errors and retry only when the status-specific guidance permits it.",
        )
    };
    json!({
        "schema_version": 1,
        "state": state,
        "data_state": data_state,
        "authorization_entitlement_distinction_proven": distinction_proven,
        "permission_owner": permission_owner,
        "required_permissions": &capability.permissions,
        "entitlement": &capability.entitlement,
        "freshness": capability.analytics_query.as_ref().and_then(|query| query.freshness.as_deref()),
        "sampling": capability.analytics_query.as_ref().and_then(|query| query.sampling.as_deref()),
        "next_action": next_action,
    })
}

pub type Result<T> = std::result::Result<T, CliError>;

pub async fn execute(cli: Cli) -> Result<ResultEnvelopeV2> {
    let command = cli.command.ok_or_else(|| {
        CliError::Input("run `cfctl --help` or pass a natural-language intent".to_owned())
    })?;
    if let Command::Guide(arguments) = &command
        && let Some(topic) = arguments.topic
    {
        return guide_topic_envelope(topic);
    }
    if matches!(command, Command::Version) {
        return version_command();
    }
    let store = StateStore::open(RuntimePaths::discover()?)?;
    match command {
        Command::Auth(arguments) => auth_command(&store, arguments.command).await,
        Command::Keys(arguments) => Box::pin(keys_command(&store, arguments.command)).await,
        Command::Catalog(arguments) => catalog_command(&store, arguments.command).await,
        Command::Call(arguments) => Box::pin(call_command(&store, arguments)).await,
        Command::Resolve(arguments) => resolve_command(&store, arguments).await,
        Command::Guide(arguments) => guide_command(&store, &arguments).await,
        Command::Plans(arguments) => Box::pin(plans_command(&store, arguments.command)).await,
        Command::Policy(arguments) => policy_command(&store, arguments.command),
        Command::Registry(arguments) => registry_command(&store, arguments.command),
        Command::Events(arguments) => events_command(&store, arguments.command),
        Command::Workspace(arguments) => workspace_command(&store, arguments.command),
        Command::Agents(arguments) => agents_command(&store, arguments.command),
        Command::Docs(arguments) => docs_command(&store, arguments.command).await,
        Command::Doctor => doctor_command(&store),
        Command::Version => version_command(),
        Command::Update(arguments) => update_command(arguments.check).await,
        Command::Migrate(arguments) => migrate_command(&store, arguments.command),
    }
}

pub async fn execute_natural_language(intent: &str) -> Result<ResultEnvelopeV2> {
    let store = StateStore::open(RuntimePaths::discover()?)?;
    let agent = configured_agent()?;
    let context = InvocationContext {
        agent_session: env::var_os("CFCTL_AGENT_SESSION").is_some(),
    };
    let invocation = AgentLauncher::new(agent).prepare(intent, &context)?;
    let action = build_intent_action(agent, intent, None)?;
    let evidence =
        store.write_evidence(EvidenceClass::AgentAction, &serde_json::to_value(&action)?)?;
    let mut process = ProcessCommand::new(&invocation.program);
    process.args(&invocation.args);
    for (key, value) in invocation.env {
        process.env(key, value);
    }
    process
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());
    let status = process
        .status()
        .await
        .map_err(|source| cli_io(Path::new(&invocation.program), source))?;
    let mut envelope = ResultEnvelopeV2::success(
        "intent",
        json!({
            "agent": agent.label(),
            "agent_exit_status": status.code(),
            "message": "The agent interpreted intent; deterministic cfctl receipts remain authoritative."
        }),
    )
    .with_evidence(evidence);
    envelope.ok = status.success();
    Ok(envelope)
}

pub fn render(envelope: &ResultEnvelopeV2, json_output: bool) -> Result<String> {
    if json_output {
        return Ok(format!("{}\n", serde_json::to_string(envelope)?));
    }
    if let Some(error) = &envelope.error {
        let next = error
            .next_step
            .as_deref()
            .map(|step| format!("\nNext: {step}"))
            .unwrap_or_default();
        return Ok(format!("Error: {}{next}\n", error.message));
    }
    if envelope.command == "guide"
        && envelope.result.get("topic").is_some()
        && let Ok(document) =
            serde_json::from_value::<GuideTopicDocumentV1>(envelope.result.clone())
    {
        return Ok(render_guide_topic_document_markdown(&document));
    }
    if envelope.command == "version"
        && let Ok(build) =
            serde_json::from_value::<cfctl_core::BuildInfoV1>(envelope.result.clone())
    {
        let commit = build.git_commit.as_deref().unwrap_or("unknown");
        let source = match build.identity_source {
            cfctl_core::BuildIdentitySourceV1::ReleaseEnv => "release_env",
            cfctl_core::BuildIdentitySourceV1::GitCheckout => "git_checkout",
            cfctl_core::BuildIdentitySourceV1::Unknown => "unknown",
        };
        return Ok(format!("cfctl {} ({commit}, {source})\n", build.version));
    }
    if let Some(message) = envelope.result.get("message").and_then(Value::as_str) {
        return Ok(format!("{message}\n"));
    }
    Ok(format!(
        "{}\n",
        serde_json::to_string_pretty(&envelope.result)?
    ))
}

fn platform_secrets(store: &StateStore) -> PlatformSecretStore {
    PlatformSecretStore::new(store.paths().data_dir.join("auth").join("secrets"))
}

fn describe_secret_backend(backend: Option<SecretBackend>) -> (&'static str, &'static str) {
    match backend {
        Some(SecretBackend::PlatformKeyring) => {
            ("platform_keyring", "in the platform credential store")
        }
        Some(SecretBackend::FallbackFile) => (
            "fallback_file",
            "in cfctl's mode-0600 file secret store because the platform keyring is unavailable (see `cfctl doctor`)",
        ),
        Some(SecretBackend::Memory) => ("memory", "in the in-process secret store"),
        None => ("unknown", "in an undetermined backend"),
    }
}

fn platform_secret_store_health(store: &StateStore) -> Result<Value> {
    let secrets = platform_secrets(store);
    let preferred = if cfg!(target_os = "macos") {
        "keychain"
    } else if cfg!(target_os = "linux") {
        "secret_service"
    } else {
        "unsupported"
    };
    let (keyring, active_backend) = match secrets.keyring_probe() {
        Ok(()) => ("ok".to_owned(), "platform_keyring"),
        Err(error) => (format!("unavailable: {error}"), "fallback_file"),
    };
    Ok(json!({
        "preferred": preferred,
        "keyring": keyring,
        "active_backend": active_backend,
        "fallback_dir": secrets.fallback_root(),
        "fallback_secret_count": secrets.fallback_secret_count()?,
    }))
}

fn standing_authorities_health(store: &StateStore) -> Result<Value> {
    let now = Utc::now();
    let authorities: Vec<Value> = store
        .list_authorities()?
        .iter()
        .map(|authority| {
            json!({
                "authority_id": authority.authority_id,
                "status": authority.status.as_str(),
                "account_id": authority.account_id,
                "zone_id": authority.zone_id,
                "bound_resources": authority.allowed_token_resources(),
                "name_prefix": authority.name_prefix,
                "capability_ids": authority.capability_ids,
                "expires_at": authority.expires_at,
                "max_runs_per_day": authority.max_runs_per_day,
                "runs_last_24h": authority.runs_in_last_day(now),
                "minted_tokens": authority.minted_token_ids.len(),
            })
        })
        .collect();
    Ok(Value::Array(authorities))
}

async fn auth_command(store: &StateStore, command: AuthCommand) -> Result<ResultEnvelopeV2> {
    let secrets = platform_secrets(store);
    let mut profiles = ProfilesConfig::load(store)?;
    match command {
        AuthCommand::Login(arguments) if !arguments.complete => {
            begin_oauth_login(store, &mut profiles, &secrets, arguments).await
        }
        AuthCommand::Login(arguments) => {
            complete_oauth_login(store, &mut profiles, &secrets, arguments).await
        }
        AuthCommand::Status(selector) => auth_status(&profiles, &secrets, &selector),
        AuthCommand::Profiles => Ok(ResultEnvelopeV2::success(
            "auth profiles",
            json!({"current": profiles.current_profile, "profiles": profiles.profiles.values().collect::<Vec<_>>() }),
        )),
        AuthCommand::Use(selector) => use_profile(store, &mut profiles, &selector),
        AuthCommand::RepairKeychainAccess(selector) => {
            repair_keychain_access(&profiles, &secrets, &selector)
        }
        AuthCommand::Logout(selector) => {
            logout_profile(store, &mut profiles, &secrets, &selector).await
        }
        AuthCommand::ImportApiToken(arguments) => {
            import_api_token(store, &mut profiles, &secrets, &arguments)
        }
        AuthCommand::ImportGlobalKey(arguments) => {
            import_global_key(store, &mut profiles, &secrets, &arguments)
        }
    }
}

fn require_oauth_client_id(client_id: Option<&str>) -> Result<&str> {
    client_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CliError::Input(
                "OAuth login needs --client-id (or CFCTL_OAUTH_CLIENT_ID). Until public cfctl OAuth is promoted, use the simple scoped lane: printf '%s' \"$CLOUDFLARE_API_TOKEN\" | cfctl auth import-api-token --account <account-id> --stdin"
                    .to_owned(),
            )
        })
}

async fn begin_oauth_login(
    store: &StateStore,
    profiles: &mut ProfilesConfig,
    secrets: &dyn SecretStore,
    arguments: AuthLoginArgs,
) -> Result<ResultEnvelopeV2> {
    let client_id = require_oauth_client_id(arguments.client_id.as_deref())?;
    let requested_scopes =
        resolve_login_scopes(store, profiles, secrets, &arguments.scopes).await?;
    let client = OAuthClientConfig::cfctl_public(client_id);
    let scopes: Vec<&str> = requested_scopes.iter().map(String::as_str).collect();
    let session = PkceSession::begin(&client, &scopes)?;
    secrets.put(
        &format!("pending/{}/pkce-verifier", arguments.profile),
        &session.code_verifier,
    )?;
    profiles.pending_logins.insert(
        arguments.profile.clone(),
        PendingLogin {
            profile_id: arguments.profile.clone(),
            state: session.state.clone(),
            client,
            scopes: requested_scopes,
            account_id: arguments.account,
        },
    );
    profiles.save(store)?;
    Ok(ResultEnvelopeV2::success(
        "auth login",
        json!({
            "authorization_url": session.authorization_url,
            "profile": arguments.profile,
            "message": "Open the authorization URL, then pipe the callback payload `STATE CODE` into `cfctl auth login --complete` with the same profile and client ID."
        }),
    ))
}

async fn complete_oauth_login(
    store: &StateStore,
    profiles: &mut ProfilesConfig,
    secrets: &dyn SecretStore,
    arguments: AuthLoginArgs,
) -> Result<ResultEnvelopeV2> {
    let client_id = require_oauth_client_id(arguments.client_id.as_deref())?;
    let pending = profiles
        .pending_logins
        .get(&arguments.profile)
        .cloned()
        .ok_or_else(|| CliError::Input(format!("no pending login for `{}`", arguments.profile)))?;
    if pending.client.client_id != client_id {
        return Err(CliError::Input(
            "OAuth client ID differs from the pending login".to_owned(),
        ));
    }
    let (state, code) = parse_callback(&read_stdin()?)?;
    if state != pending.state {
        return Err(CliError::Input(
            "OAuth state does not match the pending login".to_owned(),
        ));
    }
    let verifier_key = format!("pending/{}/pkce-verifier", arguments.profile);
    let verifier = secrets
        .get(&verifier_key)?
        .ok_or_else(|| CliError::Input("pending PKCE verifier is missing".to_owned()))?;
    let tokens =
        exchange_authorization_code(&http_client()?, &pending.client, &code, &verifier).await?;
    let mut profile = ProfileMetadata::new(
        &arguments.profile,
        ProfileKind::OAuth,
        pending.account_id.as_deref(),
    );
    profile.oauth_client_id = Some(pending.client.client_id);
    profile.oauth_scopes = tokens.scopes().into_iter().map(str::to_owned).collect();
    profile.oauth_scope_inventory_hash = oauth_scope_inventory_hash(store)?;
    mark_credential_install_pending(store, profiles, &profile, true)?;
    secrets.store_oauth_tokens(&arguments.profile, &tokens)?;
    profiles.profiles.insert(arguments.profile.clone(), profile);
    profiles.current_profile = Some(arguments.profile.clone());
    profiles.pending_logins.remove(&arguments.profile);
    profiles.save(store)?;
    secrets.delete(&verifier_key)?;
    Ok(ResultEnvelopeV2::success(
        "auth login",
        json!({
            "profile": arguments.profile,
            "scopes": tokens.scopes(),
            "expires_at": tokens.expires_at(),
            "message": "OAuth login completed; tokens were stored in the platform credential store."
        }),
    ))
}

fn auth_status(
    profiles: &ProfilesConfig,
    secrets: &dyn SecretStore,
    selector: &ProfileSelector,
) -> Result<ResultEnvelopeV2> {
    let profile = profiles
        .profiles
        .get(&selector.profile)
        .ok_or_else(|| CliError::Input(format!("profile `{}` does not exist", selector.profile)))?;
    ensure_supported_profile(profile)?;
    let credential_available = secrets.load_profile_credential(profile).is_ok();
    Ok(ResultEnvelopeV2::success(
        "auth status",
        json!({"profile": profile, "credential_available": credential_available, "selected": profiles.current_profile.as_deref() == Some(&profile.id)}),
    ))
}

fn repair_keychain_access(
    profiles: &ProfilesConfig,
    secrets: &dyn SecretStore,
    selector: &ProfileSelector,
) -> Result<ResultEnvelopeV2> {
    let mut warnings = std::io::stderr().lock();
    repair_keychain_access_with_warning(profiles, secrets, selector, &mut warnings)
}

const KEYCHAIN_REPAIR_WARNING: &str = "warning: this explicit repair may open macOS Keychain for the selected profile; cancel the system prompt to stop without changing the credential\n";

fn repair_keychain_access_with_warning(
    profiles: &ProfilesConfig,
    secrets: &dyn SecretStore,
    selector: &ProfileSelector,
    warnings: &mut dyn Write,
) -> Result<ResultEnvelopeV2> {
    let profile = profiles
        .profiles
        .get(&selector.profile)
        .ok_or_else(|| CliError::Input(format!("profile `{}` does not exist", selector.profile)))?;
    ensure_supported_profile(profile)?;
    warnings
        .write_all(KEYCHAIN_REPAIR_WARNING.as_bytes())
        .map_err(|source| CliError::Io {
            path: "stderr".to_owned(),
            source,
        })?;
    secrets.repair_profile_credential_access(profile)?;
    let backend = secrets.locate_profile_credential(profile)?;
    Ok(ResultEnvelopeV2::success(
        "auth repair-keychain-access",
        json!({
            "profile": profile.id,
            "credential_available": true,
            "backend": backend,
            "message": "The opaque credential was rewritten without disclosure using the unattended platform-reader access contract."
        }),
    ))
}

fn use_profile(
    store: &StateStore,
    profiles: &mut ProfilesConfig,
    selector: &ProfileSelector,
) -> Result<ResultEnvelopeV2> {
    let profile = profiles
        .profiles
        .get(&selector.profile)
        .ok_or_else(|| CliError::Input(format!("profile `{}` does not exist", selector.profile)))?;
    ensure_supported_profile(profile)?;
    profiles.current_profile = Some(selector.profile.clone());
    profiles.save(store)?;
    Ok(ResultEnvelopeV2::success(
        "auth use",
        json!({"profile": selector.profile, "message": "Active profile changed."}),
    ))
}

async fn logout_profile(
    store: &StateStore,
    profiles: &mut ProfilesConfig,
    secrets: &dyn SecretStore,
    selector: &ProfileSelector,
) -> Result<ResultEnvelopeV2> {
    let legacy_profile = profiles
        .profiles
        .get(&selector.profile)
        .is_some_and(|profile| profile.kind == ProfileKind::LegacyWranglerSession);
    if let Some(profile) = profiles.profiles.get(&selector.profile)
        && profile.kind == ProfileKind::OAuth
    {
        let tokens = secrets.load_profile_oauth_tokens(profile)?;
        let client_id = profile
            .oauth_client_id
            .as_deref()
            .ok_or_else(|| CliError::Input("OAuth profile is missing its client ID".to_owned()))?;
        let token = tokens
            .refresh_token()
            .unwrap_or_else(|| tokens.access_token());
        revoke_oauth_token(
            &http_client()?,
            &OAuthClientConfig::cfctl_public(client_id),
            token,
        )
        .await?;
    }
    if !legacy_profile {
        secrets.delete_profile(&selector.profile)?;
    }
    profiles.profiles.remove(&selector.profile);
    profiles.pending_logins.remove(&selector.profile);
    if profiles.current_profile.as_deref() == Some(&selector.profile) {
        profiles.current_profile = None;
    }
    profiles.save(store)?;
    Ok(ResultEnvelopeV2::success(
        "auth logout",
        json!({
            "profile": selector.profile,
            "credentials_removed": !legacy_profile,
            "legacy_profile_removed": legacy_profile,
            "message": if legacy_profile {
                "Unsupported legacy Wrangler session metadata was removed; no credential store entry was read or changed."
            } else {
                "Profile credentials and metadata were removed."
            }
        }),
    ))
}

fn import_api_token(
    store: &StateStore,
    profiles: &mut ProfilesConfig,
    secrets: &dyn SecretStore,
    arguments: &ImportApiTokenArgs,
) -> Result<ResultEnvelopeV2> {
    let token = read_import_secret(arguments.stdin, arguments.value_in.as_deref(), "API token")?;
    store_imported_api_token(
        store,
        profiles,
        secrets,
        &arguments.profile,
        &arguments.account,
        &token,
    )
}

fn store_imported_api_token(
    store: &StateStore,
    profiles: &mut ProfilesConfig,
    secrets: &dyn SecretStore,
    profile_id: &str,
    account: &str,
    token: &str,
) -> Result<ResultEnvelopeV2> {
    let account = account.trim();
    let token = token.trim();
    if account.is_empty() {
        return Err(CliError::Input(
            "API-token import requires a non-empty `--account` pin".to_owned(),
        ));
    }
    if token.is_empty() {
        return Err(CliError::Input(
            "the supplied API token was empty".to_owned(),
        ));
    }
    if token.chars().any(char::is_whitespace) {
        return Err(CliError::Input(
            "the supplied API token must be a single value without whitespace".to_owned(),
        ));
    }
    let profile = ProfileMetadata::new(profile_id, ProfileKind::ApiToken, Some(account));
    mark_credential_install_pending(store, profiles, &profile, true)?;
    secrets.store_api_token(profile_id, token)?;
    let (secret_backend, storage_note) =
        describe_secret_backend(secrets.locate_api_token(profile_id)?);
    profiles.profiles.insert(profile_id.to_owned(), profile);
    profiles.current_profile = Some(profile_id.to_owned());
    profiles.save(store)?;
    Ok(ResultEnvelopeV2::success(
        "auth import-api-token",
        json!({
            "profile": profile_id,
            "kind": "api_token",
            "account_id": account,
            "selected": true,
            "emergency_only": false,
            "secret_backend": secret_backend,
            "message": format!("API token stored {storage_note} and selected as the active profile. The token value was not written to stdout, plans, or repository files.")
        }),
    ))
}

fn import_global_key(
    store: &StateStore,
    profiles: &mut ProfilesConfig,
    secrets: &dyn SecretStore,
    arguments: &ImportGlobalKeyArgs,
) -> Result<ResultEnvelopeV2> {
    let key = read_import_secret(arguments.stdin, arguments.value_in.as_deref(), "global key")?
        .trim()
        .to_owned();
    if key.is_empty() {
        return Err(CliError::Input(
            "the supplied global key was empty".to_owned(),
        ));
    }
    let profile = ProfileMetadata::new(&arguments.profile, ProfileKind::GlobalKey, None);
    mark_credential_install_pending(store, profiles, &profile, false)?;
    secrets.store_global_key(&arguments.profile, &arguments.email, &key)?;
    let (secret_backend, storage_note) =
        describe_secret_backend(secrets.locate_global_key(&arguments.profile)?);
    profiles.profiles.insert(arguments.profile.clone(), profile);
    profiles.save(store)?;
    Ok(ResultEnvelopeV2::success(
        "auth import-global-key",
        json!({
            "profile": arguments.profile,
            "emergency_only": true,
            "selected": false,
            "secret_backend": secret_backend,
            "message": format!("Emergency global key stored {storage_note}. It was not selected.")
        }),
    ))
}

fn mark_credential_install_pending(
    store: &StateStore,
    profiles: &mut ProfilesConfig,
    complete_profile: &ProfileMetadata,
    select: bool,
) -> Result<()> {
    let mut pending_profile = complete_profile.clone();
    pending_profile.credential_generation_id = None;
    profiles
        .profiles
        .insert(pending_profile.id.clone(), pending_profile);
    if select {
        profiles.current_profile = Some(complete_profile.id.clone());
    }
    profiles.save(store)
}

async fn catalog_command(store: &StateStore, command: CatalogCommand) -> Result<ResultEnvelopeV2> {
    match command {
        CatalogCommand::Sync => sync_catalog(store).await,
        CatalogCommand::Search(arguments) => {
            let catalog = ensure_catalog(store).await?;
            let results: Vec<_> = catalog
                .search(&arguments.query)
                .into_iter()
                .take(arguments.limit)
                .map(caller_facing_capability)
                .collect();
            Ok(ResultEnvelopeV2::success(
                "catalog search",
                serde_json::to_value(results)?,
            ))
        }
        CatalogCommand::Show(selector) => {
            let catalog = ensure_catalog(store).await?;
            let capability = catalog
                .get(&selector.capability_id)
                .ok_or_else(|| capability_missing(&selector.capability_id))?;
            Ok(ResultEnvelopeV2::success(
                "catalog show",
                serde_json::to_value(caller_facing_capability(capability))?,
            ))
        }
        CatalogCommand::Changes => {
            let current = ensure_catalog(store).await?;
            let previous_path = store.paths().catalog_previous_file();
            let changes = if previous_path.is_file() {
                CatalogSnapshot::diff(&CatalogSnapshot::load(&previous_path)?, &current)
            } else {
                Vec::new()
            };
            Ok(ResultEnvelopeV2::success(
                "catalog changes",
                json!({"current_schema_hash": current.schema_hash, "changes": changes, "has_previous_snapshot": previous_path.is_file()}),
            ))
        }
        CatalogCommand::Coverage => {
            let catalog = ensure_catalog(store).await?;
            let mut coverage = serde_json::to_value(catalog.coverage())?;
            if let Some(object) = coverage.as_object_mut() {
                object.insert(
                    "operational_proof".to_owned(),
                    operational_proof_coverage(store, &catalog)?,
                );
            }
            Ok(ResultEnvelopeV2::success("catalog coverage", coverage))
        }
    }
}

async fn sync_catalog(store: &StateStore) -> Result<ResultEnvelopeV2> {
    let client = http_client()?;
    let (mut catalog, feeds) =
        tokio::try_join!(fetch_official(&client), fetch_official_text_feeds(&client))?;
    ingest_telemetry_capabilities(&mut catalog)?;
    ingest_native_control_capabilities(&mut catalog)?;
    attach_official_product_knowledge(&mut catalog, &feeds)?;
    for (program, version_argument) in [("wrangler", "--version"), ("cloudflared", "version")] {
        if which::which(program).is_ok() {
            let help = std::process::Command::new(program)
                .arg("--help")
                .output()
                .map_err(|source| cli_io(Path::new(program), source))?;
            let version = std::process::Command::new(program)
                .arg(version_argument)
                .output()
                .map_err(|source| cli_io(Path::new(program), source))?;
            ingest_cli_help(
                &mut catalog,
                program,
                String::from_utf8_lossy(&version.stdout).trim(),
                &String::from_utf8_lossy(&help.stdout),
            );
            if program == "wrangler" {
                let pages_deploy_help = std::process::Command::new(program)
                    .args(["pages", "deploy", "--help"])
                    .output()
                    .map_err(|source| cli_io(Path::new(program), source))?;
                if pages_deploy_help.status.success() {
                    ingest_wrangler_pages_deploy_help(
                        &mut catalog,
                        String::from_utf8_lossy(&version.stdout).trim(),
                        &String::from_utf8_lossy(&pages_deploy_help.stdout),
                    );
                }
                let versions_upload_help = std::process::Command::new(program)
                    .args(["versions", "upload", "--help"])
                    .output()
                    .map_err(|source| cli_io(Path::new(program), source))?;
                let versions_deploy_help = std::process::Command::new(program)
                    .args(["versions", "deploy", "--help"])
                    .output()
                    .map_err(|source| cli_io(Path::new(program), source))?;
                if versions_upload_help.status.success() && versions_deploy_help.status.success() {
                    ingest_wrangler_worker_versions_help(
                        &mut catalog,
                        String::from_utf8_lossy(&version.stdout).trim(),
                        &String::from_utf8_lossy(&versions_upload_help.stdout),
                        &String::from_utf8_lossy(&versions_deploy_help.stdout),
                    );
                }
            }
        }
    }
    ingest_governed_ui_capabilities(&mut catalog);
    catalog.refresh_hash()?;
    let oauth_scope_status = match refresh_oauth_scopes_if_authenticated(store).await {
        Ok(Some(snapshot)) => json!({
            "status": "refreshed",
            "schema_hash": snapshot.get("schema_hash"),
            "count": snapshot.pointer("/scopes").and_then(Value::as_array).map(Vec::len),
        }),
        Ok(None) => json!({"status": "not_refreshed", "reason": "no active authenticated profile"}),
        Err(error) => json!({"status": "not_refreshed", "reason": error.to_string()}),
    };
    let current_path = store.paths().catalog_file();
    let previous_catalog = preserve_previous_catalog(store)?;
    store.write_json(&current_path, &catalog)?;
    store.write_json(&docs_file(store), &feeds)?;
    let index_path = catalog_index_file(store);
    CatalogIndex::rebuild(&index_path, &catalog)?;
    let evidence = store.write_evidence(
        EvidenceClass::LiveRead,
        &json!({
            "source": catalog.source_url,
            "schema_hash": catalog.schema_hash,
            "capability_count": catalog.capabilities.len(),
            "docs_index_url": feeds.docs_index_url,
            "changelog_url": feeds.changelog_url,
            "oauth_scope_inventory": oauth_scope_status.clone(),
            "previous_catalog": previous_catalog.clone(),
        }),
    )?;
    Ok(ResultEnvelopeV2::success(
        "catalog sync",
        json!({
            "coverage": catalog.coverage(),
            "docs_fetched_at": feeds.fetched_at,
            "oauth_scope_inventory": oauth_scope_status,
            "previous_catalog": previous_catalog,
            "message": format!("Catalog synced: {} API, CLI, and governed UI capabilities indexed.", catalog.capabilities.len())
        }),
    )
    .with_evidence(evidence))
}

fn preserve_previous_catalog(store: &StateStore) -> Result<Value> {
    let current_path = store.paths().catalog_file();
    if !current_path.is_file() {
        return Ok(json!({"status": "absent"}));
    }

    match CatalogSnapshot::load(&current_path) {
        Ok(current) => {
            let schema_hash = current.schema_hash.clone();
            store.write_json(&store.paths().catalog_previous_file(), &current)?;
            Ok(json!({
                "status": "preserved",
                "schema_hash": schema_hash,
            }))
        }
        Err(error) => Ok(json!({
            "status": "discarded_invalid",
            "reason": error.to_string(),
        })),
    }
}

async fn guide_command(store: &StateStore, arguments: &GuideArgs) -> Result<ResultEnvelopeV2> {
    if let Some(topic) = arguments.topic {
        return guide_topic_envelope(topic);
    }
    let capability_id = arguments.capability_id.as_deref().ok_or_else(|| {
        CliError::Input("guide requires one capability ID or `--topic`".to_owned())
    })?;
    let catalog = ensure_catalog(store).await?;
    let capability = catalog
        .get(capability_id)
        .ok_or_else(|| capability_missing(capability_id))?;
    Ok(ResultEnvelopeV2::success(
        "guide",
        serde_json::to_value(guide_document(capability))?,
    ))
}

fn guide_topic_envelope(topic: GuideTopicArg) -> Result<ResultEnvelopeV2> {
    let topic = match topic {
        GuideTopicArg::System => GuideTopicV1::System,
        GuideTopicArg::StandingAuthority => GuideTopicV1::StandingAuthority,
    };
    Ok(ResultEnvelopeV2::success(
        "guide",
        serde_json::to_value(guide_topic_document(topic))?,
    ))
}

#[expect(
    clippy::too_many_lines,
    reason = "the public call boundary must visibly sequence catalog validation, selectors, authorization, governed reads, and immutable mutation planning"
)]
async fn call_command(store: &StateStore, arguments: CallArgs) -> Result<ResultEnvelopeV2> {
    let catalog = ensure_catalog(store).await?;
    let capability = catalog
        .get(&arguments.capability_id)
        .cloned()
        .ok_or_else(|| capability_missing(&arguments.capability_id))?;
    if is_secret_output_capability(&capability) && arguments.value_out.is_none() {
        return Err(CliError::Input(
            "secret-producing capabilities require `--value-out <new-path>`; the value is never written to stdout or evidence"
                .to_owned(),
        ));
    }
    let is_r2_log_retrieval = capability.r2_log_retrieval.is_some();
    let is_d1_full_export = capability.d1_full_export.is_some();
    let is_d1_approved_mln_import = capability.d1_approved_mln_import.is_some();
    let is_d1_approved_mln_import_poll_resume =
        capability.d1_approved_mln_import_poll_resume.is_some();
    if is_d1_approved_mln_import != arguments.source_file.is_some() {
        return Err(CliError::Input(
            "governed D1 imports require exactly one plan-creation-only `--source-file`; no other capability accepts it"
                .to_owned(),
        ));
    }
    if is_d1_approved_mln_import_poll_resume && arguments.source_file.is_some() {
        return Err(CliError::Input(
            "D1 import poll continuation derives source authority from its parent and never accepts `--source-file`"
                .to_owned(),
        ));
    }
    if arguments.credential_in.is_some() && !is_r2_log_retrieval {
        return Err(CliError::Input(
            "`--credential-in` is accepted only by the governed R2 log retrieval capability"
                .to_owned(),
        ));
    }
    if is_r2_log_retrieval && arguments.credential_in.is_none() {
        return Err(CliError::Input(
            "R2 log retrieval requires `--credential-in <mode-0600-json-path>`; credentials are never accepted as selectors or argv values"
                .to_owned(),
        ));
    }
    if is_r2_log_retrieval && arguments.out.is_none() {
        return Err(CliError::Input(
            "R2 log retrieval requires `--out <new-path>`; retained logs are never written to stdout or evidence"
                .to_owned(),
        ));
    }
    if is_r2_log_retrieval && arguments.value_out.is_some() {
        return Err(CliError::Input(
            "R2 log retrieval uses `--out` for retrieved logs; `--value-out` is reserved for one-time secret-producing mutations"
                .to_owned(),
        ));
    }
    if is_d1_full_export && arguments.out.is_none() {
        return Err(CliError::Input(
            "D1 full export requires `--out <new-path>`; the SQL dump is never written to stdout or evidence"
                .to_owned(),
        ));
    }
    if is_d1_full_export
        && (arguments.body_json.is_some() || arguments.body_stdin || !arguments.query.is_empty())
    {
        return Err(CliError::Input(
            "D1 full export accepts only account_id and database_id selectors plus `--out`; caller SQL and export filters are not supported"
                .to_owned(),
        ));
    }
    if arguments.out.is_some()
        && capability.analytics_query.is_none()
        && !is_r2_log_retrieval
        && !is_d1_full_export
    {
        return Err(CliError::Input(
            "`--out` is restricted to bounded analytics, governed R2 log retrieval, and D1 full export"
                .to_owned(),
        ));
    }
    if arguments.out.is_some() && capability.mutating {
        return Err(CliError::Input(
            "mutations cannot stream results with `--out`; create and review a plan instead"
                .to_owned(),
        ));
    }
    let mut prepared = call_input(&capability, &arguments)?;
    if is_d1_approved_mln_import {
        let profiles = ProfilesConfig::load(store)?;
        let profile = profiles.selected(arguments.profile.as_deref())?;
        validate_approved_mln_import_prerequisites(
            store,
            &capability,
            &prepared.input,
            ImportPrerequisiteContext {
                profile_id: &profile.id,
                credential_generation_id: profile.credential_generation_id.as_deref(),
                catalog_hash: &catalog.schema_hash,
                import_operation_id: None,
                before: Utc::now(),
            },
        )?;
    }
    if capability.mln_0142_post_import_schema.is_some() {
        validate_mln_0142_post_import_schema_input(store, &capability, &prepared.input)?;
    }
    let import_stage = arguments
        .source_file
        .as_deref()
        .map(|source| stage_approved_mln_migration(store, &capability, &prepared.input, source))
        .transpose()?;
    let resume_poll_authority = if is_d1_approved_mln_import_poll_resume {
        let profiles = ProfilesConfig::load(store)?;
        let profile = profiles.selected(arguments.profile.as_deref())?;
        Some(validate_and_derive_resume_poll_authority(
            store,
            &capability,
            &prepared.input,
            &profile.id,
            profile.credential_generation_id.as_deref(),
            &catalog.schema_hash,
            Utc::now(),
            None,
        )?)
    } else {
        None
    };
    prepare_r2_temporary_credentials_input(&capability, &mut prepared.input)?;
    let security_action = prepare_security_action_input(&capability, &mut prepared.input)?;
    if is_access_application_login_methods_mutation(&capability) {
        validate_access_application_login_methods_desired_input(&capability, &prepared.input)?;
    } else if is_access_human_policy_mutation(&capability) {
        validate_access_human_policy_desired_input(&capability, &prepared.input)?;
    } else {
        preflight_call_input(&capability, &prepared.input, prepared.secret_body.as_ref())?;
    }
    if !capability.mutating {
        if prepared.secret_body.is_some() {
            return Err(CliError::Input(
                "read operations cannot accept secret request bodies".to_owned(),
            ));
        }
        let r2_credentials = arguments
            .credential_in
            .as_deref()
            .map(read_r2_log_retrieval_credentials)
            .transpose()?;
        let executed = execute_read(
            store,
            &catalog,
            &capability,
            &prepared.input,
            arguments.profile.as_deref(),
            arguments.account.as_deref(),
            arguments.out.as_deref(),
            r2_credentials.as_ref(),
        )
        .await?;
        let mut envelope = executed.envelope;
        let proof_result = record_operational_proof(
            store,
            &catalog,
            &capability,
            &prepared.input,
            executed.credential_generation_id.as_deref(),
            &envelope,
        );
        apply_operational_proof_index_result(&mut envelope, proof_result);
        return Ok(envelope);
    }
    let secrets = platform_secrets(store);
    let mut secret_ref = None;
    let mut adapter_targets = Map::new();
    if worker_deployment::binds_live_state(&capability) {
        let graph = discover_registered(store)?;
        let target = worker_deployment::prepare_target(&graph, &capability, &prepared.input)?
            .ok_or_else(|| {
                CliError::Input("Worker deployment target could not be derived".to_owned())
            })?;
        adapter_targets.insert("worker_deployment".to_owned(), target);
    }
    if let Some(security_action) = security_action {
        adapter_targets.insert("security_action".to_owned(), security_action);
    }
    if let Some(secret_body) = &prepared.secret_body {
        let reference = format!("plan-input/{}", uuid::Uuid::new_v4());
        let content_hash = hash_value(secret_body)?;
        secrets.put(&reference, &serde_json::to_string(secret_body)?)?;
        prepared.input.body = Some(json!({
            "$cfctl_secret_body_ref": reference,
            "content_hash": content_hash,
        }));
        secret_ref = Some(reference.clone());
        adapter_targets.insert("secret_body_ref".to_owned(), Value::String(reference));
        adapter_targets.insert("secret_body_hash".to_owned(), Value::String(content_hash));
    }
    if let Some(value_out) = &arguments.value_out {
        adapter_targets.insert(
            "value_out".to_owned(),
            Value::String(value_out.display().to_string()),
        );
    }
    if let Some(import_stage) = import_stage {
        adapter_targets.insert("approved_mln_import".to_owned(), import_stage);
    }
    if let Some(authority) = resume_poll_authority {
        adapter_targets.insert("approved_mln_import_poll_resume".to_owned(), authority);
    }
    let result = Box::pin(create_plan(
        store,
        &catalog,
        capability,
        prepared.input,
        arguments.profile.as_deref(),
        arguments.account.as_deref(),
        Value::Object(adapter_targets),
    ))
    .await;
    if result.is_err()
        && let Some(reference) = secret_ref
    {
        secrets.delete(&reference)?;
    }
    result
}

#[expect(
    clippy::too_many_lines,
    reason = "source identity and managed staging are one fail-closed boundary"
)]
fn stage_approved_mln_migration(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
    source: &Path,
) -> Result<Value> {
    if capability.id == "d1-import-database" {
        return stage_reviewed_git_d1_migration(store, capability, input, source);
    }
    let contract = capability
        .d1_approved_mln_import
        .as_ref()
        .ok_or_else(|| CliError::Input("approved MLN import contract is missing".to_owned()))?;
    if !source.is_absolute()
        || source.components().any(|component| {
            matches!(
                component,
                std::path::Component::ParentDir | std::path::Component::CurDir
            )
        })
    {
        return Err(CliError::Input(
            "approved migration source must be an absolute normalized path".to_owned(),
        ));
    }
    let migration_id = input
        .body
        .as_ref()
        .and_then(|body| body.get("migration_id"))
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("approved migration_id is missing".to_owned()))?;
    let approved = contract
        .migrations
        .iter()
        .find(|migration| migration.migration_id == migration_id)
        .ok_or_else(|| CliError::Input("migration_id is not in the closed catalogue".to_owned()))?;
    let source_parent = source
        .parent()
        .ok_or_else(|| CliError::Input("approved migration source has no parent".to_owned()))?;
    let discovered_root = PathBuf::from(git_authority_output(
        source_parent,
        &["rev-parse", "--show-toplevel"],
    )?);
    let canonical_root = fs::canonicalize(&discovered_root).map_err(|source| CliError::Io {
        path: discovered_root.display().to_string(),
        source,
    })?;
    let expected_source = canonical_root.join(&approved.repository_relative_path);
    if source != expected_source {
        return Err(CliError::Input(format!(
            "migration {migration_id} source must be the exact reviewed repository path `{}`",
            expected_source.display()
        )));
    }
    let git_common_dir =
        validate_approved_mln_repository_authority(contract, approved, &canonical_root, None)?;
    let mut cursor = PathBuf::new();
    for component in source.components() {
        cursor.push(component.as_os_str());
        let metadata = fs::symlink_metadata(&cursor).map_err(|source| CliError::Io {
            path: cursor.display().to_string(),
            source,
        })?;
        if metadata.file_type().is_symlink() {
            return Err(CliError::Input(format!(
                "approved migration source has symlink component `{}`",
                cursor.display()
            )));
        }
    }
    let mut source_options = OpenOptions::new();
    source_options.read(true);
    #[cfg(unix)]
    source_options.custom_flags(libc::O_NOFOLLOW);
    let mut source_file = source_options
        .open(source)
        .map_err(|source_error| CliError::Io {
            path: source.display().to_string(),
            source: source_error,
        })?;
    let metadata = source_file
        .metadata()
        .map_err(|source_error| CliError::Io {
            path: source.display().to_string(),
            source: source_error,
        })?;
    if !metadata.is_file() || metadata.len() != approved.bytes {
        return Err(CliError::Input(format!(
            "migration {migration_id} source is not a regular {}-byte file",
            approved.bytes
        )));
    }
    let capacity = usize::try_from(approved.bytes)
        .map_err(|_| CliError::Input("approved migration size exceeds this host".to_owned()))?;
    let mut bytes = Vec::with_capacity(capacity);
    source_file
        .read_to_end(&mut bytes)
        .map_err(|source_error| CliError::Io {
            path: source.display().to_string(),
            source: source_error,
        })?;
    let sha256 = hex::encode(Sha256::digest(&bytes));
    let md5 = hex::encode(Md5::digest(&bytes));
    if sha256 != approved.sha256 || md5 != approved.md5 || bytes.len() as u64 != approved.bytes {
        return Err(CliError::Input(format!(
            "migration {migration_id} source bytes do not match the approved SHA-256/MD5/size catalogue"
        )));
    }
    let stage_dir = store
        .paths()
        .data_dir
        .join("import-stages")
        .join(Uuid::new_v4().to_string());
    fs::create_dir_all(&stage_dir).map_err(|source| CliError::Io {
        path: stage_dir.display().to_string(),
        source,
    })?;
    #[cfg(unix)]
    fs::set_permissions(&stage_dir, fs::Permissions::from_mode(0o700)).map_err(|source| {
        CliError::Io {
            path: stage_dir.display().to_string(),
            source,
        }
    })?;
    let stage_path = stage_dir.join(&approved.basename);
    let mut options = OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    options.mode(0o600).custom_flags(libc::O_NOFOLLOW);
    let mut stage = options.open(&stage_path).map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    stage.write_all(&bytes).map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    stage.sync_all().map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    drop(stage);
    let mut staged_options = OpenOptions::new();
    staged_options.read(true);
    #[cfg(unix)]
    staged_options.custom_flags(libc::O_NOFOLLOW);
    let mut staged_file = staged_options
        .open(&stage_path)
        .map_err(|source| CliError::Io {
            path: stage_path.display().to_string(),
            source,
        })?;
    let staged_metadata = staged_file.metadata().map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    if !staged_metadata.is_file() || staged_metadata.len() != approved.bytes {
        return Err(CliError::Input(
            "managed import stage is no longer the reviewed regular file".to_owned(),
        ));
    }
    let mut staged = Vec::with_capacity(capacity);
    staged_file
        .read_to_end(&mut staged)
        .map_err(|source| CliError::Io {
            path: stage_path.display().to_string(),
            source,
        })?;
    let staged_sha256 = hex::encode(Sha256::digest(&staged));
    let staged_md5 = hex::encode(Md5::digest(&staged));
    if staged.len() as u64 != approved.bytes
        || staged_sha256 != approved.sha256
        || staged_md5 != approved.md5
    {
        return Err(CliError::Input(
            "managed import stage did not reopen with the reviewed identity; preserve it for inspection and do not plan"
                .to_owned(),
        ));
    }
    let revalidated_common = validate_approved_mln_repository_authority(
        contract,
        approved,
        &canonical_root,
        Some(&bytes),
    )?;
    if revalidated_common != git_common_dir {
        return Err(CliError::Input(
            "reviewed MLN Git common directory changed while staging".to_owned(),
        ));
    }
    let source_authority = json!({
        "schema_version":1,
        "repository_id":contract.repository_id,
        "observed_worktree_root":canonical_root,
        "observed_git_common_dir":git_common_dir,
        "head":contract.repository_head,
        "repository_relative_path":approved.repository_relative_path,
        "git_blob_oid":approved.git_blob_oid,
    });
    Ok(json!({
        "schema_version":1,
        "migration_id":migration_id,
        "catalog_basename":approved.basename,
        "source_authority":source_authority,
        "source_authority_hash":hash_value(&source_authority)?,
        "bytes":approved.bytes,
        "sha256":format!("sha256:{}", approved.sha256),
        "md5":approved.md5,
        "stage_path":stage_path,
        "stage_lifecycle":"preserve_until_verified_or_explicitly_retired",
        "target":{
            "account_id":contract.account_id,
            "database_id":contract.database_id,
        },
        "prerequisites":input.body,
    }))
}

#[expect(
    clippy::too_many_lines,
    reason = "generic Git source identity, byte capture, and private staging are one fail-closed planning boundary"
)]
fn stage_reviewed_git_d1_migration(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
    source: &Path,
) -> Result<Value> {
    let contract = capability
        .d1_approved_mln_import
        .as_ref()
        .filter(|contract| contract.repository_id.is_empty() && contract.migrations.is_empty())
        .ok_or_else(|| {
            CliError::Input("provider-generic reviewed-Git import contract is missing".to_owned())
        })?;
    if !source.is_absolute()
        || source.components().any(|component| {
            matches!(
                component,
                std::path::Component::ParentDir | std::path::Component::CurDir
            )
        })
        || source.extension().and_then(|value| value.to_str()) != Some("sql")
    {
        return Err(CliError::Input(
            "reviewed D1 migration source must be an absolute normalized `.sql` path".to_owned(),
        ));
    }
    let source_parent = source
        .parent()
        .ok_or_else(|| CliError::Input("reviewed migration source has no parent".to_owned()))?;
    let discovered_root = PathBuf::from(git_authority_output(
        source_parent,
        &["rev-parse", "--show-toplevel"],
    )?);
    let canonical_root = fs::canonicalize(&discovered_root).map_err(|source| CliError::Io {
        path: discovered_root.display().to_string(),
        source,
    })?;
    if canonical_root != discovered_root || !source.starts_with(&canonical_root) {
        return Err(CliError::Input(
            "reviewed migration source is outside its canonical Git worktree".to_owned(),
        ));
    }
    let relative = source
        .strip_prefix(&canonical_root)
        .ok()
        .and_then(Path::to_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CliError::Input("reviewed migration path is not a portable Git path".to_owned())
        })?;
    let head = git_authority_output(&canonical_root, &["rev-parse", "HEAD"])?;
    let remote = git_authority_output(&canonical_root, &["remote", "get-url", "origin"])?;
    let repository_id = normalize_reviewed_git_repository_id(&remote)?;
    let tracked = git_authority_output(
        &canonical_root,
        &["ls-files", "--error-unmatch", "--", relative],
    )?;
    let blob_spec = format!("{head}:{relative}");
    let git_blob_oid = git_authority_output(&canonical_root, &["rev-parse", &blob_spec])?;
    let status = git_authority_output(
        &canonical_root,
        &["status", "--porcelain=v1", "--untracked-files=all"],
    )?;
    if tracked != relative || !status.is_empty() {
        return Err(CliError::Input(
            "reviewed migration repository must be clean and the source must be tracked at HEAD"
                .to_owned(),
        ));
    }
    let common = git_authority_output(&canonical_root, &["rev-parse", "--git-common-dir"])?;
    let common_path = if Path::new(&common).is_absolute() {
        PathBuf::from(common)
    } else {
        canonical_root.join(common)
    };
    let canonical_common = fs::canonicalize(&common_path).map_err(|source| CliError::Io {
        path: common_path.display().to_string(),
        source,
    })?;
    let mut cursor = PathBuf::new();
    for component in source.components() {
        cursor.push(component.as_os_str());
        let metadata = fs::symlink_metadata(&cursor).map_err(|source| CliError::Io {
            path: cursor.display().to_string(),
            source,
        })?;
        if metadata.file_type().is_symlink() {
            return Err(CliError::Input(format!(
                "reviewed migration source has symlink component `{}`",
                cursor.display()
            )));
        }
    }
    let mut source_options = OpenOptions::new();
    source_options.read(true);
    #[cfg(unix)]
    source_options.custom_flags(libc::O_NOFOLLOW);
    let mut source_file = source_options
        .open(source)
        .map_err(|source_error| CliError::Io {
            path: source.display().to_string(),
            source: source_error,
        })?;
    let metadata = source_file
        .metadata()
        .map_err(|source_error| CliError::Io {
            path: source.display().to_string(),
            source: source_error,
        })?;
    if !metadata.is_file() || metadata.len() == 0 || metadata.len() > contract.max_source_bytes {
        return Err(CliError::Input(format!(
            "reviewed migration must be a non-empty regular file no larger than {} bytes",
            contract.max_source_bytes
        )));
    }
    let capacity = usize::try_from(metadata.len())
        .map_err(|_| CliError::Input("reviewed migration size exceeds this host".to_owned()))?;
    let mut bytes = Vec::with_capacity(capacity);
    source_file
        .read_to_end(&mut bytes)
        .map_err(|source_error| CliError::Io {
            path: source.display().to_string(),
            source: source_error,
        })?;
    let blob_bytes = git_authority_bytes(&canonical_root, &["cat-file", "blob", &git_blob_oid])?;
    if bytes != blob_bytes || bytes.len() as u64 != metadata.len() {
        return Err(CliError::Input(
            "reviewed migration source differs from its exact HEAD Git blob".to_owned(),
        ));
    }
    let sha256 = hex::encode(Sha256::digest(&bytes));
    let md5 = hex::encode(Md5::digest(&bytes));
    let source_authority = json!({
        "schema_version":1,
        "repository_id":repository_id,
        "observed_worktree_root":canonical_root,
        "observed_git_common_dir":canonical_common,
        "head":head,
        "repository_relative_path":relative,
        "git_blob_oid":git_blob_oid,
    });
    let source_authority_hash = hash_value(&source_authority)?;
    let basename = source
        .file_name()
        .and_then(|value| value.to_str())
        .ok_or_else(|| CliError::Input("reviewed migration basename is not UTF-8".to_owned()))?;
    let stage_dir = store
        .paths()
        .data_dir
        .join("import-stages")
        .join(Uuid::new_v4().to_string());
    fs::create_dir_all(&stage_dir).map_err(|source| CliError::Io {
        path: stage_dir.display().to_string(),
        source,
    })?;
    #[cfg(unix)]
    fs::set_permissions(&stage_dir, fs::Permissions::from_mode(0o700)).map_err(|source| {
        CliError::Io {
            path: stage_dir.display().to_string(),
            source,
        }
    })?;
    let stage_path = stage_dir.join(basename);
    let mut stage_options = OpenOptions::new();
    stage_options.write(true).create_new(true);
    #[cfg(unix)]
    stage_options.mode(0o600).custom_flags(libc::O_NOFOLLOW);
    let mut stage = stage_options
        .open(&stage_path)
        .map_err(|source| CliError::Io {
            path: stage_path.display().to_string(),
            source,
        })?;
    stage.write_all(&bytes).map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    stage.sync_all().map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    drop(stage);
    let staged = fs::read(&stage_path).map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    if staged != bytes {
        return Err(CliError::Input(
            "private import stage did not reopen with the reviewed bytes".to_owned(),
        ));
    }
    let target = json!({
        "account_id":input.selectors.get("account_id"),
        "database_id":input.selectors.get("database_id"),
    });
    if target
        .pointer("/account_id")
        .and_then(Value::as_str)
        .is_none()
        || target
            .pointer("/database_id")
            .and_then(Value::as_str)
            .is_none()
    {
        return Err(CliError::Input(
            "reviewed D1 import target selectors are missing".to_owned(),
        ));
    }
    Ok(json!({
        "schema_version":1,
        "migration_id":source_authority_hash,
        "catalog_basename":basename,
        "source_authority":source_authority,
        "source_authority_hash":source_authority_hash,
        "bytes":bytes.len(),
        "sha256":format!("sha256:{sha256}"),
        "md5":md5,
        "stage_path":stage_path,
        "stage_lifecycle":"preserve_until_verified_or_explicitly_retired",
        "target":target,
        "prerequisites":input.body,
    }))
}

fn normalize_reviewed_git_repository_id(remote: &str) -> Result<String> {
    let trimmed = remote.trim().trim_end_matches(".git");
    if trimmed.contains('?') || trimmed.contains('#') || trimmed.contains('\n') {
        return Err(CliError::Input(
            "Git origin contains query, fragment, or control data and cannot be retained safely"
                .to_owned(),
        ));
    }
    let normalized = if let Some(rest) = trimmed.strip_prefix("https://") {
        if rest
            .split('/')
            .next()
            .is_none_or(|authority| authority.contains('@'))
        {
            return Err(CliError::Input(
                "Git HTTPS origin must not contain embedded credentials".to_owned(),
            ));
        }
        rest.to_owned()
    } else if let Some(rest) = trimmed.strip_prefix("ssh://git@") {
        rest.to_owned()
    } else if let Some(rest) = trimmed.strip_prefix("git@") {
        rest.replacen(':', "/", 1)
    } else {
        return Err(CliError::Input(
            "Git origin must be a credential-free HTTPS or git SSH repository identity".to_owned(),
        ));
    };
    if normalized.split('/').count() < 3 || normalized.contains('@') || normalized.contains(':') {
        return Err(CliError::Input(
            "Git origin is not a portable host/owner/repository identity".to_owned(),
        ));
    }
    Ok(normalized)
}

fn git_authority_output(repository_root: &Path, arguments: &[&str]) -> Result<String> {
    let mut command = StdCommand::new("git");
    command.arg("-C").arg(repository_root).args(arguments);
    clear_git_authority_environment(&mut command);
    let output = command.output().map_err(|source| CliError::Io {
        path: repository_root.display().to_string(),
        source,
    })?;
    if !output.status.success() {
        return Err(CliError::Input(format!(
            "reviewed migration repository authority command `git {}` failed closed",
            arguments.join(" ")
        )));
    }
    String::from_utf8(output.stdout)
        .map(|value| value.trim().to_owned())
        .map_err(|_| CliError::Input("Git authority output was not UTF-8".to_owned()))
}

fn git_authority_bytes(repository_root: &Path, arguments: &[&str]) -> Result<Vec<u8>> {
    let mut command = StdCommand::new("git");
    command.arg("-C").arg(repository_root).args(arguments);
    clear_git_authority_environment(&mut command);
    let output = command.output().map_err(|source| CliError::Io {
        path: repository_root.display().to_string(),
        source,
    })?;
    if !output.status.success() {
        return Err(CliError::Input(format!(
            "reviewed migration repository authority command `git {}` failed closed",
            arguments.join(" ")
        )));
    }
    Ok(output.stdout)
}

fn clear_git_authority_environment(command: &mut StdCommand) {
    for (name, _) in env::vars_os() {
        if name.as_encoded_bytes().starts_with(b"GIT_") {
            command.env_remove(name);
        }
    }
}

fn validate_approved_mln_repository_authority(
    contract: &cfctl_core::D1ApprovedMlnImportContractV1,
    migration: &cfctl_core::D1ApprovedMlnMigrationV1,
    root: &Path,
    expected_bytes: Option<&[u8]>,
) -> Result<PathBuf> {
    let canonical_root = fs::canonicalize(root).map_err(|source| CliError::Io {
        path: root.display().to_string(),
        source,
    })?;
    if canonical_root != root {
        return Err(CliError::Input(
            "reviewed migration repository root is missing, substituted, or non-canonical"
                .to_owned(),
        ));
    }
    let top = git_authority_output(root, &["rev-parse", "--show-toplevel"])?;
    let head = git_authority_output(root, &["rev-parse", "HEAD"])?;
    let remote = git_authority_output(root, &["remote", "get-url", "origin"])?;
    let common = git_authority_output(root, &["rev-parse", "--git-common-dir"])?;
    let common_path = if Path::new(&common).is_absolute() {
        PathBuf::from(common)
    } else {
        root.join(common)
    };
    let canonical_common = fs::canonicalize(&common_path).map_err(|source| CliError::Io {
        path: common_path.display().to_string(),
        source,
    })?;
    if top != canonical_root.to_string_lossy()
        || head != contract.repository_head
        || normalize_reviewed_mln_repository_id(&remote).as_deref()
            != Some(contract.repository_id.as_str())
    {
        return Err(CliError::Input(
            "reviewed migration repository identity, canonical worktree root, or HEAD drifted"
                .to_owned(),
        ));
    }
    let relative = migration.repository_relative_path.as_str();
    let tracked = git_authority_output(root, &["ls-files", "--error-unmatch", "--", relative])?;
    let blob_spec = format!("{}:{relative}", contract.repository_head);
    let blob = git_authority_output(root, &["rev-parse", &blob_spec])?;
    let status =
        git_authority_output(root, &["status", "--porcelain=v1", "--untracked-files=all"])?;
    let blob_bytes = git_authority_bytes(root, &["cat-file", "blob", &migration.git_blob_oid])?;
    if tracked != relative || blob != migration.git_blob_oid || !status.is_empty() {
        return Err(CliError::Input(
            "reviewed migration is untracked, dirty, or does not match the pinned HEAD blob"
                .to_owned(),
        ));
    }
    if expected_bytes.is_some_and(|bytes| bytes != blob_bytes) {
        return Err(CliError::Input(
            "reviewed migration source bytes differ from the exact pinned Git blob".to_owned(),
        ));
    }
    Ok(canonical_common)
}

fn normalize_reviewed_mln_repository_id(remote: &str) -> Option<String> {
    match remote {
        "https://github.com/rogu3bear/mln-web.git"
        | "https://github.com/rogu3bear/mln-web"
        | "git@github.com:rogu3bear/mln-web.git"
        | "git@github.com:rogu3bear/mln-web" => Some("github.com/rogu3bear/mln-web".to_owned()),
        "https://github.com/rogu3bear/osint-research-center.git"
        | "https://github.com/rogu3bear/osint-research-center"
        | "git@github.com:rogu3bear/osint-research-center.git"
        | "git@github.com:rogu3bear/osint-research-center" => {
            Some("github.com/rogu3bear/osint-research-center".to_owned())
        }
        _ => None,
    }
}

fn required_body_string<'a>(body: &'a Map<String, Value>, field: &str) -> Result<&'a str> {
    body.get(field)
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input(format!("approved MLN import requires {field}")))
}

const CLOSED_IMPORT_RECOVERY_BOOKMARK_MAX_AGE_MINUTES: i64 = 10;

fn validate_closed_import_recovery_bookmark(
    store: &StateStore,
    input: &CallInput,
    body: &Map<String, Value>,
    contract: &cfctl_core::D1ApprovedMlnImportContractV1,
    context: ImportPrerequisiteContext<'_>,
    subject: &str,
) -> Result<()> {
    let evidence_hash = required_body_string(body, "pre_recovery_anchor_evidence_hash")?;
    let bookmark_hash = required_body_string(body, "pre_recovery_anchor_bookmark_hash")?;
    let expected_input_hash = hash_value(&serde_json::to_value(CallInput {
        selectors: input.selectors.clone(),
        query: json!({}),
        ..CallInput::default()
    })?)?;
    let freshness_floor =
        context.before - ChronoDuration::minutes(CLOSED_IMPORT_RECOVERY_BOOKMARK_MAX_AGE_MINUTES);
    let matches = store
        .list_operational_proofs()?
        .into_iter()
        .filter(|proof| {
            proof.capability_id == "d1-time-travel-get-bookmark"
                && proof.catalog_hash == context.catalog_hash
                && proof.input_hash == expected_input_hash
                && proof.profile_id.as_deref() == Some(context.profile_id)
                && proof.account_id.as_deref() == Some(contract.account_id.as_str())
                && proof.credential_generation_id.as_deref() == context.credential_generation_id
                && proof.outcome == OperationalProofOutcomeV1::Succeeded
                && proof.evidence.content_hash == evidence_hash
                && proof.observed_at >= freshness_floor
                && proof.observed_at < context.before
        })
        .collect::<Vec<_>>();
    if matches.len() != 1 {
        return Err(CliError::Input(format!(
            "{subject} import requires exactly one governed D1 time-travel bookmark read from the 10 minutes before planning, bound to the catalog, request, target, profile, credential generation, and evidence"
        )));
    }
    let evidence = store.read_evidence_value(evidence_hash)?;
    let bookmark = evidence
        .pointer("/result/bookmark")
        .and_then(Value::as_str)
        .filter(|bookmark| !bookmark.is_empty())
        .ok_or_else(|| {
            CliError::Input(format!(
                "{subject} recovery bookmark evidence omitted the exact bookmark"
            ))
        })?;
    if evidence.get("status").and_then(Value::as_u64) != Some(200)
        || evidence.get("success").and_then(Value::as_bool) != Some(true)
        || hash_value(&Value::String(bookmark.to_owned()))? != bookmark_hash
    {
        return Err(CliError::Input(format!(
            "{subject} recovery bookmark evidence or bookmark hash drifted"
        )));
    }
    Ok(())
}

#[expect(
    clippy::too_many_lines,
    reason = "the closed 0142 then 0143 prerequisite graph is validated as one contract"
)]
fn validate_approved_mln_import_prerequisites(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
    context: ImportPrerequisiteContext<'_>,
) -> Result<()> {
    if capability.id == "d1-import-database" {
        return validate_reviewed_git_import_prerequisites(store, input, context);
    }
    let contract = capability
        .d1_approved_mln_import
        .as_ref()
        .ok_or_else(|| CliError::Input("approved MLN import contract is missing".to_owned()))?;
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("approved MLN import body is missing".to_owned()))?;
    let migration_id = body
        .get("migration_id")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("migration_id is missing".to_owned()))?;
    if capability.id == "d1-import-approved-osint-research-migration" {
        validate_closed_import_recovery_bookmark(
            store,
            input,
            body,
            contract,
            context,
            "OSINT Research",
        )?;
        return Ok(());
    }
    let pre_operation = body
        .get("pre_recovery_anchor_operation_id")
        .and_then(Value::as_str)
        .filter(|value| Uuid::parse_str(value).is_ok())
        .ok_or_else(|| {
            CliError::Input(
                "pre_recovery_anchor_operation_id must be a canonical operation id".to_owned(),
            )
        })?;
    let pre_evidence_hash = required_body_string(body, "pre_recovery_anchor_evidence_hash")?;
    let pre_output_sha256 = required_body_string(body, "pre_recovery_anchor_output_sha256")?;
    let pre_bookmark_hash = required_body_string(body, "pre_recovery_anchor_bookmark_hash")?;
    store.read_evidence_value(pre_evidence_hash)?;
    let expected_target_hash = hash_value(&json!({
        "account_id":contract.account_id,
        "database_id":contract.database_id,
    }))?;
    let expected_export_request_hash = hash_value(&serde_json::to_value(CallInput {
        selectors: input.selectors.clone(),
        query: json!({}),
        ..CallInput::default()
    })?)?;
    let pre_expectation = |before| D1RecoveryAnchorExpectation {
        operation_id: pre_operation,
        evidence_hash: pre_evidence_hash,
        output_sha256: Some(pre_output_sha256),
        bookmark_hash: pre_bookmark_hash,
        catalog_hash: context.catalog_hash,
        request_hash: &expected_export_request_hash,
        target_scope_hash: &expected_target_hash,
        account_id: &contract.account_id,
        profile_id: context.profile_id,
        credential_generation_id: context.credential_generation_id,
        after: None,
        before,
    };
    if migration_id == "0142" {
        validate_exact_d1_recovery_anchor(store, &pre_expectation(context.before))?;
        if context.import_operation_id == Some(pre_operation) {
            return Err(CliError::Input(
                "pre-0142 recovery anchor must be distinct from the import operation".to_owned(),
            ));
        }
        return Ok(());
    }
    let prior_operation = body
        .get("prior_0142_operation_id")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("0143 requires prior_0142_operation_id".to_owned()))?;
    let prior_hash = body
        .get("prior_0142_boundary_evidence_hash")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("0143 requires prior_0142_boundary_evidence_hash".to_owned())
        })?;
    let prior_proof_operation = body
        .get("prior_0142_schema_proof_operation_id")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("0143 requires prior_0142_schema_proof_operation_id".to_owned())
        })?;
    let prior_verification_hash = body
        .get("prior_0142_verification_evidence_hash")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("0143 requires prior_0142_verification_evidence_hash".to_owned())
        })?;
    let prior_plan = store.load_plan(prior_operation)?;
    let prior_input: CallInput = serde_json::from_value(prior_plan.input.clone())?;
    let prior_exact = prior_plan.capability.id == capability.id
        && mln_0142_terminal_import_state(&prior_plan)
        && prior_plan.account_id == contract.account_id
        && prior_input.selectors == input.selectors
        && prior_input
            .body
            .as_ref()
            .and_then(|body| body.get("migration_id"))
            .and_then(Value::as_str)
            == Some("0142");
    let verification_artifact_matches = prior_plan
        .transaction_artifact(TransactionStageV1::VerificationResponsePersisted)
        .and_then(|artifact| artifact.get("evidence_hash"))
        .and_then(Value::as_str)
        == Some(prior_verification_hash);
    let verification_evidence = store.read_evidence_value(prior_verification_hash)?;
    let verification_receipt_matches = verification_evidence.get("state").and_then(Value::as_str)
        == Some("verified")
        && verification_evidence
            .get("operation_id")
            .and_then(Value::as_str)
            == Some(prior_operation)
        && verification_evidence
            .get("provider_complete_evidence_hash")
            .and_then(Value::as_str)
            == Some(prior_hash)
        && verification_evidence
            .get("post_import_operation_id")
            .and_then(Value::as_str)
            == Some(prior_proof_operation);
    let prior_boundary = exact_durable_provider_complete_boundary(store, prior_operation)?;
    let boundary_matches = prior_boundary.evidence_hash == prior_hash;
    let expected_final_bookmark_hash = prior_boundary
        .checkpoint
        .pointer("/receipt/final_bookmark")
        .and_then(Value::as_str)
        .and_then(|bookmark| hash_value(&Value::String(bookmark.to_owned())).ok());
    let schema_proofs = store
        .list_operational_proofs()?
        .into_iter()
        .filter(|proof| {
            proof.mln_0142_governed_execution().is_some_and(|binding| {
                proof.capability_id == "mln-0142-post-import-schema"
                    && binding.operation_id == prior_proof_operation
                    && binding.import_operation_id == prior_operation
                    && binding.import_boundary_evidence_hash == prior_hash
                    && binding.import_plan_hash == prior_plan.content_hash
                    && binding.import_source_sha256
                        == "sha256:07e1c5bd77dd529bfe58f0eee80ad29c40fdd0f3e9c9a37163cfaa0683124af0"
                    && binding.target_scope_hash == expected_target_hash
                    && Some(binding.final_bookmark_hash.as_str())
                        == expected_final_bookmark_hash.as_deref()
                    && binding.completion_status == "completed"
            })
        })
        .collect::<Vec<_>>();
    if !prior_exact
        || !verification_artifact_matches
        || !verification_receipt_matches
        || schema_proofs.len() != 1
        || !boundary_matches
    {
        return Err(CliError::Input(
            "0143 requires one terminal verified 0142 import joined to its exact schema proof, verification evidence, and provider boundary"
                .to_owned(),
        ));
    }
    validate_exact_d1_recovery_anchor(store, &pre_expectation(prior_plan.created_at))?;
    if pre_operation == prior_operation || context.import_operation_id == Some(pre_operation) {
        return Err(CliError::Input(
            "pre-0142 recovery anchor must be distinct from both import operations".to_owned(),
        ));
    }
    let anchor_operation = body
        .get("post_0142_anchor_operation_id")
        .and_then(Value::as_str)
        .filter(|value| Uuid::parse_str(value).is_ok())
        .ok_or_else(|| {
            CliError::Input("0143 requires a distinct post-0142 recovery anchor".to_owned())
        })?;
    if anchor_operation == pre_operation
        || anchor_operation == prior_operation
        || context.import_operation_id == Some(anchor_operation)
    {
        return Err(CliError::Input(
            "0143 post-0142 recovery anchor must be distinct from both imports and the pre-0142 anchor"
                .to_owned(),
        ));
    }
    let anchor_evidence_hash = body
        .get("post_0142_anchor_evidence_hash")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("0143 requires post_0142_anchor_evidence_hash".to_owned())
        })?;
    let anchor_bookmark_hash = body
        .get("post_0142_anchor_bookmark_hash")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("0143 requires post_0142_anchor_bookmark_hash".to_owned())
        })?;
    store.read_evidence_value(anchor_evidence_hash)?;
    let closed_at = prior_plan
        .transaction_journal
        .iter()
        .find(|checkpoint| checkpoint.stage == TransactionStageV1::Closed)
        .map(|checkpoint| checkpoint.recorded_at)
        .ok_or_else(|| {
            CliError::Input("verified 0142 omitted its terminal checkpoint".to_owned())
        })?;
    let cutoff = context.before;
    let expected_profile = context.profile_id;
    let current_generation = context.credential_generation_id;
    let prior_generation = schema_proofs[0]
        .mln_0142_governed_execution()
        .map(|binding| binding.credential_generation_id.as_str())
        .ok_or_else(|| CliError::Input("verified 0142 schema proof lost its binding".to_owned()))?;
    if current_generation != Some(prior_generation) {
        return Err(CliError::Input(
            "0143 selected credential generation drifted from verified 0142".to_owned(),
        ));
    }
    let anchor_expectation = D1RecoveryAnchorExpectation {
        operation_id: anchor_operation,
        evidence_hash: anchor_evidence_hash,
        output_sha256: None,
        bookmark_hash: anchor_bookmark_hash,
        catalog_hash: context.catalog_hash,
        request_hash: &expected_export_request_hash,
        target_scope_hash: &expected_target_hash,
        account_id: &contract.account_id,
        profile_id: expected_profile,
        credential_generation_id: current_generation,
        after: Some(closed_at),
        before: cutoff,
    };
    let anchor_completed_at = validate_exact_d1_recovery_anchor(store, &anchor_expectation)?;
    let invariant_operation = body
        .get("pre_import_invariant_operation_id")
        .and_then(Value::as_str)
        .filter(|value| Uuid::parse_str(value).is_ok())
        .ok_or_else(|| {
            CliError::Input(
                "0143 requires a canonical pre_import_invariant_operation_id".to_owned(),
            )
        })?;
    let invariant_evidence_hash = required_body_string(body, "pre_import_invariant_evidence_hash")?;
    store
        .read_evidence_value(invariant_evidence_hash)
        .map_err(|error| {
            CliError::Input(format!(
                "pre_import_invariant_evidence_hash does not resolve to immutable evidence: {error}"
            ))
        })?;
    let invariant_request_hash = hash_value(&serde_json::to_value(CallInput {
        selectors: input.selectors.clone(),
        query: json!({}),
        body: Some(json!({"migration_id":"0143","phase":"pre_import"})),
        ..CallInput::default()
    })?)?;
    validate_exact_mln_0143_pre_import(
        store,
        &Mln0143PreImportExpectation {
            operation_id: invariant_operation,
            evidence_hash: invariant_evidence_hash,
            catalog_hash: context.catalog_hash,
            request_hash: &invariant_request_hash,
            target_scope_hash: &expected_target_hash,
            account_id: &contract.account_id,
            profile_id: context.profile_id,
            credential_generation_id: context.credential_generation_id,
            capability_version: contract.pre_import_capability_version,
            validator_contract_hash: &contract.pre_import_validator_contract_hash,
            fixed_query_sha256: &contract.pre_import_fixed_query_sha256,
            after: anchor_completed_at,
            before: context.before,
        },
    )?;
    Ok(())
}

fn validate_reviewed_git_import_prerequisites(
    store: &StateStore,
    input: &CallInput,
    context: ImportPrerequisiteContext<'_>,
) -> Result<()> {
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("reviewed D1 import body is missing".to_owned()))?;
    let operation_id = body
        .get("pre_recovery_anchor_operation_id")
        .and_then(Value::as_str)
        .filter(|value| Uuid::parse_str(value).is_ok())
        .ok_or_else(|| {
            CliError::Input(
                "pre_recovery_anchor_operation_id must be a canonical operation id".to_owned(),
            )
        })?;
    if context.import_operation_id == Some(operation_id) {
        return Err(CliError::Input(
            "pre-import recovery export must be distinct from the import operation".to_owned(),
        ));
    }
    let evidence_hash = required_body_string(body, "pre_recovery_anchor_evidence_hash")?;
    let output_sha256 = required_body_string(body, "pre_recovery_anchor_output_sha256")?;
    let bookmark_hash = required_body_string(body, "pre_recovery_anchor_bookmark_hash")?;
    store.read_evidence_value(evidence_hash)?;
    let account_id = input
        .selectors
        .get("account_id")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("reviewed import account_id is missing".to_owned()))?;
    let database_id = input
        .selectors
        .get("database_id")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("reviewed import database_id is missing".to_owned()))?;
    let expected_target_hash = hash_value(&json!({
        "account_id":account_id,
        "database_id":database_id,
    }))?;
    let expected_request_hash = hash_value(&serde_json::to_value(CallInput {
        selectors: input.selectors.clone(),
        query: json!({}),
        ..CallInput::default()
    })?)?;
    validate_exact_d1_recovery_anchor(
        store,
        &D1RecoveryAnchorExpectation {
            operation_id,
            evidence_hash,
            output_sha256: Some(output_sha256),
            bookmark_hash,
            catalog_hash: context.catalog_hash,
            request_hash: &expected_request_hash,
            target_scope_hash: &expected_target_hash,
            account_id,
            profile_id: context.profile_id,
            credential_generation_id: context.credential_generation_id,
            after: None,
            before: context.before,
        },
    )?;
    Ok(())
}

#[derive(Clone, Copy)]
struct ImportPrerequisiteContext<'a> {
    profile_id: &'a str,
    credential_generation_id: Option<&'a str>,
    catalog_hash: &'a str,
    import_operation_id: Option<&'a str>,
    before: chrono::DateTime<Utc>,
}

#[derive(Clone, Copy)]
struct D1RecoveryAnchorExpectation<'a> {
    operation_id: &'a str,
    evidence_hash: &'a str,
    output_sha256: Option<&'a str>,
    bookmark_hash: &'a str,
    catalog_hash: &'a str,
    request_hash: &'a str,
    target_scope_hash: &'a str,
    account_id: &'a str,
    profile_id: &'a str,
    credential_generation_id: Option<&'a str>,
    after: Option<chrono::DateTime<Utc>>,
    before: chrono::DateTime<Utc>,
}

#[derive(Clone, Copy)]
struct Mln0143PreImportExpectation<'a> {
    operation_id: &'a str,
    evidence_hash: &'a str,
    catalog_hash: &'a str,
    request_hash: &'a str,
    target_scope_hash: &'a str,
    account_id: &'a str,
    profile_id: &'a str,
    credential_generation_id: Option<&'a str>,
    capability_version: u8,
    validator_contract_hash: &'a str,
    fixed_query_sha256: &'a str,
    after: chrono::DateTime<Utc>,
    before: chrono::DateTime<Utc>,
}

fn d1_recovery_anchor_matches(
    proof: &OperationalProofV1,
    expected: &D1RecoveryAnchorExpectation<'_>,
) -> bool {
    proof
        .d1_full_export_governed_execution()
        .is_some_and(|binding| {
            binding.operation_id == expected.operation_id
                && proof.capability_id == "d1-full-export"
                && proof.evidence.content_hash == expected.evidence_hash
                && binding.manifest_evidence_hash == expected.evidence_hash
                && expected
                    .output_sha256
                    .is_none_or(|value| binding.output_file_sha256 == value)
                && binding.at_bookmark_hash == expected.bookmark_hash
                && proof.catalog_hash == expected.catalog_hash
                && binding.catalog_hash == expected.catalog_hash
                && proof.input_hash == expected.request_hash
                && binding.request_hash == expected.request_hash
                && binding.target_scope_hash == expected.target_scope_hash
                && proof.account_id.as_deref() == Some(expected.account_id)
                && proof.profile_id.as_deref() == Some(expected.profile_id)
                && binding.profile_id == expected.profile_id
                && Some(binding.credential_generation_id.as_str())
                    == expected.credential_generation_id
                && binding.completion_status == "completed"
                && expected
                    .after
                    .is_none_or(|after| binding.completed_at > after)
                && binding.completed_at < expected.before
        })
}

fn validate_exact_d1_recovery_anchor(
    store: &StateStore,
    expected: &D1RecoveryAnchorExpectation<'_>,
) -> Result<chrono::DateTime<Utc>> {
    let matches = store
        .list_operational_proofs()?
        .into_iter()
        .filter(|proof| d1_recovery_anchor_matches(proof, expected))
        .collect::<Vec<_>>();
    if matches.len() != 1 {
        return Err(CliError::Input(
            "approved MLN import requires exactly one completed governed D1 full-export anchor bound to the exact operation, evidence, output, bookmark, catalog, input, target, profile, credential generation, and chronology"
                .to_owned(),
        ));
    }
    matches[0]
        .d1_full_export_governed_execution()
        .map(|binding| binding.completed_at)
        .ok_or_else(|| CliError::Input("governed D1 export lost its execution binding".to_owned()))
}

fn mln_0143_pre_import_authority_matches(
    proof: &OperationalProofV1,
    expected: &Mln0143PreImportExpectation<'_>,
) -> bool {
    proof.mln_0143_governed_execution().is_some_and(|binding| {
        let expected_profile_identity = hash_value(&json!({
            "profile_id":expected.profile_id,
            "credential_generation_id":expected.credential_generation_id,
        }))
        .ok();
        proof.capability_id == "mln-0143-data-invariants"
            && proof.outcome == OperationalProofOutcomeV1::Succeeded
            && proof.evidence.class == EvidenceClass::LiveRead
            && proof.catalog_hash == expected.catalog_hash
            && binding.catalog_hash == expected.catalog_hash
            && proof.input_hash == expected.request_hash
            && binding.request_hash == expected.request_hash
            && proof.account_id.as_deref() == Some(expected.account_id)
            && proof.profile_id.as_deref() == Some(expected.profile_id)
            && proof.credential_generation_id.as_deref() == expected.credential_generation_id
            && Some(binding.credential_generation_id.as_str()) == expected.credential_generation_id
            && Some(binding.profile_identity_hash.as_str()) == expected_profile_identity.as_deref()
            && binding.capability_id == "mln-0143-data-invariants"
            && binding.capability_version == expected.capability_version
            && binding.validator_contract_hash == expected.validator_contract_hash
            && binding.fixed_query_sha256 == expected.fixed_query_sha256
            && binding.target_scope_hash == expected.target_scope_hash
            && binding.phase == "pre_import"
            && binding.completion_status == "completed"
            && binding.cross_operation_lineage_hash.is_none()
            && binding.completed_at == proof.observed_at
            && binding.completed_at > expected.after
            && binding.completed_at < expected.before
    })
}

fn mln_0143_pre_import_matches(
    proof: &OperationalProofV1,
    expected: &Mln0143PreImportExpectation<'_>,
) -> bool {
    mln_0143_pre_import_authority_matches(proof, expected)
        && proof.evidence.content_hash == expected.evidence_hash
        && proof.mln_0143_governed_execution().is_some_and(|binding| {
            binding.operation_id == expected.operation_id
                && binding.manifest_evidence_hash == expected.evidence_hash
        })
}

fn validate_exact_mln_0143_pre_import(
    store: &StateStore,
    expected: &Mln0143PreImportExpectation<'_>,
) -> Result<()> {
    let proofs = store.list_operational_proofs()?;
    let current_authority = proofs
        .iter()
        .filter(|proof| mln_0143_pre_import_authority_matches(proof, expected))
        .count();
    let selected = proofs
        .iter()
        .filter(|proof| mln_0143_pre_import_matches(proof, expected))
        .count();
    if current_authority != 1 || selected != 1 {
        return Err(CliError::Input(
            "0143 requires exactly one selected completed pre_import proof bound to the current catalog, closed request, target, profile, credential generation, validator/query authority, and post-export-to-plan chronology; this ordered evidence does not prove absence of out-of-band provider writes"
                .to_owned(),
        ));
    }
    Ok(())
}

fn mln_0142_terminal_import_state(plan: &PlanV1) -> bool {
    plan.status == PlanStatus::Verified && plan.transaction_stage == TransactionStageV1::Closed
}

fn validate_mln_0142_post_import_schema_input(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<()> {
    let contract = capability
        .mln_0142_post_import_schema
        .as_ref()
        .ok_or_else(|| CliError::Input("MLN 0142 schema contract is missing".to_owned()))?;
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("MLN 0142 schema proof body is missing".to_owned()))?;
    let field = |name: &str| {
        body.get(name)
            .and_then(Value::as_str)
            .ok_or_else(|| CliError::Input(format!("MLN 0142 schema proof requires `{name}`")))
    };
    let operation_id = field("import_operation_id")?;
    let boundary_hash = field("import_boundary_evidence_hash")?;
    let source_sha256 = field("import_source_sha256")?;
    let plan_hash = field("import_plan_hash")?;
    let final_bookmark_hash = field("final_bookmark_hash")?;
    let import_plan = store.load_plan(operation_id)?;
    let import_input: CallInput = serde_json::from_value(import_plan.input.clone())?;
    let exact_plan = import_plan.capability.id == "d1-import-approved-mln-migration"
        && import_plan.status == PlanStatus::Running
        && import_plan.transaction_stage == TransactionStageV1::SecretSinkPersisted
        && import_plan.content_hash == plan_hash
        && import_plan.account_id == contract.account_id
        && import_input.selectors == input.selectors
        && import_input
            .body
            .as_ref()
            .and_then(|value| value.get("migration_id"))
            .and_then(Value::as_str)
            == Some("0142");
    let boundary = exact_durable_provider_complete_boundary(store, operation_id)?;
    let boundary_matches = boundary.evidence_hash == boundary_hash
        && boundary
            .checkpoint
            .pointer("/receipt/source_sha256")
            .and_then(Value::as_str)
            == Some(source_sha256)
        && boundary
            .checkpoint
            .pointer("/receipt/final_bookmark")
            .and_then(Value::as_str)
            .and_then(|bookmark| hash_value(&Value::String(bookmark.to_owned())).ok())
            .as_deref()
            == Some(final_bookmark_hash);
    if !exact_plan
        || !boundary_matches
        || source_sha256 != contract.migration_sha256
        || field("trigger_definition_sha256")? != contract.trigger_definition_sha256
    {
        return Err(CliError::Input(
            "MLN 0142 schema proof must bind the exact running import plan, provider boundary, source, target, final bookmark, and trigger definition"
                .to_owned(),
        ));
    }
    Ok(())
}

