fn validate_security_action_governance_input(
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<()> {
    let contract = capability.security_action.as_ref().ok_or_else(|| {
        CliError::Input("security action capability omitted its governance contract".to_owned())
    })?;
    if !capability.security_action_contract_supported() {
        return Err(CliError::Input(
            "security action capability drifted from its governed safety contract".to_owned(),
        ));
    }
    let mut governance_capability = capability.clone();
    governance_capability.request_schema = Some(contract.input_schema.clone());
    validate_request_contract(&governance_capability, input)?;
    Ok(())
}

fn security_action_string<'a>(body: &'a Map<String, Value>, field: &str) -> Result<&'a str> {
    body.get(field)
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| {
            CliError::Input(format!(
                "security action requires non-empty string field `{field}`"
            ))
        })
}

fn ip_is_protected(address: std::net::IpAddr) -> bool {
    match address {
        std::net::IpAddr::V4(address) => {
            let octets = address.octets();
            address.is_unspecified()
                || address.is_loopback()
                || address.is_private()
                || address.is_link_local()
                || address.is_multicast()
                || address.is_broadcast()
                || address.is_documentation()
                || (octets[0] == 100 && (64..=127).contains(&octets[1]))
                || (octets[0] == 192 && octets[1] == 0 && octets[2] == 0)
                || (octets[0] == 198 && matches!(octets[1], 18 | 19))
        }
        std::net::IpAddr::V6(address) => {
            let segments = address.segments();
            address.is_unspecified()
                || address.is_loopback()
                || address.is_multicast()
                || address.is_unique_local()
                || address.is_unicast_link_local()
                || segments[0] == 0x2001 && segments[1] == 0x0db8
        }
    }
}

fn normalize_public_ip(value: &str) -> Result<std::net::IpAddr> {
    let address = value.parse::<std::net::IpAddr>().map_err(|_| {
        CliError::Input("security action target is not a valid IP address".to_owned())
    })?;
    if ip_is_protected(address) {
        return Err(CliError::Input(
            "security action refuses private, local, documentation, multicast, or reserved IP targets"
                .to_owned(),
        ));
    }
    Ok(address)
}

fn normalize_bounded_ipv4_prefix(value: &str) -> Result<(String, u32, u8)> {
    let (address, prefix) = value
        .split_once('/')
        .ok_or_else(|| CliError::Input("IP range targets require CIDR notation".to_owned()))?;
    let address = address
        .parse::<std::net::Ipv4Addr>()
        .map_err(|_| CliError::Input("IP range target must be an IPv4 CIDR".to_owned()))?;
    if ip_is_protected(std::net::IpAddr::V4(address)) {
        return Err(CliError::Input(
            "security action refuses private, local, documentation, multicast, or reserved IP ranges"
                .to_owned(),
        ));
    }
    let prefix = prefix
        .parse::<u8>()
        .map_err(|_| CliError::Input("IP range prefix must be an integer".to_owned()))?;
    if !(24..=32).contains(&prefix) {
        return Err(CliError::Input(
            "security action limits IPv4 ranges to /24 or narrower; broader prefixes require a separately reviewed WAF rule"
                .to_owned(),
        ));
    }
    let mask = if prefix == 0 {
        0
    } else {
        u32::MAX << (32 - u32::from(prefix))
    };
    let network = u32::from(address) & mask;
    Ok((
        format!("{}/{prefix}", std::net::Ipv4Addr::from(network)),
        network,
        prefix,
    ))
}

type NormalizedSecurityTarget = (String, String, String, bool, Option<(u32, u8)>);
type OperatorSecurityTarget = (String, String, Option<(u32, u8)>);
type NormalizedListSecurityTarget = (Value, Value, String, bool, Option<OperatorSecurityTarget>);
type NormalizedWafSecurityTarget = (String, Value, String, bool, Option<OperatorSecurityTarget>);

fn normalize_security_target(target: &Map<String, Value>) -> Result<NormalizedSecurityTarget> {
    let target_type = security_action_string(target, "type")?;
    let value = security_action_string(target, "value")?;
    match target_type {
        "ip" => {
            let address = normalize_public_ip(value)?;
            let wire_type = if address.is_ipv4() { "ip" } else { "ip6" };
            Ok((
                wire_type.to_owned(),
                address.to_string(),
                "one exact public IP address".to_owned(),
                false,
                None,
            ))
        }
        "ip_range" => {
            let (value, network, prefix) = normalize_bounded_ipv4_prefix(value)?;
            let addresses = 1_u64 << (32 - u32::from(prefix));
            Ok((
                "ip_range".to_owned(),
                value,
                format!("one IPv4 /{prefix} prefix ({addresses} addresses)"),
                true,
                Some((network, prefix)),
            ))
        }
        "asn" => {
            let numeric = value
                .trim()
                .trim_start_matches("AS")
                .trim_start_matches("as")
                .parse::<u32>()
                .ok()
                .filter(|value| *value > 0)
                .ok_or_else(|| {
                    CliError::Input("ASN target must be a positive AS number".to_owned())
                })?;
            Ok((
                "asn".to_owned(),
                format!("AS{numeric}"),
                "all traffic attributed by Cloudflare to one ASN".to_owned(),
                true,
                None,
            ))
        }
        "country" => {
            let country = value.to_ascii_uppercase();
            if country.len() != 2 || !country.bytes().all(|byte| byte.is_ascii_alphabetic()) {
                return Err(CliError::Input(
                    "country target must be a two-letter ISO country code".to_owned(),
                ));
            }
            Ok((
                "country".to_owned(),
                country,
                "all traffic classified by Cloudflare to one country".to_owned(),
                true,
                None,
            ))
        }
        _ => Err(CliError::Input(
            "security action target type must be `ip`, `ip_range`, `asn`, or `country`".to_owned(),
        )),
    }
}

fn validate_operator_not_targeted(
    operator_ip: &str,
    target_type: &str,
    target_value: &str,
    target_prefix: Option<(u32, u8)>,
) -> Result<()> {
    let operator = normalize_public_ip(operator_ip)?;
    let self_targeted = match (target_type, operator) {
        ("ip" | "ip6", address) => address.to_string() == target_value,
        ("ip_range", std::net::IpAddr::V4(address)) => {
            target_prefix.is_some_and(|(network, prefix)| {
                let mask = u32::MAX << (32 - u32::from(prefix));
                u32::from(address) & mask == network
            })
        }
        _ => false,
    };
    if self_targeted {
        return Err(CliError::Input(
            "security action would directly target the declared operator IP; the plan was not created"
                .to_owned(),
        ));
    }
    Ok(())
}

fn security_expiry(
    supplied: Option<&str>,
    default_ttl_seconds: u64,
    max_ttl_seconds: u64,
) -> Result<(chrono::DateTime<Utc>, u64)> {
    let now = Utc::now();
    let expiry = supplied.map_or_else(
        || {
            i64::try_from(default_ttl_seconds)
                .ok()
                .map(|seconds| now + ChronoDuration::seconds(seconds))
                .ok_or_else(|| CliError::Input("security action TTL is invalid".to_owned()))
        },
        |value| {
            chrono::DateTime::parse_from_rfc3339(value)
                .map(|parsed| parsed.with_timezone(&Utc))
                .map_err(|_| {
                    CliError::Input("security action `expires_at` must be RFC3339".to_owned())
                })
        },
    )?;
    let ttl = (expiry - now).num_seconds();
    if ttl < 300 {
        return Err(CliError::Input(
            "security action expiry must be at least five minutes in the future".to_owned(),
        ));
    }
    let ttl = u64::try_from(ttl)
        .map_err(|_| CliError::Input("security action expiry must be in the future".to_owned()))?;
    if ttl > max_ttl_seconds {
        return Err(CliError::Input(format!(
            "security action expiry exceeds the governed maximum of {max_ttl_seconds} seconds"
        )));
    }
    Ok((expiry, ttl))
}

#[expect(
    clippy::too_many_lines,
    reason = "the security-action normalizer keeps all scope, expiry, self-block, and audit invariants visible in one fail-closed review boundary"
)]
fn prepare_security_action_create(
    capability: &CapabilityV1,
    input: &mut CallInput,
) -> Result<Value> {
    let contract = capability
        .security_action
        .as_ref()
        .ok_or_else(|| CliError::Input("security action contract is missing".to_owned()))?;
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .cloned()
        .ok_or_else(|| CliError::Input("security action body must be an object".to_owned()))?;
    let actor = security_action_string(&body, "actor")?.to_owned();
    let evidence_ref = security_action_string(&body, "evidence_ref")?.to_owned();
    let reason = security_action_string(&body, "reason")?.trim().to_owned();
    if reason.chars().any(char::is_control) {
        return Err(CliError::Input(
            "security action reason cannot contain control characters".to_owned(),
        ));
    }
    let action = body
        .get("action")
        .and_then(Value::as_str)
        .or(contract.default_action.as_deref())
        .ok_or_else(|| CliError::Input("security action has no default action".to_owned()))?;
    if !contract
        .allowed_actions
        .iter()
        .any(|allowed| allowed == action)
    {
        return Err(CliError::Input(format!(
            "security action `{action}` is outside the governed allowlist"
        )));
    }
    let target = body
        .get("target")
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("security action target must be an object".to_owned()))?;
    let (target_type, target_value, blast_radius, broad, target_prefix) =
        normalize_security_target(target)?;
    let (expires_at, ttl_seconds) = security_expiry(
        body.get("expires_at").and_then(Value::as_str),
        contract.default_ttl_seconds,
        contract.max_ttl_seconds,
    )?;
    if broad {
        if body.get("confirm_broad_scope").and_then(Value::as_bool) != Some(true) {
            return Err(CliError::Input(
                "IP range, ASN, and country targets require `confirm_broad_scope: true` after reviewing the blast radius"
                    .to_owned(),
            ));
        }
        if action != "managed_challenge" || ttl_seconds > 3_600 {
            return Err(CliError::Input(
                "broad targets are limited to Managed Challenge for at most one hour; use a narrower target or a separately reviewed WAF design"
                    .to_owned(),
            ));
        }
    }
    if action == "block" {
        if body.get("confirm_block").and_then(Value::as_bool) != Some(true) {
            return Err(CliError::Input(
                "a block requires `confirm_block: true`; Managed Challenge is the default when confidence is incomplete"
                    .to_owned(),
            ));
        }
        let operator_ip = security_action_string(&body, "operator_ip")?;
        validate_operator_not_targeted(operator_ip, &target_type, &target_value, target_prefix)?;
        if ttl_seconds > 86_400 {
            return Err(CliError::Input(
                "blocks are limited to 24 hours; permanent blocks require a different explicitly escalated capability"
                    .to_owned(),
            ));
        }
    }
    let expires_at = expires_at.to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
    let notes = serde_json::to_string(&json!({
        "cfctl_security_v1":{
            "actor":actor,
            "evidence_ref":evidence_ref,
            "expires_at":expires_at,
            "reason":reason,
        }
    }))?;
    if notes.len() > 500 {
        return Err(CliError::Input(
            "security action audit note exceeds the Cloudflare-safe 500-byte bound".to_owned(),
        ));
    }
    input.body = Some(json!({
        "configuration":{"target":target_type,"value":target_value},
        "mode":action,
        "notes":notes,
    }));
    Ok(json!({
        "schema_version":1,
        "kind":"create_expiring",
        "action":action,
        "actor":actor,
        "evidence_ref":evidence_ref,
        "expires_at":expires_at,
        "reason":reason,
        "target":{"type":target_type,"value":target_value},
        "blast_radius":blast_radius,
        "ttl_seconds":ttl_seconds,
        "managed_challenge_default":true,
        "permanent_action":false,
        "anonymous_identity_inferred":false,
        "self_block_checked":action == "block",
        "wire_note_hash":hash_value(&Value::String(notes))?,
    }))
}

fn normalize_list_security_target(
    target: &Map<String, Value>,
) -> Result<NormalizedListSecurityTarget> {
    let target_type = security_action_string(target, "type")?;
    let raw = security_action_string(target, "value")?;
    match target_type {
        "ip" => {
            let address = normalize_public_ip(raw)?;
            let value = address.to_string();
            Ok((
                json!({"ip":value}),
                json!({"type":"ip","value":value}),
                "one exact public IP address".to_owned(),
                false,
                Some((
                    if address.is_ipv4() { "ip" } else { "ip6" }.to_owned(),
                    value,
                    None,
                )),
            ))
        }
        "ip_range" => {
            let (value, network, prefix) = normalize_bounded_ipv4_prefix(raw)?;
            let addresses = 1_u64 << (32 - u32::from(prefix));
            Ok((
                json!({"ip":value}),
                json!({"type":"ip_range","value":value}),
                format!("one IPv4 /{prefix} prefix ({addresses} addresses)"),
                true,
                Some(("ip_range".to_owned(), value, Some((network, prefix)))),
            ))
        }
        "asn" => {
            let numeric = raw
                .trim()
                .trim_start_matches("AS")
                .trim_start_matches("as")
                .parse::<u32>()
                .ok()
                .filter(|value| *value > 0)
                .ok_or_else(|| {
                    CliError::Input("ASN target must be a positive AS number".to_owned())
                })?;
            Ok((
                json!({"asn":numeric}),
                json!({"type":"asn","value":format!("AS{numeric}")}),
                "all traffic attributed by Cloudflare to one ASN".to_owned(),
                true,
                None,
            ))
        }
        "hostname" => {
            let hostname = match url::Host::parse(raw).map_err(|_| {
                CliError::Input("hostname target must be one valid exact hostname".to_owned())
            })? {
                url::Host::Domain(hostname) => hostname.to_ascii_lowercase(),
                _ => {
                    return Err(CliError::Input(
                        "hostname targets cannot be IP literals; use target type `ip`".to_owned(),
                    ));
                }
            };
            if hostname.len() > 253
                || hostname.starts_with('.')
                || hostname.ends_with('.')
                || hostname.contains('*')
            {
                return Err(CliError::Input(
                    "hostname target must be one normalized exact DNS hostname".to_owned(),
                ));
            }
            Ok((
                json!({"hostname":{"url_hostname":hostname}}),
                json!({"type":"hostname","value":hostname}),
                "all requests matching one exact hostname in every reviewed list consumer"
                    .to_owned(),
                false,
                None,
            ))
        }
        _ => Err(CliError::Input(
            "List security target type must be `ip`, `ip_range`, `asn`, or `hostname`".to_owned(),
        )),
    }
}

#[expect(
    clippy::too_many_lines,
    reason = "list-backed enforcement requires one auditable boundary for consumer scope, target normalization, expiry, self-block, and receipt construction"
)]
fn prepare_list_security_action_create(
    capability: &CapabilityV1,
    input: &mut CallInput,
) -> Result<Value> {
    let contract = capability
        .security_action
        .as_ref()
        .ok_or_else(|| CliError::Input("List security action contract is missing".to_owned()))?;
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .cloned()
        .ok_or_else(|| CliError::Input("List security action body must be an object".to_owned()))?;
    let actor = security_action_string(&body, "actor")?.to_owned();
    let evidence_ref = security_action_string(&body, "evidence_ref")?.to_owned();
    let reason = security_action_string(&body, "reason")?.trim().to_owned();
    if reason.chars().any(char::is_control) {
        return Err(CliError::Input(
            "List security action reason cannot contain control characters".to_owned(),
        ));
    }
    if body.get("confirm_consumer_scope").and_then(Value::as_bool) != Some(true) {
        return Err(CliError::Input(
            "List membership can affect every referencing rule; review those consumers and set `confirm_consumer_scope: true`"
                .to_owned(),
        ));
    }
    let action = body
        .get("action")
        .and_then(Value::as_str)
        .or(contract.default_action.as_deref())
        .ok_or_else(|| CliError::Input("List security action has no default action".to_owned()))?;
    if !contract
        .allowed_actions
        .iter()
        .any(|allowed| allowed == action)
    {
        return Err(CliError::Input(format!(
            "List consumer action `{action}` is outside the governed allowlist"
        )));
    }
    let target = body
        .get("target")
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("List security target must be an object".to_owned()))?;
    let (wire_target, normalized_target, blast_radius, broad, operator_target) =
        normalize_list_security_target(target)?;
    let (expires_at, ttl_seconds) = security_expiry(
        body.get("expires_at").and_then(Value::as_str),
        contract.default_ttl_seconds,
        contract.max_ttl_seconds,
    )?;
    if broad {
        if body.get("confirm_broad_scope").and_then(Value::as_bool) != Some(true) {
            return Err(CliError::Input(
                "prefix and ASN List targets require `confirm_broad_scope: true` after reviewing every consumer"
                    .to_owned(),
            ));
        }
        if action != "managed_challenge" || ttl_seconds > 3_600 {
            return Err(CliError::Input(
                "broad List targets are limited to an expected Managed Challenge action for at most one hour"
                    .to_owned(),
            ));
        }
    }
    if action == "block" {
        if body.get("confirm_block").and_then(Value::as_bool) != Some(true) {
            return Err(CliError::Input(
                "an expected block consumer requires `confirm_block: true`; Managed Challenge is the default"
                    .to_owned(),
            ));
        }
        let Some((wire_type, target_value, prefix)) = operator_target.as_ref() else {
            return Err(CliError::Input(
                "governed List block use is limited to one exact public IP; prefixes, ASNs, and hostnames use Managed Challenge"
                    .to_owned(),
            ));
        };
        if wire_type == "ip_range" {
            return Err(CliError::Input(
                "governed List block use is limited to one exact public IP; prefixes use Managed Challenge"
                    .to_owned(),
            ));
        }
        let operator_ip = security_action_string(&body, "operator_ip")?;
        validate_operator_not_targeted(operator_ip, wire_type, target_value, *prefix)?;
        if ttl_seconds > 86_400 {
            return Err(CliError::Input(
                "List-backed blocks are limited to 24 hours; permanent blocks require separate escalation"
                    .to_owned(),
            ));
        }
    }
    let expires_at = expires_at.to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
    let target_hash = hash_value(&normalized_target)?;
    let audit = json!({
        "cfctl_list_security_v1":{
            "actor":actor,
            "evidence_ref":evidence_ref,
            "expected_consumer_action":action,
            "expires_at":expires_at,
            "reason":reason,
            "target_hash":target_hash,
        }
    });
    let comment = serde_json::to_string(&audit)?;
    if comment.len() > 500 {
        return Err(CliError::Input(
            "List security audit comment exceeds the Cloudflare-safe 500-byte bound".to_owned(),
        ));
    }
    let mut wire = wire_target.as_object().cloned().ok_or_else(|| {
        CliError::Input("normalized List target did not produce one wire item".to_owned())
    })?;
    wire.insert("comment".to_owned(), Value::String(comment.clone()));
    input.body = Some(Value::Array(vec![Value::Object(wire)]));
    Ok(json!({
        "schema_version":1,
        "kind":"add_expiring_list_member",
        "actor":actor,
        "evidence_ref":evidence_ref,
        "expires_at":expires_at,
        "reason":reason,
        "target":normalized_target,
        "target_hash":target_hash,
        "expected_consumer_action":action,
        "blast_radius":blast_radius,
        "ttl_seconds":ttl_seconds,
        "consumer_scope_confirmed":true,
        "managed_challenge_default":true,
        "permanent_action":false,
        "anonymous_identity_inferred":false,
        "self_block_checked":action == "block",
        "wire_comment_hash":hash_value(&Value::String(comment))?,
    }))
}

fn prepare_list_security_action_remove(input: &mut CallInput) -> Result<Value> {
    let member_id = input
        .body
        .as_ref()
        .and_then(|body| body.get("member_id"))
        .and_then(Value::as_str)
        .filter(|identity| identity.len() == 32)
        .ok_or_else(|| {
            CliError::Input(
                "expired List member removal requires one 32-character member_id".to_owned(),
            )
        })?
        .to_owned();
    let mut receipt = prepare_security_action_remove(input, "remove_expired_list_member")?;
    input.body = Some(json!({"items":[{"id":member_id}]}));
    let receipt_object = receipt.as_object_mut().ok_or_else(|| {
        CliError::Input("security action removal did not produce an object receipt".to_owned())
    })?;
    receipt_object.insert("member_id".to_owned(), Value::String(member_id));
    Ok(receipt)
}

fn rule_string_literal(value: &str) -> Result<String> {
    serde_json::to_string(value).map_err(CliError::from)
}

#[expect(
    clippy::too_many_lines,
    reason = "the closed WAF target matrix keeps every accepted target form and its blast-radius semantics together for auditability"
)]
fn normalize_waf_security_target(
    target: &Map<String, Value>,
) -> Result<NormalizedWafSecurityTarget> {
    let target_type = security_action_string(target, "type")?;
    let raw = security_action_string(target, "value")?;
    match target_type {
        "ip" => {
            let address = normalize_public_ip(raw)?;
            let value = address.to_string();
            Ok((
                format!("ip.src eq {value}"),
                json!({"type":"ip","value":value}),
                "one exact public IP address".to_owned(),
                false,
                Some((
                    if address.is_ipv4() { "ip" } else { "ip6" }.to_owned(),
                    value,
                    None,
                )),
            ))
        }
        "ip_range" => {
            let (value, network, prefix) = normalize_bounded_ipv4_prefix(raw)?;
            let addresses = 1_u64 << (32 - u32::from(prefix));
            Ok((
                format!("ip.src in {{{value}}}"),
                json!({"type":"ip_range","value":value}),
                format!("one IPv4 /{prefix} prefix ({addresses} addresses)"),
                true,
                Some((
                    "ip_range".to_owned(),
                    value,
                    Some((network, prefix)),
                )),
            ))
        }
        "asn" => {
            let numeric = raw
                .trim()
                .trim_start_matches("AS")
                .trim_start_matches("as")
                .parse::<u32>()
                .ok()
                .filter(|value| *value > 0)
                .ok_or_else(|| CliError::Input("ASN target must be a positive AS number".to_owned()))?;
            Ok((
                format!("ip.src.asnum eq {numeric}"),
                json!({"type":"asn","value":format!("AS{numeric}")}),
                "all traffic attributed by Cloudflare to one ASN".to_owned(),
                true,
                None,
            ))
        }
        "country" => {
            let country = raw.to_ascii_uppercase();
            if country.len() != 2 || !country.bytes().all(|byte| byte.is_ascii_alphabetic()) {
                return Err(CliError::Input(
                    "country target must be a two-letter ISO country code".to_owned(),
                ));
            }
            Ok((
                format!("ip.src.country eq {}", rule_string_literal(&country)?),
                json!({"type":"country","value":country}),
                "all traffic classified by Cloudflare to one country".to_owned(),
                true,
                None,
            ))
        }
        "hostname" => {
            let hostname = match url::Host::parse(raw).map_err(|_| {
                CliError::Input("hostname target must be one valid exact hostname".to_owned())
            })? {
                url::Host::Domain(hostname) => hostname.to_ascii_lowercase(),
                _ => {
                    return Err(CliError::Input(
                        "hostname targets cannot be IP literals; use target type `ip`".to_owned(),
                    ));
                }
            };
            if hostname.len() > 253 || hostname.starts_with('.') || hostname.ends_with('.') {
                return Err(CliError::Input(
                    "hostname target must be one normalized DNS hostname".to_owned(),
                ));
            }
            Ok((
                format!("http.host eq {}", rule_string_literal(&hostname)?),
                json!({"type":"hostname","value":hostname}),
                "all requests to one exact hostname in the selected zone".to_owned(),
                false,
                None,
            ))
        }
        "path" => {
            if !raw.starts_with('/')
                || raw.len() > 2_048
                || raw.chars().any(char::is_control)
                || raw.contains('?')
                || raw.contains('#')
            {
                return Err(CliError::Input(
                    "path target must be one exact URI path beginning with `/`, without query, fragment, or control characters"
                        .to_owned(),
                ));
            }
            Ok((
                format!("http.request.uri.path eq {}", rule_string_literal(raw)?),
                json!({"type":"path","value":raw}),
                "all requests to one exact path across the selected zone".to_owned(),
                false,
                None,
            ))
        }
        "ja4" => {
            let fingerprint = raw.to_ascii_lowercase();
            if !(20..=64).contains(&fingerprint.len())
                || !fingerprint
                    .bytes()
                    .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
            {
                return Err(CliError::Input(
                    "JA4 target must be a 20-64 character lowercase alphanumeric/underscore fingerprint"
                        .to_owned(),
                ));
            }
            Ok((
                format!(
                    "cf.bot_management.ja4 eq {}",
                    rule_string_literal(&fingerprint)?
                ),
                json!({"type":"ja4","value":fingerprint}),
                "all requests with one exact JA4 fingerprint; Cloudflare requires Enterprise Bot Management"
                    .to_owned(),
                false,
                None,
            ))
        }
        _ => Err(CliError::Input(
            "WAF security target type must be `ip`, `ip_range`, `asn`, `country`, `hostname`, `path`, or `ja4`"
                .to_owned(),
        )),
    }
}

#[expect(
    clippy::too_many_lines,
    reason = "WAF enforcement planning keeps evidence, target, action, scope, expiry, self-block, and escalation checks in one fail-closed review boundary"
)]
fn prepare_waf_security_action_create(
    capability: &CapabilityV1,
    input: &mut CallInput,
) -> Result<Value> {
    let contract = capability
        .security_action
        .as_ref()
        .ok_or_else(|| CliError::Input("WAF security action contract is missing".to_owned()))?;
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .cloned()
        .ok_or_else(|| CliError::Input("WAF security action body must be an object".to_owned()))?;
    let actor = security_action_string(&body, "actor")?.to_owned();
    let evidence_ref = security_action_string(&body, "evidence_ref")?.to_owned();
    let reason = security_action_string(&body, "reason")?.trim().to_owned();
    if reason.chars().any(char::is_control) {
        return Err(CliError::Input(
            "security action reason cannot contain control characters".to_owned(),
        ));
    }
    let action = body
        .get("action")
        .and_then(Value::as_str)
        .or(contract.default_action.as_deref())
        .ok_or_else(|| CliError::Input("WAF security action has no default action".to_owned()))?;
    if !contract
        .allowed_actions
        .iter()
        .any(|allowed| allowed == action)
    {
        return Err(CliError::Input(format!(
            "WAF security action `{action}` is outside the governed allowlist"
        )));
    }
    let target = body
        .get("target")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            CliError::Input("WAF security action target must be an object".to_owned())
        })?;
    let (expression, normalized_target, blast_radius, broad, operator_target) =
        normalize_waf_security_target(target)?;
    let (expires_at, ttl_seconds) = security_expiry(
        body.get("expires_at").and_then(Value::as_str),
        contract.default_ttl_seconds,
        contract.max_ttl_seconds,
    )?;
    if broad {
        if body.get("confirm_broad_scope").and_then(Value::as_bool) != Some(true) {
            return Err(CliError::Input(
                "IP range, ASN, and country WAF targets require `confirm_broad_scope: true` after reviewing the blast radius"
                    .to_owned(),
            ));
        }
        if action != "managed_challenge" || ttl_seconds > 3_600 {
            return Err(CliError::Input(
                "broad WAF targets are limited to Managed Challenge for at most one hour"
                    .to_owned(),
            ));
        }
    }
    if action == "block" {
        if body.get("confirm_block").and_then(Value::as_bool) != Some(true) {
            return Err(CliError::Input(
                "a WAF block requires `confirm_block: true`; Managed Challenge is the default when confidence is incomplete"
                    .to_owned(),
            ));
        }
        let Some((wire_type, target_value, prefix)) = operator_target.as_ref() else {
            return Err(CliError::Input(
                "governed WAF block is limited to one exact public IP; hostname, path, fingerprint, ASN, country, and prefix blocks require a separately reviewed policy design"
                    .to_owned(),
            ));
        };
        if wire_type == "ip_range" {
            return Err(CliError::Input(
                "governed WAF block is limited to one exact public IP; prefixes use Managed Challenge"
                    .to_owned(),
            ));
        }
        let operator_ip = security_action_string(&body, "operator_ip")?;
        validate_operator_not_targeted(operator_ip, wire_type, target_value, *prefix)?;
        if ttl_seconds > 86_400 {
            return Err(CliError::Input(
                "WAF blocks are limited to 24 hours; permanent blocks require separate escalation"
                    .to_owned(),
            ));
        }
    }
    if action == "skip"
        && (body.get("confirm_skip").and_then(Value::as_bool) != Some(true)
            || body.get("confirm_broad_scope").and_then(Value::as_bool) != Some(true)
            || ttl_seconds > 3_600)
    {
        return Err(CliError::Input(
                "skip requires `confirm_skip: true`, `confirm_broad_scope: true`, and an expiry within one hour; cfctl only skips the managed WAF phase"
                    .to_owned(),
            ));
    }
    if normalized_target.get("type").and_then(Value::as_str) == Some("ja4")
        && body
            .get("confirm_enterprise_bot_management")
            .and_then(Value::as_bool)
            != Some(true)
    {
        return Err(CliError::Input(
            "JA4 targeting requires `confirm_enterprise_bot_management: true`; Cloudflare documents this field as Enterprise with Bot Management"
                .to_owned(),
        ));
    }
    let expires_at = expires_at.to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
    let audit = json!({
        "cfctl_security_v1":{
            "actor":actor,
            "evidence_ref":evidence_ref,
            "expires_at":expires_at,
            "reason":reason,
            "target":normalized_target,
        }
    });
    let description = serde_json::to_string(&audit)?;
    if description.len() > 500 {
        return Err(CliError::Input(
            "WAF security action audit description exceeds the 500-byte governed bound".to_owned(),
        ));
    }
    let correlation_hash = hash_value(&json!({
        "action":action,
        "actor":actor,
        "evidence_ref":evidence_ref,
        "expires_at":expires_at,
        "reason":reason,
        "target":normalized_target,
    }))?;
    let ref_suffix = correlation_hash
        .strip_prefix("sha256:")
        .and_then(|hash| hash.get(..24))
        .ok_or_else(|| {
            CliError::Input("WAF security action correlation hash is invalid".to_owned())
        })?;
    let reference = format!("cfctl_security_{ref_suffix}");
    let mut wire = serde_json::Map::from_iter([
        ("action".to_owned(), Value::String(action.to_owned())),
        ("description".to_owned(), Value::String(description.clone())),
        ("enabled".to_owned(), Value::Bool(true)),
        ("expression".to_owned(), Value::String(expression.clone())),
        ("ref".to_owned(), Value::String(reference.clone())),
    ]);
    if action == "skip" {
        wire.insert(
            "action_parameters".to_owned(),
            json!({"phases":["http_request_firewall_managed"]}),
        );
    }
    input.body = Some(Value::Object(wire));
    Ok(json!({
        "schema_version":1,
        "kind":"create_expiring_waf",
        "action":action,
        "actor":actor,
        "evidence_ref":evidence_ref,
        "expires_at":expires_at,
        "reason":reason,
        "target":normalized_target,
        "expression":expression,
        "correlation_ref":reference,
        "blast_radius":blast_radius,
        "ttl_seconds":ttl_seconds,
        "managed_challenge_default":true,
        "permanent_action":false,
        "anonymous_identity_inferred":false,
        "self_block_checked":action == "block",
        "skip_scope":(action == "skip").then_some("http_request_firewall_managed"),
        "wire_description_hash":hash_value(&Value::String(description))?,
    }))
}

fn prepare_security_action_remove(input: &mut CallInput, kind: &str) -> Result<Value> {
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .cloned()
        .ok_or_else(|| {
            CliError::Input("expired-action removal body must be an object".to_owned())
        })?;
    let actor = security_action_string(&body, "actor")?.to_owned();
    let evidence_ref = security_action_string(&body, "evidence_ref")?.to_owned();
    let expires_at = security_action_string(&body, "expires_at")?.to_owned();
    let reason = security_action_string(&body, "reason")?.trim().to_owned();
    let source_operation_id = security_action_string(&body, "source_operation_id")?.to_owned();
    let expiry = chrono::DateTime::parse_from_rfc3339(&expires_at)
        .map_err(|_| CliError::Input("removal `expires_at` must be RFC3339".to_owned()))?
        .with_timezone(&Utc);
    if expiry > Utc::now() {
        return Err(CliError::Input(
            "the security action has not reached its removal deadline; use the source operation's exact rollback only when early removal is intentionally required"
                .to_owned(),
        ));
    }
    input.body = None;
    Ok(json!({
        "schema_version":1,
        "kind":kind,
        "actor":actor,
        "evidence_ref":evidence_ref,
        "expires_at":expiry.to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
        "reason":reason,
        "source_operation_id":source_operation_id,
        "anonymous_identity_inferred":false,
    }))
}

fn prepare_security_action_input(
    capability: &CapabilityV1,
    input: &mut CallInput,
) -> Result<Option<Value>> {
    let Some(contract) = capability.security_action.as_ref() else {
        return Ok(None);
    };
    validate_security_action_governance_input(capability, input)?;
    let receipt = match (capability.id.as_str(), contract.kind) {
        (SECURITY_IP_RULE_CREATE_ID, SecurityActionKindV1::CreateExpiring) => {
            prepare_security_action_create(capability, input)?
        }
        (SECURITY_IP_RULE_REMOVE_ID, SecurityActionKindV1::RemoveExpired) => {
            prepare_security_action_remove(input, "remove_expired")?
        }
        (SECURITY_WAF_RULE_CREATE_ID, SecurityActionKindV1::CreateExpiring) => {
            prepare_waf_security_action_create(capability, input)?
        }
        (SECURITY_WAF_RULE_REMOVE_ID, SecurityActionKindV1::RemoveExpired) => {
            prepare_security_action_remove(input, "remove_expired_waf")?
        }
        (SECURITY_LIST_MEMBER_CREATE_ID, SecurityActionKindV1::AddExpiringListMember) => {
            prepare_list_security_action_create(capability, input)?
        }
        (SECURITY_LIST_MEMBER_REMOVE_ID, SecurityActionKindV1::RemoveExpiredListMember) => {
            prepare_list_security_action_remove(input)?
        }
        _ => {
            return Err(CliError::Input(
                "security action renderer is not implemented for this exact capability identity"
                    .to_owned(),
            ));
        }
    };
    Ok(Some(receipt))
}

fn security_action_adapter_target(adapter_targets: &Value) -> Option<&Value> {
    adapter_targets
        .get("security_action")
        .filter(|value| value.is_object())
}

fn should_bind_security_action_state(capability: &CapabilityV1, adapter_targets: &Value) -> bool {
    capability.security_action_contract_supported()
        && matches!(
            capability.id.as_str(),
            SECURITY_IP_RULE_CREATE_ID
                | SECURITY_IP_RULE_REMOVE_ID
                | SECURITY_WAF_RULE_CREATE_ID
                | SECURITY_WAF_RULE_REMOVE_ID
                | SECURITY_LIST_MEMBER_CREATE_ID
                | SECURITY_LIST_MEMBER_REMOVE_ID
        )
        && security_action_adapter_target(adapter_targets).is_some()
}

fn security_collection_complete(response: &CloudflareResponseV1) -> bool {
    response.result_info.as_ref().is_some_and(|result_info| {
        let page = result_info.get("page").and_then(Value::as_u64);
        let total_pages = result_info.get("total_pages").and_then(Value::as_u64);
        (page.is_some() && page == total_pages)
            || result_info
                .get("cfctl_cursor_complete")
                .and_then(Value::as_bool)
                == Some(true)
    })
}

fn security_rule_planned_body(plan: &PlanV1) -> Result<Value> {
    let input: CallInput = serde_json::from_value(plan.input.clone())?;
    input.body.ok_or_else(|| {
        CliError::Input(
            "source security action plan omitted its exact Cloudflare rule body".to_owned(),
        )
    })
}

fn validate_security_action_removal_source(
    store: &StateStore,
    metadata: &Value,
    zone_id: &str,
    rule_id: &str,
) -> Result<Value> {
    let operation_id = metadata
        .get("source_operation_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CliError::Input("expired-action removal omitted its source operation ID".to_owned())
        })?;
    let plan = load_validated_plan(store, operation_id)?;
    if plan.status != PlanStatus::Verified
        || plan.capability.id != SECURITY_IP_RULE_CREATE_ID
        || plan
            .targets
            .pointer("/selectors/zone_id")
            .and_then(Value::as_str)
            != Some(zone_id)
        || plan
            .targets
            .pointer("/adapter/security_action/evidence_ref")
            .and_then(Value::as_str)
            != metadata.get("evidence_ref").and_then(Value::as_str)
        || plan
            .targets
            .pointer("/adapter/security_action/expires_at")
            .and_then(Value::as_str)
            != metadata.get("expires_at").and_then(Value::as_str)
    {
        return Err(CliError::Input(
            "expired-action removal is not bound to a verified source security-action plan with the same zone, evidence, and deadline"
                .to_owned(),
        ));
    }
    let boundary_rule_id = plan
        .transaction_artifact(TransactionStageV1::BoundaryResponsePersisted)
        .and_then(|artifact| artifact.get("resource_id"))
        .and_then(Value::as_str);
    if boundary_rule_id != Some(rule_id) {
        return Err(CliError::Input(
            "expired-action rule ID does not match the hash-bound identity returned by its source plan"
                .to_owned(),
        ));
    }
    security_rule_planned_body(&plan)
}

#[expect(
    clippy::too_many_lines,
    reason = "IP access-rule verification deliberately captures current state, audit lineage, expiry, conflicts, and removal guidance in one receipt"
)]
fn security_action_state_receipt(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
    adapter_targets: &Value,
    account_id: &str,
    response: &CloudflareResponseV1,
) -> Result<Value> {
    if !response.success || !(200..300).contains(&response.status) {
        return Err(CliError::Input(format!(
            "Cloudflare rejected the security-action current-state read with HTTP {}; the mutation boundary was not crossed",
            response.status
        )));
    }
    if !security_collection_complete(response) {
        return Err(CliError::Input(
            "security-action current-state read did not prove complete pagination; the mutation boundary was not crossed"
                .to_owned(),
        ));
    }
    let rules = response.result.as_array().ok_or_else(|| {
        CliError::Input(
            "security-action current-state read did not return a rule collection".to_owned(),
        )
    })?;
    let metadata = security_action_adapter_target(adapter_targets).ok_or_else(|| {
        CliError::Input("security-action governance receipt is missing".to_owned())
    })?;
    let zone_id = input
        .selectors
        .get("zone_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| CliError::Input("security action requires `zone_id`".to_owned()))?;
    let kind = metadata
        .get("kind")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("security-action governance receipt omitted its kind".to_owned())
        })?;
    let state = match kind {
        "create_expiring" => {
            let target = metadata.get("target").ok_or_else(|| {
                CliError::Input("security-action governance receipt omitted its target".to_owned())
            })?;
            let conflicts = rules
                .iter()
                .filter(|rule| rule.get("configuration") == Some(target))
                .map(|rule| {
                    json!({
                        "id":rule.get("id").cloned().unwrap_or(Value::Null),
                        "mode":rule.get("mode").cloned().unwrap_or(Value::Null),
                        "notes_hash":rule.get("notes").map(hash_value).transpose().unwrap_or(None),
                    })
                })
                .collect::<Vec<_>>();
            if !conflicts.is_empty() {
                return Err(CliError::Input(format!(
                    "security action target already has {} matching rule(s); inspect and resolve the duplicate or conflict before creating another action",
                    conflicts.len()
                )));
            }
            json!({
                "matching_rule_count":0,
                "target":target,
                "action":metadata.get("action").cloned().unwrap_or(Value::Null),
            })
        }
        "remove_expired" => {
            let rule_id = input
                .selectors
                .get("rule_id")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    CliError::Input("expired-action removal requires `rule_id`".to_owned())
                })?;
            let planned_rule =
                validate_security_action_removal_source(store, metadata, zone_id, rule_id)?;
            let matching = rules
                .iter()
                .filter(|rule| rule.get("id").and_then(Value::as_str) == Some(rule_id))
                .collect::<Vec<_>>();
            if matching.len() != 1 {
                return Err(CliError::Input(format!(
                    "expired-action removal requires exactly one live rule with the source identity; found {}",
                    matching.len()
                )));
            }
            let live_projection = json!({
                "configuration":matching[0].get("configuration").cloned().unwrap_or(Value::Null),
                "mode":matching[0].get("mode").cloned().unwrap_or(Value::Null),
                "notes":matching[0].get("notes").cloned().unwrap_or(Value::Null),
            });
            if live_projection != planned_rule {
                return Err(CliError::Input(
                    "expired security rule drifted from the exact body verified by its source operation; inspect it before removal"
                        .to_owned(),
                ));
            }
            json!({
                "matching_rule_count":1,
                "rule_id":rule_id,
                "live_rule_hash":hash_value(&live_projection)?,
                "source_operation_id":metadata.get("source_operation_id").cloned().unwrap_or(Value::Null),
            })
        }
        _ => {
            return Err(CliError::Input(
                "security-action governance receipt has an unsupported kind".to_owned(),
            ));
        }
    };
    Ok(json!({
        "schema_version":1,
        "source_capability_id":SECURITY_IP_RULE_STATE_CAPABILITY_ID,
        "source_path":SECURITY_IP_RULE_COLLECTION_PATH,
        "target_capability_id":capability.id,
        "target_method":capability.method,
        "target_path":capability.path,
        "account_id":account_id,
        "zone_id":zone_id,
        "kind":kind,
        "evidence_ref":metadata.get("evidence_ref").cloned().unwrap_or(Value::Null),
        "expires_at":metadata.get("expires_at").cloned().unwrap_or(Value::Null),
        "state":state,
    }))
}

fn validate_waf_security_action_removal_source(
    store: &StateStore,
    metadata: &Value,
    zone_id: &str,
    ruleset_id: &str,
    rule_id: &str,
) -> Result<Value> {
    let operation_id = metadata
        .get("source_operation_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CliError::Input("expired WAF action omitted its source operation ID".to_owned())
        })?;
    let plan = load_validated_plan(store, operation_id)?;
    if plan.status != PlanStatus::Verified
        || plan.capability.id != SECURITY_WAF_RULE_CREATE_ID
        || plan
            .targets
            .pointer("/selectors/zone_id")
            .and_then(Value::as_str)
            != Some(zone_id)
        || plan
            .targets
            .pointer("/selectors/ruleset_id")
            .and_then(Value::as_str)
            != Some(ruleset_id)
        || plan
            .targets
            .pointer("/adapter/security_action/evidence_ref")
            .and_then(Value::as_str)
            != metadata.get("evidence_ref").and_then(Value::as_str)
        || plan
            .targets
            .pointer("/adapter/security_action/expires_at")
            .and_then(Value::as_str)
            != metadata.get("expires_at").and_then(Value::as_str)
    {
        return Err(CliError::Input(
            "expired WAF removal is not bound to a verified source security-action plan with the same zone, ruleset, evidence, and deadline"
                .to_owned(),
        ));
    }
    let boundary_rule_id = plan
        .transaction_artifact(TransactionStageV1::BoundaryResponsePersisted)
        .and_then(|artifact| artifact.get("resource_id"))
        .and_then(Value::as_str);
    if boundary_rule_id != Some(rule_id) {
        return Err(CliError::Input(
            "expired WAF rule ID does not match the correlated identity in its source plan receipt"
                .to_owned(),
        ));
    }
    security_rule_planned_body(&plan)
}

#[expect(
    clippy::too_many_lines,
    reason = "WAF verification deliberately binds ruleset state, normalized target, audit lineage, expiry, conflicts, and rollback guidance in one receipt"
)]
fn waf_security_action_state_receipt(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
    adapter_targets: &Value,
    account_id: &str,
    response: &CloudflareResponseV1,
) -> Result<Value> {
    if !response.success || response.status != 200 {
        return Err(CliError::Input(format!(
            "Cloudflare rejected the WAF current-state read with HTTP {}; the mutation boundary was not crossed",
            response.status
        )));
    }
    let rules = response
        .result
        .get("rules")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            CliError::Input(
                "WAF current-state read did not return the complete ruleset rule array".to_owned(),
            )
        })?;
    let metadata = security_action_adapter_target(adapter_targets).ok_or_else(|| {
        CliError::Input("WAF security-action governance receipt is missing".to_owned())
    })?;
    let zone_id = input
        .selectors
        .get("zone_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| CliError::Input("WAF security action requires `zone_id`".to_owned()))?;
    let ruleset_id = input
        .selectors
        .get("ruleset_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| CliError::Input("WAF security action requires `ruleset_id`".to_owned()))?;
    let kind = metadata
        .get("kind")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("WAF security-action governance receipt omitted its kind".to_owned())
        })?;
    let state = match kind {
        "create_expiring_waf" => {
            let correlation = metadata
                .get("correlation_ref")
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    CliError::Input(
                        "WAF security-action receipt omitted its correlation reference".to_owned(),
                    )
                })?;
            let expression = metadata
                .get("expression")
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    CliError::Input(
                        "WAF security-action receipt omitted its compiled expression".to_owned(),
                    )
                })?;
            let conflicts = rules
                .iter()
                .filter(|rule| {
                    rule.get("ref").and_then(Value::as_str) == Some(correlation)
                        || rule.get("expression").and_then(Value::as_str) == Some(expression)
                })
                .map(|rule| {
                    json!({
                        "id":rule.get("id").cloned().unwrap_or(Value::Null),
                        "action":rule.get("action").cloned().unwrap_or(Value::Null),
                        "ref":rule.get("ref").cloned().unwrap_or(Value::Null),
                        "expression_hash":rule.get("expression").map(hash_value).transpose().unwrap_or(None),
                    })
                })
                .collect::<Vec<_>>();
            if !conflicts.is_empty() {
                return Err(CliError::Input(format!(
                    "WAF target already has {} correlated or expression-equivalent rule(s); inspect and resolve the duplicate or conflict before creating another action",
                    conflicts.len()
                )));
            }
            json!({
                "matching_rule_count":0,
                "correlation_ref":correlation,
                "expression_hash":hash_value(&Value::String(expression.to_owned()))?,
                "action":metadata.get("action").cloned().unwrap_or(Value::Null),
                "ruleset_rule_count":rules.len(),
            })
        }
        "remove_expired_waf" => {
            let rule_id = input
                .selectors
                .get("rule_id")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    CliError::Input("expired WAF removal requires `rule_id`".to_owned())
                })?;
            let planned_rule = validate_waf_security_action_removal_source(
                store, metadata, zone_id, ruleset_id, rule_id,
            )?;
            let matching = rules
                .iter()
                .filter(|rule| rule.get("id").and_then(Value::as_str) == Some(rule_id))
                .collect::<Vec<_>>();
            if matching.len() != 1 {
                return Err(CliError::Input(format!(
                    "expired WAF removal requires exactly one live rule with the source identity; found {}",
                    matching.len()
                )));
            }
            let planned = planned_rule.as_object().ok_or_else(|| {
                CliError::Input("verified source WAF body is not an object".to_owned())
            })?;
            let live_projection = Value::Object(
                planned
                    .keys()
                    .map(|key| {
                        (
                            key.clone(),
                            matching[0].get(key).cloned().unwrap_or(Value::Null),
                        )
                    })
                    .collect(),
            );
            if live_projection != planned_rule {
                return Err(CliError::Input(
                    "expired WAF rule drifted from the exact body verified by its source operation; inspect it before removal"
                        .to_owned(),
                ));
            }
            json!({
                "matching_rule_count":1,
                "rule_id":rule_id,
                "live_rule_hash":hash_value(&live_projection)?,
                "source_operation_id":metadata.get("source_operation_id").cloned().unwrap_or(Value::Null),
            })
        }
        _ => {
            return Err(CliError::Input(
                "WAF security-action governance receipt has an unsupported kind".to_owned(),
            ));
        }
    };
    Ok(json!({
        "schema_version":1,
        "source_capability_id":SECURITY_WAF_RULE_STATE_CAPABILITY_ID,
        "source_path":SECURITY_WAF_RULE_PARENT_PATH,
        "target_capability_id":capability.id,
        "target_method":capability.method,
        "target_path":capability.path,
        "account_id":account_id,
        "zone_id":zone_id,
        "ruleset_id":ruleset_id,
        "kind":kind,
        "evidence_ref":metadata.get("evidence_ref").cloned().unwrap_or(Value::Null),
        "expires_at":metadata.get("expires_at").cloned().unwrap_or(Value::Null),
        "state":state,
    }))
}

fn list_item_target_projection(item: &Value) -> Option<Value> {
    let mut targets = Vec::new();
    if let Some(ip) = item.get("ip").and_then(Value::as_str) {
        targets.push(json!({"ip":ip}));
    }
    if let Some(asn) = item.get("asn").and_then(Value::as_u64) {
        targets.push(json!({"asn":asn}));
    }
    if let Some(hostname) = item
        .pointer("/hostname/url_hostname")
        .and_then(Value::as_str)
    {
        targets.push(json!({"hostname":{"url_hostname":hostname}}));
    }
    (targets.len() == 1).then(|| targets.remove(0))
}

fn list_item_verification_projection(item: &Value) -> Option<Value> {
    let comment = item
        .get("comment")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())?;
    let mut projection = list_item_target_projection(item)?.as_object()?.clone();
    projection.insert("comment".to_owned(), Value::String(comment.to_owned()));
    Some(Value::Object(projection))
}

fn validated_list_member_removal_source(
    store: &StateStore,
    metadata: &Value,
    account_id: &str,
    list_id: &str,
    member_id: &str,
) -> Result<Value> {
    let operation_id = metadata
        .get("source_operation_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CliError::Input(
                "expired List member removal omitted its source operation ID".to_owned(),
            )
        })?;
    let plan = load_validated_plan(store, operation_id)?;
    let verification_passed = plan
        .transaction_artifact(TransactionStageV1::VerificationResponsePersisted)
        .and_then(|artifact| artifact.get("state"))
        .and_then(Value::as_str)
        == Some("passed");
    if !(plan.status == PlanStatus::Verified
        || (plan.status == PlanStatus::RectificationRequired && verification_passed))
        || plan.capability.id != SECURITY_LIST_MEMBER_CREATE_ID
        || plan
            .targets
            .pointer("/selectors/account_id")
            .and_then(Value::as_str)
            != Some(account_id)
        || plan
            .targets
            .pointer("/selectors/list_id")
            .and_then(Value::as_str)
            != Some(list_id)
        || plan
            .targets
            .pointer("/adapter/security_action/evidence_ref")
            .and_then(Value::as_str)
            != metadata.get("evidence_ref").and_then(Value::as_str)
        || plan
            .targets
            .pointer("/adapter/security_action/expires_at")
            .and_then(Value::as_str)
            != metadata.get("expires_at").and_then(Value::as_str)
    {
        return Err(CliError::Input(
            "expired List member removal is not bound to a verified source add with the same account, list, evidence, and deadline"
                .to_owned(),
        ));
    }
    let verified_member_id = plan
        .transaction_artifact(TransactionStageV1::VerificationResponsePersisted)
        .and_then(|artifact| artifact.get("resource_id"))
        .and_then(Value::as_str);
    if verified_member_id != Some(member_id) {
        return Err(CliError::Input(
            "List member ID does not match the correlated identity in the source verification receipt"
                .to_owned(),
        ));
    }
    let source_input: CallInput = serde_json::from_value(plan.input.clone())?;
    source_input
        .body
        .as_ref()
        .and_then(Value::as_array)
        .filter(|items| items.len() == 1)
        .and_then(|items| items.first())
        .and_then(list_item_verification_projection)
        .ok_or_else(|| {
            CliError::Input(
                "verified source List plan omitted its exact one-member wire projection".to_owned(),
            )
        })
}

#[expect(
    clippy::too_many_lines,
    reason = "list-member verification deliberately binds list and member state, consumer scope, expiry, duplicate detection, and removal guidance"
)]
fn list_security_action_state_receipt(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
    adapter_targets: &Value,
    account_id: &str,
    metadata_response: &CloudflareResponseV1,
    items_response: &CloudflareResponseV1,
) -> Result<Value> {
    if !metadata_response.success || metadata_response.status != 200 {
        return Err(CliError::Input(format!(
            "Cloudflare rejected the List metadata read with HTTP {}; the mutation boundary was not crossed",
            metadata_response.status
        )));
    }
    if !items_response.success || items_response.status != 200 {
        return Err(CliError::Input(format!(
            "Cloudflare rejected the List member read with HTTP {}; the mutation boundary was not crossed",
            items_response.status
        )));
    }
    if !security_collection_complete(items_response) {
        return Err(CliError::Input(
            "List member current-state read did not prove complete cursor pagination; the mutation boundary was not crossed"
                .to_owned(),
        ));
    }
    let list_kind = metadata_response
        .result
        .get("kind")
        .and_then(Value::as_str)
        .filter(|kind| matches!(*kind, "ip" | "asn" | "hostname"))
        .ok_or_else(|| {
            CliError::Input(
                "List metadata did not report one governed IP, ASN, or hostname kind".to_owned(),
            )
        })?;
    let items = items_response.result.as_array().ok_or_else(|| {
        CliError::Input("List member current-state read did not return an item array".to_owned())
    })?;
    let metadata = security_action_adapter_target(adapter_targets).ok_or_else(|| {
        CliError::Input("List security-action governance receipt is missing".to_owned())
    })?;
    let list_id = input
        .selectors
        .get("list_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| CliError::Input("List security action requires `list_id`".to_owned()))?;
    let kind = metadata
        .get("kind")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("List security-action receipt omitted its kind".to_owned())
        })?;
    let state = match kind {
        "add_expiring_list_member" => {
            let planned = input
                .body
                .as_ref()
                .and_then(Value::as_array)
                .filter(|items| items.len() == 1)
                .and_then(|items| items.first())
                .ok_or_else(|| {
                    CliError::Input("List add plan does not contain one wire item".to_owned())
                })?;
            let target = metadata.get("target").ok_or_else(|| {
                CliError::Input("List security-action receipt omitted its target".to_owned())
            })?;
            let expected_kind = match target.get("type").and_then(Value::as_str) {
                Some("ip" | "ip_range") => "ip",
                Some("asn") => "asn",
                Some("hostname") => "hostname",
                _ => {
                    return Err(CliError::Input(
                        "List security target type is outside the governed kind mapping".to_owned(),
                    ));
                }
            };
            if list_kind != expected_kind {
                return Err(CliError::Input(format!(
                    "target type requires a `{expected_kind}` List, but the selected List reports kind `{list_kind}`"
                )));
            }
            let planned_target = list_item_target_projection(planned).ok_or_else(|| {
                CliError::Input("List add plan has no exact target projection".to_owned())
            })?;
            let planned_comment = planned.get("comment").and_then(Value::as_str);
            let conflicts = items
                .iter()
                .filter(|item| {
                    list_item_target_projection(item).as_ref() == Some(&planned_target)
                        || (planned_comment.is_some()
                            && item.get("comment").and_then(Value::as_str) == planned_comment)
                })
                .count();
            if conflicts != 0 {
                return Err(CliError::Input(format!(
                    "selected List already has {conflicts} target-equivalent or correlation-equivalent member(s); resolve the duplicate before adding another"
                )));
            }
            json!({
                "matching_member_count":0,
                "target_hash":hash_value(&planned_target)?,
                "expected_consumer_action":metadata.get("expected_consumer_action").cloned().unwrap_or(Value::Null),
                "consumer_scope_confirmed":metadata.get("consumer_scope_confirmed").cloned().unwrap_or(Value::Null),
            })
        }
        "remove_expired_list_member" => {
            let member_id = metadata
                .get("member_id")
                .and_then(Value::as_str)
                .filter(|identity| !identity.is_empty())
                .ok_or_else(|| {
                    CliError::Input("expired List removal omitted its member identity".to_owned())
                })?;
            let planned = validated_list_member_removal_source(
                store, metadata, account_id, list_id, member_id,
            )?;
            let matching = items
                .iter()
                .filter(|item| item.get("id").and_then(Value::as_str) == Some(member_id))
                .collect::<Vec<_>>();
            if matching.len() != 1 {
                return Err(CliError::Input(format!(
                    "expired List removal requires exactly one live member with the source identity; found {}",
                    matching.len()
                )));
            }
            let live = list_item_verification_projection(matching[0]).ok_or_else(|| {
                CliError::Input("live List member has an invalid target/comment shape".to_owned())
            })?;
            if live != planned {
                return Err(CliError::Input(
                    "expired List member drifted from the exact target and audit comment verified by its source operation"
                        .to_owned(),
                ));
            }
            json!({
                "matching_member_count":1,
                "member_id":member_id,
                "live_member_hash":hash_value(&live)?,
                "source_operation_id":metadata.get("source_operation_id").cloned().unwrap_or(Value::Null),
            })
        }
        _ => {
            return Err(CliError::Input(
                "List security-action receipt has an unsupported kind".to_owned(),
            ));
        }
    };
    Ok(json!({
        "schema_version":1,
        "source_capability_ids":[SECURITY_LIST_METADATA_CAPABILITY_ID,SECURITY_LIST_MEMBER_STATE_CAPABILITY_ID],
        "source_paths":[SECURITY_LIST_METADATA_PATH,SECURITY_LIST_MEMBER_COLLECTION_PATH],
        "target_capability_id":capability.id,
        "target_method":capability.method,
        "target_path":capability.path,
        "account_id":account_id,
        "list_id":list_id,
        "list_kind":list_kind,
        "list_item_count":items.len(),
        "kind":kind,
        "evidence_ref":metadata.get("evidence_ref").cloned().unwrap_or(Value::Null),
        "expires_at":metadata.get("expires_at").cloned().unwrap_or(Value::Null),
        "state":state,
        "redaction":"raw List target values and audit comments are represented only by hashes",
    }))
}

#[expect(
    clippy::too_many_lines,
    reason = "security-action current-state reads form one fail-closed dispatcher whose branches produce the evidence bound into immutable plans"
)]
async fn read_live_security_action_state(
    store: &StateStore,
    catalog: &CatalogSnapshot,
    capability: &CapabilityV1,
    input: &CallInput,
    adapter_targets: &Value,
    account_id: &str,
    credential: &AuthCredential,
) -> Result<(Value, EvidenceV1)> {
    if !should_bind_security_action_state(capability, adapter_targets) {
        return Err(CliError::Input(
            "security action drifted from its governed current-state contract".to_owned(),
        ));
    }
    if matches!(
        capability.id.as_str(),
        SECURITY_LIST_MEMBER_CREATE_ID | SECURITY_LIST_MEMBER_REMOVE_ID
    ) {
        let metadata_source = catalog
            .get(SECURITY_LIST_METADATA_CAPABILITY_ID)
            .ok_or_else(|| capability_missing(SECURITY_LIST_METADATA_CAPABILITY_ID))?;
        let items_source = catalog
            .get(SECURITY_LIST_MEMBER_STATE_CAPABILITY_ID)
            .ok_or_else(|| capability_missing(SECURITY_LIST_MEMBER_STATE_CAPABILITY_ID))?;
        if metadata_source.method != "GET"
            || metadata_source.path != SECURITY_LIST_METADATA_PATH
            || metadata_source.mutating
            || items_source.method != "GET"
            || items_source.path != SECURITY_LIST_MEMBER_COLLECTION_PATH
            || items_source.mutating
            || !matches!(
                metadata_source.adapter_status,
                AdapterStatus::Native | AdapterStatus::DynamicApi
            )
            || !matches!(
                items_source.adapter_status,
                AdapterStatus::Native | AdapterStatus::DynamicApi
            )
        {
            return Err(CliError::Input(
                "List security-action state sources drifted from the governed metadata plus complete-member reads"
                    .to_owned(),
            ));
        }
        let selectors = json!({
            "account_id":input.selectors.get("account_id").cloned().unwrap_or(Value::Null),
            "list_id":input.selectors.get("list_id").cloned().unwrap_or(Value::Null),
        });
        let executor = Executor::new(http_client()?, API_BASE_URL)?;
        let metadata_response = executor
            .execute_read(
                metadata_source,
                &CallInput {
                    selectors: selectors.clone(),
                    query: json!({}),
                    body: None,
                    ..CallInput::default()
                },
                credential,
            )
            .await?;
        let items_response = executor
            .execute_read(
                items_source,
                &CallInput {
                    selectors,
                    query: json!({"per_page":500}),
                    body: None,
                    ..CallInput::default()
                },
                credential,
            )
            .await?;
        let receipt = list_security_action_state_receipt(
            store,
            capability,
            input,
            adapter_targets,
            account_id,
            &metadata_response,
            &items_response,
        )?;
        let evidence = store.write_evidence(EvidenceClass::LiveRead, &receipt)?;
        return Ok((receipt, evidence));
    }
    if matches!(
        capability.id.as_str(),
        SECURITY_WAF_RULE_CREATE_ID | SECURITY_WAF_RULE_REMOVE_ID
    ) {
        let source = catalog
            .get(SECURITY_WAF_RULE_STATE_CAPABILITY_ID)
            .ok_or_else(|| capability_missing(SECURITY_WAF_RULE_STATE_CAPABILITY_ID))?;
        if source.method != "GET"
            || source.path != SECURITY_WAF_RULE_PARENT_PATH
            || source.mutating
            || !matches!(
                source.adapter_status,
                AdapterStatus::Native | AdapterStatus::DynamicApi
            )
        {
            return Err(CliError::Input(
                "WAF state source capability drifted from the governed exact-ruleset read"
                    .to_owned(),
            ));
        }
        let response = Executor::new(http_client()?, API_BASE_URL)?
            .execute_read(
                source,
                &CallInput {
                    selectors: json!({
                        "zone_id":input.selectors.get("zone_id").cloned().unwrap_or(Value::Null),
                        "ruleset_id":input.selectors.get("ruleset_id").cloned().unwrap_or(Value::Null),
                    }),
                    query: json!({}),
                    body: None,
                    ..CallInput::default()
                },
                credential,
            )
            .await?;
        let receipt = waf_security_action_state_receipt(
            store,
            capability,
            input,
            adapter_targets,
            account_id,
            &response,
        )?;
        let evidence = store.write_evidence(EvidenceClass::LiveRead, &receipt)?;
        return Ok((receipt, evidence));
    }
    let source = catalog
        .get(SECURITY_IP_RULE_STATE_CAPABILITY_ID)
        .ok_or_else(|| capability_missing(SECURITY_IP_RULE_STATE_CAPABILITY_ID))?;
    if source.method != "GET"
        || source.path != SECURITY_IP_RULE_COLLECTION_PATH
        || source.mutating
        || !matches!(
            source.adapter_status,
            AdapterStatus::Native | AdapterStatus::DynamicApi
        )
    {
        return Err(CliError::Input(
            "security-action state source capability drifted from the governed complete rule-list read"
                .to_owned(),
        ));
    }
    let metadata = security_action_adapter_target(adapter_targets).ok_or_else(|| {
        CliError::Input("security-action governance receipt is missing".to_owned())
    })?;
    let query = match metadata.get("kind").and_then(Value::as_str) {
        Some("create_expiring") => json!({
            "configuration.value":metadata.pointer("/target/value").cloned().unwrap_or(Value::Null),
            "match":"all",
            "per_page":50,
        }),
        Some("remove_expired") => json!({
            "notes":metadata.get("evidence_ref").cloned().unwrap_or(Value::Null),
            "match":"all",
            "per_page":50,
        }),
        _ => {
            return Err(CliError::Input(
                "security-action governance receipt has an unsupported kind".to_owned(),
            ));
        }
    };
    let response = Executor::new(http_client()?, API_BASE_URL)?
        .execute_read(
            source,
            &CallInput {
                selectors: json!({
                    "zone_id":input.selectors.get("zone_id").cloned().unwrap_or(Value::Null),
                }),
                query,
                body: None,
                ..CallInput::default()
            },
            credential,
        )
        .await?;
    let receipt = security_action_state_receipt(
        store,
        capability,
        input,
        adapter_targets,
        account_id,
        &response,
    )?;
    let evidence = store.write_evidence(EvidenceClass::LiveRead, &receipt)?;
    Ok((receipt, evidence))
}

fn preflight_call_input(
    capability: &CapabilityV1,
    input: &CallInput,
    secret_body: Option<&Value>,
) -> Result<()> {
    let mut resolved = input.clone();
    if let Some(secret_body) = secret_body {
        resolved.body = Some(secret_body.clone());
    }
    validate_request_contract(capability, &resolved)?;
    validate_cloudflare_tunnel_configuration_ingress(capability, &resolved)?;
    validate_warp_connector_configuration_semantics(capability, &resolved)?;
    validate_d1_database_create_semantics(capability, &resolved)?;
    validate_worker_script_secret_semantics(capability, &resolved)?;
    validate_r2_temporary_credentials_semantics(capability, &resolved)?;
    Ok(())
}

const R2_TEMPORARY_CREDENTIALS_CAPABILITY_ID: &str = "r2-create-temp-access-credentials";
const R2_TEMPORARY_CREDENTIALS_PATH: &str = "/accounts/{account_id}/r2/temp-access-credentials";
const R2_PARENT_TOKEN_VERIFY_CAPABILITY_ID: &str = "user-api-tokens-verify-token";
const R2_PARENT_TOKEN_VERIFY_PATH: &str = "/user/tokens/verify";
const R2_PARENT_TOKEN_PRECONDITION: &str = "r2_parent_token";
const R2_ACTIVE_PROFILE_TOKEN_ID: &str = "$cfctl_active_profile_token_id";
const R2_TEMPORARY_CREDENTIAL_PERMISSIONS: [&str; 6] = [
    "Workers R2 Storage Write",
    "Workers R2 Storage Read",
    "Workers R2 Storage Bucket Item Write",
    "Workers R2 Storage Bucket Item Read",
    "Workers R2 Data Catalog Write",
    "Workers R2 Data Catalog Read",
];

fn is_r2_temporary_credentials_operation_identity(capability: &CapabilityV1) -> bool {
    capability.id == R2_TEMPORARY_CREDENTIALS_CAPABILITY_ID
        && capability.title == "Create Temporary Access Credentials"
        && capability.method == "POST"
        && capability.path == R2_TEMPORARY_CREDENTIALS_PATH
        && capability.product == "R2 Bucket"
        && capability.account_scope == "account"
}

fn is_r2_temporary_credentials_capability(capability: &CapabilityV1) -> bool {
    is_r2_temporary_credentials_operation_identity(capability)
        && capability.permissions
            == R2_TEMPORARY_CREDENTIAL_PERMISSIONS
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
        && capability.risk == RiskClass::SecretSensitive
        && capability.effect == EffectClass::IdentityOrOwnership
        && !capability.verification.required
        && capability.verification.strategy == "sink_write_and_source_response_status"
        && capability.request_schema.as_ref().is_some_and(|schema| {
            schema
                .pointer("/properties/parentAccessKeyId/x-cfctl-derived-from-active-profile")
                .and_then(Value::as_bool)
                == Some(true)
        })
}

fn prepare_r2_temporary_credentials_input(
    capability: &CapabilityV1,
    input: &mut CallInput,
) -> Result<()> {
    if !is_r2_temporary_credentials_capability(capability) {
        return Ok(());
    }
    let body = input
        .body
        .as_mut()
        .and_then(Value::as_object_mut)
        .ok_or_else(|| {
            CliError::Input("R2 temporary credentials require a JSON object body".to_owned())
        })?;
    if body.contains_key("parentAccessKeyId") {
        return Err(CliError::Input(
            "omit `parentAccessKeyId`; cfctl derives and hash-binds it from the active API-token profile so callers cannot redirect signing to another parent"
                .to_owned(),
        ));
    }
    body.insert(
        "parentAccessKeyId".to_owned(),
        Value::String(R2_ACTIVE_PROFILE_TOKEN_ID.to_owned()),
    );
    Ok(())
}

fn should_bind_r2_parent_token(capability: &CapabilityV1) -> bool {
    is_r2_temporary_credentials_capability(capability)
        && capability.mutating
        && matches!(
            capability.adapter_status,
            AdapterStatus::Native | AdapterStatus::DynamicApi
        )
}

fn r2_parent_token_verify_contract_supported(capability: &CapabilityV1) -> bool {
    capability.id == R2_PARENT_TOKEN_VERIFY_CAPABILITY_ID
        && capability.title == "Verify Token"
        && capability.method == "GET"
        && capability.path == R2_PARENT_TOKEN_VERIFY_PATH
        && capability.product == "User API Tokens"
        && capability.account_scope == "user"
        && !capability.mutating
        && capability.request_schema.is_none()
        && capability.permissions.is_empty()
        && capability.selectors.is_empty()
        && matches!(
            capability.adapter_status,
            AdapterStatus::Native | AdapterStatus::DynamicApi
        )
        && capability
            .response_contract
            .as_ref()
            .is_some_and(|contract| {
                matches!(
                    contract.body_mode,
                    cfctl_core::ResponseBodyModeV1::CloudflareJsonEnvelope
                ) && contract.success_statuses == ["200"]
                    && contract.success_media_types == ["application/json"]
            })
}

fn r2_parent_permission_contract(permission: &str) -> Result<Value> {
    let allowed_capabilities: &[&str] = match permission {
        "admin-read-write" => &[
            "object_read",
            "object_write",
            "object_list",
            "bucket_configuration_read",
            "bucket_configuration_write",
            "data_catalog_read",
            "data_catalog_write",
        ],
        "admin-read-only" => &[
            "object_read",
            "object_list",
            "bucket_configuration_read",
            "data_catalog_read",
        ],
        "object-read-write" => &["object_read", "object_write", "object_list"],
        "object-read-only" => &["object_read", "object_list"],
        _ => {
            return Err(CliError::Input(format!(
                "unsupported R2 temporary credential permission `{permission}`"
            )));
        }
    };
    Ok(json!({
        "rule": "temporary_scope_must_not_exceed_parent",
        "enforced_by": "cloudflare",
        "requested_scope": permission,
        "allowed_capabilities": allowed_capabilities,
    }))
}

fn r2_delegated_scope(input: &CallInput) -> Result<Value> {
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| {
            CliError::Input("R2 temporary credentials require a JSON object body".to_owned())
        })?;
    let mut scope = Map::new();
    for field in ["bucket", "permission", "ttlSeconds", "prefixes", "objects"] {
        if let Some(value) = body.get(field) {
            scope.insert(field.to_owned(), value.clone());
        }
    }
    Ok(Value::Object(scope))
}

fn apply_r2_parent_token_response(
    capability: &CapabilityV1,
    account_id: &str,
    input: &mut CallInput,
    response: &CloudflareResponseV1,
) -> Result<Value> {
    if !should_bind_r2_parent_token(capability) {
        return Err(CliError::Input(
            "R2 temporary credential operation drifted from its governed parent-token contract"
                .to_owned(),
        ));
    }
    if !response.success || response.status != 200 {
        return Err(CliError::Input(format!(
            "active API-token verification did not return the exact successful HTTP 200 contract (received {}); the mutation boundary was not crossed",
            response.status
        )));
    }
    let parent_access_key_id = response
        .result
        .get("id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty() && value.len() <= 128)
        .ok_or_else(|| {
            CliError::Input(
                "active API-token verification omitted a bounded token id; the mutation boundary was not crossed"
                    .to_owned(),
            )
        })?;
    let token_status = response
        .result
        .get("status")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input(
                "active API-token verification omitted token status; the mutation boundary was not crossed"
                    .to_owned(),
            )
        })?;
    if token_status != "active" {
        return Err(CliError::Input(format!(
            "selected API-token profile is not active (status `{token_status}`); the mutation boundary was not crossed"
        )));
    }
    let body = input
        .body
        .as_mut()
        .and_then(Value::as_object_mut)
        .ok_or_else(|| {
            CliError::Input("R2 temporary credentials require a JSON object body".to_owned())
        })?;
    let planned_parent = body
        .get("parentAccessKeyId")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input(
                "R2 temporary credential request omitted its cfctl-derived parent token marker"
                    .to_owned(),
            )
        })?;
    if planned_parent != R2_ACTIVE_PROFILE_TOKEN_ID && planned_parent != parent_access_key_id {
        return Err(CliError::Input(
            "R2 temporary credential parent token differs from the selected API-token profile; the mutation boundary was not crossed"
                .to_owned(),
        ));
    }
    body.insert(
        "parentAccessKeyId".to_owned(),
        Value::String(parent_access_key_id.to_owned()),
    );
    let delegated_scope = r2_delegated_scope(input)?;
    let permission = delegated_scope
        .get("permission")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("R2 temporary credential permission is missing".to_owned())
        })?;
    Ok(json!({
        "schema_version": 1,
        "source_capability_id": R2_PARENT_TOKEN_VERIFY_CAPABILITY_ID,
        "source_path": R2_PARENT_TOKEN_VERIFY_PATH,
        "target_capability_id": capability.id,
        "target_method": capability.method,
        "target_path": capability.path,
        "target_scope": "account",
        "account_id": account_id,
        "parent_access_key_id": parent_access_key_id,
        "token_status": token_status,
        "delegated_scope": delegated_scope,
        "parent_permission_contract": r2_parent_permission_contract(permission)?,
    }))
}

async fn read_live_r2_parent_token(
    store: &StateStore,
    catalog: &CatalogSnapshot,
    capability: &CapabilityV1,
    input: &mut CallInput,
    account_id: &str,
    credential: &AuthCredential,
) -> Result<(Value, EvidenceV1)> {
    let source_capability = catalog
        .get(R2_PARENT_TOKEN_VERIFY_CAPABILITY_ID)
        .ok_or_else(|| capability_missing(R2_PARENT_TOKEN_VERIFY_CAPABILITY_ID))?;
    if !r2_parent_token_verify_contract_supported(source_capability) {
        return Err(CliError::Input(
            "R2 parent-token source capability drifted from the governed user-token verification read"
                .to_owned(),
        ));
    }
    let executor = Executor::new(http_client()?, API_BASE_URL)?;
    let response = executor
        .execute_read(source_capability, &CallInput::default(), credential)
        .await?;
    let receipt = apply_r2_parent_token_response(capability, account_id, input, &response)?;
    let evidence = store.write_evidence(EvidenceClass::LiveRead, &receipt)?;
    Ok((receipt, evidence))
}

fn validate_r2_temporary_credentials_semantics(
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<()> {
    if !is_r2_temporary_credentials_capability(capability) {
        return Ok(());
    }
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| {
            CliError::Input("R2 temporary credentials require a JSON object body".to_owned())
        })?;
    let allowed = [
        "bucket",
        "objects",
        "parentAccessKeyId",
        "permission",
        "prefixes",
        "ttlSeconds",
    ];
    if let Some(field) = body.keys().find(|field| !allowed.contains(&field.as_str())) {
        return Err(CliError::Input(format!(
            "R2 temporary credentials reject undeclared body field `{field}`"
        )));
    }
    let bucket = body
        .get("bucket")
        .and_then(Value::as_str)
        .filter(|bucket| !bucket.trim().is_empty())
        .ok_or_else(|| {
            CliError::Input("R2 temporary credentials require a non-empty `bucket`".to_owned())
        })?;
    let _ = bucket;
    let ttl = body
        .get("ttlSeconds")
        .and_then(Value::as_u64)
        .filter(|ttl| (1..=604_800).contains(ttl))
        .ok_or_else(|| {
            CliError::Input(
                "R2 temporary credential `ttlSeconds` must be a whole number from 1 through 604800; use the shortest practical TTL"
                    .to_owned(),
            )
        })?;
    let _ = ttl;
    for field in ["prefixes", "objects"] {
        let Some(values) = body.get(field) else {
            continue;
        };
        let values = values.as_array().ok_or_else(|| {
            CliError::Input(format!(
                "R2 temporary credential `{field}` must be an array of non-empty strings"
            ))
        })?;
        let mut unique = BTreeSet::new();
        for value in values {
            let value = value
                .as_str()
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    CliError::Input(format!(
                        "R2 temporary credential `{field}` must contain only non-empty strings"
                    ))
                })?;
            if !unique.insert(value) {
                return Err(CliError::Input(format!(
                    "R2 temporary credential `{field}` contains duplicate path `{value}`"
                )));
            }
        }
    }
    Ok(())
}

fn validate_d1_database_create_semantics(
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<()> {
    if capability.id != "d1-create-database" {
        return Ok(());
    }
    let Some(body) = input.body.as_ref().and_then(Value::as_object) else {
        return Ok(());
    };
    if body.contains_key("jurisdiction") && body.contains_key("primary_location_hint") {
        return Err(CliError::Input(
            "D1 database creation cannot combine `jurisdiction` with `primary_location_hint`: Cloudflare gives jurisdiction precedence and ignores the location hint; choose the hard jurisdiction boundary or the best-effort location hint"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_cloudflare_tunnel_configuration_ingress(
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<()> {
    if !is_cloudflare_tunnel_configuration_mutation(capability) {
        return Ok(());
    }
    let ingress = input
        .body
        .as_ref()
        .and_then(|body| body.pointer("/config/ingress"))
        .and_then(Value::as_array)
        .filter(|rules| !rules.is_empty())
        .ok_or_else(|| {
            CliError::Input(
                "Tunnel configuration requires at least one ingress rule and a final catch-all rule"
                    .to_owned(),
            )
        })?;
    for (index, rule) in ingress.iter().enumerate() {
        let service = rule
            .get("service")
            .and_then(Value::as_str)
            .filter(|service| !service.trim().is_empty())
            .ok_or_else(|| {
                CliError::Input(format!(
                    "Tunnel ingress rule {} requires a non-empty service",
                    index + 1
                ))
            })?;
        let _ = service;
        let matches_all_traffic =
            rule.get("hostname").and_then(Value::as_str) == Some("") && rule.get("path").is_none();
        if matches_all_traffic && index + 1 != ingress.len() {
            return Err(CliError::Input(format!(
                "Tunnel ingress rule {} is a catch-all, so every later rule is unreachable; move the catch-all to the end",
                index + 1
            )));
        }
        if index + 1 == ingress.len() && !matches_all_traffic {
            return Err(CliError::Input(
                "Tunnel configuration requires a final catch-all ingress rule with an empty hostname and no path"
                    .to_owned(),
            ));
        }
    }
    Ok(())
}

fn validate_warp_connector_configuration_semantics(
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<()> {
    if !is_warp_connector_configuration_mutation(capability) {
        return Ok(());
    }
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| {
            CliError::Input("WARP Connector configuration requires a JSON object body".to_owned())
        })?;
    let mode = body.get("ha_mode").and_then(Value::as_str).ok_or_else(|| {
        CliError::Input("WARP Connector configuration requires string field `ha_mode`".to_owned())
    })?;
    let config = body.get("config").filter(|value| !value.is_null());
    match mode {
        "none" | "disabled" => {
            if config.is_some_and(|value| {
                value
                    .as_object()
                    .is_none_or(|configuration| !configuration.is_empty())
            }) {
                return Err(CliError::Input(format!(
                    "WARP Connector HA mode `{mode}` requires `config` to be omitted, null, or an empty object"
                )));
            }
        }
        "aws" => {
            let fnr_id = config
                .and_then(|value| value.get("fnr_id"))
                .and_then(Value::as_str)
                .filter(|value| !value.trim().is_empty())
                .ok_or_else(|| {
                    CliError::Input(
                        "WARP Connector HA mode `aws` requires a non-empty `config.fnr_id`"
                            .to_owned(),
                    )
                })?;
            let _ = fnr_id;
        }
        "local" => {
            let configuration = config.and_then(Value::as_object).ok_or_else(|| {
                CliError::Input("WARP Connector HA mode `local` requires `config.vips`".to_owned())
            })?;
            let mut addresses = BTreeSet::new();
            validate_warp_connector_vip_addresses(configuration, "vips", true, &mut addresses)?;
            validate_warp_connector_vip_addresses(
                configuration,
                "vips_previous",
                false,
                &mut addresses,
            )?;
        }
        _ => {
            return Err(CliError::Input(format!(
                "unsupported WARP Connector HA mode `{mode}`"
            )));
        }
    }
    Ok(())
}

fn validate_worker_script_secret_semantics(
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<()> {
    if !is_worker_script_secret_input_only_capability(capability) {
        return Ok(());
    }
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| {
            CliError::Input("Worker script secret input requires a JSON object body".to_owned())
        })?;
    let secret_type = body.get("type").and_then(Value::as_str).ok_or_else(|| {
        CliError::Input("Worker script secret input requires string field `type`".to_owned())
    })?;
    let has_base64 = body.contains_key("key_base64");
    let has_jwk = body.contains_key("key_jwk");
    if has_base64 && has_jwk {
        return Err(CliError::Input(
            "Worker script secret_key input accepts exactly one key material field: `key_base64` or `key_jwk`"
                .to_owned(),
        ));
    }
    match secret_type {
        "secret_text" => {
            if body.get("text").and_then(Value::as_str).is_none() {
                return Err(CliError::Input(
                    "Worker script secret_text input requires string field `text`".to_owned(),
                ));
            }
            if has_base64 || has_jwk {
                return Err(CliError::Input(
                    "Worker script secret_text accepts only `text`, never key material fields"
                        .to_owned(),
                ));
            }
        }
        "secret_key" => {
            let format = body.get("format").and_then(Value::as_str).ok_or_else(|| {
                CliError::Input(
                    "Worker script secret_key input requires string field `format`".to_owned(),
                )
            })?;
            if format == "jwk" {
                if !has_jwk || has_base64 {
                    return Err(CliError::Input(
                        "Worker script secret_key format `jwk` requires `key_jwk` and forbids `key_base64`"
                            .to_owned(),
                    ));
                }
            } else if matches!(format, "raw" | "pkcs8" | "spki") {
                if !has_base64 || has_jwk {
                    return Err(CliError::Input(format!(
                        "Worker script secret_key format `{format}` requires `key_base64` and forbids `key_jwk`"
                    )));
                }
            } else {
                return Err(CliError::Input(
                    "Worker script secret_key format must be one of `raw`, `pkcs8`, `spki`, or `jwk`"
                        .to_owned(),
                ));
            }
        }
        _ => {
            return Err(CliError::Input(
                "Worker script secret type must be `secret_text` or `secret_key`".to_owned(),
            ));
        }
    }
    Ok(())
}

fn validate_warp_connector_vip_addresses(
    configuration: &Map<String, Value>,
    field: &str,
    required: bool,
    addresses: &mut BTreeSet<std::net::IpAddr>,
) -> Result<()> {
    let Some(values) = configuration.get(field) else {
        return if required {
            Err(CliError::Input(format!(
                "WARP Connector HA mode `local` requires `config.{field}`"
            )))
        } else {
            Ok(())
        };
    };
    let values = values.as_array().ok_or_else(|| {
        CliError::Input(format!(
            "WARP Connector `config.{field}` must be an array of IP addresses"
        ))
    })?;
    for (index, value) in values.iter().enumerate() {
        let address = value
            .get("address")
            .and_then(Value::as_str)
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| {
                CliError::Input(format!(
                    "WARP Connector `config.{field}[{index}].address` must be a non-empty IP address"
                ))
            })?;
        let address_identity = address.parse::<std::net::IpAddr>().map_err(|_| {
            CliError::Input(format!(
                "WARP Connector `config.{field}[{index}].address` is not a valid IPv4 or IPv6 address"
            ))
        })?;
        if !addresses.insert(address_identity) {
            return Err(CliError::Input(format!(
                "WARP Connector IP address `{address}` is duplicated across the current and previous VIP sets"
            )));
        }
    }
    Ok(())
}

#[derive(Debug)]
struct ExecutedRead {
    envelope: ResultEnvelopeV2,
    credential_generation_id: Option<String>,
}

#[expect(
    clippy::too_many_lines,
    reason = "the versioned parent evidence contract stays explicit and auditable as one fail-closed gate"
)]
fn mln_0143_parent_manifests(
    store: &StateStore,
    catalog: &CatalogSnapshot,
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<Vec<(String, Value)>> {
    let Some(contract) = capability.mln_0143_data_invariants.as_ref() else {
        return Ok(Vec::new());
    };
    if contract.capability_version != 5
        || !contract
            .expected_validator_contract_hash()
            .is_ok_and(|hash| hash == contract.validator_contract_hash)
    {
        return Err(CliError::Input(
            "MLN 0143 validator contract is stale or internally inconsistent".to_owned(),
        ));
    }
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("MLN 0143 invariant input must be an object".to_owned()))?;
    let phase = body
        .get("phase")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("MLN 0143 invariant phase is missing".to_owned()))?;
    validate_mln_cross_operation_lineage(store, contract, input, phase)?;
    let required: &[(&str, &str)] = match phase {
        "pre_import" => &[],
        "post_import" => &[("pre_import_evidence_hash", "pre_import")],
        "post_restore" => &[
            ("pre_import_evidence_hash", "pre_import"),
            ("post_import_evidence_hash", "post_import"),
        ],
        _ => {
            return Err(CliError::Input(
                "MLN 0143 invariant phase is unsupported".to_owned(),
            ));
        }
    };
    let target_scope_hash = hash_value(&json!({
        "account_id":contract.account_id,
        "database_id":contract.database_id,
    }))?;
    required
        .iter()
        .map(|(field, expected_phase)| {
            let evidence_hash = body.get(*field).and_then(Value::as_str).ok_or_else(|| {
                CliError::Input(format!("MLN 0143 `{phase}` requires `{field}`"))
            })?;
            let matching_proofs = store
                .list_operational_proofs()?
                .into_iter()
                .filter(|proof| {
                    proof.evidence.content_hash == evidence_hash
                        && proof.mln_0143_governed_execution().is_some_and(|binding| {
                            binding.capability_id == capability.id
                                && binding.capability_version == contract.capability_version
                                && binding.validator_contract_hash
                                    == contract.validator_contract_hash
                                && binding.fixed_query_sha256 == contract.fixed_query_sha256
                                && binding.catalog_hash == catalog.schema_hash
                                && binding.target_scope_hash == target_scope_hash
                                && binding.phase == *expected_phase
                                && binding.manifest_evidence_hash == evidence_hash
                                && binding.completion_status == "completed"
                        })
                })
                .collect::<Vec<_>>();
            if matching_proofs.len() != 1 {
                return Err(CliError::Input(format!(
                    "MLN 0143 parent evidence `{field}` requires exactly one matching completed governed execution proof"
                )));
            }
            let stored = store.read_evidence_value(evidence_hash)?;
            let manifest = stored.get("result").unwrap_or(&stored);
            let expected_table_hash = if *expected_phase == "post_import" {
                contract.post_table_definition_hash.as_str()
            } else {
                contract.pre_table_definition_hash.as_str()
            };
            let assertions = manifest.get("assertions").and_then(Value::as_object);
            let exact_assertions = [
                "old_table_absent",
                "unique_hash_index_present",
                "event_index_exact_non_unique_shape",
                "document_index_exact_non_unique_shape",
                "foreign_key_check_empty",
                "duplicate_hash_groups_zero",
                "invalid_evidence_kinds_zero",
                "invalid_advanced_events_zero",
                "prior_0142_terminal_trigger_present",
            ];
            let expected_trigger_hashes = if *expected_phase == "pre_import" {
                json!([])
            } else {
                json!(contract.trigger_definition_hashes)
            };
            let projection = manifest.get("projection").and_then(Value::as_object);
            let query = manifest.get("query").and_then(Value::as_object);
            let valid = manifest.get("capability_id").and_then(Value::as_str)
                == Some("mln-0143-data-invariants")
                && manifest.get("capability_version").and_then(Value::as_u64)
                    == Some(u64::from(contract.capability_version))
                && manifest.get("migration_id").and_then(Value::as_str) == Some("0143")
                && manifest.get("migration_sha256").and_then(Value::as_str)
                    == Some(contract.migration_sha256.as_str())
                && manifest
                    .get("validator_contract_hash")
                    .and_then(Value::as_str)
                    == Some(contract.validator_contract_hash.as_str())
                && manifest.get("target_scope_hash").and_then(Value::as_str)
                    == Some(target_scope_hash.as_str())
                && manifest.get("phase").and_then(Value::as_str) == Some(*expected_phase)
                && manifest.get("complete").and_then(Value::as_bool) == Some(true)
                && manifest.get("semantic_schema_hash").and_then(Value::as_str)
                    == Some(expected_table_hash)
                && manifest.get("packet_hash").and_then(Value::as_str).is_some()
                && manifest.get("packet_count").and_then(Value::as_u64).is_some()
                && manifest
                    .get("packet_non_target_hash")
                    .and_then(Value::as_str)
                    .is_some()
                && manifest
                    .get("packet_non_target_count")
                    .and_then(Value::as_u64)
                    .is_some()
                && manifest
                    .get("prior_0142_trigger_definition_hash")
                    .and_then(Value::as_str)
                    == Some(contract.prior_0142_trigger_definition_hash.as_str())
                && assertions.is_some_and(|assertions| {
                    assertions.len() == exact_assertions.len()
                        && exact_assertions.iter().all(|field| {
                            assertions.get(*field).and_then(Value::as_bool) == Some(true)
                        })
                })
                && projection.is_some_and(|projection| {
                    projection.len() == 3
                        && projection.get("digest").and_then(Value::as_str).is_some()
                        && projection.get("count").and_then(Value::as_u64).is_some()
                        && projection
                            .get("counts_by_kind")
                            .is_some_and(Value::is_array)
                })
                && manifest.get("trigger_definition_hashes") == Some(&expected_trigger_hashes)
                && query.is_some_and(|query| {
                    query.len() == 9
                        && query.get("sha256").and_then(Value::as_str)
                            == Some(contract.fixed_query_sha256.as_str())
                        && [
                            "row_limit",
                            "probe_rows",
                            "byte_limit",
                            "timeout_seconds",
                            "received_rows",
                            "provider_rows_read",
                        ]
                        .iter()
                        .all(|field| query.get(*field).and_then(Value::as_u64).is_some())
                        && query
                            .get("provider_duration")
                            .and_then(Value::as_f64)
                            .is_some()
                        && query.get("bounds_saturated").and_then(Value::as_bool)
                            == Some(false)
                })
                && manifest.pointer("/query/sha256").and_then(Value::as_str)
                    == Some(contract.fixed_query_sha256.as_str())
                && manifest.pointer("/query/bounds_saturated").and_then(Value::as_bool)
                    == Some(false);
            if !valid {
                return Err(CliError::Input(format!(
                    "MLN 0143 parent evidence `{field}` does not match the required capability, migration, target, completeness, or phase"
                )));
            }
            Ok((evidence_hash.to_owned(), manifest.clone()))
        })
        .collect()
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Mln0143RestoreAnchorJoin {
    input_source_operation_id: String,
    receipt_source_operation_id: String,
    input_source_evidence_hash: String,
    receipt_source_evidence_hash: String,
    input_target_bookmark_hash: String,
    requested_bookmark_hash: String,
    observed_bookmark_hash: String,
    account_id: String,
    profile_id: String,
    catalog_hash: String,
    credential_generation_id: String,
    anchor_completed_at: chrono::DateTime<Utc>,
    restore_created_at: chrono::DateTime<Utc>,
}

fn mln_0143_restore_anchor_matches(
    observed: &Mln0143RestoreAnchorJoin,
    expected: &Mln0143RestoreAnchorJoin,
) -> bool {
    observed == expected && observed.anchor_completed_at < observed.restore_created_at
}

#[expect(
    clippy::too_many_lines,
    reason = "cross-operation import and restore joins are one fail-closed lineage gate"
)]
fn validate_mln_cross_operation_lineage(
    store: &StateStore,
    contract: &cfctl_core::Mln0143DataInvariantsContractV1,
    input: &CallInput,
    phase: &str,
) -> Result<()> {
    if phase == "pre_import" {
        return Ok(());
    }
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("MLN lineage body is missing".to_owned()))?;
    let field = |name: &str| {
        body.get(name)
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| CliError::Input(format!("MLN lineage requires `{name}`")))
    };
    let import_operation_id = field("import_operation_id")?;
    let boundary_hash = field("import_boundary_evidence_hash")?;
    let import_source_sha256 = field("import_source_sha256")?;
    let import_plan_hash = field("import_plan_hash")?;
    let import_plan = store.load_plan(import_operation_id)?;
    let import_input: CallInput = serde_json::from_value(import_plan.input.clone())?;
    let StoredPlanRecord::Current(import_plan_v2) =
        store.load_stored_plan_record(import_operation_id)?
    else {
        return Err(CliError::Input(
            "MLN lineage import operation is not a current immutable PlanV2".to_owned(),
        ));
    };
    let exact_plan = import_plan.capability.id == "d1-import-approved-mln-migration"
        && import_plan.status == PlanStatus::Verified
        && import_plan.transaction_stage == TransactionStageV1::Closed
        && import_plan.account_id == contract.account_id
        && import_plan.content_hash == import_plan_hash
        && import_plan_v2.plan.content_hash == import_plan.content_hash
        && import_input.selectors == input.selectors
        && import_input
            .body
            .as_ref()
            .and_then(|body| body.get("migration_id"))
            .and_then(Value::as_str)
            == Some("0143");
    let boundary = exact_durable_provider_complete_boundary(store, import_operation_id)?;
    let boundary_matches = boundary.evidence_hash == boundary_hash
        && boundary
            .checkpoint
            .pointer("/receipt/source_sha256")
            .and_then(Value::as_str)
            == Some(import_source_sha256);
    if !exact_plan
        || import_source_sha256
            != "sha256:9b089ead4c284fe92f8a9f81296ac34aa98702585305e36b5c4f345fe774871d"
        || !boundary_matches
    {
        return Err(CliError::Input(
            "post-import lineage does not resolve to exactly one same-target approved 0143 provider-complete boundary"
                .to_owned(),
        ));
    }
    if phase != "post_restore" {
        return Ok(());
    }
    let restore_operation_id = field("restore_operation_id")?;
    let restore_evidence_hash = field("restore_evidence_hash")?;
    let restore_plan = store.load_plan(restore_operation_id)?;
    let StoredPlanRecord::Current(restore_plan_v2) =
        store.load_stored_plan_record(restore_operation_id)?
    else {
        return Err(CliError::Input(
            "post_restore operation is not a current immutable PlanV2".to_owned(),
        ));
    };
    let restore_input: CallInput = serde_json::from_value(restore_plan.input.clone())?;
    let import_body = import_input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| {
            CliError::Input("0143 import lost its closed prerequisite body".to_owned())
        })?;
    let import_field = |name: &str| {
        import_body
            .get(name)
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| CliError::Input(format!("0143 import omitted `{name}`")))
    };
    let anchor_operation_id = import_field("post_0142_anchor_operation_id")?;
    let anchor_evidence_hash = import_field("post_0142_anchor_evidence_hash")?;
    let anchor_bookmark_hash = import_field("post_0142_anchor_bookmark_hash")?;
    let prior_0142_operation_id = import_field("prior_0142_operation_id")?;
    let prior_0142_plan = store.load_plan(prior_0142_operation_id)?;
    let prior_0142_closed_at = prior_0142_plan
        .transaction_journal
        .iter()
        .find(|checkpoint| checkpoint.stage == TransactionStageV1::Closed)
        .map(|checkpoint| checkpoint.recorded_at)
        .ok_or_else(|| CliError::Input("0142 import lost its Closed checkpoint".to_owned()))?;
    let target_scope_hash = hash_value(&json!({
        "account_id":contract.account_id,
        "database_id":contract.database_id,
    }))?;
    let anchor_request_hash = hash_value(&serde_json::to_value(CallInput {
        selectors: input.selectors.clone(),
        query: json!({}),
        ..CallInput::default()
    })?)?;
    let anchor_completed_at = validate_exact_d1_recovery_anchor(
        store,
        &D1RecoveryAnchorExpectation {
            operation_id: anchor_operation_id,
            evidence_hash: anchor_evidence_hash,
            output_sha256: None,
            bookmark_hash: anchor_bookmark_hash,
            catalog_hash: &import_plan.catalog_hash,
            request_hash: &anchor_request_hash,
            target_scope_hash: &target_scope_hash,
            account_id: &contract.account_id,
            profile_id: &import_plan.profile_id,
            credential_generation_id: Some(import_plan_v2.pins.credential_generation_id.as_str()),
            after: Some(prior_0142_closed_at),
            before: import_plan.created_at,
        },
    )?;
    let restore_evidence = store.read_evidence_value(restore_evidence_hash)?;
    let receipt = restore_evidence
        .pointer("/result/_cfctl")
        .or_else(|| restore_evidence.pointer("/result/result/_cfctl"))
        .ok_or_else(|| {
            CliError::Input("restore evidence omitted the exact bookmark receipt".to_owned())
        })?;
    let hash_bookmark = |value: Option<&str>| {
        value
            .map(|value| hash_value(&Value::String(value.to_owned())))
            .transpose()
    };
    let previous_hash = hash_bookmark(receipt.get("previous_bookmark").and_then(Value::as_str))?
        .ok_or_else(|| CliError::Input("restore previous bookmark is missing".to_owned()))?;
    let requested_hash = hash_bookmark(receipt.get("target_bookmark").and_then(Value::as_str))?
        .ok_or_else(|| CliError::Input("restore requested bookmark is missing".to_owned()))?;
    let observed_hash = hash_bookmark(receipt.get("returned_bookmark").and_then(Value::as_str))?
        .ok_or_else(|| CliError::Input("restore observed bookmark is missing".to_owned()))?;
    let receipt_source_operation_id = receipt.get("source_operation_id").and_then(Value::as_str);
    let receipt_source_evidence_hash = receipt.get("source_evidence_hash").and_then(Value::as_str);
    let restore_body = restore_input.body.as_ref();
    let observed_anchor_join = Mln0143RestoreAnchorJoin {
        input_source_operation_id: restore_body
            .and_then(|body| body.get("source_operation_id"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned(),
        receipt_source_operation_id: receipt_source_operation_id.unwrap_or_default().to_owned(),
        input_source_evidence_hash: restore_body
            .and_then(|body| body.get("source_evidence_hash"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned(),
        receipt_source_evidence_hash: receipt_source_evidence_hash.unwrap_or_default().to_owned(),
        input_target_bookmark_hash: restore_body
            .and_then(|body| body.get("target_bookmark"))
            .and_then(Value::as_str)
            .and_then(|bookmark| hash_value(&Value::String(bookmark.to_owned())).ok())
            .unwrap_or_default(),
        requested_bookmark_hash: requested_hash.clone(),
        observed_bookmark_hash: observed_hash.clone(),
        account_id: restore_plan.account_id.clone(),
        profile_id: restore_plan.profile_id.clone(),
        catalog_hash: restore_plan.catalog_hash.clone(),
        credential_generation_id: restore_plan_v2.pins.credential_generation_id.clone(),
        anchor_completed_at,
        restore_created_at: restore_plan.created_at,
    };
    let expected_anchor_join = Mln0143RestoreAnchorJoin {
        input_source_operation_id: anchor_operation_id.to_owned(),
        receipt_source_operation_id: anchor_operation_id.to_owned(),
        input_source_evidence_hash: anchor_evidence_hash.to_owned(),
        receipt_source_evidence_hash: anchor_evidence_hash.to_owned(),
        input_target_bookmark_hash: anchor_bookmark_hash.to_owned(),
        requested_bookmark_hash: anchor_bookmark_hash.to_owned(),
        observed_bookmark_hash: anchor_bookmark_hash.to_owned(),
        account_id: import_plan.account_id.clone(),
        profile_id: import_plan.profile_id.clone(),
        catalog_hash: import_plan.catalog_hash.clone(),
        credential_generation_id: import_plan_v2.pins.credential_generation_id.clone(),
        anchor_completed_at,
        restore_created_at: restore_plan.created_at,
    };
    let boundary_evidence_matches = restore_plan
        .transaction_artifact(TransactionStageV1::BoundaryResponsePersisted)
        .and_then(|artifact| artifact.get("apply_evidence_hash"))
        .and_then(Value::as_str)
        == Some(restore_evidence_hash);
    let exact_restore = restore_plan.capability.id == "d1-restore-exact-bookmark"
        && restore_plan.status == PlanStatus::Verified
        && restore_plan.transaction_stage == TransactionStageV1::Closed
        && restore_plan.account_id == contract.account_id
        && restore_plan.profile_id == import_plan.profile_id
        && restore_plan.catalog_hash == import_plan.catalog_hash
        && restore_plan_v2.plan.content_hash == restore_plan.content_hash
        && restore_plan_v2.pins.catalog_hash == import_plan_v2.pins.catalog_hash
        && mln_0143_restore_anchor_matches(&observed_anchor_join, &expected_anchor_join)
        && restore_input.selectors == input.selectors
        && boundary_evidence_matches
        && previous_hash == field("restore_previous_bookmark_hash")?
        && requested_hash == field("restore_requested_bookmark_hash")?
        && observed_hash == field("restore_observed_bookmark_hash")?;
    if !exact_restore {
        return Err(CliError::Input(
            "post_restore lineage does not resolve to the exact approved verified bookmark restore and import boundary"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_mln_0143_lineage_result(
    input: &CallInput,
    current: &Value,
    parents: &[(String, Value)],
) -> Result<()> {
    let Some(phase) = input
        .body
        .as_ref()
        .and_then(|body| body.get("phase"))
        .and_then(Value::as_str)
    else {
        return Ok(());
    };
    if phase == "pre_import" {
        return Ok(());
    }
    let (_, pre) = parents.first().ok_or_else(|| {
        CliError::Input("MLN 0143 post phase omitted its pre-import parent".to_owned())
    })?;
    for pointer in [
        "/projection/digest",
        "/projection/count",
        "/projection/counts_by_kind",
    ] {
        if current.pointer(pointer) != pre.pointer(pointer) {
            return Err(CliError::Input(
                "MLN 0143 evidence projection drifted from the bound pre-import baseline"
                    .to_owned(),
            ));
        }
    }
    if phase == "post_import"
        && (current.get("packet_non_target_hash") != pre.get("packet_non_target_hash")
            || current.get("packet_non_target_count") != pre.get("packet_non_target_count"))
    {
        return Err(CliError::Input(
            "MLN 0143 packet configuration drifted outside the authorized advisor delta".to_owned(),
        ));
    }
    if phase == "post_restore" {
        if current.get("packet_hash") != pre.get("packet_hash")
            || current.get("packet_count") != pre.get("packet_count")
        {
            return Err(CliError::Input(
                "MLN 0143 restored packet configuration differs from the pre-import baseline"
                    .to_owned(),
            ));
        }
        let (post_hash, post) = parents.get(1).ok_or_else(|| {
            CliError::Input("MLN 0143 post-restore omitted its post-import parent".to_owned())
        })?;
        let pre_hash = &parents[0].0;
        if post
            .pointer("/lineage/pre_import_evidence_hash")
            .and_then(Value::as_str)
            != Some(pre_hash)
            || input
                .body
                .as_ref()
                .and_then(|body| body.get("post_import_evidence_hash"))
                .and_then(Value::as_str)
                != Some(post_hash)
        {
            return Err(CliError::Input(
                "MLN 0143 post-import evidence does not name the same pre-import baseline"
                    .to_owned(),
            ));
        }
        for pointer in ["/semantic_schema_hash", "/packet_hash"] {
            if current.pointer(pointer) != pre.pointer(pointer) {
                return Err(CliError::Input(
                    "MLN 0143 restored schema or packet digest differs from the pre-import baseline"
                        .to_owned(),
                ));
            }
        }
    }
    Ok(())
}

impl ExecutedRead {
    fn without_credential(envelope: ResultEnvelopeV2) -> Self {
        Self {
            envelope,
            credential_generation_id: None,
        }
    }
}

#[expect(
    clippy::too_many_arguments,
    clippy::too_many_lines,
    reason = "read execution receives explicit catalog, selector, credential generation, private retrieval, and file-output inputs so no authority or destination is hidden in ambient state"
)]
async fn execute_read(
    store: &StateStore,
    catalog: &CatalogSnapshot,
    capability: &cfctl_core::CapabilityV1,
    input: &CallInput,
    requested_profile: Option<&str>,
    requested_account: Option<&str>,
    output_path: Option<&Path>,
    r2_credentials: Option<&R2LogRetrievalCredentials>,
) -> Result<ExecutedRead> {
    if capability.workflow.is_some() {
        return Ok(ExecutedRead::without_credential(execute_native_workflow(
            store, catalog, capability,
        )?));
    }
    match capability.adapter_status {
        AdapterStatus::DelegatedCli => {
            return execute_delegated_read(
                store,
                catalog,
                capability,
                input,
                requested_profile,
                requested_account,
            )
            .await;
        }
        AdapterStatus::GovernedUi => {
            return Ok(ExecutedRead::without_credential(execute_governed_ui_read(
                store,
                catalog,
                capability,
                input,
                requested_profile,
                requested_account,
            )?));
        }
        AdapterStatus::Blocked => {
            return Ok(ExecutedRead::without_credential(
                blocked_capability_envelope(
                    "call",
                    capability,
                    capability
                        .blocked_reason
                        .as_deref()
                        .unwrap_or("no executable adapter is available"),
                ),
            ));
        }
        AdapterStatus::Native | AdapterStatus::DynamicApi => {}
    }
    let mln_0143_parents = mln_0143_parent_manifests(store, catalog, capability, input)?;
    let profiles = ProfilesConfig::load(store)?;
    let profile = profiles.selected(requested_profile)?;
    let credential_generation_id = credential_generation_for_read(profile)?;
    let account_id = resolve_account_id(store, profile, requested_account, input)?;
    let credential = fresh_credential(profile, &platform_secrets(store)).await?;
    let executor = Executor::new(http_client()?, API_BASE_URL)?;
    let response = if capability.r2_log_retrieval.is_some() {
        let output_path = output_path.ok_or(CloudflareError::R2LogOutputFileRequired)?;
        let r2_credentials = r2_credentials.ok_or(CloudflareError::R2LogCredentialsRequired)?;
        executor
            .execute_r2_log_retrieval_to_file(
                capability,
                input,
                &credential,
                r2_credentials,
                output_path,
            )
            .await?
    } else if let Some(output_path) = output_path {
        executor
            .execute_read_to_file(capability, input, &credential, output_path)
            .await?
    } else {
        executor
            .execute_read(capability, input, &credential)
            .await?
    };
    if capability.mln_0143_data_invariants.is_some() {
        validate_mln_0143_lineage_result(input, &response.result, &mln_0143_parents)?;
    }
    let mut sanitized =
        redact_response_for_capability(capability, &serde_json::to_value(&response)?);
    if let Some(object) = sanitized.as_object_mut() {
        object.insert(
            "availability".to_owned(),
            live_read_availability(capability, &response),
        );
    }
    let evidence = store.write_evidence(EvidenceClass::LiveRead, &sanitized)?;
    let mut envelope = ResultEnvelopeV2::success("call", sanitized).with_evidence(evidence);
    envelope.capability_id = Some(capability.id.clone());
    envelope.profile_id = Some(profile.id.clone());
    envelope.account_id = account_id;
    envelope.ok = response.success;
    envelope.performed = true;
    if capability.mln_0143_data_invariants.is_some() {
        let verified = response.result.get("complete").and_then(Value::as_bool) == Some(true)
            && response
                .result
                .pointer("/query/bounds_saturated")
                .and_then(Value::as_bool)
                == Some(false);
        envelope.verification.state = if verified {
            VerificationState::Passed
        } else {
            VerificationState::Failed
        };
        envelope.verification.basis =
            Some("closed MLN 0143 phase assertions and bounded completeness manifest".to_owned());
    } else if capability.d1_full_export.is_some() {
        let verified = response
            .result
            .pointer("/output_file/hash_matches")
            .and_then(Value::as_bool)
            == Some(true)
            && response
                .result
                .pointer("/output_file/exists")
                .and_then(Value::as_bool)
                == Some(true);
        envelope.verification.state = if verified {
            VerificationState::Passed
        } else {
            VerificationState::Failed
        };
        envelope.verification.basis =
            Some("same output file exists and its SHA-256 matches the streamed receipt".to_owned());
    } else {
        envelope.verification.state = VerificationState::NotApplicable;
        envelope.verification.basis = Some(format!(
            "live Cloudflare read pinned to catalog {}",
            catalog.schema_hash
        ));
    }
    // A non-2xx Cloudflare response is `Ok` at the transport layer but a failure
    // to the agent. Without an ErrorV1 it would surface as `ok:false` with no
    // guidance; attach a status-specific next step so the agent knows the move.
    if !response.success {
        let (code, next_step) = live_read_failure_guidance(response.status);
        envelope.error = Some(ErrorV1 {
            code: code.to_owned(),
            message: format!(
                "the Cloudflare read did not succeed (HTTP {}) for capability `{}`",
                response.status, capability.id
            ),
            next_step: Some(next_step),
        });
    }
    Ok(ExecutedRead {
        envelope,
        credential_generation_id: Some(credential_generation_id),
    })
}

async fn execute_delegated_read(
    store: &StateStore,
    catalog: &CatalogSnapshot,
    capability: &CapabilityV1,
    input: &CallInput,
    requested_profile: Option<&str>,
    requested_account: Option<&str>,
) -> Result<ExecutedRead> {
    let profiles = ProfilesConfig::load(store)?;
    let profile = profiles.selected(requested_profile)?;
    let credential_generation_id = credential_generation_for_read(profile)?;
    let account_id = resolve_account_id(store, profile, requested_account, input)?;
    let credential = fresh_credential(profile, &platform_secrets(store)).await?;
    let receipt = run_delegated_cli(
        capability,
        input,
        &credential,
        account_id.as_deref(),
        &store.paths().cache_dir,
    )
    .await?;
    let evidence = store.write_evidence(EvidenceClass::LiveRead, &receipt)?;
    Ok(ExecutedRead {
        envelope: delegated_read_envelope(
            &catalog.schema_hash,
            &capability.id,
            &profile.id,
            account_id,
            receipt,
            evidence,
        ),
        credential_generation_id: Some(credential_generation_id),
    })
}

fn credential_generation_for_read(profile: &ProfileMetadata) -> Result<String> {
    let generation = profile.credential_generation_id.as_deref().ok_or_else(|| {
        CliError::Input(format!(
            "profile `{}` has no credential generation; re-import or log in again",
            profile.id
        ))
    })?;
    Uuid::parse_str(generation).map_err(|_| {
        CliError::Input(format!(
            "profile `{}` has an invalid credential generation; re-import or log in again",
            profile.id
        ))
    })?;
    Ok(generation.to_owned())
}

fn delegated_read_envelope(
    catalog_hash: &str,
    capability_id: &str,
    profile_id: &str,
    account_id: Option<String>,
    receipt: Value,
    evidence: EvidenceV1,
) -> ResultEnvelopeV2 {
    let success = receipt
        .get("success")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let mut envelope = ResultEnvelopeV2::success("call", receipt).with_evidence(evidence);
    envelope.ok = success;
    envelope.performed = true;
    envelope.capability_id = Some(capability_id.to_owned());
    envelope.profile_id = Some(profile_id.to_owned());
    envelope.account_id = account_id;
    envelope.verification.state = VerificationState::NotApplicable;
    envelope.verification.basis = Some(format!(
        "governed CLI read pinned to catalog {catalog_hash}"
    ));
    envelope
}

fn apply_operational_proof_index_result(envelope: &mut ResultEnvelopeV2, proof_result: Result<()>) {
    if let Err(error) = proof_result {
        envelope.ok = false;
        envelope.error = Some(ErrorV1 {
            code: "CFCTL_OPERATIONAL_PROOF_INDEX_FAILED".to_owned(),
            message: format!(
                "the bounded read completed, but its operational-proof index row was not durably recorded: {error}"
            ),
            next_step: Some(
                "Preserve the live-read evidence receipt, repair the local cfctl data directory, and repeat the bounded read before relying on workflow freshness or catalog operational-proof coverage."
                    .to_owned(),
            ),
        });
    }
}

fn execute_governed_ui_read(
    store: &StateStore,
    catalog: &CatalogSnapshot,
    capability: &CapabilityV1,
    input: &CallInput,
    requested_profile: Option<&str>,
    requested_account: Option<&str>,
) -> Result<ResultEnvelopeV2> {
    let profiles = ProfilesConfig::load(store)?;
    let profile = profiles.selected(requested_profile)?;
    let account_id = resolve_account_id(store, profile, requested_account, input)?;
    let agent = configured_agent()?;
    let target = json!({
        "capability_id": capability.id,
        "url": capability.path,
        "selectors": input.selectors,
        "query": input.query,
        "catalog_hash": catalog.schema_hash,
    });
    let action = build_ui_action(
        agent,
        None,
        account_id.as_deref(),
        target,
        &format!(
            "Observe only: {}. Use the authenticated Cloudflare dashboard only after confirming API and CLI coverage cannot answer it. Capture redacted before evidence and do not mutate state.",
            capability.title
        ),
        false,
    )?;
    let evidence =
        store.write_evidence(EvidenceClass::AgentAction, &serde_json::to_value(&action)?)?;
    let mut envelope = ResultEnvelopeV2::success(
        "call",
        json!({
            "agent_action": action,
            "performed": false,
            "message": "Governed UI observation handoff created. The action is target-bound evidence, not authority or proof that the UI was inspected."
        }),
    )
    .with_evidence(evidence);
    envelope.capability_id = Some(capability.id.clone());
    envelope.profile_id = Some(profile.id.clone());
    envelope.account_id = account_id;
    envelope.verification.state = VerificationState::Pending;
    envelope.verification.basis =
        Some("awaiting hash-bound before/after UI evidence from the configured agent".to_owned());
    Ok(envelope)
}

async fn execute_delegated_plan(
    store: &StateStore,
    plan: &mut PlanV1,
    input: &CallInput,
    credential: &AuthCredential,
    secrets: &dyn SecretStore,
) -> Result<ResultEnvelopeV2> {
    let receipt = if plan.capability.id == "cloudflared.tunnel" {
        run_quick_tunnel(store, plan, input).await?
    } else {
        run_delegated_cli(
            &plan.capability,
            input,
            credential,
            Some(&plan.account_id),
            &store.paths().cache_dir,
        )
        .await?
    };
    let success = receipt
        .get("success")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let evidence = store.write_evidence(EvidenceClass::Apply, &receipt)?;
    persist_transaction_stage_with_artifact(
        store,
        plan,
        TransactionStageV1::BoundaryResponsePersisted,
        json!({
            "adapter": "delegated_cli",
            "apply_evidence_hash": evidence.content_hash,
            "success": success,
        }),
    )?;
    persist_secret_lifecycle(store, plan, success, Some(&receipt), secrets)?;
    if !success {
        // A delegated CLI can fail after applying part of a mutation (Wrangler
        // may upload and promote a Worker before a trigger update fails). Keep
        // the transaction open for rectification and report that the boundary
        // was performed; a non-zero exit is not proof of zero side effects.
        plan.status = PlanStatus::RectificationRequired;
        store.save_plan(plan)?;
        return Ok(delegated_cli_failure_envelope(plan, receipt, evidence));
    }

    persist_transaction_stage(
        store,
        plan,
        TransactionStageV1::VerificationAttemptPersisted,
    )?;
    let verification = verify_delegated_cli_plan(store, plan, input, &receipt, credential).await;
    let verification_evidence =
        store.write_evidence(EvidenceClass::PostChangeVerification, &verification)?;
    let passed = verification
        .get("passed")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let basis = verification
        .get("basis")
        .and_then(Value::as_str)
        .unwrap_or("delegated CLI verification did not return a basis")
        .to_owned();
    plan.status = if passed {
        PlanStatus::Verified
    } else {
        PlanStatus::RectificationRequired
    };
    persist_transaction_stage_with_artifact(
        store,
        plan,
        TransactionStageV1::VerificationResponsePersisted,
        json!({
            "state": if passed { "passed" } else { "failed" },
            "basis_hash": hash_value(&json!(basis))?,
            "evidence_hash": verification_evidence.content_hash,
        }),
    )?;
    if passed {
        persist_transaction_stage(store, plan, TransactionStageV1::Closed)?;
    } else {
        store.save_plan(plan)?;
    }

    let mut envelope = ResultEnvelopeV2::success("plans run", receipt).with_evidence(evidence);
    envelope.evidence.push(verification_evidence);
    envelope.ok = passed;
    envelope.performed = true;
    envelope.operation_id = Some(plan.operation_id.clone());
    envelope.capability_id = Some(plan.capability.id.clone());
    envelope.profile_id = Some(plan.profile_id.clone());
    envelope.account_id = Some(plan.account_id.clone());
    envelope.policy_decision = Some(plan.policy.clone());
    envelope.verification.state = if passed {
        VerificationState::Passed
    } else {
        VerificationState::Failed
    };
    envelope.verification.basis = Some(basis.clone());
    if !passed {
        envelope.error = Some(ErrorV1 {
            code: "CFCTL_VERIFICATION_FAILED".to_owned(),
            message: basis,
            next_step: Some(format!(
                "Do not replay the deployment; inspect live state with `cfctl plans rectify {}`.",
                plan.operation_id
            )),
        });
    }
    Ok(envelope)
}

fn delegated_cli_failure_envelope(
    plan: &PlanV1,
    receipt: Value,
    evidence: EvidenceV1,
) -> ResultEnvelopeV2 {
    let mut envelope = ResultEnvelopeV2::success("plans run", receipt).with_evidence(evidence);
    envelope.ok = false;
    envelope.performed = true;
    envelope.operation_id = Some(plan.operation_id.clone());
    envelope.capability_id = Some(plan.capability.id.clone());
    envelope.profile_id = Some(plan.profile_id.clone());
    envelope.account_id = Some(plan.account_id.clone());
    envelope.policy_decision = Some(plan.policy.clone());
    envelope.verification.state = VerificationState::Failed;
    envelope.verification.basis =
        Some("the governed subprocess returned a failing exit status".to_owned());
    envelope.error = Some(ErrorV1 {
        code: "CFCTL_DELEGATED_CLI_FAILED".to_owned(),
        message:
            "the governed subprocess returned a failing exit status; partial mutation is possible"
                .to_owned(),
        next_step: Some(format!(
            "Do not replay automatically; inspect the receipt and use `cfctl plans rectify {}`.",
            plan.operation_id
        )),
    });
    envelope
}

async fn verify_delegated_cli_plan(
    store: &StateStore,
    plan: &PlanV1,
    input: &CallInput,
    receipt: &Value,
    credential: &AuthCredential,
) -> Value {
    if plan.capability.verification.strategy == "trycloudflare_https_url_reaches_reviewed_origin" {
        return verify_quick_tunnel_plan(input, receipt).await;
    }
    if plan.capability.verification.strategy
        == "wrangler_pages_production_deployment_reports_commit_hash"
    {
        let Some(project_name) = input
            .query
            .get("project_name")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
        else {
            return json!({
                "passed": false,
                "basis": "the Pages deployment plan omitted its required project_name selector",
            });
        };
        let Some(branch) = input
            .query
            .get("branch")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
        else {
            return json!({
                "passed": false,
                "basis": "the Pages deployment plan omitted its required branch selector",
                "project_name": project_name,
            });
        };
        let Some(commit_hash) = input
            .query
            .get("commit_hash")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
        else {
            return json!({
                "passed": false,
                "basis": "the Pages deployment plan omitted its required commit_hash selector",
                "project_name": project_name,
                "branch": branch,
            });
        };
        return verify_wrangler_pages_production_deployment(
            project_name,
            branch,
            commit_hash,
            credential,
            &plan.account_id,
            &store.paths().cache_dir,
        )
        .await;
    }

    if plan.capability.verification.strategy == "wrangler_worker_version_reports_expected_message" {
        return verify_wrangler_worker_version_upload_plan(store, plan, input, receipt, credential)
            .await;
    }

    if plan.capability.verification.strategy
        == "wrangler_worker_versions_deployment_reports_expected_traffic"
    {
        return verify_wrangler_worker_versions_deploy_plan(store, plan, input, credential).await;
    }

    if plan.capability.verification.strategy
        != "wrangler_deployment_status_reports_promoted_version"
    {
        return json!({
            "passed": false,
            "basis": format!(
                "delegated CLI verification strategy `{}` is not implemented",
                plan.capability.verification.strategy
            ),
        });
    }
    let Some(version_id) = wrangler_deploy_version_id(receipt) else {
        return json!({
            "passed": false,
            "basis": "Wrangler reported deploy success without a parseable Current Version ID",
        });
    };
    let Some(config) = input
        .query
        .get("config")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
    else {
        return json!({
            "passed": false,
            "basis": "the deployment plan omitted its required Wrangler config selector",
            "version_id": version_id,
        });
    };

    verify_wrangler_deployment_status(
        config,
        &version_id,
        credential,
        &plan.account_id,
        &store.paths().cache_dir,
    )
    .await
}

async fn verify_wrangler_worker_version_upload_plan(
    store: &StateStore,
    plan: &PlanV1,
    input: &CallInput,
    receipt: &Value,
    credential: &AuthCredential,
) -> Value {
    let Some(version_id) = wrangler_worker_version_id(receipt) else {
        return json!({
            "passed": false,
            "basis": "Wrangler reported upload success without a parseable Worker Version ID",
        });
    };
    let Some(config) = input.query.get("config").and_then(Value::as_str) else {
        return json!({
            "passed": false,
            "basis": "the version upload plan omitted its required Wrangler config selector",
            "version_id": version_id,
        });
    };
    let Some(message) = input.query.get("message").and_then(Value::as_str) else {
        return json!({
            "passed": false,
            "basis": "the version upload plan omitted its required message selector",
            "version_id": version_id,
        });
    };
    verify_wrangler_worker_version(
        config,
        &version_id,
        message,
        credential,
        &plan.account_id,
        &store.paths().cache_dir,
    )
    .await
}

async fn verify_wrangler_worker_versions_deploy_plan(
    store: &StateStore,
    plan: &PlanV1,
    input: &CallInput,
    credential: &AuthCredential,
) -> Value {
    let Some(version_id) = input
        .query
        .get("argument")
        .and_then(Value::as_str)
        .and_then(wrangler_versions_deploy_version_id)
    else {
        return json!({
            "passed": false,
            "basis": "the versions deployment plan did not contain exactly one UUID@100 traffic target",
        });
    };
    let Some(config) = input.query.get("config").and_then(Value::as_str) else {
        return json!({
            "passed": false,
            "basis": "the versions deployment plan omitted its required Wrangler config selector",
            "version_id": version_id,
        });
    };
    verify_wrangler_deployment_status(
        config,
        &version_id,
        credential,
        &plan.account_id,
        &store.paths().cache_dir,
    )
    .await
}

async fn verify_wrangler_pages_production_deployment(
    project_name: &str,
    branch: &str,
    commit_hash: &str,
    credential: &AuthCredential,
    account_id: &str,
    cache_dir: &Path,
) -> Value {
    let mut command = ProcessCommand::new("wrangler");
    command
        .args([
            "pages",
            "deployment",
            "list",
            "--project-name",
            project_name,
            "--environment",
            "production",
            "--json",
        ])
        .env_clear()
        .env("PATH", env::var_os("PATH").unwrap_or_default())
        .env("HOME", env::var_os("HOME").unwrap_or_default())
        .env("NO_COLOR", "1")
        .kill_on_drop(true)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for (name, value) in governed_cli_workspace_env("wrangler", Some(account_id), cache_dir) {
        command.env(name, value);
    }
    match credential {
        AuthCredential::Bearer { token } => {
            command.env("CLOUDFLARE_API_TOKEN", token);
        }
        AuthCredential::GlobalKey { email, key } => {
            command
                .env("CLOUDFLARE_EMAIL", email)
                .env("CLOUDFLARE_API_KEY", key);
        }
    }
    let output = match tokio::time::timeout(Duration::from_mins(2), command.output()).await {
        Ok(Ok(output)) => output,
        Ok(Err(error)) => {
            return json!({
                "passed": false,
                "basis": format!("Wrangler Pages deployment verification could not start: {error}"),
                "project_name": project_name,
                "branch": branch,
                "commit_hash": commit_hash,
            });
        }
        Err(_) => {
            return json!({
                "passed": false,
                "basis": "Wrangler Pages deployment verification timed out",
                "project_name": project_name,
                "branch": branch,
                "commit_hash": commit_hash,
            });
        }
    };
    let stdout = redact_subprocess_text(&String::from_utf8_lossy(&output.stdout), credential);
    let stderr = redact_subprocess_text(&String::from_utf8_lossy(&output.stderr), credential);
    if !output.status.success() {
        return json!({
            "passed": false,
            "basis": "Wrangler Pages deployment verification returned a failing exit status",
            "project_name": project_name,
            "branch": branch,
            "commit_hash": commit_hash,
            "exit_status": output.status.code(),
            "stdout": stdout,
            "stderr": stderr,
        });
    }
    let deployments = match serde_json::from_str::<Value>(stdout.trim()) {
        Ok(deployments) => deployments,
        Err(error) => {
            return json!({
                "passed": false,
                "basis": format!("Wrangler Pages deployment output was not JSON: {error}"),
                "project_name": project_name,
                "branch": branch,
                "commit_hash": commit_hash,
                "stdout": stdout,
                "stderr": stderr,
            });
        }
    };
    let passed =
        wrangler_pages_deployment_has_commit(&deployments, project_name, branch, commit_hash);
    json!({
        "passed": passed,
        "basis": if passed {
            format!("Wrangler Pages production deployment for {project_name} reports successful commit {commit_hash} on branch {branch}")
        } else {
            format!("Wrangler Pages production deployments for {project_name} do not report successful commit {commit_hash} on branch {branch}")
        },
        "project_name": project_name,
        "branch": branch,
        "commit_hash": commit_hash,
        "readback": deployments,
        "stderr": stderr,
    })
}

fn wrangler_pages_deployment_has_commit(
    value: &Value,
    expected_project_name: &str,
    expected_branch: &str,
    expected_commit_hash: &str,
) -> bool {
    match value {
        Value::Array(items) => items.iter().any(|item| {
            wrangler_pages_deployment_has_commit(
                item,
                expected_project_name,
                expected_branch,
                expected_commit_hash,
            )
        }),
        Value::Object(fields) => {
            let matches = fields.get("project_name").and_then(Value::as_str)
                == Some(expected_project_name)
                && fields.get("environment").and_then(Value::as_str) == Some("production")
                && value
                    .pointer("/deployment_trigger/metadata/branch")
                    .and_then(Value::as_str)
                    == Some(expected_branch)
                && value
                    .pointer("/deployment_trigger/metadata/commit_hash")
                    .and_then(Value::as_str)
                    == Some(expected_commit_hash)
                && value
                    .pointer("/latest_stage/status")
                    .and_then(Value::as_str)
                    == Some("success");
            matches
                || fields.values().any(|nested| {
                    wrangler_pages_deployment_has_commit(
                        nested,
                        expected_project_name,
                        expected_branch,
                        expected_commit_hash,
                    )
                })
        }
        _ => false,
    }
}

/// Wrangler discovers dotenv credentials relative to its process working
/// directory. A plan reviewed against one Worker config could therefore pass
/// its account checks and then resolve a different account token when cfctl
/// ran from somewhere else, so every governed Wrangler subprocess is pinned to
/// the reviewed config's own directory.
fn wrangler_config_directory(config: &str) -> Result<PathBuf> {
    let parent = Path::new(config)
        .parent()
        .ok_or_else(|| CliError::Input("Wrangler config path has no parent".to_owned()))?;
    if parent.as_os_str().is_empty() {
        Ok(PathBuf::from("."))
    } else {
        Ok(parent.to_path_buf())
    }
}

async fn verify_wrangler_deployment_status(
    config: &str,
    version_id: &str,
    credential: &AuthCredential,
    account_id: &str,
    cache_dir: &Path,
) -> Value {
    let working_directory = match wrangler_config_directory(config) {
        Ok(directory) => directory,
        Err(error) => {
            return json!({
                "passed": false,
                "basis": format!("Wrangler deployment-status verification could not resolve the reviewed config directory: {error}"),
                "version_id": version_id,
            });
        }
    };
    let mut command = ProcessCommand::new("wrangler");
    command
        .args(["deployments", "status", "--config", config, "--json"])
        .current_dir(working_directory)
        .env_clear()
        .env("PATH", env::var_os("PATH").unwrap_or_default())
        .env("HOME", env::var_os("HOME").unwrap_or_default())
        .env("NO_COLOR", "1")
        .kill_on_drop(true)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for (name, value) in governed_cli_workspace_env("wrangler", Some(account_id), cache_dir) {
        command.env(name, value);
    }
    match credential {
        AuthCredential::Bearer { token } => {
            command.env("CLOUDFLARE_API_TOKEN", token);
        }
        AuthCredential::GlobalKey { email, key } => {
            command
                .env("CLOUDFLARE_EMAIL", email)
                .env("CLOUDFLARE_API_KEY", key);
        }
    }
    let output = match tokio::time::timeout(Duration::from_mins(2), command.output()).await {
        Ok(Ok(output)) => output,
        Ok(Err(error)) => {
            return json!({
                "passed": false,
                "basis": format!("Wrangler deployment-status verification could not start: {error}"),
                "version_id": version_id,
            });
        }
        Err(_) => {
            return json!({
                "passed": false,
                "basis": "Wrangler deployment-status verification timed out",
                "version_id": version_id,
            });
        }
    };
    let stdout = redact_subprocess_text(&String::from_utf8_lossy(&output.stdout), credential);
    let stderr = redact_subprocess_text(&String::from_utf8_lossy(&output.stderr), credential);
    if !output.status.success() {
        return json!({
            "passed": false,
            "basis": "Wrangler deployment-status verification returned a failing exit status",
            "version_id": version_id,
            "exit_status": output.status.code(),
            "stdout": stdout,
            "stderr": stderr,
        });
    }
    let status = match serde_json::from_str::<Value>(stdout.trim()) {
        Ok(status) => status,
        Err(error) => {
            return json!({
                "passed": false,
                "basis": format!("Wrangler deployment-status output was not JSON: {error}"),
                "version_id": version_id,
                "stdout": stdout,
                "stderr": stderr,
            });
        }
    };
    let passed = wrangler_status_has_promoted_version(&status, version_id);
    json!({
        "passed": passed,
        "basis": if passed {
            format!("Wrangler production deployment reports promoted version {version_id}")
        } else {
            format!("Wrangler production deployment does not report version {version_id} at 100 percent")
        },
        "version_id": version_id,
        "readback": status,
        "stderr": stderr,
    })
}

async fn verify_wrangler_worker_version(
    config: &str,
    version_id: &str,
    expected_message: &str,
    credential: &AuthCredential,
    account_id: &str,
    cache_dir: &Path,
) -> Value {
    let working_directory = match wrangler_config_directory(config) {
        Ok(directory) => directory,
        Err(error) => {
            return json!({
                "passed": false,
                "basis": format!("Wrangler version verification could not resolve the reviewed config directory: {error}"),
                "version_id": version_id,
            });
        }
    };
    let mut command = ProcessCommand::new("wrangler");
    command
        .args(["versions", "view", version_id, "--config", config, "--json"])
        .current_dir(working_directory)
        .env_clear()
        .env("PATH", env::var_os("PATH").unwrap_or_default())
        .env("HOME", env::var_os("HOME").unwrap_or_default())
        .env("NO_COLOR", "1")
        .kill_on_drop(true)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for (name, value) in governed_cli_workspace_env("wrangler", Some(account_id), cache_dir) {
        command.env(name, value);
    }
    match credential {
        AuthCredential::Bearer { token } => {
            command.env("CLOUDFLARE_API_TOKEN", token);
        }
        AuthCredential::GlobalKey { email, key } => {
            command
                .env("CLOUDFLARE_EMAIL", email)
                .env("CLOUDFLARE_API_KEY", key);
        }
    }
    let output = match tokio::time::timeout(Duration::from_mins(2), command.output()).await {
        Ok(Ok(output)) => output,
        Ok(Err(error)) => {
            return json!({
                "passed": false,
                "basis": format!("Wrangler version verification could not start: {error}"),
                "version_id": version_id,
            });
        }
        Err(_) => {
            return json!({
                "passed": false,
                "basis": "Wrangler version verification timed out",
                "version_id": version_id,
            });
        }
    };
    let stdout = redact_subprocess_text(&String::from_utf8_lossy(&output.stdout), credential);
    let stderr = redact_subprocess_text(&String::from_utf8_lossy(&output.stderr), credential);
    if !output.status.success() {
        return json!({
            "passed": false,
            "basis": "Wrangler version verification returned a failing exit status",
            "version_id": version_id,
            "exit_status": output.status.code(),
            "stdout": stdout,
            "stderr": stderr,
        });
    }
    let version = match serde_json::from_str::<Value>(stdout.trim()) {
        Ok(version) => version,
        Err(error) => {
            return json!({
                "passed": false,
                "basis": format!("Wrangler version output was not JSON: {error}"),
                "version_id": version_id,
                "stdout": stdout,
                "stderr": stderr,
            });
        }
    };
    let passed = wrangler_version_readback_matches(&version, version_id, expected_message);
    json!({
        "passed": passed,
        "basis": if passed {
            format!("Wrangler reports uploaded version {version_id} with the reviewed message")
        } else {
            format!("Wrangler version readback did not bind {version_id} to the reviewed message")
        },
        "version_id": version_id,
        "readback": version,
        "stderr": stderr,
    })
}

fn wrangler_deploy_version_id(receipt: &Value) -> Option<String> {
    receipt
        .get("stdout")
        .and_then(Value::as_str)?
        .lines()
        .find_map(|line| line.trim().strip_prefix("Current Version ID:"))
        .map(str::trim)
        .filter(|value| {
            !value.is_empty()
                && value
                    .chars()
                    .all(|character| character.is_ascii_alphanumeric() || character == '-')
        })
        .map(str::to_owned)
}

fn wrangler_worker_version_id(receipt: &Value) -> Option<String> {
    receipt
        .get("stdout")
        .and_then(Value::as_str)?
        .lines()
        .find_map(|line| line.trim().strip_prefix("Worker Version ID:"))
        .map(str::trim)
        .filter(|value| Uuid::parse_str(value).is_ok())
        .map(str::to_owned)
}

fn wrangler_versions_deploy_version_id(spec: &str) -> Option<String> {
    let (version_id, percentage) = spec.split_once('@')?;
    if percentage == "100" && Uuid::parse_str(version_id).is_ok() {
        Some(version_id.to_owned())
    } else {
        None
    }
}

fn wrangler_version_readback_matches(
    value: &Value,
    expected_version_id: &str,
    expected_message: &str,
) -> bool {
    value.get("id").and_then(Value::as_str) == Some(expected_version_id)
        && value
            .pointer("/annotations/workers~1message")
            .and_then(Value::as_str)
            == Some(expected_message)
}

fn wrangler_status_has_promoted_version(value: &Value, expected_version_id: &str) -> bool {
    match value {
        Value::Array(items) => items
            .iter()
            .any(|item| wrangler_status_has_promoted_version(item, expected_version_id)),
        Value::Object(fields) => {
            let matches = fields
                .get("version_id")
                .and_then(Value::as_str)
                .is_some_and(|version_id| version_id == expected_version_id);
            let promoted = fields.get("percentage").is_some_and(|percentage| {
                percentage
                    .as_f64()
                    .is_some_and(|percentage| (percentage - 100.0).abs() < f64::EPSILON)
                    || percentage.as_str() == Some("100")
            });
            (matches && promoted)
                || fields
                    .values()
                    .any(|value| wrangler_status_has_promoted_version(value, expected_version_id))
        }
        _ => false,
    }
}

fn execute_governed_ui_plan(
    store: &StateStore,
    plan: &mut PlanV1,
    input: &CallInput,
    secrets: &dyn SecretStore,
) -> Result<ResultEnvelopeV2> {
    let agent = configured_agent()?;
    let target = json!({
        "capability_id": plan.capability.id,
        "url": plan.capability.path,
        "selectors": input.selectors,
        "query": input.query,
        "body": input.body.as_ref().map(redact_json),
        "plan_hash": plan.content_hash,
    });
    let action = build_ui_action(
        agent,
        Some(&plan.operation_id),
        Some(&plan.account_id),
        target,
        &format!(
            "Execute only the exact approved Cloudflare dashboard action: {}. Bind the session to account {}, capture redacted before/after evidence, and stop on any target or content drift.",
            plan.capability.title, plan.account_id
        ),
        true,
    )?;
    let evidence =
        store.write_evidence(EvidenceClass::AgentAction, &serde_json::to_value(&action)?)?;
    plan.status = PlanStatus::RectificationRequired;
    persist_transaction_stage_with_artifact(
        store,
        plan,
        TransactionStageV1::BoundaryResponsePersisted,
        json!({
            "adapter": "governed_ui",
            "agent_action_evidence_hash": evidence.content_hash,
            "performed": false,
            "success": false,
        }),
    )?;
    persist_secret_lifecycle(store, plan, false, None, secrets)?;
    let mut envelope = ResultEnvelopeV2::success(
        "plans run",
        json!({
            "agent_action": action,
            "performed": false,
            "message": "Approved UI action handed off. cfctl does not claim the dashboard change was performed until hash-bound before/after evidence is returned."
        }),
    )
    .with_evidence(evidence);
    envelope.performed = false;
    envelope.operation_id = Some(plan.operation_id.clone());
    envelope.capability_id = Some(plan.capability.id.clone());
    envelope.profile_id = Some(plan.profile_id.clone());
    envelope.account_id = Some(plan.account_id.clone());
    envelope.policy_decision = Some(plan.policy.clone());
    envelope.verification.state = VerificationState::Pending;
    envelope.verification.basis =
        Some("awaiting hash-bound governed UI completion evidence".to_owned());
    Ok(envelope)
}

async fn run_delegated_cli(
    capability: &CapabilityV1,
    input: &CallInput,
    credential: &AuthCredential,
    account_id: Option<&str>,
    cache_dir: &Path,
) -> Result<Value> {
    let mut path_parts = capability.path.split_whitespace();
    let program = path_parts
        .next()
        .ok_or_else(|| CliError::Input("delegated capability has no program".to_owned()))?;
    if !matches!(program, "wrangler" | "cloudflared") {
        return Err(CliError::Input(format!(
            "delegated program `{program}` is not governed by cfctl"
        )));
    }
    let mut command = ProcessCommand::new(program);
    command.args(path_parts);
    if let Some(config) = input
        .query
        .get("config")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
    {
        command.current_dir(wrangler_config_directory(config)?);
    }
    append_cli_input(&mut command, &input.selectors)?;
    append_cli_input(&mut command, &input.query)?;
    if input.body.is_some() {
        return Err(CliError::Input(
            "delegated CLI request bodies need a capability-specific native adapter".to_owned(),
        ));
    }
    command
        .env_clear()
        .env("PATH", env::var_os("PATH").unwrap_or_default())
        .env("HOME", env::var_os("HOME").unwrap_or_default())
        .env("NO_COLOR", "1")
        .kill_on_drop(true)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for (name, value) in governed_cli_workspace_env(program, account_id, cache_dir) {
        command.env(name, value);
    }
    match credential {
        AuthCredential::Bearer { token } => {
            command.env("CLOUDFLARE_API_TOKEN", token);
        }
        AuthCredential::GlobalKey { email, key } => {
            command
                .env("CLOUDFLARE_EMAIL", email)
                .env("CLOUDFLARE_API_KEY", key);
        }
    }
    let label = capability.path.clone();
    let output = tokio::time::timeout(Duration::from_mins(2), command.output())
        .await
        .map_err(|_| CliError::SubprocessTimeout(label.clone()))?
        .map_err(|source| cli_io(Path::new(program), source))?;
    let stdout = redact_subprocess_text(&String::from_utf8_lossy(&output.stdout), credential);
    let stderr = redact_subprocess_text(&String::from_utf8_lossy(&output.stderr), credential);
    Ok(json!({
        "adapter": "delegated_cli",
        "command": capability.path,
        "exit_status": output.status.code(),
        "success": output.status.success(),
        "stdout": stdout,
        "stderr": stderr,
        "credential_environment": match credential {
            AuthCredential::Bearer { .. } => ["CLOUDFLARE_API_TOKEN"].as_slice(),
            AuthCredential::GlobalKey { .. } => ["CLOUDFLARE_EMAIL", "CLOUDFLARE_API_KEY"].as_slice(),
        },
    }))
}

async fn run_quick_tunnel(store: &StateStore, plan: &PlanV1, input: &CallInput) -> Result<Value> {
    let (origin, health_path) = quick_tunnel_request(input)?;
    let runtime_dir = store
        .paths()
        .data_dir
        .join("quick-tunnels")
        .join(&plan.operation_id);
    fs::create_dir_all(&runtime_dir).map_err(|source| CliError::Io {
        path: runtime_dir.display().to_string(),
        source,
    })?;
    let log_path = runtime_dir.join("cloudflared.log");
    let mut child = spawn_quick_tunnel_process(&origin, &runtime_dir, &log_path)?;
    let Some(pid) = child.id() else {
        return Err(CliError::Input(
            "cloudflared started without an observable process id".to_owned(),
        ));
    };
    let started_at = Utc::now().to_rfc3339();
    let deadline = tokio::time::Instant::now() + Duration::from_secs(30);

    loop {
        let log_text = fs::read_to_string(&log_path).unwrap_or_default();
        if let Some(public_url) = trycloudflare_public_url(&log_text) {
            return Ok(json!({
                "adapter": "delegated_cli",
                "command": "cloudflared tunnel --url [reviewed-loopback-origin]",
                "success": true,
                "exit_status": Value::Null,
                "origin_url": origin,
                "health_path": health_path,
                "public_url": public_url,
                "pid": pid,
                "started_at": started_at,
                "log_path": log_path,
                "credential_environment": [],
            }));
        }
        match child.try_wait() {
            Ok(Some(status)) => {
                return Ok(json!({
                    "adapter": "delegated_cli",
                    "command": "cloudflared tunnel --url [reviewed-loopback-origin]",
                    "success": false,
                    "exit_status": status.code(),
                    "origin_url": origin,
                    "health_path": health_path,
                    "pid": pid,
                    "started_at": started_at,
                    "log_path": log_path,
                    "stderr": log_text,
                    "credential_environment": [],
                }));
            }
            Ok(None) => {}
            Err(source) => {
                terminate_quick_tunnel(&mut child).await;
                return Err(CliError::Io {
                    path: format!("cloudflared process {pid}"),
                    source,
                });
            }
        }
        if tokio::time::Instant::now() >= deadline {
            terminate_quick_tunnel(&mut child).await;
            return Ok(json!({
                "adapter": "delegated_cli",
                "command": "cloudflared tunnel --url [reviewed-loopback-origin]",
                "success": false,
                "exit_status": Value::Null,
                "origin_url": origin,
                "health_path": health_path,
                "pid": pid,
                "started_at": started_at,
                "log_path": log_path,
                "stderr": log_text,
                "failure": "cloudflared did not report a TryCloudflare URL within 30 seconds",
                "credential_environment": [],
            }));
        }
        tokio::time::sleep(Duration::from_millis(250)).await;
    }
}

fn quick_tunnel_request(input: &CallInput) -> Result<(String, Option<String>)> {
    let origin = input
        .query
        .get("url")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("quick tunnel requires query control `url`".to_owned()))
        .and_then(validated_quick_tunnel_origin)?;
    let health_path = input
        .query
        .get("health_path")
        .and_then(Value::as_str)
        .map(str::to_owned);
    quick_tunnel_verification_url(
        "https://contract-check.trycloudflare.com",
        health_path.as_deref(),
    )?;
    Ok((origin, health_path))
}

fn spawn_quick_tunnel_process(
    origin: &str,
    runtime_dir: &Path,
    log_path: &Path,
) -> Result<tokio::process::Child> {
    let log = secure_create_new(log_path)?;
    let stderr = log.try_clone().map_err(|source| CliError::Io {
        path: log_path.display().to_string(),
        source,
    })?;
    let mut command = ProcessCommand::new("cloudflared");
    command
        .args(["tunnel", "--url", origin])
        .env_clear()
        .env("PATH", env::var_os("PATH").unwrap_or_default())
        .env("HOME", runtime_dir)
        .env("NO_COLOR", "1")
        .stdin(Stdio::null())
        .stdout(Stdio::from(log))
        .stderr(Stdio::from(stderr));
    command.spawn().map_err(|source| CliError::Io {
        path: "cloudflared".to_owned(),
        source,
    })
}

async fn terminate_quick_tunnel(child: &mut tokio::process::Child) {
    let _ = child.kill().await;
    let _ = child.wait().await;
}

fn secure_create_new(path: &Path) -> Result<fs::File> {
    let mut options = OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    options.mode(0o600);
    options.open(path).map_err(|source| CliError::Io {
        path: path.display().to_string(),
        source,
    })
}

fn validated_quick_tunnel_origin(raw: &str) -> Result<String> {
    let parsed = url::Url::parse(raw)
        .map_err(|error| CliError::Input(format!("invalid quick tunnel origin URL: {error}")))?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err(CliError::Input(
            "quick tunnel origin must use http or https".to_owned(),
        ));
    }
    if !matches!(parsed.host_str(), Some("127.0.0.1" | "localhost" | "::1")) {
        return Err(CliError::Input(
            "quick tunnel origin must resolve to explicit loopback".to_owned(),
        ));
    }
    if parsed.port().is_none() {
        return Err(CliError::Input(
            "quick tunnel origin must include an explicit port".to_owned(),
        ));
    }
    if !parsed.username().is_empty()
        || parsed.password().is_some()
        || parsed.path() != "/"
        || parsed.query().is_some()
        || parsed.fragment().is_some()
    {
        return Err(CliError::Input(
            "quick tunnel origin must not contain credentials, a path, query, or fragment"
                .to_owned(),
        ));
    }
    Ok(parsed.to_string())
}

fn trycloudflare_public_url(log: &str) -> Option<String> {
    log.split_whitespace().find_map(|token| {
        let candidate = token.trim_matches(|character: char| {
            matches!(
                character,
                '|' | '"' | '\'' | '(' | ')' | '[' | ']' | '<' | '>' | ',' | ';'
            )
        });
        let parsed = url::Url::parse(candidate).ok()?;
        let host = parsed.host_str()?;
        (parsed.scheme() == "https"
            && host.ends_with(".trycloudflare.com")
            && parsed.port().is_none()
            && parsed.username().is_empty()
            && parsed.password().is_none())
        .then(|| candidate.trim_end_matches('/').to_owned())
    })
}

fn quick_tunnel_verification_url(public_url: &str, health_path: Option<&str>) -> Result<String> {
    let mut parsed = url::Url::parse(public_url)
        .map_err(|error| CliError::Input(format!("invalid TryCloudflare URL: {error}")))?;
    if parsed.scheme() != "https"
        || !parsed
            .host_str()
            .is_some_and(|host| host.ends_with(".trycloudflare.com"))
        || parsed.port().is_some()
        || !parsed.username().is_empty()
        || parsed.password().is_some()
    {
        return Err(CliError::Input(
            "verification URL must be an HTTPS trycloudflare.com subdomain".to_owned(),
        ));
    }
    let path = health_path.unwrap_or("/");
    if !path.starts_with('/')
        || path.starts_with("//")
        || path.contains('?')
        || path.contains('#')
        || path.contains("://")
    {
        return Err(CliError::Input(
            "quick tunnel health_path must be one relative absolute-path reference".to_owned(),
        ));
    }
    parsed.set_path(path);
    parsed.set_query(None);
    parsed.set_fragment(None);
    Ok(parsed.to_string())
}

async fn verify_quick_tunnel_plan(input: &CallInput, receipt: &Value) -> Value {
    let context = match quick_tunnel_verification_context(input, receipt) {
        Ok(context) => context,
        Err(error) => {
            return json!({
                "passed": false,
                "basis": error.to_string(),
            });
        }
    };
    let (origin, public_url, public_health, local_health, pid) = context;
    if !quick_tunnel_process_is_alive(pid) {
        return json!({
            "passed": false,
            "basis": "cloudflared process exited before public verification",
            "public_url": public_url,
            "pid": pid,
        });
    }
    let client = match http_client() {
        Ok(client) => client,
        Err(error) => {
            return json!({
                "passed": false,
                "basis": format!("could not construct tunnel verifier: {error}"),
                "public_url": public_url,
                "pid": pid,
            });
        }
    };
    let (local_status, local_body) = match fetch_quick_tunnel_response(&client, &local_health).await
    {
        Ok(response) => response,
        Err(error) => {
            return json!({
                "passed": false,
                "basis": format!("reviewed local origin verification failed: {error}"),
                "public_url": public_url,
                "pid": pid,
            });
        }
    };
    let (public_status, public_body) =
        match fetch_quick_tunnel_response(&client, &public_health).await {
            Ok(response) => response,
            Err(error) => {
                return json!({
                    "passed": false,
                    "basis": format!("TryCloudflare HTTPS verification failed: {error}"),
                    "public_url": public_url,
                    "pid": pid,
                });
            }
        };
    let bodies_match = local_body == public_body;
    let passed = (200..300).contains(&local_status)
        && local_status == public_status
        && bodies_match
        && quick_tunnel_process_is_alive(pid);
    json!({
        "passed": passed,
        "basis": if passed {
            "the recorded cloudflared process is alive and the public HTTPS verification response matches the reviewed loopback origin"
        } else {
            "public TryCloudflare response did not match the reviewed loopback origin"
        },
        "public_url": public_url,
        "verification_url": public_health,
        "origin_url": origin,
        "origin_verification_url": local_health,
        "pid": pid,
        "local_status": local_status,
        "public_status": public_status,
        "response_body_match": bodies_match,
    })
}

fn quick_tunnel_verification_context(
    input: &CallInput,
    receipt: &Value,
) -> Result<(String, String, String, String, u64)> {
    let public_url = receipt
        .get("public_url")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("cloudflared did not report a public URL".to_owned()))?
        .to_owned();
    let pid = receipt
        .get("pid")
        .and_then(Value::as_u64)
        .ok_or_else(|| CliError::Input("cloudflared did not report a process id".to_owned()))?;
    let (origin, health_path) = quick_tunnel_request(input)?;
    if receipt.get("origin_url").and_then(Value::as_str) != Some(origin.as_str()) {
        return Err(CliError::Input(
            "cloudflared receipt origin does not match the reviewed plan origin".to_owned(),
        ));
    }
    let public_health = quick_tunnel_verification_url(&public_url, health_path.as_deref())?;
    let local_health = url::Url::parse(&origin)
        .and_then(|base| base.join(health_path.as_deref().unwrap_or("/")))
        .map_err(|error| {
            CliError::Input(format!(
                "could not build reviewed local verification URL: {error}"
            ))
        })?
        .to_string();
    Ok((origin, public_url, public_health, local_health, pid))
}

async fn fetch_quick_tunnel_response(
    client: &reqwest::Client,
    url: &str,
) -> Result<(u16, Vec<u8>)> {
    let response = client.get(url).send().await?;
    let status = response.status().as_u16();
    let body = response.bytes().await?.to_vec();
    Ok((status, body))
}

fn quick_tunnel_process_is_alive(pid: u64) -> bool {
    let Ok(pid) = i32::try_from(pid) else {
        return false;
    };
    StdCommand::new("/bin/kill")
        .args(["-0", &pid.to_string()])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .is_ok_and(|status| status.success())
}

/// Environment that must survive cfctl's fail-closed `env_clear()` boundary
/// for delegated CLI subprocesses.
///
/// Wrangler otherwise discovers its mutable account/config cache beneath the
/// closest `node_modules`, which writes operator state into the reviewed
/// workspace. Binding the cache to cfctl's platform cache directory keeps that
/// state outside source trees. The plan-selected account ID also prevents
/// Wrangler from enumerating accounts and writing a selection cache at all.
fn governed_cli_workspace_env(
    program: &str,
    account_id: Option<&str>,
    cache_dir: &Path,
) -> Vec<(&'static str, OsString)> {
    if program != "wrangler" {
        return Vec::new();
    }
    let mut environment = vec![(
        WRANGLER_CACHE_ENV,
        cache_dir.join(WRANGLER_CACHE_SUBDIRECTORY).into_os_string(),
    )];
    if let Some(account_id) = account_id.filter(|value| !value.is_empty()) {
        environment.push((WRANGLER_ACCOUNT_ENV, OsString::from(account_id)));
    }
    environment
}

fn governed_cli_environment_contract(cache_dir: &Path) -> Value {
    json!({
        "schema_version": 1,
        "wrangler": {
            "account_binding": "selected_cfctl_account",
            "account_env": WRANGLER_ACCOUNT_ENV,
            "cache_binding": "cfctl_platform_cache",
            "cache_env": WRANGLER_CACHE_ENV,
            "cache_dir": cache_dir.join(WRANGLER_CACHE_SUBDIRECTORY),
            "survives_env_clear": true,
        },
    })
}

fn append_cli_input(command: &mut ProcessCommand, input: &Value) -> Result<()> {
    let fields = input
        .as_object()
        .ok_or_else(|| CliError::Input("CLI selectors and query must be objects".to_owned()))?;
    for (key, value) in fields {
        let rendered = value
            .as_str()
            .map_or_else(|| value.to_string(), str::to_owned);
        if matches!(key.as_str(), "argument" | "arg" | "path") {
            command.arg(rendered);
        } else {
            command
                .arg(format!("--{}", key.replace('_', "-")))
                .arg(rendered);
        }
    }
    Ok(())
}

fn redact_subprocess_text(text: &str, credential: &AuthCredential) -> String {
    let mut sanitized = text.to_owned();
    for secret in [credential.bearer_token(), credential.global_key()]
        .into_iter()
        .flatten()
    {
        sanitized = sanitized.replace(secret, "[REDACTED]");
    }
    sanitized
        .lines()
        .map(|line| {
            let lower = line.to_ascii_lowercase();
            if [
                "access_token",
                "api_token",
                "api key",
                "authorization:",
                "password=",
            ]
            .iter()
            .any(|marker| lower.contains(marker))
            {
                "[REDACTED SECRET-BEARING LINE]".to_owned()
            } else {
                line.to_owned()
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn delete_plan_secret(plan: &PlanV1, secrets: &dyn SecretStore) -> Result<bool> {
    let Some(reference) = plan_secret_body_ref(plan).map(str::to_owned) else {
        return Ok(false);
    };
    secrets.delete(&reference)?;
    Ok(true)
}

