async fn prepare_live_plan_preconditions(
    store: &StateStore,
    catalog: &CatalogSnapshot,
    capability: &CapabilityV1,
    input: &CallInput,
    adapter_targets: &Value,
    account_id: &str,
    credential: Option<&AuthCredential>,
) -> Result<LivePlanPreconditions> {
    Ok(LivePlanPreconditions {
        entitlement: None,
        zone_account: None,
        pages_project_absence: prepare_pages_project_absence_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        r2_parent_token: None,
        global_warp_override_state: prepare_global_warp_override_state_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        d1_read_replication_state: prepare_d1_read_replication_state_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        kv_empty_namespace_state: prepare_kv_empty_namespace_state_precondition(
            store,
            catalog,
            capability,
            input,
            adapter_targets,
            account_id,
            credential,
        )
        .await?,
        d1_empty_database_state: prepare_d1_empty_database_state_precondition(
            store,
            catalog,
            capability,
            input,
            adapter_targets,
            account_id,
            credential,
        )
        .await?,
        cloudflare_tunnel_configuration_state:
            prepare_cloudflare_tunnel_configuration_state_precondition(
                store, catalog, capability, input, account_id, credential,
            )
            .await?,
        warp_connector_configuration_state:
            prepare_warp_connector_configuration_state_precondition(
                store, catalog, capability, input, account_id, credential,
            )
            .await?,
        web_analytics_rum_state: prepare_web_analytics_rum_state_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        dns_record_state: prepare_dns_record_state_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        same_path_prior_state: prepare_same_path_prior_state_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        security_action_state: prepare_security_action_state_precondition(
            store,
            catalog,
            capability,
            input,
            adapter_targets,
            account_id,
            credential,
        )
        .await?,
        oauth_client_secret_state: prepare_oauth_client_secret_state_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        oauth_client_update_state: prepare_oauth_client_update_state_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        worker_custom_domain_state: worker_custom_domain::prepare_state_precondition(
            store, catalog, capability, input, account_id, credential,
        )
        .await?,
        worker_deployment_state: prepare_worker_deployment_state_precondition(
            store,
            catalog,
            capability,
            adapter_targets,
            account_id,
            credential,
        )
        .await?,
    })
}

struct PlanAuthority<'a> {
    profile: &'a ProfileMetadata,
    account_id: &'a str,
}

struct LivePlanPreconditions {
    entitlement: Option<(Value, EvidenceV1)>,
    zone_account: Option<(Value, EvidenceV1)>,
    pages_project_absence: Option<(Value, EvidenceV1)>,
    r2_parent_token: Option<(Value, EvidenceV1)>,
    global_warp_override_state: Option<(Value, EvidenceV1)>,
    d1_read_replication_state: Option<(Value, EvidenceV1)>,
    d1_empty_database_state: Option<(Value, EvidenceV1)>,
    kv_empty_namespace_state: Option<(Value, EvidenceV1)>,
    cloudflare_tunnel_configuration_state: Option<(Value, EvidenceV1)>,
    warp_connector_configuration_state: Option<(Value, EvidenceV1)>,
    web_analytics_rum_state: Option<(Value, EvidenceV1)>,
    dns_record_state: Option<(Value, EvidenceV1)>,
    same_path_prior_state: Option<(Value, EvidenceV1)>,
    security_action_state: Option<(Value, EvidenceV1)>,
    oauth_client_secret_state: Option<(Value, EvidenceV1)>,
    oauth_client_update_state: Option<(Value, EvidenceV1)>,
    worker_custom_domain_state: Option<(Value, EvidenceV1)>,
    worker_deployment_state: Option<(Value, EvidenceV1)>,
}

fn plan_targets(
    input: &CallInput,
    account_id: &str,
    adapter_targets: &Value,
    live_preconditions: &LivePlanPreconditions,
) -> Value {
    let mut targets = json!({
        "selectors": input.selectors,
        "account_id": account_id,
        "adapter": adapter_targets,
    });
    if let Some((receipt, _)) = &live_preconditions.pages_project_absence {
        targets["live_preconditions"][PAGES_PROJECT_ABSENCE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.global_warp_override_state {
        targets["live_preconditions"]["global_warp_override_state"] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.d1_read_replication_state {
        targets["live_preconditions"][D1_READ_REPLICATION_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.d1_empty_database_state {
        targets["live_preconditions"][D1_EMPTY_DATABASE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.kv_empty_namespace_state {
        targets["live_preconditions"][KV_EMPTY_NAMESPACE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.cloudflare_tunnel_configuration_state {
        targets["live_preconditions"][CLOUDFLARE_TUNNEL_CONFIGURATION_STATE_PRECONDITION] =
            receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.warp_connector_configuration_state {
        targets["live_preconditions"][WARP_CONNECTOR_CONFIGURATION_STATE_PRECONDITION] =
            receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.web_analytics_rum_state {
        targets["live_preconditions"][WEB_ANALYTICS_RUM_STATE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.dns_record_state {
        targets["live_preconditions"][DNS_RECORD_STATE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.same_path_prior_state {
        targets["live_preconditions"][SAME_PATH_PRIOR_STATE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.security_action_state {
        targets["live_preconditions"][SECURITY_ACTION_STATE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.oauth_client_secret_state {
        targets["live_preconditions"][OAUTH_CLIENT_KEY_OVERLAP_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.oauth_client_update_state {
        targets["live_preconditions"][OAUTH_CLIENT_UPDATE_STATE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.worker_custom_domain_state {
        targets["live_preconditions"]
            [worker_custom_domain::WORKER_CUSTOM_DOMAIN_STATE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.worker_deployment_state {
        targets["live_preconditions"][worker_deployment::STATE_PRECONDITION] = receipt.clone();
    }
    if let Some((receipt, _)) = &live_preconditions.r2_parent_token {
        targets["live_preconditions"][R2_PARENT_TOKEN_PRECONDITION] = receipt.clone();
    }
    targets
}

fn bind_live_plan_preconditions(
    plan: &mut PlanV1,
    live_preconditions: &LivePlanPreconditions,
) -> Result<()> {
    for (name, precondition) in [
        ("entitlement", &live_preconditions.entitlement),
        ("zone_account", &live_preconditions.zone_account),
        (
            PAGES_PROJECT_ABSENCE_PRECONDITION,
            &live_preconditions.pages_project_absence,
        ),
        (
            "global_warp_override_state",
            &live_preconditions.global_warp_override_state,
        ),
        (
            D1_READ_REPLICATION_PRECONDITION,
            &live_preconditions.d1_read_replication_state,
        ),
        (
            D1_EMPTY_DATABASE_PRECONDITION,
            &live_preconditions.d1_empty_database_state,
        ),
        (
            KV_EMPTY_NAMESPACE_PRECONDITION,
            &live_preconditions.kv_empty_namespace_state,
        ),
        (
            CLOUDFLARE_TUNNEL_CONFIGURATION_STATE_PRECONDITION,
            &live_preconditions.cloudflare_tunnel_configuration_state,
        ),
        (
            WARP_CONNECTOR_CONFIGURATION_STATE_PRECONDITION,
            &live_preconditions.warp_connector_configuration_state,
        ),
        (
            WEB_ANALYTICS_RUM_STATE_PRECONDITION,
            &live_preconditions.web_analytics_rum_state,
        ),
        (
            DNS_RECORD_STATE_PRECONDITION,
            &live_preconditions.dns_record_state,
        ),
        (
            SAME_PATH_PRIOR_STATE_PRECONDITION,
            &live_preconditions.same_path_prior_state,
        ),
        (
            SECURITY_ACTION_STATE_PRECONDITION,
            &live_preconditions.security_action_state,
        ),
        (
            OAUTH_CLIENT_KEY_OVERLAP_PRECONDITION,
            &live_preconditions.oauth_client_secret_state,
        ),
        (
            OAUTH_CLIENT_UPDATE_STATE_PRECONDITION,
            &live_preconditions.oauth_client_update_state,
        ),
        (
            worker_custom_domain::WORKER_CUSTOM_DOMAIN_STATE_PRECONDITION,
            &live_preconditions.worker_custom_domain_state,
        ),
        (
            worker_deployment::STATE_PRECONDITION,
            &live_preconditions.worker_deployment_state,
        ),
        (
            R2_PARENT_TOKEN_PRECONDITION,
            &live_preconditions.r2_parent_token,
        ),
    ] {
        if let Some((receipt, _)) = precondition {
            plan.precondition_hashes
                .insert(name.to_owned(), hash_value(receipt)?);
        }
    }
    Ok(())
}

fn planned_cloudflare_diff(
    plan: &PlanV1,
    input: &CallInput,
    live_preconditions: &LivePlanPreconditions,
) -> Value {
    let mut diff = json!({
        "request_method": plan.capability.method,
        "request_path": plan.capability.path,
        "request_body": input.body,
    });
    if let Some((receipt, _)) = &live_preconditions.global_warp_override_state {
        diff["observed_before"] = json!({
            "disconnect": receipt.get("disconnect").cloned().unwrap_or(Value::Null),
        });
        diff["planned_after"] = json!({
            "disconnect": input
                .body
                .as_ref()
                .and_then(|body| body.get("disconnect"))
                .cloned()
                .unwrap_or(Value::Null),
        });
    }
    if let Some((receipt, _)) = &live_preconditions.d1_read_replication_state {
        diff["observed_before"] = json!({
            "read_replication": receipt
                .get("read_replication")
                .cloned()
                .unwrap_or(Value::Null),
        });
        diff["planned_after"] = json!({
            "read_replication": input
                .body
                .as_ref()
                .and_then(|body| body.get("read_replication"))
                .cloned()
                .unwrap_or(Value::Null),
        });
    }
    if let Some((receipt, _)) = &live_preconditions.cloudflare_tunnel_configuration_state {
        diff["observed_before"] = json!({
            "config": receipt.get("prior_config").cloned().unwrap_or(Value::Null),
        });
        diff["planned_after"] = json!({
            "config": input
                .body
                .as_ref()
                .and_then(|body| body.get("config"))
                .cloned()
                .unwrap_or(Value::Null),
        });
    }
    if let Some((receipt, _)) = &live_preconditions.warp_connector_configuration_state {
        diff["observed_before"] = json!({
            "ha_mode": receipt
                .get("prior_ha_mode")
                .cloned()
                .unwrap_or(Value::Null),
            "config": receipt.get("prior_config").cloned().unwrap_or(Value::Null),
        });
        diff["planned_after"] = input.body.clone().unwrap_or(Value::Null);
    }
    if let Some((receipt, _)) = &live_preconditions.web_analytics_rum_state {
        diff["observed_before"] = json!({
            "value": receipt.get("prior_value").cloned().unwrap_or(Value::Null),
        });
        diff["planned_after"] = json!({
            "value": input
                .body
                .as_ref()
                .and_then(|body| body.get("value"))
                .cloned()
                .unwrap_or(Value::Null),
        });
    }
    if let Some((receipt, _)) = &live_preconditions.dns_record_state {
        diff["observed_before"] = receipt.get("prior_record").cloned().unwrap_or(Value::Null);
        diff["planned_after"] = input.body.clone().unwrap_or(Value::Null);
    }
    if let Some((receipt, _)) = &live_preconditions.same_path_prior_state {
        diff["observed_before"] = receipt.get("prior_state").cloned().unwrap_or(Value::Null);
        diff["planned_after"] = input.body.clone().unwrap_or(Value::Null);
    }
    if let Some((receipt, _)) = &live_preconditions.security_action_state {
        diff["security_current_state"] = receipt.get("state").cloned().unwrap_or(Value::Null);
        diff["security_governance"] = plan
            .targets
            .pointer("/adapter/security_action")
            .cloned()
            .unwrap_or(Value::Null);
    }
    if let Some((receipt, _)) = &live_preconditions.oauth_client_secret_state {
        let observed_before = receipt
            .get("key_overlap_active")
            .cloned()
            .unwrap_or(Value::Null);
        diff["observed_before"] = json!({"key_overlap_active": observed_before});
        diff["planned_after"] = json!({
            "key_overlap_active": !observed_before.as_bool().unwrap_or(false)
        });
    }
    apply_oauth_client_update_plan_diff(&mut diff, input, live_preconditions);
    apply_worker_deployment_plan_diff(&mut diff, plan, live_preconditions);
    diff
}

fn apply_worker_deployment_plan_diff(
    diff: &mut Value,
    plan: &PlanV1,
    live_preconditions: &LivePlanPreconditions,
) {
    if let Some((state, _)) = &live_preconditions.worker_deployment_state {
        worker_deployment::apply_plan_diff(diff, plan, state);
    }
}

fn apply_oauth_client_update_plan_diff(
    diff: &mut Value,
    input: &CallInput,
    live_preconditions: &LivePlanPreconditions,
) {
    if let Some((receipt, _)) = &live_preconditions.oauth_client_update_state {
        diff["observed_before"] = receipt.get("prior_state").cloned().unwrap_or(Value::Null);
        diff["planned_after"] = input.body.clone().unwrap_or(Value::Null);
        diff["irreversible_visibility_promotion"] = Value::Bool(
            input.body.as_ref().and_then(|body| body.get("visibility")) == Some(&json!("public")),
        );
    }
}

fn prepare_pages_source_remote_precondition(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
) -> Result<Option<Value>> {
    if !should_bind_pages_project_absence(capability) {
        return Ok(None);
    }
    let graph = discover_registered(store)?;
    let repository = registered_pages_source_repository(&graph, input)?;
    pages_source_remote_snapshot(repository, input).map(Some)
}

#[expect(
    clippy::too_many_lines,
    reason = "PlanV1 compatibility, PlanV2 pins, durable persistence, and the returned preview must be constructed from one immutable preparation context"
)]
fn persist_prepared_plan(
    store: &StateStore,
    catalog: &CatalogSnapshot,
    capability: cfctl_core::CapabilityV1,
    input: CallInput,
    authority: PlanAuthority<'_>,
    adapter_targets: Value,
    live_preconditions: LivePlanPreconditions,
) -> Result<ResultEnvelopeV2> {
    let PlanAuthority {
        profile,
        account_id,
    } = authority;
    validate_api_token_creation_contract(&capability, &input, &adapter_targets, account_id)?;
    validate_prepared_r2_parent_token_contract(
        &capability,
        &input,
        profile,
        account_id,
        &live_preconditions,
    )?;
    let impact = plan_impact(store, &capability, &input, account_id)?;
    let compiled_policy = PolicyEngine.evaluate(&capability, &impact.policy);
    let active_policy = active_admission_policy(store)?;
    let policy = active_policy.as_ref().map_or_else(
        || Ok(compiled_policy.clone()),
        |bundle| bundle.tighten(&compiled_policy, &capability),
    )?;
    if policy.disposition == PolicyDisposition::Blocked {
        return Ok(blocked_capability_envelope(
            "call",
            &capability,
            &policy.reasons.join("; "),
        ));
    }
    let pages_source_remote = prepare_pages_source_remote_precondition(store, &capability, &input)?;
    let mut targets = plan_targets(&input, account_id, &adapter_targets, &live_preconditions);
    if let Some(snapshot) = &pages_source_remote {
        targets["source_preconditions"][PAGES_SOURCE_REMOTE_PRECONDITION] = snapshot.clone();
    }
    let mut plan = PlanV1::draft(
        &profile.id,
        account_id,
        &catalog.schema_hash,
        capability,
        targets,
    )?;
    match profile.kind {
        ProfileKind::OAuth => "oauth",
        ProfileKind::ApiToken => "api_token",
        ProfileKind::LegacyWranglerSession => "unsupported_legacy_wrangler_session",
        ProfileKind::GlobalKey => "emergency_global_key",
    }
    .clone_into(&mut plan.permission_lane);
    plan.input = serde_json::to_value(&input)?;
    if is_oauth_client_create_operation_identity(&plan.capability) {
        preflight_secret_sink(&plan)?;
    }
    plan.precondition_hashes
        .insert("catalog".to_owned(), catalog.schema_hash.clone());
    plan.precondition_hashes
        .insert("request_input".to_owned(), hash_value(&plan.input)?);
    bind_live_plan_preconditions(&mut plan, &live_preconditions)?;
    if let Some(snapshot) = &pages_source_remote {
        plan.precondition_hashes.insert(
            PAGES_SOURCE_REMOTE_PRECONDITION.to_owned(),
            hash_value(snapshot)?,
        );
    }
    plan.precondition_hashes
        .extend(workspace_precondition_hashes_for_scope(
            store,
            &impact.affected_repositories,
            &impact.local_artifact_paths,
        )?);
    plan.affected_repositories = impact.affected_repositories;
    plan.affected_resources = impact.affected_resources;
    plan.local_diffs = impact.local_diffs;
    let cloudflare_diff = planned_cloudflare_diff(&plan, &input, &live_preconditions);
    plan.cloudflare_diffs.push(cloudflare_diff);
    plan.verification_steps
        .push(plan.capability.verification.strategy.clone());
    if let Some(strategy) = &plan.capability.rollback.strategy {
        plan.compensation_steps.push(strategy.clone());
    }
    if let Some(warning) = &plan.capability.rollback.warning {
        plan.non_reversible_warnings.push(warning.clone());
    }
    plan.policy = policy.clone();
    plan.refresh_hash()?;
    let build_identity_hash = hash_value(&serde_json::to_value(current_build_info())?)?;
    let credential_generation_id = profile.credential_generation_id.clone().ok_or_else(|| {
        CliError::guided(
            "CFCTL_CREDENTIAL_UNBOUND",
            format!(
                "profile `{}` has no credential generation and cannot create a PlanV2",
                profile.id
            ),
            format!(
                "Re-import or log in to profile `{}` before creating the mutation plan.",
                profile.id
            ),
        )
    })?;
    let admission_policy_hash = active_policy.as_ref().map_or_else(
        || {
            hash_value(&json!({"compiled_safety_floor": compiled_policy}))
                .map(|hash| format!("compiled:{hash}"))
        },
        |bundle| Ok(format!("bundle:{}", bundle.content_hash)),
    )?;
    let workspace_graph_hash = plan
        .precondition_hashes
        .get("workspace_graph")
        .cloned()
        .ok_or_else(|| {
            CliError::Input("PlanV2 requires a pinned workspace graph hash".to_owned())
        })?;
    let resource_observation_hashes = plan
        .precondition_hashes
        .iter()
        .filter(|(key, _)| {
            !matches!(
                key.as_str(),
                "catalog" | "request_input" | "workspace_graph"
            )
        })
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect();
    let plan_v2 = PlanV2::new(
        plan.clone(),
        PlanPinsV2 {
            build_identity_hash,
            catalog_hash: catalog.schema_hash.clone(),
            credential_generation_id,
            admission_policy_hash,
            authority_hash: None,
            workspace_graph_hash,
            resource_observation_hashes,
            cost_budget: None,
        },
    )?;
    store.save_plan_v2(&plan_v2)?;
    let evidence =
        store.write_evidence(EvidenceClass::Preview, &serde_json::to_value(&plan_v2)?)?;
    let mut envelope = ResultEnvelopeV2::success(
        "call",
        json!({
            "plan": plan,
            "plan_v2": plan_v2,
            "approval_command": approval_command_argv(&plan.capability, &plan.operation_id).join(" "),
            "run_command": format!("cfctl plans run {}", plan.operation_id),
            "message": if policy.disposition == PolicyDisposition::AutoExecute {
                "Plan created and policy-authorized for automatic execution; run the exact operation ID."
            } else {
                "Plan created. Review it, then approve the exact operation ID with y/n."
            }
        }),
    )
    .with_evidence(evidence);
    envelope.capability_id = Some(plan.capability.id.clone());
    envelope.operation_id = Some(plan.operation_id.clone());
    envelope.profile_id = Some(profile.id.clone());
    envelope.account_id = Some(account_id.to_owned());
    envelope.policy_decision = Some(policy);
    envelope.verification.state = VerificationState::Pending;
    prepend_prepared_plan_evidence(&mut envelope, live_preconditions);
    Ok(envelope)
}

fn prepend_prepared_plan_evidence(
    envelope: &mut ResultEnvelopeV2,
    live_preconditions: LivePlanPreconditions,
) {
    for (_, evidence) in [
        live_preconditions.entitlement,
        live_preconditions.zone_account,
        live_preconditions.global_warp_override_state,
        live_preconditions.d1_read_replication_state,
        live_preconditions.cloudflare_tunnel_configuration_state,
        live_preconditions.warp_connector_configuration_state,
        live_preconditions.web_analytics_rum_state,
        live_preconditions.dns_record_state,
        live_preconditions.same_path_prior_state,
        live_preconditions.security_action_state,
        live_preconditions.oauth_client_secret_state,
        live_preconditions.oauth_client_update_state,
        live_preconditions.r2_parent_token,
    ]
    .into_iter()
    .flatten()
    {
        envelope.evidence.insert(0, evidence);
    }
}

fn validate_prepared_r2_parent_token_contract(
    capability: &CapabilityV1,
    input: &CallInput,
    profile: &ProfileMetadata,
    account_id: &str,
    live_preconditions: &LivePlanPreconditions,
) -> Result<()> {
    if !is_r2_temporary_credentials_operation_identity(capability) {
        return Ok(());
    }
    if !should_bind_r2_parent_token(capability) || profile.kind != ProfileKind::ApiToken {
        return Err(CliError::Input(
            "R2 temporary credential plan is inconsistent with its governed active API-token parent contract"
                .to_owned(),
        ));
    }
    let (receipt, _) = live_preconditions.r2_parent_token.as_ref().ok_or_else(|| {
        CliError::Input(
            "R2 temporary credential plan is missing its live parent-token receipt".to_owned(),
        )
    })?;
    let parent = input
        .body
        .as_ref()
        .and_then(|body| body.get("parentAccessKeyId"))
        .and_then(Value::as_str);
    if receipt.get("account_id").and_then(Value::as_str) != Some(account_id)
        || receipt.get("parent_access_key_id").and_then(Value::as_str) != parent
    {
        return Err(CliError::Input(
            "R2 temporary credential parent-token receipt does not match the planned account and request"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_api_token_creation_contract(
    capability: &CapabilityV1,
    input: &CallInput,
    adapter_targets: &Value,
    account_id: &str,
) -> Result<()> {
    let Some(inventory_contract) = token_permission_inventory_contract(&capability.id) else {
        return Ok(());
    };
    let inventory = adapter_targets
        .get("permission_inventory")
        .ok_or_else(|| {
            CliError::Input(
                "direct token-create calls are blocked because they do not bind a fresh permission inventory; use `cfctl keys mint`"
                    .to_owned(),
            )
        })?;
    if inventory
        .get("source_capability_id")
        .and_then(Value::as_str)
        != Some(inventory_contract.capability_id)
    {
        return Err(CliError::Input(format!(
            "token mint permission metadata is not bound to the required `{}` inventory capability",
            inventory_contract.capability_id
        )));
    }
    let selected_groups = inventory
        .get("selected_groups")
        .and_then(Value::as_array)
        .filter(|groups| !groups.is_empty())
        .ok_or_else(|| {
            CliError::Input(
                "token mint permission inventory contains no selected groups".to_owned(),
            )
        })?;
    let selected_ids = selected_groups
        .iter()
        .map(|group| {
            group
                .get("id")
                .and_then(Value::as_str)
                .map(str::to_owned)
                .ok_or_else(|| {
                    CliError::Input(
                        "token mint permission inventory contains a group without an ID".to_owned(),
                    )
                })
        })
        .collect::<Result<Vec<_>>>()?;
    let normalized_groups =
        validate_selected_permission_groups(&selected_ids, &Value::Array(selected_groups.clone()))?;
    let policy_bindings = token_policy_bindings_from_inventory(
        inventory,
        &normalized_groups,
        &selected_ids,
        account_id,
    )?;
    let expected_hash = inventory
        .get("selected_groups_hash")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("token mint permission inventory hash is missing".to_owned())
        })?;
    if hash_value(&serde_json::to_value(&normalized_groups)?)? != expected_hash {
        return Err(CliError::Input(
            "token mint permission inventory metadata does not match its bound hash".to_owned(),
        ));
    }
    let evidence_hashes = inventory
        .get("evidence_hashes")
        .and_then(Value::as_array)
        .filter(|hashes| {
            !hashes.is_empty()
                && hashes.iter().all(|hash| {
                    hash.as_str()
                        .is_some_and(|hash| hash.starts_with("sha256:") && hash.len() == 71)
                })
        })
        .ok_or_else(|| {
            CliError::Input(
                "token mint permission inventory is missing a live-read evidence hash".to_owned(),
            )
        })?;
    if evidence_hashes.len() != 1 {
        return Err(CliError::Input(
            "token mint permission inventory must bind exactly one live-read evidence receipt"
                .to_owned(),
        ));
    }
    validate_token_policy_body_bindings(input.body.as_ref(), &policy_bindings)
}

#[derive(Clone, Copy)]
struct TokenPermissionInventoryContract {
    capability_id: &'static str,
    path: &'static str,
    account_selector: bool,
}

fn token_permission_inventory_contract(
    token_create_capability_id: &str,
) -> Option<TokenPermissionInventoryContract> {
    match token_create_capability_id {
        "account-api-tokens-create-token" => Some(TokenPermissionInventoryContract {
            capability_id: "account-api-tokens-list-permission-groups",
            path: "/accounts/{account_id}/tokens/permission_groups",
            account_selector: true,
        }),
        "user-api-tokens-create-token" => Some(TokenPermissionInventoryContract {
            capability_id: "permission-groups-list-permission-groups",
            path: "/user/tokens/permission_groups",
            account_selector: false,
        }),
        _ => None,
    }
}

/// A standing authority's groups must all be bindable to something the
/// authority actually pins. Account scope is always acceptable; zone scope only
/// when the authority pins a zone. A group supporting neither would be
/// unmintable under the authority, so reject it at draft time rather than
/// leaving a dead group in an approved allowlist.
fn validate_standing_authority_group_scopes(groups: &[Value], zone_id: Option<&str>) -> Result<()> {
    let account_scope = "com.cloudflare.api.account";
    if zone_id.is_none() {
        return validate_permission_group_resource_scope(groups, account_scope);
    }
    let zone_scope = "com.cloudflare.api.account.zone";
    for group in groups {
        let id = group
            .get("id")
            .and_then(Value::as_str)
            .unwrap_or("<missing>");
        if !permission_group_supports_scope(group, account_scope)
            && !permission_group_supports_scope(group, zone_scope)
        {
            return Err(CliError::Input(format!(
                "permission group `{id}` supports neither `{account_scope}` nor `{zone_scope}`, so no child of this authority could bind it"
            )));
        }
    }
    Ok(())
}

fn validate_permission_group_resource_scope(groups: &[Value], required_scope: &str) -> Result<()> {
    for group in groups {
        let id = group
            .get("id")
            .and_then(Value::as_str)
            .unwrap_or("<missing>");
        let supports_scope = group
            .get("scopes")
            .and_then(Value::as_array)
            .is_some_and(|scopes| {
                scopes
                    .iter()
                    .any(|scope| scope.as_str() == Some(required_scope))
            });
        if !supports_scope {
            return Err(CliError::Input(format!(
                "permission group `{id}` does not support the required resource scope `{required_scope}`"
            )));
        }
    }
    Ok(())
}

/// Resolves the least-privilege resource scope for a mint: the whole `--account`
/// (default) or a single `--zone`. Returns the permission scope selected groups
/// must support and the exact policy resource `{scope}.{id}`. Zone-scoped
/// permission groups (Cache Purge, DNS Write, …) carry scope
/// `com.cloudflare.api.account.zone`, which the whole-account scope does not
/// admit — resolving to the zone scope is what lets those groups mint through
/// the governed lane instead of an out-of-band raw token.
fn resolve_mint_token_scope(
    arguments: &KeyMutationArgs,
    account: &str,
) -> Result<(&'static str, String)> {
    match arguments.zone.as_deref() {
        Some(zone_id) => {
            if arguments.user {
                return Err(CliError::Input(
                    "zone-scoped minting is account-owned; omit --user (the token still belongs to --account)"
                        .to_owned(),
                ));
            }
            validate_zone_id(zone_id)?;
            Ok((
                "com.cloudflare.api.account.zone",
                format!("com.cloudflare.api.account.zone.{zone_id}"),
            ))
        }
        None => Ok((
            "com.cloudflare.api.account",
            format!("com.cloudflare.api.account.{account}"),
        )),
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct TokenPolicyBinding {
    permission_scope: String,
    token_resource: String,
    permission_group_ids: Vec<String>,
}

impl TokenPolicyBinding {
    fn as_json(&self) -> Value {
        json!({
            "permission_scope": self.permission_scope,
            "token_resource": self.token_resource,
            "permission_group_ids": self.permission_group_ids,
        })
    }
}

fn permission_group_supports_scope(group: &Value, scope: &str) -> bool {
    group
        .get("scopes")
        .and_then(Value::as_array)
        .is_some_and(|scopes| {
            scopes
                .iter()
                .any(|candidate| candidate.as_str() == Some(scope))
        })
}

/// Partitions a token's selected permissions into the exact resource scopes
/// Cloudflare accepts. With `--zone`, zone-capable permissions are bound to the
/// named zone while account-only permissions remain bound to the account. A
/// group supporting neither resource class fails closed.
fn resolve_mint_token_bindings(
    arguments: &KeyMutationArgs,
    account: &str,
    selected_groups: &[Value],
) -> Result<Vec<TokenPolicyBinding>> {
    let (preferred_scope, preferred_resource) = resolve_mint_token_scope(arguments, account)?;
    let account_scope = "com.cloudflare.api.account";
    let account_resource = format!("{account_scope}.{account}");
    let mut account_ids = Vec::new();
    let mut preferred_ids = Vec::new();

    for group in selected_groups {
        let id = group.get("id").and_then(Value::as_str).ok_or_else(|| {
            CliError::Input("selected permission group is missing its ID".to_owned())
        })?;
        if preferred_scope != account_scope
            && permission_group_supports_scope(group, preferred_scope)
        {
            preferred_ids.push(id.to_owned());
        } else if permission_group_supports_scope(group, account_scope) {
            account_ids.push(id.to_owned());
        } else {
            return Err(CliError::Input(format!(
                "permission group `{id}` supports neither the account resource scope nor the requested `{preferred_scope}` scope"
            )));
        }
    }

    let mut bindings = Vec::new();
    if !account_ids.is_empty() {
        bindings.push(TokenPolicyBinding {
            permission_scope: account_scope.to_owned(),
            token_resource: account_resource,
            permission_group_ids: account_ids,
        });
    }
    if !preferred_ids.is_empty() {
        bindings.push(TokenPolicyBinding {
            permission_scope: preferred_scope.to_owned(),
            token_resource: preferred_resource,
            permission_group_ids: preferred_ids,
        });
    }
    Ok(bindings)
}

fn token_policy_bindings_from_inventory(
    inventory: &Value,
    selected_groups: &[Value],
    selected_ids: &[String],
    account_id: &str,
) -> Result<Vec<TokenPolicyBinding>> {
    let Some(raw_bindings) = inventory.get("permission_bindings") else {
        // Backward compatibility for plans minted before mixed-scope support.
        let permission_scope = inventory
            .get("permission_scope")
            .and_then(Value::as_str)
            .unwrap_or("com.cloudflare.api.account");
        let default_resource = format!("com.cloudflare.api.account.{account_id}");
        let token_resource = inventory
            .get("token_resource")
            .and_then(Value::as_str)
            .unwrap_or(&default_resource);
        validate_token_binding_resource(permission_scope, token_resource, account_id)?;
        validate_permission_group_resource_scope(selected_groups, permission_scope)?;
        return Ok(vec![TokenPolicyBinding {
            permission_scope: permission_scope.to_owned(),
            token_resource: token_resource.to_owned(),
            permission_group_ids: selected_ids.to_vec(),
        }]);
    };

    let raw_bindings = raw_bindings
        .as_array()
        .filter(|bindings| !bindings.is_empty())
        .ok_or_else(|| CliError::Input("token mint permission bindings are empty".to_owned()))?;
    let groups_by_id = selected_groups
        .iter()
        .filter_map(|group| {
            group
                .get("id")
                .and_then(Value::as_str)
                .map(|id| (id, group))
        })
        .collect::<BTreeMap<_, _>>();
    let mut bound_ids = Vec::new();
    let mut resources = BTreeSet::new();
    let mut bindings = Vec::new();
    for raw in raw_bindings {
        let permission_scope = raw
            .get("permission_scope")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                CliError::Input("token mint permission binding has no scope".to_owned())
            })?;
        let token_resource = raw
            .get("token_resource")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                CliError::Input("token mint permission binding has no resource".to_owned())
            })?;
        validate_token_binding_resource(permission_scope, token_resource, account_id)?;
        if !resources.insert(token_resource.to_owned()) {
            return Err(CliError::Input(
                "token mint permission bindings repeat a resource".to_owned(),
            ));
        }
        let permission_group_ids = raw
            .get("permission_group_ids")
            .and_then(Value::as_array)
            .filter(|ids| !ids.is_empty())
            .ok_or_else(|| {
                CliError::Input("token mint permission binding has no permission groups".to_owned())
            })?
            .iter()
            .map(|id| {
                id.as_str().map(str::to_owned).ok_or_else(|| {
                    CliError::Input(
                        "token mint permission binding contains a non-string group ID".to_owned(),
                    )
                })
            })
            .collect::<Result<Vec<_>>>()?;
        for id in &permission_group_ids {
            let group = groups_by_id.get(id.as_str()).ok_or_else(|| {
                CliError::Input(format!(
                    "token mint permission binding references unselected group `{id}`"
                ))
            })?;
            validate_permission_group_resource_scope(
                std::slice::from_ref(group),
                permission_scope,
            )?;
            bound_ids.push(id.clone());
        }
        bindings.push(TokenPolicyBinding {
            permission_scope: permission_scope.to_owned(),
            token_resource: token_resource.to_owned(),
            permission_group_ids,
        });
    }
    let original_len = bound_ids.len();
    bound_ids.sort();
    bound_ids.dedup();
    if original_len != bound_ids.len() || bound_ids != selected_ids {
        return Err(CliError::Input(
            "token mint permission bindings do not partition the selected live inventory exactly once".to_owned(),
        ));
    }
    Ok(bindings)
}

/// Builds one least-privilege token-create policy per exact resource binding,
/// plus an optional expiry. The contract validator rechecks every policy
/// against the hash-bound live permission inventory before the mint runs.
fn build_mint_policy_body(
    name: &str,
    bindings: &[TokenPolicyBinding],
    ttl_hours: Option<u32>,
) -> Value {
    let mut body = json!({
        "name": name,
        "policies": bindings.iter().map(|binding| json!({
            "effect": "allow",
            "permission_groups": binding.permission_group_ids.iter().map(|id| json!({"id": id})).collect::<Vec<_>>(),
            "resources": {binding.token_resource.clone(): "*"}
        })).collect::<Vec<_>>()
    });
    if let Some(hours) = ttl_hours {
        // Cloudflare's token API requires seconds-precision UTC with a `Z`
        // suffix (e.g. 2005-12-30T01:02:03Z) and rejects the fractional-second
        // `+00:00` form that `to_rfc3339()` emits with a 400.
        body["expires_on"] = json!(
            (Utc::now() + ChronoDuration::hours(i64::from(hours)))
                .format("%Y-%m-%dT%H:%M:%SZ")
                .to_string()
        );
    }
    body
}

/// Fail-closed local check on a `--zone` argument: Cloudflare zone ids are
/// 32-character lowercase hex. Cross-account zone ownership is still enforced at
/// the Cloudflare boundary when the governed plan runs; this only rejects
/// obviously-malformed input before it becomes a plan.
fn validate_zone_id(zone_id: &str) -> Result<()> {
    let well_formed = zone_id.len() == 32
        && zone_id
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte));
    if well_formed {
        Ok(())
    } else {
        Err(CliError::Input(format!(
            "`--zone` expects a 32-character lowercase-hex Cloudflare zone id, got `{zone_id}`"
        )))
    }
}

/// Fail-closed: the token resource must be exactly `{scope}.{id}` where `id` is
/// a single concrete account/zone identifier — ASCII alphanumeric and `-` only.
/// This rejects a nested scope (`.zone.<id>` under the account scope, or the
/// reverse) AND a wildcard id (`*`), so no claimed permission scope can be
/// widened to a broader resource even if the hash-bound metadata were tampered.
fn validate_resource_is_single_concrete_id_under_scope(
    expected_resource: &str,
    permission_scope: &str,
) -> Result<()> {
    let ok = expected_resource
        .strip_prefix(permission_scope)
        .and_then(|rest| rest.strip_prefix('.'))
        .is_some_and(|id| {
            !id.is_empty()
                && id
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
        });
    if ok {
        Ok(())
    } else {
        Err(CliError::Input(format!(
            "token mint resource `{expected_resource}` is not a single concrete resource under its declared permission scope `{permission_scope}`"
        )))
    }
}

fn validate_token_binding_resource(
    permission_scope: &str,
    token_resource: &str,
    account_id: &str,
) -> Result<()> {
    validate_resource_is_single_concrete_id_under_scope(token_resource, permission_scope)?;
    match permission_scope {
        "com.cloudflare.api.account" => {
            let expected = format!("com.cloudflare.api.account.{account_id}");
            if token_resource != expected {
                return Err(CliError::Input(format!(
                    "token mint account resource must be the selected account `{expected}`"
                )));
            }
        }
        "com.cloudflare.api.account.zone" => {
            let zone_id = token_resource
                .strip_prefix("com.cloudflare.api.account.zone.")
                .ok_or_else(|| {
                    CliError::Input(format!(
                        "token mint zone resource `{token_resource}` is not under the declared zone scope"
                    ))
                })?;
            validate_zone_id(zone_id)?;
        }
        other => {
            return Err(CliError::Input(format!(
                "token mint permission binding uses unsupported resource scope `{other}`"
            )));
        }
    }
    Ok(())
}

#[cfg(test)]
fn validate_token_policy_body(
    body: Option<&Value>,
    selected_ids: &[String],
    expected_resource: &str,
) -> Result<()> {
    validate_token_policy_body_bindings(
        body,
        &[TokenPolicyBinding {
            permission_scope: String::new(),
            token_resource: expected_resource.to_owned(),
            permission_group_ids: selected_ids.to_vec(),
        }],
    )
}

fn validate_token_policy_body_bindings(
    body: Option<&Value>,
    bindings: &[TokenPolicyBinding],
) -> Result<()> {
    let policies = body
        .and_then(|body| body.get("policies"))
        .and_then(Value::as_array)
        .filter(|policies| policies.len() == bindings.len())
        .ok_or_else(|| {
            CliError::Input(
                "token minting requires exactly one hash-bound least-privilege policy per resource binding".to_owned(),
            )
        })?;
    let expected = bindings
        .iter()
        .map(|binding| {
            let mut ids = binding.permission_group_ids.clone();
            ids.sort();
            (binding.token_resource.clone(), ids)
        })
        .collect::<BTreeMap<_, _>>();
    let mut actual = BTreeMap::new();
    for policy in policies {
        if policy.get("effect").and_then(Value::as_str) != Some("allow") {
            return Err(CliError::Input(
                "token minting requires explicit allow policies".to_owned(),
            ));
        }
        let mut body_ids = policy
            .get("permission_groups")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                CliError::Input("token mint policy has no permission-group list".to_owned())
            })?
            .iter()
            .map(|group| {
                group
                    .get("id")
                    .and_then(Value::as_str)
                    .map(str::to_owned)
                    .ok_or_else(|| {
                        CliError::Input(
                            "token mint policy contains a permission group without an ID"
                                .to_owned(),
                        )
                    })
            })
            .collect::<Result<Vec<_>>>()?;
        let original_len = body_ids.len();
        body_ids.sort();
        body_ids.dedup();
        if original_len != body_ids.len() {
            return Err(CliError::Input(
                "token mint policy repeats a permission group".to_owned(),
            ));
        }
        let resources = policy
            .get("resources")
            .and_then(Value::as_object)
            .filter(|resources| resources.len() == 1)
            .ok_or_else(|| {
                CliError::Input("token mint policy must bind exactly one resource".to_owned())
            })?;
        let (resource, value) = resources.iter().next().ok_or_else(|| {
            CliError::Input("token mint policy must bind exactly one resource".to_owned())
        })?;
        if value.as_str() != Some("*") || actual.insert(resource.clone(), body_ids).is_some() {
            return Err(CliError::Input(
                "token mint policy resource binding is invalid or repeated".to_owned(),
            ));
        }
    }
    if actual != expected {
        let expected_resources = expected.keys().cloned().collect::<Vec<_>>().join(", ");
        return Err(CliError::Input(format!(
            "token mint policies do not exactly match the hash-bound permission/resource partition for `{expected_resources}`"
        )));
    }
    Ok(())
}

struct PlannedImpact {
    policy: ImpactContext,
    affected_repositories: Vec<String>,
    affected_resources: Vec<String>,
    local_diffs: Vec<Value>,
    local_artifact_paths: Vec<PathBuf>,
}

fn pages_github_source(input: &CallInput) -> Result<(&str, &str, &str)> {
    let body = input.body.as_ref().ok_or_else(|| {
        CliError::Input("Pages Git integration requires a request body".to_owned())
    })?;
    if body.pointer("/source/type").and_then(Value::as_str) != Some("github") {
        return Err(CliError::Input(
            "Pages project creation requires an exact GitHub source input".to_owned(),
        ));
    }
    let required = |pointer: &str, label: &str| {
        body.pointer(pointer)
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| CliError::Input(format!("Pages Git source requires `{label}`")))
    };
    let owner = required("/source/config/owner", "source.config.owner")?;
    let repository = required("/source/config/repo_name", "source.config.repo_name")?;
    let branch = required("/production_branch", "production_branch")?;
    if body
        .pointer("/source/config/production_branch")
        .and_then(Value::as_str)
        != Some(branch)
    {
        return Err(CliError::Input(
            "Pages source and project production branches must match exactly".to_owned(),
        ));
    }
    if !github_path_segment_is_safe(owner)
        || !github_path_segment_is_safe(repository)
        || !git_branch_name_is_safe(branch)
    {
        return Err(CliError::Input(
            "Pages Git source repository or branch identity is malformed".to_owned(),
        ));
    }
    Ok((owner, repository, branch))
}

fn github_path_segment_is_safe(value: &str) -> bool {
    !value.is_empty()
        && value != "."
        && value != ".."
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
}

fn git_branch_name_is_safe(value: &str) -> bool {
    !value.is_empty()
        && !value.starts_with('-')
        && !value.starts_with('.')
        && !value.ends_with('.')
        && !value.ends_with('/')
        && !value.contains("..")
        && !value.contains("@{")
        && !value.bytes().any(|byte| {
            byte <= b' '
                || byte == 0x7f
                || matches!(byte, b'~' | b'^' | b':' | b'?' | b'*' | b'[' | b'\\')
        })
}

fn github_remote_identity(remote: &str) -> Option<(String, String)> {
    let path = if let Some(path) = remote.strip_prefix("git@github.com:") {
        path.to_owned()
    } else {
        let parsed = url::Url::parse(remote).ok()?;
        let valid_https = parsed.scheme() == "https" && parsed.username().is_empty();
        let valid_ssh = parsed.scheme() == "ssh" && parsed.username() == "git";
        if (!valid_https && !valid_ssh)
            || parsed.password().is_some()
            || parsed.port().is_some()
            || parsed.host_str() != Some("github.com")
            || parsed.query().is_some()
            || parsed.fragment().is_some()
        {
            return None;
        }
        parsed.path().trim_start_matches('/').to_owned()
    };
    let path = path.strip_suffix(".git").unwrap_or(&path);
    let mut segments = path.split('/');
    let owner = segments.next()?;
    let repository = segments.next()?;
    if segments.next().is_some()
        || !github_path_segment_is_safe(owner)
        || !github_path_segment_is_safe(repository)
    {
        return None;
    }
    Some((owner.to_ascii_lowercase(), repository.to_ascii_lowercase()))
}

#[derive(Debug)]
struct BoundedPagesGitOutput {
    success: bool,
    code: Option<i32>,
    stdout: String,
}

fn run_bounded_pages_git_program(
    program: &Path,
    repository_root: Option<&Path>,
    arguments: &[&str],
    timeout: Duration,
) -> Result<BoundedPagesGitOutput> {
    let program = program.to_path_buf();
    let repository_root = repository_root.map(Path::to_path_buf);
    let arguments = arguments
        .iter()
        .map(OsString::from)
        .collect::<Vec<OsString>>();
    let path = env::var_os("PATH").unwrap_or_default();
    let inherited_environment = [
        "HOME",
        "XDG_CONFIG_HOME",
        "USERPROFILE",
        "HOMEDRIVE",
        "HOMEPATH",
        "SSH_AUTH_SOCK",
    ]
    .into_iter()
    .filter_map(|name| env::var_os(name).map(|value| (name, value)))
    .collect::<Vec<_>>();

    std::thread::spawn(move || {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|_| {
                CliError::Input("Pages source Git proof runtime was unavailable".to_owned())
            })?;
        runtime.block_on(async move {
            let mut command = processkit::Command::new(&program);
            if let Some(repository_root) = repository_root {
                command = command.arg("-C").arg(repository_root);
            } else {
                command = command.current_dir(env::temp_dir());
            }
            command = command
                .args(arguments)
                .env_clear()
                .env("PATH", path)
                .env("GIT_TERMINAL_PROMPT", "0")
                .env("GIT_ASKPASS", "")
                .env("SSH_ASKPASS", "")
                .env("SSH_ASKPASS_REQUIRE", "never")
                .env("GCM_INTERACTIVE", "Never")
                .stdin(processkit::Stdin::empty())
                .stderr(processkit::StdioMode::Null)
                .output_buffer(processkit::OutputBufferPolicy::bounded(8_192).with_max_bytes(8_192))
                .timeout(timeout);
            for (name, value) in inherited_environment {
                command = command.env(name, value);
            }
            let output = command.output_bytes().await.map_err(|_| {
                CliError::Input("Pages source Git proof could not start or complete".to_owned())
            })?;
            if output.timed_out() {
                return Err(CliError::SubprocessTimeout(
                    "Pages source Git proof".to_owned(),
                ));
            }
            if output.truncated() || output.stdout().len() > 8_192 {
                return Err(CliError::Input(
                    "Pages source Git proof output exceeded its fixed bound".to_owned(),
                ));
            }
            let stdout = String::from_utf8(output.stdout().clone()).map_err(|_| {
                CliError::Input("Pages source Git proof output was not UTF-8".to_owned())
            })?;
            Ok(BoundedPagesGitOutput {
                success: output.is_success(),
                code: output.code(),
                stdout,
            })
        })
    })
    .join()
    .map_err(|_| CliError::Input("Pages source Git proof runtime failed".to_owned()))?
}

fn pages_git_output(
    repository_root: Option<&Path>,
    arguments: &[&str],
    timeout: Duration,
    allow_no_match: bool,
) -> Result<String> {
    let output =
        run_bounded_pages_git_program(Path::new("git"), repository_root, arguments, timeout)?;
    if output.success {
        return Ok(output.stdout);
    }
    if allow_no_match && output.code == Some(1) && output.stdout.is_empty() {
        return Ok(String::new());
    }
    Err(CliError::Input(
        "Pages source Git proof failed without exposing subprocess output".to_owned(),
    ))
}

fn configured_origin(repository_root: &Path) -> Result<Option<String>> {
    let output = pages_git_output(
        Some(repository_root),
        &["config", "--get-all", "remote.origin.url"],
        PAGES_GIT_CONFIG_TIMEOUT,
        true,
    )?;
    if output.is_empty() {
        return Ok(None);
    }
    let rows = output.lines().collect::<Vec<_>>();
    if rows.len() != 1 || rows[0].is_empty() || rows[0].trim() != rows[0] {
        return Err(CliError::Input(
            "Pages source repository must have exactly one raw effective origin URL".to_owned(),
        ));
    }
    Ok(Some(rows[0].to_owned()))
}

fn matching_git_url_rewrite(config: &str, candidates: &[&str]) -> Result<bool> {
    for row in config.lines().filter(|row| !row.is_empty()) {
        let Some(separator) = row.find(char::is_whitespace) else {
            return Err(CliError::Input(
                "Pages source Git URL rewrite configuration was malformed".to_owned(),
            ));
        };
        let (key, value) = row.split_at(separator);
        let value = value.trim();
        if !key.starts_with("url.") || !key.ends_with(".insteadof") || value.is_empty() {
            return Err(CliError::Input(
                "Pages source Git URL rewrite configuration was malformed".to_owned(),
            ));
        }
        if candidates
            .iter()
            .any(|candidate| candidate.starts_with(value))
        {
            return Ok(true);
        }
    }
    Ok(false)
}

fn registered_pages_source_repository<'a>(
    graph: &'a WorkspaceGraph,
    input: &CallInput,
) -> Result<&'a RepositoryNode> {
    let (owner, repository, _) = pages_github_source(input)?;
    let expected = (owner.to_ascii_lowercase(), repository.to_ascii_lowercase());
    let mut matches = Vec::new();
    for candidate in &graph.repositories {
        let Ok(Some(origin)) = configured_origin(&candidate.path) else {
            continue;
        };
        if github_remote_identity(&origin).as_ref() == Some(&expected) {
            matches.push(candidate);
        }
    }
    if matches.len() != 1 {
        return Err(CliError::Input(format!(
            "Pages Git source must match exactly one registered repository; found {}",
            matches.len()
        )));
    }
    Ok(matches[0])
}

fn parse_pages_remote_head(output: &str, branch: &str) -> Result<String> {
    let expected_ref = format!("refs/heads/{branch}");
    let rows = output.lines().collect::<Vec<_>>();
    let Some(row) = rows.first() else {
        return Err(CliError::Input(
            "Pages source branch did not resolve to one exact remote commit".to_owned(),
        ));
    };
    let Some((commit, remote_ref)) = row.split_once('\t') else {
        return Err(CliError::Input(
            "Pages source branch returned a malformed remote identity".to_owned(),
        ));
    };
    if rows.len() != 1 || remote_ref != expected_ref || !is_canonical_git_sha1(commit) {
        return Err(CliError::Input(
            "Pages source branch did not resolve to one exact remote commit".to_owned(),
        ));
    }
    Ok(commit.to_owned())
}

fn is_canonical_git_sha1(value: &str) -> bool {
    value.len() == 40
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn pages_source_remote_receipt(input: &CallInput, remote_commit: &str) -> Result<Value> {
    let (owner, repository, branch) = pages_github_source(input)?;
    if !is_canonical_git_sha1(remote_commit) {
        return Err(CliError::Input(
            "Pages source branch returned a malformed remote commit".to_owned(),
        ));
    }
    Ok(json!({
        "schema_version": 1,
        "provider": "github",
        "owner": owner.to_ascii_lowercase(),
        "repository": repository.to_ascii_lowercase(),
        "branch": branch,
        "remote_ref": format!("refs/heads/{branch}"),
        "remote_commit": remote_commit,
    }))
}

fn pages_source_remote_snapshot(repository: &RepositoryNode, input: &CallInput) -> Result<Value> {
    let (owner, repository_name, branch) = pages_github_source(input)?;
    let expected = (
        owner.to_ascii_lowercase(),
        repository_name.to_ascii_lowercase(),
    );
    let origin = configured_origin(&repository.path)?.ok_or_else(|| {
        CliError::Input("Pages source repository has no raw local origin URL".to_owned())
    })?;
    if github_remote_identity(&origin).as_ref() != Some(&expected) {
        return Err(CliError::Input(
            "Pages source repository origin drifted from the reviewed GitHub identity".to_owned(),
        ));
    }
    let canonical_remote = format!("https://github.com/{owner}/{repository_name}.git");
    let rewrites = pages_git_output(
        Some(&repository.path),
        &["config", "--get-regexp", "^url\\..*\\.insteadof$"],
        PAGES_GIT_CONFIG_TIMEOUT,
        true,
    )?;
    if matching_git_url_rewrite(&rewrites, &[&origin, &canonical_remote])? {
        return Err(CliError::Input(
            "Pages source Git identity is subject to a configured URL substitution".to_owned(),
        ));
    }
    let remote_ref = format!("refs/heads/{branch}");
    let output = pages_git_output(
        None,
        &[
            "-c",
            "credential.helper=",
            "ls-remote",
            "--exit-code",
            "--refs",
            &canonical_remote,
            &remote_ref,
        ],
        PAGES_GIT_REMOTE_TIMEOUT,
        false,
    )?;
    let remote_commit = parse_pages_remote_head(&output, branch)?;
    pages_source_remote_receipt(input, &remote_commit)
}

fn plan_impact(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
    account_id: &str,
) -> Result<PlannedImpact> {
    let selector_map = input.selectors.as_object();
    let query_map = input.query.as_object();
    let missing_required = capability.selectors.iter().any(|selector| {
        if !selector.required || (selector.name == "account_id" && !account_id.is_empty()) {
            return false;
        }
        let values = if selector.location == "query" {
            query_map
        } else {
            selector_map
        };
        values.and_then(|map| map.get(&selector.name)).is_none()
    });
    let graph = discover_registered(store)?;
    let mut affected_resources = Vec::new();
    if let Some(selectors) = selector_map {
        for (key, value) in selectors {
            if let Some(value) = value.as_str() {
                affected_resources.push(format!("{key}:{value}"));
            }
        }
    }
    let workspace_resource_keys = workspace_resource_keys(capability, input);
    affected_resources.extend(workspace_resource_keys.iter().cloned());
    affected_resources.sort();
    affected_resources.dedup();
    let workspace_impact = graph.impact_for(&workspace_resource_keys);
    let local_artifact_paths = plan_local_artifact_paths(capability, input)?;
    let mut affected_repositories = workspace_impact.affected_repositories.clone();
    if should_bind_pages_project_absence(capability) {
        let source_repository = registered_pages_source_repository(&graph, input)?;
        affected_repositories.push(source_repository.path.display().to_string());
    }
    for artifact in &local_artifact_paths {
        let repository = repository_owning_path(&graph, artifact).ok_or_else(|| {
            CliError::Input(format!(
                "local deployment artifact `{}` is not owned by a registered repository",
                artifact.display()
            ))
        })?;
        affected_repositories.push(repository.path.display().to_string());
    }
    affected_repositories.sort();
    affected_repositories.dedup();
    affected_resources.extend(
        local_artifact_paths
            .iter()
            .map(|path| format!("source_artifact:{}", path.display())),
    );
    affected_resources.sort();
    affected_resources.dedup();
    let mut local_diffs = workspace_impact
        .local_diffs
        .iter()
        .map(serde_json::to_value)
        .collect::<std::result::Result<Vec<_>, _>>()?;
    append_local_artifact_diffs(&graph, &local_artifact_paths, &mut local_diffs)?;
    for repository_id in &affected_repositories {
        let Some(repository) = graph.repository(repository_id) else {
            continue;
        };
        for config in &repository.configs {
            let diff = json!({
                "repository": repository.path,
                "path": config.path,
                "kind": config.kind,
                "content_hash": config.content_hash,
                "head_content_hash": config.head_content_hash,
                "worktree_diff_hash": config.worktree_diff_hash,
                "dirty": config.dirty,
            });
            if !local_diffs.contains(&diff) {
                local_diffs.push(diff);
            }
        }
    }
    local_diffs.sort_by_key(|value| value["path"].as_str().unwrap_or_default().to_owned());
    let policy = ImpactContext {
        affected_repositories: affected_repositories.len(),
        affected_resources: affected_resources.len(),
        dependent_configurations: local_diffs.len(),
        has_unmanaged_dependencies: workspace_impact.has_unmanaged_dependencies,
        has_dirty_overlap: affected_repositories.iter().any(|repository_id| {
            graph
                .repository(repository_id)
                .is_some_and(|repository| repository.git.dirty)
        }),
        selector_ambiguous: missing_required,
    };
    Ok(PlannedImpact {
        policy,
        affected_repositories,
        affected_resources,
        local_diffs,
        local_artifact_paths,
    })
}

fn append_local_artifact_diffs(
    graph: &WorkspaceGraph,
    artifact_paths: &[PathBuf],
    local_diffs: &mut Vec<Value>,
) -> Result<()> {
    for artifact in artifact_paths {
        let repository = repository_owning_path(graph, artifact).ok_or_else(|| {
            CliError::Input(format!(
                "local deployment artifact `{}` is not owned by a registered repository",
                artifact.display()
            ))
        })?;
        local_diffs.push(json!({
            "repository": repository.path,
            "path": artifact,
            "kind": "deployment_artifact",
            "content_hash": hash_directory_artifact(artifact)?,
            "head_content_hash": Value::Null,
            "worktree_diff_hash": Value::Null,
            "dirty": false,
        }));
    }
    Ok(())
}

fn plan_local_artifact_paths(capability: &CapabilityV1, input: &CallInput) -> Result<Vec<PathBuf>> {
    if worker_deployment::binds_artifact(capability) {
        return worker_deployment::artifact_paths(capability, input);
    }
    if capability.id != "wrangler.pages-deploy" {
        return Ok(Vec::new());
    }
    let raw = input
        .query
        .get("argument")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("Pages deployment requires an artifact directory".to_owned())
        })?;
    let path = fs::canonicalize(raw).map_err(|source| cli_io(Path::new(raw), source))?;
    if !path.is_dir() {
        return Err(CliError::Input(format!(
            "Pages deployment artifact `{}` is not a directory",
            path.display()
        )));
    }
    Ok(vec![path])
}

fn repository_owning_path<'a>(
    graph: &'a WorkspaceGraph,
    path: &Path,
) -> Option<&'a cfctl_workspace::RepositoryNode> {
    graph
        .repositories
        .iter()
        .filter(|repository| path.starts_with(&repository.path))
        .max_by_key(|repository| repository.path.components().count())
}

fn workspace_resource_keys(capability: &CapabilityV1, input: &CallInput) -> Vec<String> {
    let mut resources = Vec::new();
    collect_workspace_resource_keys(capability, &input.selectors, None, &mut resources);
    collect_workspace_resource_keys(capability, &input.query, None, &mut resources);
    if let Some(body) = &input.body {
        collect_workspace_resource_keys(capability, body, None, &mut resources);
        if should_bind_pages_project_absence(capability)
            && let Some(name) = body.get("name").and_then(Value::as_str)
            && !name.is_empty()
        {
            resources.push(format!("pages_project:{name}"));
        }
    }
    resources.sort();
    resources.dedup();
    resources
}

fn collect_workspace_resource_keys(
    capability: &CapabilityV1,
    value: &Value,
    field: Option<&str>,
    resources: &mut Vec<String>,
) {
    match value {
        Value::Object(object) => {
            for (key, value) in object {
                collect_workspace_resource_keys(capability, value, Some(key), resources);
            }
        }
        Value::Array(values) => {
            for value in values {
                collect_workspace_resource_keys(capability, value, field, resources);
            }
        }
        Value::String(value) => {
            let field = field.unwrap_or_default().to_ascii_lowercase();
            let product = capability.product.to_ascii_lowercase();
            let is_hostname_name = field == "name"
                && value.contains('.')
                && (capability.path.contains("/dns_records") || product.contains("dns record"));
            let is_hostname_pattern = field == "pattern"
                && (capability.path.contains("/workers/routes")
                    || product.contains("worker route"));
            let resource = if field.contains("hostname") || is_hostname_name || is_hostname_pattern
            {
                hostname_from_resource_value(value).map(|hostname| format!("hostname:{hostname}"))
            } else if field == "zone_name" {
                Some(format!("zone:{value}"))
            } else if matches!(field.as_str(), "script_name" | "worker" | "worker_name") {
                Some(format!("worker:{value}"))
            } else if matches!(field.as_str(), "bucket_name" | "r2_bucket") {
                Some(format!("r2_bucket:{value}"))
            } else if matches!(field.as_str(), "database_id" | "database_name") {
                Some(format!("d1_database:{value}"))
            } else if matches!(field.as_str(), "namespace_id" | "kv_namespace_id")
                && (capability.path.contains("/storage/kv/namespaces")
                    || product == "workers kv namespace")
            {
                Some(format!("kv_namespace:{value}"))
            } else if matches!(field.as_str(), "queue" | "queue_name") {
                Some(format!("queue:{value}"))
            } else if matches!(field.as_str(), "service" | "service_name") {
                Some(format!("service:{value}"))
            } else {
                None
            };
            if let Some(resource) = resource {
                resources.push(resource);
            }
        }
        _ => {}
    }
}

fn hostname_from_resource_value(value: &str) -> Option<String> {
    let without_scheme = value
        .split_once("://")
        .map_or(value, |(_, remainder)| remainder);
    let hostname = without_scheme
        .split('/')
        .next()
        .unwrap_or_default()
        .trim_start_matches("*.")
        .trim_end_matches('*')
        .trim_end_matches('.');
    (!hostname.is_empty()).then(|| hostname.to_owned())
}

async fn plans_command(store: &StateStore, command: PlansCommand) -> Result<ResultEnvelopeV2> {
    match command {
        PlansCommand::Show(selector) | PlansCommand::Status(selector) => {
            show_plan(store, &selector)
        }
        PlansCommand::Approve(arguments) => approve_plan(store, &arguments),
        PlansCommand::Run(selector) => Box::pin(run_plan(store, &selector)).await,
        PlansCommand::Resume(selector) => Box::pin(resume_plan(store, &selector)).await,
        PlansCommand::Rectify(selector) => Box::pin(rectify_plan(store, &selector)).await,
        PlansCommand::Cancel(selector) => cancel_plan(store, &selector),
    }
}

fn load_validated_plan(store: &StateStore, operation_id: &str) -> Result<PlanV1> {
    let record = store.load_stored_plan_record(operation_id)?;
    let plan = match record {
        StoredPlanRecord::Current(plan) => plan.plan,
        StoredPlanRecord::LegacyReadable(plan) | StoredPlanRecord::RequiredSidecarMissing(plan) => {
            *plan
        }
        StoredPlanRecord::ProjectionDrift { .. } => {
            return Err(CliError::guided(
                "CFCTL_PLAN_V2_DRIFT",
                format!(
                    "PlanV2 `{operation_id}` disagrees with its PlanV1 compatibility projection"
                ),
                "Do not approve, run, or resume this plan. Inspect the canonical PlanV2 and repair its compatibility projection before proceeding.",
            ));
        }
        StoredPlanRecord::Corrupt { reason, .. } => {
            return Err(CliError::guided(
                "CFCTL_PLAN_CORRUPT",
                format!("plan `{operation_id}` is corrupt: {reason}"),
                "Do not replay or replace the plan in place. Preserve the files and inspect the exact durable record before recovery.",
            ));
        }
    };
    plan.validate_transaction_journal()?;
    Ok(plan)
}

fn ensure_plan_execution_contract(store: &StateStore, plan: &PlanV1) -> Result<()> {
    match store.load_stored_plan_record(&plan.operation_id)? {
        StoredPlanRecord::Current(_) => Ok(()),
        StoredPlanRecord::LegacyReadable(_) => Err(CliError::guided(
            "CFCTL_PLAN_REPLAN_REQUIRED",
            format!(
                "historical PlanV1 mutation `{}` remains readable but cannot be approved or executed",
                plan.operation_id
            ),
            format!(
                "Re-run `cfctl call {}` with the original reviewed selectors and body to create a fully pinned PlanV2.",
                plan.capability.id
            ),
        )),
        StoredPlanRecord::RequiredSidecarMissing(_) => Err(CliError::guided(
            "CFCTL_PLAN_V2_MISSING",
            format!(
                "current mutation plan `{}` is missing its required canonical PlanV2 document",
                plan.operation_id
            ),
            format!(
                "Do not approve or execute this incomplete plan. Re-run `cfctl call {}` to create a new fully pinned PlanV2.",
                plan.capability.id
            ),
        )),
        StoredPlanRecord::ProjectionDrift { .. } => Err(CliError::guided(
            "CFCTL_PLAN_V2_DRIFT",
            "the canonical PlanV2 disagrees with its PlanV1 compatibility projection",
            "Do not approve, run, or resume this plan until its durable projection is repaired.",
        )),
        StoredPlanRecord::Corrupt { reason, .. } => Err(CliError::guided(
            "CFCTL_PLAN_CORRUPT",
            reason,
            "Preserve the durable files and inspect the exact plan record before recovery.",
        )),
    }
}

fn validate_plan_v2_runtime_pins(
    store: &StateStore,
    plan: &PlanV1,
    profile: &ProfileMetadata,
) -> Result<()> {
    let StoredPlanRecord::Current(plan_v2) = store.load_stored_plan_record(&plan.operation_id)?
    else {
        ensure_plan_execution_contract(store, plan)?;
        return Err(CliError::guided(
            "CFCTL_PLAN_V2_MISSING",
            "the execution contract is not a current PlanV2",
            "Create and approve a new fully pinned PlanV2.",
        ));
    };
    let plan_v2 = *plan_v2;
    let current_build_hash = hash_value(&serde_json::to_value(current_build_info())?)?;
    if plan_v2.pins.build_identity_hash != current_build_hash {
        return Err(CliError::guided(
            "CFCTL_PLAN_BUILD_DRIFT",
            "the running build identity no longer matches the PlanV2 pin",
            format!(
                "Re-run `cfctl call {}` under the current checkout build.",
                plan.capability.id
            ),
        ));
    }
    if profile.credential_generation_id.as_deref()
        != Some(plan_v2.pins.credential_generation_id.as_str())
    {
        return Err(CliError::guided(
            "CFCTL_PLAN_CREDENTIAL_DRIFT",
            "the selected credential generation no longer matches the PlanV2 pin",
            format!(
                "Re-authenticate profile `{}` and create a new plan.",
                profile.id
            ),
        ));
    }
    let current_policy = active_admission_policy(store)?;
    match current_policy {
        Some(bundle)
            if plan_v2.pins.admission_policy_hash != format!("bundle:{}", bundle.content_hash) =>
        {
            return Err(CliError::guided(
                "CFCTL_PLAN_POLICY_DRIFT",
                "the active admission policy no longer matches the PlanV2 pin",
                format!(
                    "Re-run `cfctl call {}` under the active bundle.",
                    plan.capability.id
                ),
            ));
        }
        None if !plan_v2
            .pins
            .admission_policy_hash
            .starts_with("compiled:sha256:") =>
        {
            return Err(CliError::guided(
                "CFCTL_PLAN_POLICY_DRIFT",
                "the PlanV2 was created under an admission bundle that is no longer active",
                format!(
                    "Re-run `cfctl call {}` under the compiled safety floor.",
                    plan.capability.id
                ),
            ));
        }
        _ => {}
    }
    if let Some(authority_hash) = &plan_v2.pins.authority_hash {
        let authority = store
            .list_authorities()?
            .into_iter()
            .find(|authority| &authority.content_hash == authority_hash)
            .ok_or_else(|| {
                CliError::guided(
                    "CFCTL_PLAN_AUTHORITY_DRIFT",
                    "the PlanV2 authority pin no longer resolves",
                    "Create and approve a new token lifecycle policy, then re-plan.",
                )
            })?;
        authority.ensure_operational()?;
    }
    Ok(())
}

fn persist_transaction_stage(
    store: &StateStore,
    plan: &mut PlanV1,
    stage: TransactionStageV1,
) -> Result<()> {
    plan.record_transaction_stage(stage)?;
    store.save_plan(plan)?;
    Ok(())
}

fn persist_transaction_stage_with_artifact(
    store: &StateStore,
    plan: &mut PlanV1,
    stage: TransactionStageV1,
    artifact: Value,
) -> Result<()> {
    plan.record_transaction_stage_with_artifact(stage, artifact)?;
    store.save_plan(plan)?;
    Ok(())
}

fn show_plan(store: &StateStore, selector: &PlanSelector) -> Result<ResultEnvelopeV2> {
    let record = store.load_stored_plan_record(&selector.operation_id)?;
    let plan = record.readable_plan().cloned().ok_or_else(|| {
        let reason = match &record {
            StoredPlanRecord::Corrupt { reason, .. } => reason.as_str(),
            _ => "the plan has no readable body",
        };
        CliError::guided(
            "CFCTL_PLAN_CORRUPT",
            reason,
            "Preserve the durable files and inspect the exact plan record before recovery.",
        )
    })?;
    plan.validate_transaction_journal()?;
    let mut result = serde_json::to_value(&plan)?;
    let plan_v2 = match &record {
        StoredPlanRecord::Current(plan)
        | StoredPlanRecord::ProjectionDrift { current: plan, .. } => Some(plan),
        _ => None,
    };
    if let Some(object) = result.as_object_mut() {
        object.insert("plan_v2".to_owned(), serde_json::to_value(plan_v2)?);
        object.insert(
            "execution_compatible".to_owned(),
            json!(record.execution_compatible()),
        );
        object.insert(
            "execution_incompatibility_reason".to_owned(),
            serde_json::to_value(record.execution_incompatibility_reason())?,
        );
    }
    let mut envelope = ResultEnvelopeV2::success("plans show", result);
    envelope.operation_id = Some(plan.operation_id);
    envelope.capability_id = Some(plan.capability.id);
    envelope.policy_decision = Some(plan.policy);
    envelope.verification.state = verification_for_status(plan.status);
    Ok(envelope)
}

fn approve_plan(store: &StateStore, arguments: &PlanApproveArgs) -> Result<ResultEnvelopeV2> {
    let _lock = store.lock_plan(&arguments.operation_id)?;
    let mut plan = load_validated_plan(store, &arguments.operation_id)?;
    ensure_plan_execution_contract(store, &plan)?;
    let max_cost = arguments.max_cost.as_deref().map(parse_money).transpose()?;
    plan.approve(arguments.yes, max_cost)?;
    store.save_plan(&plan)?;
    let evidence = store.write_evidence(EvidenceClass::Preview, &serde_json::to_value(&plan)?)?;
    let mut envelope = ResultEnvelopeV2::success(
        "plans approve",
        json!({
            "operation_id": plan.operation_id,
            "content_hash": plan.content_hash,
            "expires_at": plan.expires_at,
            "run_command": format!("cfctl plans run {}", plan.operation_id),
            "message": "The exact hash-bound plan is approved."
        }),
    )
    .with_evidence(evidence);
    envelope.operation_id = Some(plan.operation_id);
    envelope.capability_id = Some(plan.capability.id);
    envelope.policy_decision = Some(plan.policy);
    Ok(envelope)
}

fn cancel_plan(store: &StateStore, selector: &PlanSelector) -> Result<ResultEnvelopeV2> {
    let _lock = store.lock_plan(&selector.operation_id)?;
    // Deliberately load the storage classification, not the execution
    // contract: cancellation must
    // de-authorize even a plan whose journal or content no longer validates —
    // refusing would preserve exactly the authority being retired.
    let record = store.load_stored_plan_record(&selector.operation_id)?;
    let mut plan = record.readable_plan().cloned().ok_or_else(|| {
        CliError::guided(
            "CFCTL_PLAN_CORRUPT",
            "the plan has no readable canonical body to cancel",
            "Preserve the durable record and inspect it before attempting recovery.",
        )
    })?;
    plan.cancel()?;
    store.save_plan(&plan)?;
    let evidence = store.write_evidence(EvidenceClass::Preview, &serde_json::to_value(&plan)?)?;
    let mut envelope = ResultEnvelopeV2::success(
        "plans cancel",
        json!({
            "operation_id": plan.operation_id,
            "status": plan_status_label(plan.status),
            "cancelled_at": plan.cancelled_at,
            "message": "The plan's latent authority is retired; it can no longer be approved or run."
        }),
    )
    .with_evidence(evidence);
    envelope.operation_id = Some(plan.operation_id);
    envelope.capability_id = Some(plan.capability.id);
    envelope.policy_decision = Some(plan.policy);
    Ok(envelope)
}

#[expect(
    clippy::too_many_lines,
    reason = "execution revalidates capability-specific immutable authority before dispatch"
)]
async fn run_plan(store: &StateStore, selector: &PlanSelector) -> Result<ResultEnvelopeV2> {
    let _lock = store.lock_plan(&selector.operation_id)?;
    let catalog = ensure_catalog(store).await?;
    let mut plan = load_validated_plan(store, &selector.operation_id)?;
    ensure_plan_execution_contract(store, &plan)?;
    if plan.catalog_hash != catalog.schema_hash {
        return Err(CliError::Input(format!(
            "catalog drift invalidated the plan: planned {}, current {}",
            plan.catalog_hash, catalog.schema_hash
        )));
    }
    validate_plan_preconditions(store, &plan)?;
    if plan.capability.adapter_status == AdapterStatus::Blocked {
        let mut envelope = blocked_capability_envelope(
            "plans run",
            &plan.capability,
            plan.capability
                .blocked_reason
                .as_deref()
                .unwrap_or("the approved capability no longer has an executable adapter"),
        );
        envelope.operation_id = Some(plan.operation_id.clone());
        envelope.profile_id = Some(plan.profile_id.clone());
        envelope.account_id = Some(plan.account_id.clone());
        return Ok(envelope);
    }
    preflight_secret_sink(&plan)?;
    let profiles = ProfilesConfig::load(store)?;
    let profile = profiles.selected(Some(&plan.profile_id))?;
    if plan.capability.d1_approved_mln_import.is_some() {
        let execution_input: CallInput = serde_json::from_value(plan.input.clone())?;
        validate_approved_mln_import_prerequisites(
            store,
            &plan.capability,
            &execution_input,
            ImportPrerequisiteContext {
                profile_id: &plan.profile_id,
                credential_generation_id: profile.credential_generation_id.as_deref(),
                catalog_hash: &plan.catalog_hash,
                import_operation_id: Some(&plan.operation_id),
                before: plan.created_at,
            },
        )?;
    }
    if plan.capability.d1_approved_mln_import_poll_resume.is_some() {
        let execution_input: CallInput = serde_json::from_value(plan.input.clone())?;
        let derived = validate_and_derive_resume_poll_authority(
            store,
            &plan.capability,
            &execution_input,
            &plan.profile_id,
            profile.credential_generation_id.as_deref(),
            &plan.catalog_hash,
            plan.created_at,
            Some(&plan.operation_id),
        )?;
        if plan
            .targets
            .pointer("/adapter/approved_mln_import_poll_resume")
            != Some(&derived)
        {
            return Err(CliError::Input(
                "poll continuation authority drifted after planning; do not cross the provider boundary"
                    .to_owned(),
            ));
        }
    }
    validate_plan_v2_runtime_pins(store, &plan, profile)?;
    if is_r2_temporary_credentials_operation_identity(&plan.capability)
        && profile.kind != ProfileKind::ApiToken
    {
        return Err(CliError::Input(
            "R2 temporary credential plan no longer selects its required scoped API-token profile; the mutation boundary was not crossed"
                .to_owned(),
        ));
    }
    let secrets = platform_secrets(store);
    let credential = fresh_credential(profile, &secrets).await?;
    let execution_input = resolved_plan_input(&plan, &secrets)?;
    let adapter_targets = plan.targets.get("adapter").unwrap_or(&Value::Null);
    validate_worker_deployment_local_authority(store, &plan, &execution_input)?;
    validate_api_token_creation_contract(
        &plan.capability,
        &execution_input,
        adapter_targets,
        &plan.account_id,
    )?;
    let live_precondition_evidence = validate_live_plan_precondition_evidence(
        store,
        &catalog,
        &plan,
        &execution_input,
        &credential,
        None,
    )
    .await?;
    plan.mark_consumed()?;
    store.save_plan(&plan)?;
    persist_transaction_stage(
        store,
        &mut plan,
        TransactionStageV1::BoundaryAttemptPersisted,
    )?;
    Box::pin(execute_consumed_plan(
        store,
        &catalog,
        &mut plan,
        &execution_input,
        &credential,
        &secrets,
        live_precondition_evidence,
    ))
    .await
}

/// The standing-authority execution lane. Identical to `run_plan` in every
/// pre-consumption re-verification (catalog hash, workspace and live
/// precondition hashes, token contract, secret sink); it differs only at the
/// consumption gate, where the authority's blast-radius bounds are validated
/// against the exact resolved execution input and consumption is recorded
/// against the authority instead of a per-operation approval.
async fn run_plan_under_standing_authority(
    store: &StateStore,
    operation_id: &str,
    authority_id: &str,
) -> Result<ResultEnvelopeV2> {
    // Lock order is always plan -> authority. The plan lock may span async
    // preflight; the authority lock is acquired only for the synchronous
    // admission critical section below and is released before network I/O.
    let _plan_lock = store.lock_plan(operation_id)?;
    let authority_snapshot = store.load_authority(authority_id)?;
    store.bind_plan_authority_hash(operation_id, &authority_snapshot.content_hash)?;
    let catalog = ensure_catalog(store).await?;
    let mut plan = load_validated_plan(store, operation_id)?;
    ensure_plan_execution_contract(store, &plan)?;
    if plan.catalog_hash != catalog.schema_hash {
        return Err(CliError::Input(format!(
            "catalog drift invalidated the plan: planned {}, current {}",
            plan.catalog_hash, catalog.schema_hash
        )));
    }
    validate_plan_preconditions(store, &plan)?;
    if plan.capability.adapter_status == AdapterStatus::Blocked {
        let mut envelope = blocked_capability_envelope(
            "plans run",
            &plan.capability,
            plan.capability
                .blocked_reason
                .as_deref()
                .unwrap_or("the approved capability no longer has an executable adapter"),
        );
        envelope.operation_id = Some(plan.operation_id.clone());
        envelope.profile_id = Some(plan.profile_id.clone());
        envelope.account_id = Some(plan.account_id.clone());
        return Ok(envelope);
    }
    preflight_secret_sink(&plan)?;
    let profiles = ProfilesConfig::load(store)?;
    let profile = profiles.selected(Some(&plan.profile_id))?;
    validate_plan_v2_runtime_pins(store, &plan, profile)?;
    let secrets = platform_secrets(store);
    let credential = fresh_credential(profile, &secrets).await?;
    let execution_input = resolved_plan_input(&plan, &secrets)?;
    let adapter_targets = plan.targets.get("adapter").unwrap_or(&Value::Null);
    validate_worker_deployment_local_authority(store, &plan, &execution_input)?;
    validate_api_token_creation_contract(
        &plan.capability,
        &execution_input,
        adapter_targets,
        &plan.account_id,
    )?;
    let live_precondition_evidence = validate_live_plan_precondition_evidence(
        store,
        &catalog,
        &plan,
        &execution_input,
        &credential,
        Some(&authority_snapshot),
    )
    .await?;
    authorize_standing_execution(&authority_snapshot, &plan, &execution_input)?;
    let standing_evidence =
        admit_standing_plan(store, &mut plan, &authority_snapshot, &execution_input)?;
    let admitted_authority_id = authority_snapshot.authority_id.clone();
    let mut envelope = Box::pin(execute_consumed_plan(
        store,
        &catalog,
        &mut plan,
        &execution_input,
        &credential,
        &secrets,
        live_precondition_evidence,
    ))
    .await?;
    envelope.evidence.push(standing_evidence);
    if let Some(result) = envelope.result.as_object_mut() {
        result.insert(
            "standing_authority_id".to_owned(),
            json!(admitted_authority_id),
        );
    }
    Ok(envelope)
}

/// Performs the synchronous standing-authority admission transaction while
/// the caller holds the plan lock. No network or async work is permitted in
/// this critical section.
fn admit_standing_plan(
    store: &StateStore,
    plan: &mut PlanV1,
    authority_snapshot: &StandingAuthorityV1,
    execution_input: &CallInput,
) -> Result<EvidenceV1> {
    let authority_guard = store.lock_authority(&authority_snapshot.authority_id)?;
    let mut authority = store.load_authority(&authority_snapshot.authority_id)?;
    if authority.content_hash != authority_snapshot.content_hash {
        return Err(CliError::Input(
            "standing authority changed during live preflight; the mutation boundary was not crossed"
                .to_owned(),
        ));
    }
    // The live inventory was validated against the snapshot. Exact
    // content-hash equality plus the operational/hash check below proves
    // that the locked authority carries the same immutable allowlist.
    let admission_time = Utc::now();
    authorize_standing_execution_at(&authority, plan, execution_input, admission_time)?;
    plan.mark_consumed_via_standing_authority(&authority)?;
    // Durable reservation is the admission linearization point. It is saved
    // before plan consumption so a persistence failure may spend a budget
    // slot but can never permit an unaccounted boundary attempt.
    authority.reserve_run(admission_time, &plan.operation_id, &plan.capability.id)?;
    store.save_authority_guarded(&authority, &authority_guard)?;
    store.save_plan(plan)?;
    let evidence = store.write_evidence(
        EvidenceClass::StandingApply,
        &json!({
            "standing_authority_id": authority.authority_id,
            "standing_authority_content_hash": authority.content_hash,
            "operation_id": plan.operation_id,
            "capability_id": plan.capability.id,
            "account_id": plan.account_id,
            "admission": "durable_run_reservation",
        }),
    )?;
    persist_transaction_stage(store, plan, TransactionStageV1::BoundaryAttemptPersisted)?;
    Ok(evidence)
}

/// Validates the authority's bounds against the exact execution input the
/// boundary call will use — never a re-derivation.
fn authorize_standing_execution(
    authority: &StandingAuthorityV1,
    plan: &PlanV1,
    input: &CallInput,
) -> Result<()> {
    authorize_standing_execution_at(authority, plan, input, Utc::now())
}

fn authorize_standing_execution_at(
    authority: &StandingAuthorityV1,
    plan: &PlanV1,
    input: &CallInput,
    now: chrono::DateTime<Utc>,
) -> Result<()> {
    if plan.capability.id.ends_with("create-token") {
        let body = input.body.as_ref().ok_or_else(|| {
            CliError::Input("a standing mint requires the plan's request body".to_owned())
        })?;
        let child_name = body.get("name").and_then(Value::as_str).ok_or_else(|| {
            CliError::Input("a standing mint requires a child token name".to_owned())
        })?;
        let requested_group_ids: Vec<String> = body
            .get("policies")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|policy| policy.get("permission_groups").and_then(Value::as_array))
            .flatten()
            .filter_map(|group| group.get("id").and_then(Value::as_str))
            .map(str::to_owned)
            .collect();
        // Each policy's `resources` object is keyed by the resource string the
        // child token would bind. The authority bounds which of those are
        // permitted, so collect every key rather than assuming one policy.
        let requested_resources: Vec<String> = body
            .get("policies")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|policy| policy.get("resources").and_then(Value::as_object))
            .flat_map(serde_json::Map::keys)
            .map(String::to_owned)
            .collect();
        let child_expires_at = body
            .get("expires_on")
            .and_then(Value::as_str)
            .map(|raw| {
                chrono::DateTime::parse_from_rfc3339(raw)
                    .map(|parsed| parsed.with_timezone(&Utc))
                    .map_err(|error| {
                        CliError::Input(format!(
                            "the standing mint carries an unparseable expires_on: {error}"
                        ))
                    })
            })
            .transpose()?;
        authority.authorize_token_create(
            now,
            child_name,
            &requested_group_ids,
            &requested_resources,
            child_expires_at,
        )?;
    } else if plan.capability.id.ends_with("delete-token") {
        let token_id = input
            .selectors
            .get("token_id")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                CliError::Input("a standing revoke requires a token_id selector".to_owned())
            })?;
        authority.authorize_token_delete(now, token_id)?;
    } else {
        return Err(CliError::Input(format!(
            "standing authorities do not cover capability `{}`",
            plan.capability.id
        )));
    }
    Ok(())
}

/// Returns the created token ID only when the validated transaction journal
/// proves that this exact authority admitted the plan and Cloudflare returned
/// a successful creation receipt. Revocation is intentionally not consulted:
/// lineage reconciliation records an already-crossed boundary; it grants no
/// new authority.
fn validated_standing_lineage_token_id<'a>(
    plan: &'a PlanV1,
    authority: &StandingAuthorityV1,
) -> Result<Option<&'a str>> {
    plan.validate_transaction_journal()?;
    let Some(binding) = plan.transaction_artifact(TransactionStageV1::ConsumptionPersisted) else {
        return Ok(None);
    };
    let bound_authority_id = binding
        .get("standing_authority_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CliError::Input(
                "standing consumption receipt has no authority ID; do not replay the mutation"
                    .to_owned(),
            )
        })?;
    let bound_authority_hash = binding
        .get("standing_authority_content_hash")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CliError::Input(
                "standing consumption receipt has no authority content hash; do not replay the mutation"
                    .to_owned(),
            )
        })?;
    if bound_authority_id != authority.authority_id
        || bound_authority_hash != authority.content_hash
    {
        return Err(CliError::Input(
            "standing consumption receipt does not bind the exact authority; do not replay the mutation"
                .to_owned(),
        ));
    }
    let approval_matches = authority
        .approval
        .as_ref()
        .is_some_and(|approval| approval.approved_content_hash == authority.content_hash);
    if !approval_matches {
        return Err(CliError::Input(
            "standing authority no longer carries the approval bound by the consumption receipt; do not replay the mutation"
                .to_owned(),
        ));
    }
    let matching_reservations = authority
        .run_log
        .iter()
        .filter(|run| run.operation_id == plan.operation_id)
        .collect::<Vec<_>>();
    if matching_reservations.len() != 1
        || matching_reservations[0].capability_id != plan.capability.id
    {
        return Err(CliError::Input(
            "standing boundary receipt was not durably reserved exactly once under the same authority capability; do not replay the mutation"
                .to_owned(),
        ));
    }
    if plan.account_id != authority.account_id
        || plan.capability.id != "account-api-tokens-create-token"
        || !authority
            .capability_ids
            .iter()
            .any(|capability_id| capability_id == &plan.capability.id)
    {
        return Err(CliError::Input(
            "standing token receipt account or capability does not match its authority; do not replay the mutation"
                .to_owned(),
        ));
    }
    let Some(response) = plan.transaction_artifact(TransactionStageV1::BoundaryResponsePersisted)
    else {
        return Ok(None);
    };
    let success = response
        .get("success")
        .and_then(Value::as_bool)
        .ok_or_else(|| {
            CliError::Input(
                "standing boundary receipt has no success result; do not replay the mutation"
                    .to_owned(),
            )
        })?;
    if !success {
        return Ok(None);
    }
    response
        .get("resource_id")
        .and_then(Value::as_str)
        .filter(|resource_id| !resource_id.trim().is_empty())
        .map(Some)
        .ok_or_else(|| {
            CliError::Input(
                "successful standing token receipt has no resource ID; do not replay the mutation and run `cfctl plans rectify`"
                    .to_owned(),
            )
        })
}

fn standing_consumption_authority_id(plan: &PlanV1) -> Result<Option<&str>> {
    let Some(binding) = plan.transaction_artifact(TransactionStageV1::ConsumptionPersisted) else {
        return Ok(None);
    };
    if binding.get("standing_authority_id").is_none()
        && binding.get("standing_authority_content_hash").is_none()
    {
        return Ok(None);
    }
    binding
        .get("standing_authority_id")
        .and_then(Value::as_str)
        .filter(|authority_id| !authority_id.is_empty())
        .map(Some)
        .ok_or_else(|| {
            CliError::Input(
                "standing consumption receipt has no authority ID; do not replay the mutation"
                    .to_owned(),
            )
        })
}

fn reconcile_standing_lineage_from_plan(
    store: &StateStore,
    plan: &PlanV1,
) -> Result<Option<EvidenceV1>> {
    let Some(authority_id) = standing_consumption_authority_id(plan)? else {
        return Ok(None);
    };
    if plan.capability.id != "account-api-tokens-create-token" {
        return Ok(None);
    }
    let guard = store.lock_authority(authority_id)?;
    let mut authority = store.load_authority(authority_id)?;
    let Some(token_id) = validated_standing_lineage_token_id(plan, &authority)? else {
        return Ok(None);
    };
    let already_recorded = authority
        .minted_token_ids
        .iter()
        .any(|recorded| recorded == token_id);
    authority.record_minted_token(token_id);
    if !already_recorded {
        store.save_authority_guarded(&authority, &guard)?;
    }
    let boundary_receipt_hash = plan
        .transaction_journal
        .iter()
        .find(|checkpoint| checkpoint.stage == TransactionStageV1::BoundaryResponsePersisted)
        .and_then(|checkpoint| checkpoint.artifact_hash.as_deref())
        .ok_or_else(|| {
            CliError::Input(
                "standing boundary response has no validated artifact hash; do not replay the mutation"
                    .to_owned(),
            )
        })?;
    let evidence = store.write_evidence(
        EvidenceClass::StandingApply,
        &json!({
            "standing_authority_id": authority.authority_id,
            "standing_authority_content_hash": authority.content_hash,
            "operation_id": plan.operation_id,
            "token_id": token_id,
            "source_boundary_receipt_hash": boundary_receipt_hash,
            "reconciled": true,
        }),
    )?;
    Ok(Some(evidence))
}

fn recover_standing_lineage(store: &StateStore, authority_id: &str) -> Result<Vec<EvidenceV1>> {
    let mut evidence = Vec::new();
    for snapshot in store.list_plans()? {
        if standing_consumption_authority_id(&snapshot)? != Some(authority_id) {
            continue;
        }
        let _plan_lock = store.lock_plan(&snapshot.operation_id)?;
        let plan = load_validated_plan(store, &snapshot.operation_id)?;
        if standing_consumption_authority_id(&plan)? != Some(authority_id) {
            continue;
        }
        if let Some(item) = reconcile_standing_lineage_from_plan(store, &plan)? {
            evidence.push(item);
        }
    }
    Ok(evidence)
}

