fn exact_durable_action_response_failure(
    store: &StateStore,
    plan: &PlanV1,
    action: &str,
) -> Result<(EvidenceV1, Value)> {
    let (target, migration_id, _) = import_plan_runtime_lineage(plan)?;
    let input_hash = hash_value(&plan.input)?;
    let failures = store
        .read_d1_import_checkpoints(&plan.operation_id)?
        .into_iter()
        .filter(|(_, checkpoint)| {
            let Some(step) = checkpoint.get("step").and_then(Value::as_str) else {
                return false;
            };
            let step_matches = match action {
                "ingest" => step == "ingest_response",
                "poll" => step.starts_with("poll_response_"),
                _ => false,
            };
            let Some(result) = checkpoint
                .pointer("/receipt/result")
                .and_then(Value::as_object)
            else {
                return false;
            };
            let allowed = [
                "type",
                "status",
                "success",
                "at_bookmark",
                "result",
                "provider_error_present",
            ];
            let projected = result.keys().all(|key| allowed.contains(&key.as_str()))
                && result.get("result").is_none_or(|nested| {
                    nested.as_object().is_some_and(|object| {
                        object.len() == 1 && object.contains_key("final_bookmark")
                    })
                });
            step_matches
                && checkpoint.get("schema_version").and_then(Value::as_u64) == Some(1)
                && checkpoint.get("operation_id").and_then(Value::as_str)
                    == Some(plan.operation_id.as_str())
                && checkpoint.get("performed").and_then(Value::as_bool) == Some(true)
                && checkpoint
                    .get("rectification_required")
                    .and_then(Value::as_bool)
                    == Some(true)
                && checkpoint
                    .pointer("/receipt/response_action")
                    .and_then(Value::as_str)
                    == Some(action)
                && checkpoint
                    .pointer("/receipt/provider")
                    .and_then(Value::as_str)
                    == Some("cloudflare")
                && checkpoint
                    .pointer("/receipt/effect")
                    .and_then(Value::as_str)
                    == Some("d1_import_response")
                && checkpoint
                    .pointer("/receipt/migration_id")
                    .and_then(Value::as_str)
                    == Some(migration_id.as_str())
                && checkpoint.pointer("/receipt/target") == Some(&target)
                && checkpoint
                    .pointer("/receipt/plan_input_hash")
                    .and_then(Value::as_str)
                    == Some(input_hash.as_str())
                && checkpoint
                    .pointer("/receipt/no_replay")
                    .and_then(Value::as_bool)
                    == Some(true)
                && checkpoint.pointer("/receipt/etag").is_none()
                && projected
        })
        .collect::<Vec<_>>();
    if failures.len() != 1 {
        return Err(CliError::Input(format!(
            "known {action} response requires exactly one operation-bound durable redacted checkpoint"
        )));
    }
    let (hash, checkpoint) = &failures[0];
    if store.read_evidence_value(hash)? != *checkpoint {
        return Err(CliError::Input(format!(
            "known {action}-response evidence does not match its immutable checkpoint"
        )));
    }
    Ok((
        EvidenceV1::new(
            EvidenceClass::Apply,
            hash,
            &store
                .paths()
                .data_dir
                .join("evidence")
                .join(format!("{}.json", hash.trim_start_matches("sha256:")))
                .display()
                .to_string(),
        ),
        checkpoint.clone(),
    ))
}

fn known_import_action_response_failure_envelope(
    store: &StateStore,
    plan: &mut PlanV1,
    error: CloudflareError,
    secrets: &dyn SecretStore,
) -> ResultEnvelopeV2 {
    plan.status = PlanStatus::RectificationRequired;
    let action = if matches!(error, CloudflareError::D1ImportIngestResponseFailure) {
        "ingest"
    } else {
        "poll"
    };
    match exact_durable_action_response_failure(store, plan, action) {
        Ok((evidence, checkpoint)) => {
            let provider_rejected = checkpoint
                .pointer("/receipt/success")
                .and_then(Value::as_bool)
                == Some(false)
                || checkpoint
                    .pointer("/receipt/result/status")
                    .and_then(Value::as_str)
                    == Some("error");
            let outcome = if provider_rejected {
                "provider_rejected"
            } else {
                "invalid_provider_response"
            };
            let artifact = json!({
                "adapter":"dynamic_api",
                "performed":true,
                "success":false,
                "outcome":outcome,
                "receipt_available":true,
                "response_action":action,
                "response_evidence_hash":evidence.content_hash,
            });
            let _ = persist_transaction_stage_with_artifact(
                store,
                plan,
                TransactionStageV1::BoundaryResponsePersisted,
                artifact,
            );
            let _ = persist_secret_lifecycle(store, plan, false, None, secrets);
            post_boundary_failure_envelope(
                plan,
                json!({
                    "success":false,
                    "outcome":outcome,
                    "receipt_available":true,
                    "response_action":action,
                }),
                Some(evidence),
                None,
                &CliError::Input(format!(
                    "Cloudflare returned a known rejected or invalid D1 import {action} response"
                )),
                true,
                &format!(
                    "the exact action-projected Cloudflare {action} response is durable; no later import action occurred and the import must not be replayed"
                ),
            )
        }
        Err(error) => {
            let _ = store.save_plan(plan);
            post_boundary_failure_envelope(
                plan,
                json!({
                    "success":false,
                    "outcome":"provider_response_receipt_invalid",
                    "receipt_available":false,
                    "response_action":action,
                }),
                None,
                None,
                &error,
                true,
                &format!(
                    "Cloudflare returned an {action} response, but its exact durable redacted checkpoint could not be uniquely resolved; do not replay"
                ),
            )
        }
    }
}

#[expect(
    clippy::too_many_arguments,
    clippy::too_many_lines,
    reason = "canonical poll authority binds every immutable lineage dimension explicitly"
)]
fn exact_in_progress_poll_receipt(
    store: &StateStore,
    plan: &PlanV1,
    hash: &str,
    checkpoint: &Value,
    expected_attempt: u64,
    target: &Value,
    input_hash: &str,
    migration_id: &str,
    bookmark: &str,
) -> bool {
    let expected_step = format!("poll_response_{expected_attempt}");
    let Some(receipt) = checkpoint.get("receipt").and_then(Value::as_object) else {
        return false;
    };
    let Some(result) = receipt.get("result").and_then(Value::as_object) else {
        return false;
    };
    let receipt_fields = [
        "http_status",
        "success",
        "response_action",
        "provider",
        "effect",
        "migration_id",
        "target",
        "plan_input_hash",
        "result",
        "errors",
        "provider_errors_present",
        "no_replay",
        "etag_present",
        "etag_sha256",
        "cf_ray",
    ];
    let result_fields = [
        "type",
        "status",
        "success",
        "at_bookmark",
        "result",
        "provider_error_present",
    ];
    let nested_result = result.get("result").and_then(Value::as_object);
    let etag_present = receipt.get("etag_present").and_then(Value::as_bool);
    let etag_hash = receipt.get("etag_sha256");
    let etag_exact = match (etag_present, etag_hash) {
        (Some(false), Some(value)) => value.is_null(),
        (Some(true), Some(value)) => value
            .as_str()
            .and_then(|hash| hash.strip_prefix("sha256:"))
            .is_some_and(|digest| {
                digest.len() == 64 && digest.bytes().all(|byte| byte.is_ascii_hexdigit())
            }),
        _ => false,
    };
    let cf_ray_exact = receipt.get("cf_ray").is_some_and(|value| {
        value.is_null()
            || value.as_str().is_some_and(|ray| {
                !ray.is_empty()
                    && ray.len() <= 128
                    && ray
                        .bytes()
                        .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
            })
    });
    checkpoint
        .as_object()
        .is_some_and(|object| object.len() == 6)
        && checkpoint.get("schema_version").and_then(Value::as_u64) == Some(1)
        && checkpoint.get("operation_id").and_then(Value::as_str)
            == Some(plan.operation_id.as_str())
        && checkpoint.get("step").and_then(Value::as_str) == Some(expected_step.as_str())
        && checkpoint.get("performed").and_then(Value::as_bool) == Some(true)
        && checkpoint
            .get("rectification_required")
            .and_then(Value::as_bool)
            == Some(false)
        && receipt.len() == receipt_fields.len()
        && receipt_fields
            .iter()
            .all(|field| receipt.contains_key(*field))
        && receipt.get("http_status").and_then(Value::as_u64) == Some(200)
        && receipt.get("success").and_then(Value::as_bool) == Some(true)
        && receipt.get("response_action").and_then(Value::as_str) == Some("poll")
        && receipt.get("provider").and_then(Value::as_str) == Some("cloudflare")
        && receipt.get("effect").and_then(Value::as_str) == Some("d1_import_response")
        && receipt.get("migration_id").and_then(Value::as_str) == Some(migration_id)
        && receipt.get("target") == Some(target)
        && receipt.get("plan_input_hash").and_then(Value::as_str) == Some(input_hash)
        && result.len() == result_fields.len()
        && result_fields
            .iter()
            .all(|field| result.contains_key(*field))
        && result.get("type").and_then(Value::as_str) == Some("import")
        && matches!(
            result.get("status").and_then(Value::as_str),
            Some("active" | "pending")
        )
        && result.get("success").and_then(Value::as_bool) == Some(true)
        && result.get("at_bookmark").and_then(Value::as_str) == Some(bookmark)
        && result
            .get("provider_error_present")
            .and_then(Value::as_bool)
            == Some(false)
        && nested_result.is_some_and(|nested| {
            nested.len() == 1
                && nested.contains_key("final_bookmark")
                && nested.get("final_bookmark").is_some_and(Value::is_null)
        })
        && receipt
            .get("errors")
            .and_then(Value::as_array)
            .is_some_and(Vec::is_empty)
        && receipt
            .get("provider_errors_present")
            .and_then(Value::as_bool)
            == Some(false)
        && receipt.get("no_replay").and_then(Value::as_bool) == Some(false)
        && etag_exact
        && cf_ray_exact
        && checkpoint.get("error").is_none()
        && store
            .read_evidence_value(hash)
            .is_ok_and(|evidence| evidence == *checkpoint)
}

#[expect(
    clippy::too_many_lines,
    reason = "poll exhaustion authority joins ingest lineage every bounded poll and terminal receipt"
)]
fn exact_durable_poll_exhaustion(
    store: &StateStore,
    plan: &PlanV1,
) -> Result<(EvidenceV1, Value, EvidenceV1)> {
    let (target, migration_id, _) = import_plan_runtime_lineage(plan)?;
    let max_poll_attempts = plan
        .capability
        .d1_approved_mln_import
        .as_ref()
        .map(|contract| contract.max_poll_attempts)
        .ok_or_else(|| CliError::Input("governed D1 import contract is missing".to_owned()))?;
    let input_hash = hash_value(&plan.input)?;
    let source_sha256 = plan
        .targets
        .pointer("/adapter/approved_mln_import/sha256")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("approved MLN import source identity is missing".to_owned())
        })?;
    let checkpoints = store.read_d1_import_checkpoints(&plan.operation_id)?;
    let accepted = exact_accepted_ingest_bookmarks(store, plan, &checkpoints, &target, &input_hash);
    if accepted.len() != 1 {
        return Err(CliError::Input(
            "poll exhaustion requires exactly one durable accepted-ingest bookmark".to_owned(),
        ));
    }
    let bookmark = &accepted[0];
    let accepted_entries = checkpoints
        .iter()
        .enumerate()
        .filter(|(_, (hash, checkpoint))| {
            checkpoint.get("step").and_then(Value::as_str) == Some("ingest_response")
                && checkpoint
                    .pointer("/receipt/effect")
                    .and_then(Value::as_str)
                    == Some("d1_import_ingest_accepted")
                && checkpoint
                    .pointer("/receipt/result/at_bookmark")
                    .and_then(Value::as_str)
                    == Some(bookmark.as_str())
                && store
                    .read_evidence_value(hash)
                    .is_ok_and(|evidence| evidence == *checkpoint)
        })
        .collect::<Vec<_>>();
    if accepted_entries.len() != 1 {
        return Err(CliError::Input(
            "poll exhaustion requires exactly one accepted-ingest checkpoint and evidence"
                .to_owned(),
        ));
    }
    let (accepted_index, (accepted_hash, _)) = accepted_entries[0];
    let mut attempts = checkpoints
        .iter()
        .enumerate()
        .filter_map(|(index, (hash, checkpoint))| {
            let step = checkpoint.get("step").and_then(Value::as_str)?;
            let attempt = step.strip_prefix("poll_response_")?.parse::<u64>().ok()?;
            let exact = exact_in_progress_poll_receipt(
                store,
                plan,
                hash,
                checkpoint,
                attempt,
                &target,
                &input_hash,
                migration_id.as_str(),
                bookmark,
            );
            exact.then_some((index, attempt))
        })
        .collect::<Vec<_>>();
    attempts.sort_unstable_by_key(|(_, attempt)| *attempt);
    let expected_attempts = (1..=max_poll_attempts)
        .enumerate()
        .map(|(offset, attempt)| (accepted_index + offset + 1, attempt))
        .collect::<Vec<_>>();
    if attempts != expected_attempts {
        return Err(CliError::Input(
            "poll exhaustion requires one chronological durable in-progress receipt per approved attempt"
                .to_owned(),
        ));
    }
    if checkpoints.iter().any(|(_, checkpoint)| {
        checkpoint.get("step").and_then(Value::as_str) == Some("provider_complete")
    }) {
        return Err(CliError::Input(
            "poll exhaustion conflicts with a provider_complete checkpoint".to_owned(),
        ));
    }
    let exhausted = checkpoints
        .iter()
        .enumerate()
        .filter(|(index, (_, checkpoint))| {
            let exact_receipt_shape = checkpoint
                .get("receipt")
                .and_then(Value::as_object)
                .is_some_and(|receipt| receipt.len() == 12);
            *index == accepted_index + usize::try_from(max_poll_attempts).unwrap_or(usize::MAX) + 1
                && *index + 1 == checkpoints.len()
                && checkpoint.get("step").and_then(Value::as_str)
                    == Some("poll_in_progress_exhausted")
                && checkpoint.get("performed").and_then(Value::as_bool) == Some(true)
                && checkpoint
                    .get("rectification_required")
                    .and_then(Value::as_bool)
                    == Some(true)
                && checkpoint
                    .pointer("/receipt/provider")
                    .and_then(Value::as_str)
                    == Some("cloudflare")
                && checkpoint
                    .pointer("/receipt/effect")
                    .and_then(Value::as_str)
                    == Some("d1_import_poll_in_progress_exhausted")
                && checkpoint
                    .pointer("/receipt/migration_id")
                    .and_then(Value::as_str)
                    == Some(migration_id.as_str())
                && checkpoint.pointer("/receipt/target") == Some(&target)
                && checkpoint
                    .pointer("/receipt/plan_input_hash")
                    .and_then(Value::as_str)
                    == Some(input_hash.as_str())
                && checkpoint
                    .pointer("/receipt/source_sha256")
                    .and_then(Value::as_str)
                    == Some(source_sha256)
                && checkpoint
                    .pointer("/receipt/at_bookmark")
                    .and_then(Value::as_str)
                    == Some(bookmark.as_str())
                && checkpoint
                    .pointer("/receipt/attempt_count")
                    .and_then(Value::as_u64)
                    == Some(max_poll_attempts)
                && checkpoint
                    .pointer("/receipt/attempt_bound")
                    .and_then(Value::as_u64)
                    == Some(max_poll_attempts)
                && checkpoint
                    .pointer("/receipt/outcome")
                    .and_then(Value::as_str)
                    == Some("poll_in_progress_exhausted")
                && checkpoint
                    .pointer("/receipt/receipt_available")
                    .and_then(Value::as_bool)
                    == Some(true)
                && checkpoint
                    .pointer("/receipt/no_replay")
                    .and_then(Value::as_bool)
                    == Some(true)
                && exact_receipt_shape
        })
        .collect::<Vec<_>>();
    if exhausted.len() != 1 {
        return Err(CliError::Input(
            "poll exhaustion requires exactly one lineage-bound durable receipt".to_owned(),
        ));
    }
    let (_, (hash, checkpoint)) = exhausted[0];
    if store.read_evidence_value(hash)? != *checkpoint {
        return Err(CliError::Input(
            "poll exhaustion evidence does not match its immutable checkpoint".to_owned(),
        ));
    }
    Ok((
        EvidenceV1::new(
            EvidenceClass::Apply,
            hash,
            &store
                .paths()
                .data_dir
                .join("evidence")
                .join(format!("{}.json", hash.trim_start_matches("sha256:")))
                .display()
                .to_string(),
        ),
        checkpoint.clone(),
        EvidenceV1::new(
            EvidenceClass::Apply,
            accepted_hash,
            &store
                .paths()
                .data_dir
                .join("evidence")
                .join(format!(
                    "{}.json",
                    accepted_hash.trim_start_matches("sha256:")
                ))
                .display()
                .to_string(),
        ),
    ))
}

#[derive(Debug, Clone)]
struct ResumePollExhaustionAuthority {
    exhaustion_evidence: EvidenceV1,
    exhaustion_checkpoint: Value,
    accepted_ingest_evidence: EvidenceV1,
    accepted_bookmark: String,
    root_operation_id: String,
    root_plan_hash: String,
    root_input: Value,
    root_stage: Value,
}

fn boundary_artifact_hash(plan: &PlanV1, stage: TransactionStageV1) -> Option<&str> {
    plan.transaction_journal
        .iter()
        .find(|checkpoint| checkpoint.stage == stage)
        .and_then(|checkpoint| checkpoint.artifact_hash.as_deref())
}

#[expect(
    clippy::too_many_lines,
    reason = "continuation exhaustion validates every receipt and inherited authority field"
)]
fn exact_resume_poll_exhaustion(
    store: &StateStore,
    plan: &PlanV1,
) -> Result<ResumePollExhaustionAuthority> {
    let authority = plan
        .targets
        .pointer("/adapter/approved_mln_import_poll_resume")
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("poll continuation authority is missing".to_owned()))?;
    let root_operation_id = authority
        .get("root_operation_id")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("poll continuation root operation is missing".to_owned()))?;
    let root_plan_hash = authority
        .get("root_plan_hash")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("poll continuation root plan hash is missing".to_owned()))?;
    let root_input = authority
        .get("root_input")
        .cloned()
        .ok_or_else(|| CliError::Input("poll continuation root input is missing".to_owned()))?;
    let root_stage = authority
        .get("root_stage")
        .cloned()
        .ok_or_else(|| CliError::Input("poll continuation root stage is missing".to_owned()))?;
    let accepted_hash = authority
        .get("accepted_ingest_evidence_hash")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("accepted-ingest evidence identity is missing".to_owned())
        })?;
    let accepted_bookmark = authority
        .get("accepted_bookmark")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| CliError::Input("accepted-ingest bookmark is missing".to_owned()))?;
    let contract = plan
        .capability
        .d1_approved_mln_import_poll_resume
        .as_ref()
        .ok_or_else(|| CliError::Input("poll continuation contract is missing".to_owned()))?;
    let target = if plan.capability.id == "d1-resume-database-import-poll" {
        authority
            .get("target")
            .cloned()
            .ok_or_else(|| CliError::Input("poll continuation target is missing".to_owned()))?
    } else {
        json!({"account_id":contract.account_id,"database_id":contract.database_id})
    };
    let input_hash = hash_value(&plan.input)?;
    let migration_id = root_input
        .pointer("/body/migration_id")
        .or_else(|| root_stage.get("migration_id"))
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("root migration identity is missing".to_owned()))?;
    let source_sha256 = root_stage
        .get("sha256")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("root source identity is missing".to_owned()))?;
    let checkpoints = store.read_d1_import_checkpoints(&plan.operation_id)?;
    let attempts = checkpoints
        .iter()
        .enumerate()
        .filter_map(|(index, (hash, checkpoint))| {
            let attempt = checkpoint
                .get("step")
                .and_then(Value::as_str)?
                .strip_prefix("poll_response_")?
                .parse::<u64>()
                .ok()?;
            exact_in_progress_poll_receipt(
                store,
                plan,
                hash,
                checkpoint,
                attempt,
                &target,
                &input_hash,
                migration_id,
                accepted_bookmark,
            )
            .then_some((index, attempt))
        })
        .collect::<Vec<_>>();
    let expected = (1..=contract.max_poll_attempts)
        .enumerate()
        .collect::<Vec<_>>();
    if attempts != expected {
        return Err(CliError::Input(
            "poll continuation exhaustion requires every bounded chronological in-progress receipt"
                .to_owned(),
        ));
    }
    let exhausted = checkpoints
        .iter()
        .enumerate()
        .filter(|(index, (_, checkpoint))| {
            *index == usize::try_from(contract.max_poll_attempts).unwrap_or(usize::MAX)
                && *index + 1 == checkpoints.len()
                && checkpoint.get("step").and_then(Value::as_str)
                    == Some("poll_in_progress_exhausted")
                && checkpoint.get("performed").and_then(Value::as_bool) == Some(true)
                && checkpoint
                    .get("rectification_required")
                    .and_then(Value::as_bool)
                    == Some(true)
                && checkpoint
                    .pointer("/receipt/provider")
                    .and_then(Value::as_str)
                    == Some("cloudflare")
                && checkpoint
                    .pointer("/receipt/effect")
                    .and_then(Value::as_str)
                    == Some("d1_import_poll_in_progress_exhausted")
                && checkpoint
                    .pointer("/receipt/migration_id")
                    .and_then(Value::as_str)
                    == Some(migration_id)
                && checkpoint.pointer("/receipt/target") == Some(&target)
                && checkpoint
                    .pointer("/receipt/plan_input_hash")
                    .and_then(Value::as_str)
                    == Some(input_hash.as_str())
                && checkpoint
                    .pointer("/receipt/source_sha256")
                    .and_then(Value::as_str)
                    == Some(source_sha256)
                && checkpoint
                    .pointer("/receipt/at_bookmark")
                    .and_then(Value::as_str)
                    == Some(accepted_bookmark)
                && checkpoint
                    .pointer("/receipt/attempt_count")
                    .and_then(Value::as_u64)
                    == Some(contract.max_poll_attempts)
                && checkpoint
                    .pointer("/receipt/attempt_bound")
                    .and_then(Value::as_u64)
                    == Some(contract.max_poll_attempts)
                && checkpoint
                    .pointer("/receipt/no_replay")
                    .and_then(Value::as_bool)
                    == Some(true)
                && checkpoint
                    .pointer("/receipt/outcome")
                    .and_then(Value::as_str)
                    == Some("poll_in_progress_exhausted")
                && checkpoint
                    .pointer("/receipt/receipt_available")
                    .and_then(Value::as_bool)
                    == Some(true)
        })
        .collect::<Vec<_>>();
    if exhausted.len() != 1 {
        return Err(CliError::Input(
            "poll continuation requires exactly one terminal exhaustion receipt".to_owned(),
        ));
    }
    let (_, (hash, checkpoint)) = exhausted[0];
    let accepted = store.read_evidence_value(accepted_hash)?;
    let root_input_hash = hash_value(&root_input)?;
    let accepted_exact = accepted.get("schema_version").and_then(Value::as_u64) == Some(1)
        && accepted.get("operation_id").and_then(Value::as_str) == Some(root_operation_id)
        && accepted.get("step").and_then(Value::as_str) == Some("ingest_response")
        && accepted.get("performed").and_then(Value::as_bool) == Some(true)
        && accepted
            .get("rectification_required")
            .and_then(Value::as_bool)
            == Some(false)
        && accepted
            .pointer("/receipt/http_status")
            .and_then(Value::as_u64)
            == Some(200)
        && accepted
            .pointer("/receipt/success")
            .and_then(Value::as_bool)
            == Some(true)
        && accepted
            .pointer("/receipt/response_action")
            .and_then(Value::as_str)
            == Some("ingest")
        && accepted
            .pointer("/receipt/provider")
            .and_then(Value::as_str)
            == Some("cloudflare")
        && accepted.pointer("/receipt/effect").and_then(Value::as_str)
            == Some("d1_import_ingest_accepted")
        && accepted
            .pointer("/receipt/migration_id")
            .and_then(Value::as_str)
            == Some(migration_id)
        && accepted.pointer("/receipt/target") == Some(&target)
        && accepted
            .pointer("/receipt/plan_input_hash")
            .and_then(Value::as_str)
            == Some(root_input_hash.as_str())
        && accepted
            .pointer("/receipt/no_replay")
            .and_then(Value::as_bool)
            == Some(false)
        && accepted
            .pointer("/receipt/result/type")
            .and_then(Value::as_str)
            == Some("import")
        && matches!(
            accepted
                .pointer("/receipt/result/status")
                .and_then(Value::as_str),
            Some("active" | "pending")
        )
        && accepted
            .pointer("/receipt/result/success")
            .and_then(Value::as_bool)
            == Some(true)
        && accepted
            .pointer("/receipt/result/at_bookmark")
            .and_then(Value::as_str)
            == Some(accepted_bookmark)
        && accepted
            .pointer("/receipt/errors")
            .and_then(Value::as_array)
            .is_some_and(Vec::is_empty);
    if store.read_evidence_value(hash)? != *checkpoint || !accepted_exact {
        return Err(CliError::Input(
            "poll continuation exhaustion or accepted-ingest evidence drifted".to_owned(),
        ));
    }
    Ok(ResumePollExhaustionAuthority {
        exhaustion_evidence: EvidenceV1::new(
            EvidenceClass::Apply,
            hash,
            &store
                .paths()
                .data_dir
                .join("evidence")
                .join(format!("{}.json", hash.trim_start_matches("sha256:")))
                .display()
                .to_string(),
        ),
        exhaustion_checkpoint: checkpoint.clone(),
        accepted_ingest_evidence: EvidenceV1::new(
            EvidenceClass::Apply,
            accepted_hash,
            &store
                .paths()
                .data_dir
                .join("evidence")
                .join(format!(
                    "{}.json",
                    accepted_hash.trim_start_matches("sha256:")
                ))
                .display()
                .to_string(),
        ),
        accepted_bookmark: accepted_bookmark.to_owned(),
        root_operation_id: root_operation_id.to_owned(),
        root_plan_hash: root_plan_hash.to_owned(),
        root_input,
        root_stage,
    })
}

#[expect(
    clippy::too_many_lines,
    reason = "resume completion validates one exact durable checkpoint and every root-to-child lineage field together"
)]
fn exact_durable_resume_provider_complete_boundary(
    store: &StateStore,
    plan: &PlanV1,
) -> Result<DurableProviderCompleteBoundary> {
    let authority = plan
        .targets
        .pointer("/adapter/approved_mln_import_poll_resume")
        .ok_or_else(|| CliError::Input("poll continuation authority is missing".to_owned()))?;
    let contract = plan
        .capability
        .d1_approved_mln_import_poll_resume
        .as_ref()
        .ok_or_else(|| CliError::Input("poll continuation contract is missing".to_owned()))?;
    let root_input = authority
        .get("root_input")
        .ok_or_else(|| CliError::Input("root input is missing".to_owned()))?;
    let root_stage = authority
        .get("root_stage")
        .ok_or_else(|| CliError::Input("root stage is missing".to_owned()))?;
    let migration_id = root_input
        .pointer("/body/migration_id")
        .or_else(|| root_stage.get("migration_id"))
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("root migration identity is missing".to_owned()))?;
    let accepted_bookmark = authority
        .get("accepted_bookmark")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("accepted bookmark is missing".to_owned()))?;
    let target = if plan.capability.id == "d1-resume-database-import-poll" {
        authority
            .get("target")
            .cloned()
            .ok_or_else(|| CliError::Input("poll continuation target is missing".to_owned()))?
    } else {
        json!({"account_id":contract.account_id,"database_id":contract.database_id})
    };
    let input_hash = hash_value(&plan.input)?;
    let checkpoints = store.read_d1_import_checkpoints(&plan.operation_id)?;
    let completed = checkpoints
        .iter()
        .filter(|(_, checkpoint)| {
            checkpoint.get("step").and_then(Value::as_str) == Some("provider_complete")
        })
        .collect::<Vec<_>>();
    if completed.len() != 1 {
        return Err(CliError::Input(
            "poll continuation requires exactly one provider completion".to_owned(),
        ));
    }
    let (hash, checkpoint) = completed[0];
    let exact = checkpoint.get("schema_version").and_then(Value::as_u64) == Some(1)
        && checkpoint.get("operation_id").and_then(Value::as_str)
            == Some(plan.operation_id.as_str())
        && checkpoint.get("performed").and_then(Value::as_bool) == Some(true)
        && checkpoint
            .get("rectification_required")
            .and_then(Value::as_bool)
            == Some(false)
        && checkpoint
            .pointer("/receipt/provider")
            .and_then(Value::as_str)
            == Some("cloudflare")
        && checkpoint
            .pointer("/receipt/effect")
            .and_then(Value::as_str)
            == Some("d1_import_provider_complete")
        && checkpoint
            .pointer("/receipt/response_action")
            .and_then(Value::as_str)
            == Some("poll")
        && checkpoint
            .pointer("/receipt/migration_id")
            .and_then(Value::as_str)
            == Some(migration_id)
        && checkpoint.pointer("/receipt/target") == Some(&target)
        && checkpoint
            .pointer("/receipt/plan_input_hash")
            .and_then(Value::as_str)
            == Some(input_hash.as_str())
        && checkpoint.pointer("/receipt/source_sha256") == root_stage.get("sha256")
        && checkpoint.pointer("/receipt/source_md5") == root_stage.get("md5")
        && checkpoint.pointer("/receipt/source_bytes") == root_stage.get("bytes")
        && checkpoint.pointer("/receipt/source_authority_hash")
            == root_stage.get("source_authority_hash")
        && checkpoint
            .pointer("/receipt/stage_identity_hash")
            .and_then(Value::as_str)
            == hash_value(root_stage).ok().as_deref()
        && checkpoint
            .pointer("/receipt/at_bookmark")
            .and_then(Value::as_str)
            == Some(accepted_bookmark)
        && checkpoint
            .pointer("/receipt/final_bookmark")
            .and_then(Value::as_str)
            .is_some_and(|value| !value.is_empty())
        && checkpoint.pointer("/receipt/root_operation_id") == authority.get("root_operation_id")
        && checkpoint.pointer("/receipt/root_plan_hash") == authority.get("root_plan_hash")
        && checkpoint.pointer("/receipt/parent_operation_id")
            == authority.get("parent_operation_id")
        && checkpoint.pointer("/receipt/parent_exhaustion_evidence_hash")
            == authority.get("parent_exhaustion_evidence_hash");
    if !exact || store.read_evidence_value(hash)? != *checkpoint {
        return Err(CliError::Input(
            "poll continuation provider completion is not exact and durable".to_owned(),
        ));
    }
    Ok(DurableProviderCompleteBoundary {
        evidence_hash: hash.clone(),
        checkpoint: checkpoint.clone(),
    })
}

#[expect(
    clippy::too_many_arguments,
    clippy::too_many_lines,
    reason = "the child-plan admission joins immutable parent, root, evidence, and sibling authority"
)]
fn validate_and_derive_resume_poll_authority(
    store: &StateStore,
    capability: &CapabilityV1,
    input: &CallInput,
    profile_id: &str,
    credential_generation_id: Option<&str>,
    catalog_hash: &str,
    before: DateTime<Utc>,
    child_operation_id: Option<&str>,
) -> Result<Value> {
    let contract = capability
        .d1_approved_mln_import_poll_resume
        .as_ref()
        .ok_or_else(|| CliError::Input("poll continuation contract is missing".to_owned()))?;
    let body = input
        .body
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| CliError::Input("poll continuation body is missing".to_owned()))?;
    let expected = [
        "parent_operation_id",
        "parent_plan_hash",
        "exhaustion_evidence_hash",
        "accepted_ingest_evidence_hash",
        "accepted_bookmark_hash",
    ]
    .into_iter()
    .collect::<BTreeSet<_>>();
    if body.keys().map(String::as_str).collect::<BTreeSet<_>>() != expected {
        return Err(CliError::Input(
            "poll continuation accepts only the five immutable parent receipt identities"
                .to_owned(),
        ));
    }
    let field = |name| required_body_string(body, name);
    let parent_operation_id = field("parent_operation_id")?;
    Uuid::parse_str(parent_operation_id).map_err(|_| {
        CliError::Input("parent_operation_id must be one canonical UUID".to_owned())
    })?;
    let StoredPlanRecord::Current(parent_v2) =
        store.load_stored_plan_record(parent_operation_id)?
    else {
        return Err(CliError::Input(
            "poll continuation parent must be an immutable PlanV2".to_owned(),
        ));
    };
    let parent = &parent_v2.plan;
    let parent_target = if contract.root_capability_id == "d1-import-database" {
        if parent.capability.id == contract.root_capability_id {
            parent
                .targets
                .pointer("/adapter/approved_mln_import/target")
        } else {
            parent
                .targets
                .pointer("/adapter/approved_mln_import_poll_resume/target")
        }
        .cloned()
        .ok_or_else(|| CliError::Input("poll parent target is missing".to_owned()))?
    } else {
        json!({
            "account_id":contract.account_id,
            "database_id":contract.database_id,
        })
    };
    let parent_account_id = parent_target
        .get("account_id")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("poll parent account target is missing".to_owned()))?;
    if parent.content_hash != field("parent_plan_hash")?
        || parent_v2.pins.catalog_hash != parent.catalog_hash
        || parent_v2.pins.credential_generation_id.is_empty()
        || parent.created_at >= before
        || parent.profile_id != profile_id
        || parent.catalog_hash != catalog_hash
        || parent_v2.pins.credential_generation_id != credential_generation_id.unwrap_or_default()
        || parent.account_id != parent_account_id
        || input.selectors != parent_target
    {
        return Err(CliError::Input(
            "poll continuation parent PlanV2, chronology, profile, credential, account, or catalog drifted"
                .to_owned(),
        ));
    }
    let exhaustion = if parent.capability.id == contract.root_capability_id {
        validate_trusted_root_import_plan(store, &parent_v2)?;
        let (exhaustion_evidence, exhaustion_checkpoint, accepted_ingest_evidence) =
            exact_durable_poll_exhaustion(store, parent)?;
        let accepted_bookmark = exhaustion_checkpoint
            .pointer("/receipt/at_bookmark")
            .and_then(Value::as_str)
            .ok_or_else(|| CliError::Input("root exhaustion bookmark is missing".to_owned()))?
            .to_owned();
        ResumePollExhaustionAuthority {
            exhaustion_evidence,
            exhaustion_checkpoint,
            accepted_ingest_evidence,
            accepted_bookmark,
            root_operation_id: parent.operation_id.clone(),
            root_plan_hash: parent.content_hash.clone(),
            root_input: parent.input.clone(),
            root_stage: parent
                .targets
                .pointer("/adapter/approved_mln_import")
                .cloned()
                .ok_or_else(|| CliError::Input("root managed stage is missing".to_owned()))?,
        }
    } else if parent.capability.id == capability.id {
        exact_resume_poll_exhaustion(store, parent)?
    } else {
        return Err(CliError::Input(
            "poll continuation parent is neither the root import nor a poll child".to_owned(),
        ));
    };
    let accepted_bookmark_hash = hash_value(&Value::String(exhaustion.accepted_bookmark.clone()))?;
    if exhaustion.exhaustion_evidence.content_hash != field("exhaustion_evidence_hash")?
        || exhaustion.accepted_ingest_evidence.content_hash
            != field("accepted_ingest_evidence_hash")?
        || accepted_bookmark_hash != field("accepted_bookmark_hash")?
    {
        return Err(CliError::Input(
            "poll continuation caller receipt identities do not match canonical parent authority"
                .to_owned(),
        ));
    }
    let boundary = parent
        .transaction_artifact(TransactionStageV1::BoundaryResponsePersisted)
        .ok_or_else(|| {
            CliError::Input("parent exhaustion boundary artifact is missing".to_owned())
        })?;
    if boundary.get("outcome").and_then(Value::as_str) != Some("poll_in_progress_exhausted")
        || boundary
            .get("poll_exhaustion_evidence_hash")
            .and_then(Value::as_str)
            != Some(exhaustion.exhaustion_evidence.content_hash.as_str())
        || boundary
            .get("accepted_ingest_evidence_hash")
            .and_then(Value::as_str)
            != Some(exhaustion.accepted_ingest_evidence.content_hash.as_str())
        || boundary_artifact_hash(parent, TransactionStageV1::BoundaryResponsePersisted)
            != hash_value(boundary).ok().as_deref()
    {
        return Err(CliError::Input(
            "parent BoundaryResponse artifact does not authenticate its exhaustion".to_owned(),
        ));
    }
    for sibling in store.list_plans()? {
        if child_operation_id == Some(sibling.operation_id.as_str()) {
            continue;
        }
        let sibling_authority = sibling
            .targets
            .pointer("/adapter/approved_mln_import_poll_resume");
        let same_exhaustion = sibling_authority
            .and_then(|value| value.get("parent_operation_id"))
            .and_then(Value::as_str)
            == Some(parent_operation_id)
            && sibling_authority
                .and_then(|value| value.get("parent_exhaustion_evidence_hash"))
                .and_then(Value::as_str)
                == Some(exhaustion.exhaustion_evidence.content_hash.as_str());
        if same_exhaustion {
            let crossed_consumption = sibling.transaction_journal.iter().any(|checkpoint| {
                matches!(
                    checkpoint.stage,
                    TransactionStageV1::ConsumptionPersisted
                        | TransactionStageV1::BoundaryAttemptPersisted
                        | TransactionStageV1::BoundaryResponsePersisted
                        | TransactionStageV1::VerificationAttemptPersisted
                        | TransactionStageV1::VerificationResponsePersisted
                        | TransactionStageV1::CompensationAttemptPersisted
                        | TransactionStageV1::CompensationResponsePersisted
                        | TransactionStageV1::Closed
                )
            });
            let provider_checkpoint_exists = !store
                .read_d1_import_checkpoints(&sibling.operation_id)?
                .is_empty();
            let replaceable = sibling.status == PlanStatus::Cancelled
                && !crossed_consumption
                && !provider_checkpoint_exists;
            if !replaceable {
                return Err(CliError::Input(
                    "this exact exhaustion already has a poll child or crossed child boundary"
                        .to_owned(),
                ));
            }
        }
    }
    let capability_contract_hash = hash_value(&serde_json::to_value(capability)?)?;
    Ok(json!({
        "schema_version":1,
        "parent_operation_id":parent.operation_id,
        "parent_plan_hash":parent.content_hash,
        "parent_boundary_artifact_hash":boundary_artifact_hash(parent,TransactionStageV1::BoundaryResponsePersisted),
        "parent_exhaustion_evidence_hash":exhaustion.exhaustion_evidence.content_hash,
        "accepted_ingest_evidence_hash":exhaustion.accepted_ingest_evidence.content_hash,
        "accepted_bookmark":exhaustion.accepted_bookmark,
        "accepted_bookmark_hash":accepted_bookmark_hash,
        "root_operation_id":exhaustion.root_operation_id,
        "root_plan_hash":exhaustion.root_plan_hash,
        "root_input":exhaustion.root_input,
        "root_stage":exhaustion.root_stage,
        "target":parent_target,
        "profile_id":profile_id,
        "credential_generation_id":credential_generation_id,
        "catalog_hash":catalog_hash,
        "capability_contract_hash":capability_contract_hash,
    }))
}

fn known_import_poll_exhausted_envelope(
    store: &StateStore,
    plan: &mut PlanV1,
    secrets: &dyn SecretStore,
) -> ResultEnvelopeV2 {
    plan.status = PlanStatus::RectificationRequired;
    let authority = if plan.capability.d1_approved_mln_import.is_some() {
        exact_durable_poll_exhaustion(store, plan)
    } else {
        exact_resume_poll_exhaustion(store, plan).map(|authority| {
            (
                authority.exhaustion_evidence,
                authority.exhaustion_checkpoint,
                authority.accepted_ingest_evidence,
            )
        })
    };
    match authority {
        Ok((evidence, checkpoint, accepted_ingest_evidence)) => {
            let artifact = json!({
                "adapter":"dynamic_api",
                "performed":true,
                "success":false,
                "outcome":"poll_in_progress_exhausted",
                "receipt_available":true,
                "poll_exhaustion_evidence_hash":evidence.content_hash,
                "accepted_ingest_evidence_hash":accepted_ingest_evidence.content_hash,
            });
            let mut local_failures = Vec::new();
            if let Err(error) = persist_transaction_stage_with_artifact(
                store,
                plan,
                TransactionStageV1::BoundaryResponsePersisted,
                artifact,
            ) {
                local_failures.push(format!("poll-exhaustion receipt binding failed: {error}"));
            }
            if let Err(error) = persist_secret_lifecycle(store, plan, false, None, secrets) {
                local_failures.push(format!(
                    "poll-exhaustion secret lifecycle persistence failed: {error}"
                ));
            }
            let detail = if local_failures.is_empty() {
                "Cloudflare D1 import remains in progress after the approved poll bound".to_owned()
            } else {
                format!(
                    "Cloudflare D1 import remains in progress after the approved poll bound; {}",
                    local_failures.join("; ")
                )
            };
            post_boundary_failure_envelope(
                plan,
                json!({
                    "success":false,
                    "outcome":"poll_in_progress_exhausted",
                    "receipt_available":true,
                    "at_bookmark_hash":checkpoint.pointer("/receipt/at_bookmark").and_then(Value::as_str).and_then(|value| hash_value(&Value::String(value.to_owned())).ok()),
                    "attempt_count":checkpoint.pointer("/receipt/attempt_count"),
                    "attempt_bound":checkpoint.pointer("/receipt/attempt_bound"),
                    "accepted_ingest_evidence_hash":accepted_ingest_evidence.content_hash,
                }),
                Some(evidence),
                None,
                &CliError::Input(detail),
                true,
                "the exact accepted-ingest bookmark and every bounded in-progress poll receipt are durable; do not replay init/upload/ingest",
            )
        }
        Err(error) => post_boundary_failure_envelope(
            plan,
            json!({
                "success":false,
                "outcome":"poll_exhaustion_receipt_invalid",
                "receipt_available":false,
            }),
            None,
            None,
            &error,
            true,
            "poll exhaustion lineage could not be resolved exactly; do not replay any import stage",
        ),
    }
}

fn approved_mln_import_execution_error_envelope(
    store: &StateStore,
    plan: &mut PlanV1,
    error: CloudflareError,
    secrets: &dyn SecretStore,
) -> ResultEnvelopeV2 {
    if matches!(error, CloudflareError::D1ImportProviderFailure) {
        return known_import_provider_failure_envelope(store, plan, secrets);
    }
    if matches!(
        error,
        CloudflareError::D1ImportUploadResponseIntegrityFailure
    ) {
        return known_import_upload_response_failure_envelope(store, plan, secrets);
    }
    if matches!(error, CloudflareError::D1ImportInitResponseFailure) {
        return known_import_init_response_failure_envelope(store, plan, secrets);
    }
    if matches!(
        error,
        CloudflareError::D1ImportIngestResponseFailure
            | CloudflareError::D1ImportPollResponseFailure
    ) {
        return known_import_action_response_failure_envelope(store, plan, error, secrets);
    }
    if matches!(error, CloudflareError::D1ImportPollInProgressExhausted) {
        return known_import_poll_exhausted_envelope(store, plan, secrets);
    }
    if !matches!(
        plan.status,
        PlanStatus::RectificationRequired | PlanStatus::Failed
    ) {
        plan.status = PlanStatus::RectificationRequired;
    }
    let _ = store.save_plan(plan);
    let mut envelope = process_api_transport_failure(store, plan, &CliError::from(error), secrets);
    envelope.performed = true;
    envelope
}

fn persist_d1_import_checkpoint(
    store: &StateStore,
    operation_id: &str,
    checkpoint: &D1ImportCheckpointV1,
) -> std::result::Result<(), String> {
    let value = serde_json::to_value(checkpoint).map_err(|error| error.to_string())?;
    let checkpoint_hash = store
        .record_d1_import_checkpoint(operation_id, &value)
        .map_err(|error| error.to_string())?;
    let terminal_provider_failure = (checkpoint.step == "init_response"
        || checkpoint.step == "ingest_response"
        || checkpoint.step.starts_with("poll_response_"))
        && checkpoint
            .receipt
            .pointer("/result/status")
            .and_then(Value::as_str)
            == Some("error")
        && checkpoint
            .receipt
            .pointer("/result/success")
            .and_then(Value::as_bool)
            == Some(false);
    let durable_apply = checkpoint.step == "provider_complete"
        || checkpoint.step.starts_with("poll_response_")
        || terminal_provider_failure
        || (checkpoint.receipt.get("effect").and_then(Value::as_str) == Some("d1_import_response")
            && checkpoint.rectification_required)
        || checkpoint.receipt.get("effect").and_then(Value::as_str)
            == Some("d1_import_ingest_accepted")
        || checkpoint.receipt.get("effect").and_then(Value::as_str)
            == Some("d1_import_transport_uncertain")
        || checkpoint.receipt.get("effect").and_then(Value::as_str)
            == Some("d1_import_upload_response")
        || checkpoint.receipt.get("effect").and_then(Value::as_str)
            == Some("d1_import_poll_in_progress_exhausted");
    if durable_apply {
        let evidence = store
            .write_evidence(EvidenceClass::Apply, &value)
            .map_err(|error| error.to_string())?;
        if evidence.content_hash != checkpoint_hash {
            return Err(
                "D1 import checkpoint and immutable apply evidence hashes diverged".to_owned(),
            );
        }
    }
    Ok(())
}

#[expect(
    clippy::too_many_lines,
    reason = "special import execution durably binds checkpoints evidence and pending verification"
)]
async fn execute_approved_mln_import_plan(
    store: &StateStore,
    executor: &Executor,
    plan: &mut PlanV1,
    execution_input: &CallInput,
    credential: &AuthCredential,
    secrets: &dyn SecretStore,
) -> Result<ResultEnvelopeV2> {
    let stage_path = plan
        .targets
        .pointer("/adapter/approved_mln_import/stage_path")
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .ok_or_else(|| {
            CliError::Input(
                "approved MLN import plan omitted its managed stage identity; do not run"
                    .to_owned(),
            )
        })?;
    validate_managed_mln_stage_authority(plan)?;
    let checkpoint_operation_id = plan.operation_id.clone();
    let response = match executor
        .execute_d1_approved_mln_import(
            plan,
            execution_input,
            credential,
            &stage_path,
            |checkpoint: &D1ImportCheckpointV1| {
                persist_d1_import_checkpoint(store, &checkpoint_operation_id, checkpoint)
            },
        )
        .await
    {
        Ok(response) => response,
        Err(error) => {
            return Ok(approved_mln_import_execution_error_envelope(
                store, plan, error, secrets,
            ));
        }
    };
    let (response_value, apply_evidence, lineage_evidence) =
        match process_api_boundary_response(store, plan, &response, secrets)? {
            ApiBoundaryResponseOutcome::Ready {
                response_value,
                apply_evidence,
                lineage_evidence,
            } => (response_value, apply_evidence, lineage_evidence),
            ApiBoundaryResponseOutcome::Recovery(envelope) => return Ok(envelope),
        };
    if !response.success {
        if !matches!(
            plan.status,
            PlanStatus::RectificationRequired | PlanStatus::Failed
        ) {
            plan.status = PlanStatus::RectificationRequired;
        }
        store.save_plan(plan)?;
        return Ok(post_boundary_failure_envelope(
            plan,
            response_value,
            Some(apply_evidence),
            lineage_evidence,
            &CliError::Input(
                "Cloudflare did not complete the approved import; preserve all checkpoints and do not replay"
                    .to_owned(),
            ),
            true,
            "the import boundary was crossed but provider completion was not proven",
        ));
    }
    if let Err(error) = exact_durable_provider_complete_boundary(store, plan.operation_id.as_str())
    {
        plan.status = PlanStatus::RectificationRequired;
        store.save_plan(plan)?;
        return Ok(post_boundary_failure_envelope(
            plan,
            response_value,
            Some(apply_evidence),
            lineage_evidence,
            &error,
            true,
            "the import boundary was crossed but exact durable provider completion was not proven",
        ));
    }
    if matches!(
        plan.capability.id.as_str(),
        "d1-import-approved-osint-research-migration" | "d1-import-database"
    ) {
        let subject = if plan.capability.id == "d1-import-database" {
            "reviewed-Git D1"
        } else {
            "OSINT Research"
        };
        let verification = match verify_api_plan(
            store,
            executor,
            plan,
            &response,
            execution_input,
            credential,
        )
        .await
        {
            Ok(verification) => verification,
            Err(error) => {
                return Ok(post_boundary_failure_envelope(
                    plan,
                    response_value,
                    Some(apply_evidence),
                    lineage_evidence,
                    &error,
                    true,
                    &format!(
                        "the {subject} import completed, but its schema-marker verification could not be persisted"
                    ),
                ));
            }
        };
        let finalization: Result<()> =
            if matches!(plan.status, PlanStatus::Verified | PlanStatus::Failed) {
                persist_transaction_stage(store, plan, TransactionStageV1::Closed)
            } else {
                store.save_plan(plan).map_err(CliError::from)
            };
        let finalization_error = finalization.err();
        return Ok(api_plan_result_envelope(
            plan,
            response_value,
            apply_evidence,
            lineage_evidence,
            verification,
            true,
            finalization_error.as_ref(),
        ));
    }
    if matches!(
        plan.status,
        PlanStatus::RectificationRequired | PlanStatus::Failed
    ) {
        store.save_plan(plan)?;
        return Ok(post_boundary_failure_envelope(
            plan,
            response_value,
            Some(apply_evidence),
            lineage_evidence,
            &CliError::Input(
                "approved MLN import ended in a terminal failure state; do not replay".to_owned(),
            ),
            true,
            "terminal import evidence cannot be overwritten by a pending-proof state",
        ));
    }
    plan.status = PlanStatus::Running;
    store.save_plan(plan)?;
    let mut envelope =
        ResultEnvelopeV2::success("plans run", response_value).with_evidence(apply_evidence);
    envelope.ok = false;
    envelope.performed = true;
    envelope.operation_id = Some(plan.operation_id.clone());
    envelope.capability_id = Some(plan.capability.id.clone());
    envelope.profile_id = Some(plan.profile_id.clone());
    envelope.account_id = Some(plan.account_id.clone());
    envelope.policy_decision = Some(plan.policy.clone());
    envelope.verification.state = VerificationState::Pending;
    envelope.verification.basis = Some(
        "provider_complete is durable; the operation remains unverified until the exact governed post_import MLN invariant proof is attached"
            .to_owned(),
    );
    envelope.error = Some(ErrorV1 {
        code: "CFCTL_D1_IMPORT_POST_IMPORT_PROOF_REQUIRED".to_owned(),
        message: "D1 import crossed the provider boundary but is not publication proof".to_owned(),
        next_step: Some(format!(
            "Run the exact mln-0143-data-invariants post_import read bound to operation {}, then run `cfctl plans rectify {}`.",
            plan.operation_id, plan.operation_id
        )),
    });
    if let Some(evidence) = lineage_evidence {
        envelope.evidence.push(evidence);
    }
    Ok(envelope)
}

fn validate_managed_mln_stage_authority(plan: &PlanV1) -> Result<()> {
    if plan.capability.id == "d1-import-database" {
        return validate_managed_reviewed_git_stage_authority(plan);
    }
    let contract = plan
        .capability
        .d1_approved_mln_import
        .as_ref()
        .ok_or_else(|| CliError::Input("approved MLN import contract is missing".to_owned()))?;
    let migration_id = plan
        .input
        .get("body")
        .and_then(|body| body.get("migration_id"))
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("managed import migration identity is missing".to_owned())
        })?;
    let migration = contract
        .migrations
        .iter()
        .find(|migration| migration.migration_id == migration_id)
        .ok_or_else(|| CliError::Input("managed import migration is not catalogued".to_owned()))?;
    let staged = plan
        .targets
        .pointer("/adapter/approved_mln_import")
        .ok_or_else(|| CliError::Input("managed import stage binding is missing".to_owned()))?;
    let authority = staged
        .get("source_authority")
        .ok_or_else(|| CliError::Input("managed source authority is missing".to_owned()))?;
    let authority_hash = hash_value(authority)?;
    let expected_sha256 = format!("sha256:{}", migration.sha256);
    if authority.get("schema_version").and_then(Value::as_u64) != Some(1)
        || authority.get("repository_id").and_then(Value::as_str)
            != Some(contract.repository_id.as_str())
        || authority.get("head").and_then(Value::as_str) != Some(contract.repository_head.as_str())
        || authority
            .get("repository_relative_path")
            .and_then(Value::as_str)
            != Some(migration.repository_relative_path.as_str())
        || authority.get("git_blob_oid").and_then(Value::as_str)
            != Some(migration.git_blob_oid.as_str())
        || authority
            .get("observed_worktree_root")
            .and_then(Value::as_str)
            .is_none_or(str::is_empty)
        || authority
            .get("observed_git_common_dir")
            .and_then(Value::as_str)
            .is_none_or(str::is_empty)
        || staged.get("source_authority_hash").and_then(Value::as_str)
            != Some(authority_hash.as_str())
        || staged.get("sha256").and_then(Value::as_str) != Some(expected_sha256.as_str())
        || staged.get("md5").and_then(Value::as_str) != Some(migration.md5.as_str())
        || staged.get("bytes").and_then(Value::as_u64) != Some(migration.bytes)
    {
        return Err(CliError::Input(
            "managed import stage lost its exact source-authority or byte identity".to_owned(),
        ));
    }
    let stage_path = staged
        .get("stage_path")
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .ok_or_else(|| CliError::Input("managed import stage path is missing".to_owned()))?;
    let mut options = OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    options.custom_flags(libc::O_NOFOLLOW);
    let mut file = options.open(&stage_path).map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    let metadata = file.metadata().map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes)
        .map_err(|source| CliError::Io {
            path: stage_path.display().to_string(),
            source,
        })?;
    if !metadata.is_file()
        || metadata.len() != migration.bytes
        || bytes.len() as u64 != migration.bytes
        || hex::encode(Sha256::digest(&bytes)) != migration.sha256
        || hex::encode(Md5::digest(&bytes)) != migration.md5
    {
        return Err(CliError::Input(
            "managed import stage no longer matches the consumed reviewed source".to_owned(),
        ));
    }
    Ok(())
}

#[expect(
    clippy::too_many_lines,
    reason = "execution-time authority revalidates Git, target, content, and private-stage identities as one fail-closed boundary"
)]
fn validate_managed_reviewed_git_stage_authority(plan: &PlanV1) -> Result<()> {
    let contract = plan
        .capability
        .d1_approved_mln_import
        .as_ref()
        .filter(|contract| contract.repository_id.is_empty() && contract.migrations.is_empty())
        .ok_or_else(|| {
            CliError::Input("provider-generic reviewed-Git import contract is missing".to_owned())
        })?;
    let staged = plan
        .targets
        .pointer("/adapter/approved_mln_import")
        .ok_or_else(|| CliError::Input("managed import stage binding is missing".to_owned()))?;
    let authority = staged
        .get("source_authority")
        .ok_or_else(|| CliError::Input("managed source authority is missing".to_owned()))?;
    let authority_hash = hash_value(authority)?;
    let root = authority
        .get("observed_worktree_root")
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .ok_or_else(|| CliError::Input("managed source worktree root is missing".to_owned()))?;
    let common = authority
        .get("observed_git_common_dir")
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .ok_or_else(|| {
            CliError::Input("managed source Git common directory is missing".to_owned())
        })?;
    let repository_id = authority
        .get("repository_id")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("managed source repository identity is missing".to_owned())
        })?;
    let head = authority
        .get("head")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("managed source HEAD is missing".to_owned()))?;
    let relative = authority
        .get("repository_relative_path")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("managed source relative path is missing".to_owned()))?;
    let blob = authority
        .get("git_blob_oid")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("managed source Git blob is missing".to_owned()))?;
    let canonical_root = fs::canonicalize(&root).map_err(|source| CliError::Io {
        path: root.display().to_string(),
        source,
    })?;
    let canonical_common = fs::canonicalize(&common).map_err(|source| CliError::Io {
        path: common.display().to_string(),
        source,
    })?;
    let remote = git_authority_output(&canonical_root, &["remote", "get-url", "origin"])?;
    let blob_spec = format!("{head}:{relative}");
    let observed_blob = git_authority_output(&canonical_root, &["rev-parse", &blob_spec])?;
    let status = git_authority_output(
        &canonical_root,
        &["status", "--porcelain=v1", "--untracked-files=all"],
    )?;
    let observed_common =
        git_authority_output(&canonical_root, &["rev-parse", "--git-common-dir"])?;
    let observed_common = if Path::new(&observed_common).is_absolute() {
        PathBuf::from(observed_common)
    } else {
        canonical_root.join(observed_common)
    };
    let source_path = canonical_root.join(relative);
    let source_bytes = git_authority_bytes(&canonical_root, &["cat-file", "blob", blob])?;
    let worktree_bytes = fs::read(&source_path).map_err(|source| CliError::Io {
        path: source_path.display().to_string(),
        source,
    })?;
    if canonical_root != root
        || fs::canonicalize(observed_common).ok().as_ref() != Some(&canonical_common)
        || normalize_reviewed_git_repository_id(&remote)?.as_str() != repository_id
        || git_authority_output(&canonical_root, &["rev-parse", "HEAD"])? != head
        || observed_blob != blob
        || !status.is_empty()
        || source_bytes != worktree_bytes
    {
        return Err(CliError::Input(
            "reviewed Git source authority changed after planning; do not execute the import"
                .to_owned(),
        ));
    }
    let bytes = staged
        .get("bytes")
        .and_then(Value::as_u64)
        .filter(|bytes| *bytes > 0 && *bytes <= contract.max_source_bytes)
        .ok_or_else(|| CliError::Input("managed source size is outside its bound".to_owned()))?;
    let sha256 = staged
        .get("sha256")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("managed source SHA-256 is missing".to_owned()))?;
    let md5 = staged
        .get("md5")
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("managed source MD5 is missing".to_owned()))?;
    let target = json!({
        "account_id":plan.input.pointer("/selectors/account_id"),
        "database_id":plan.input.pointer("/selectors/database_id"),
    });
    if authority.get("schema_version").and_then(Value::as_u64) != Some(1)
        || staged.get("source_authority_hash").and_then(Value::as_str)
            != Some(authority_hash.as_str())
        || staged.get("migration_id").and_then(Value::as_str) != Some(authority_hash.as_str())
        || staged.get("target") != Some(&target)
        || source_bytes.len() as u64 != bytes
        || format!("sha256:{}", hex::encode(Sha256::digest(&source_bytes))) != sha256
        || hex::encode(Md5::digest(&source_bytes)) != md5
    {
        return Err(CliError::Input(
            "managed import stage lost its exact source, target, or byte identity".to_owned(),
        ));
    }
    let stage_path = staged
        .get("stage_path")
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .ok_or_else(|| CliError::Input("managed import stage path is missing".to_owned()))?;
    let mut options = OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    options.custom_flags(libc::O_NOFOLLOW);
    let mut file = options.open(&stage_path).map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    let metadata = file.metadata().map_err(|source| CliError::Io {
        path: stage_path.display().to_string(),
        source,
    })?;
    let mut staged_bytes = Vec::new();
    file.read_to_end(&mut staged_bytes)
        .map_err(|source| CliError::Io {
            path: stage_path.display().to_string(),
            source,
        })?;
    #[cfg(unix)]
    let private_mode = metadata.permissions().mode() & 0o777 == 0o600;
    #[cfg(not(unix))]
    let private_mode = true;
    if !metadata.is_file()
        || !private_mode
        || metadata.len() != bytes
        || staged_bytes != source_bytes
    {
        return Err(CliError::Input(
            "private managed import stage no longer matches the reviewed source".to_owned(),
        ));
    }
    Ok(())
}

enum ApiBoundaryResponseOutcome {
    Ready {
        response_value: Value,
        apply_evidence: EvidenceV1,
        lineage_evidence: Option<EvidenceV1>,
    },
    Recovery(ResultEnvelopeV2),
}

/// Persists the non-secret response receipt, always attempts the one-time
/// secret sink, and reconciles lineage only when the boundary receipt was
/// durably saved. Any local failure after a successful response returns a
/// no-replay recovery envelope instead of losing boundary truth through the
/// generic top-level error path.
fn process_api_boundary_response(
    store: &StateStore,
    plan: &mut PlanV1,
    response: &CloudflareResponseV1,
    secrets: &dyn SecretStore,
) -> Result<ApiBoundaryResponseOutcome> {
    let response_value =
        redact_response_for_capability(&plan.capability, &serde_json::to_value(response)?);
    let mut failures = Vec::new();
    let apply_evidence = match store.write_evidence(EvidenceClass::Apply, &response_value) {
        Ok(evidence) => Some(evidence),
        Err(error) => {
            plan.status = PlanStatus::RectificationRequired;
            failures.push(format!("apply evidence persistence failed: {error}"));
            None
        }
    };
    let boundary_response_persisted = match persist_transaction_stage_with_artifact(
        store,
        plan,
        TransactionStageV1::BoundaryResponsePersisted,
        boundary_response_artifact(plan, response, apply_evidence.as_ref()),
    ) {
        Ok(()) => true,
        Err(error) => {
            plan.status = PlanStatus::RectificationRequired;
            failures.push(format!("boundary response persistence failed: {error}"));
            false
        }
    };
    let lifecycle = persist_secret_lifecycle_and_reconcile_lineage(
        store,
        plan,
        response.success,
        Some(&response.result),
        secrets,
        boundary_response_persisted,
    );
    if let Some(error) = lifecycle.error {
        failures.push(error.to_string());
    }
    if !failures.is_empty() {
        let error = CliError::Input(failures.join("; "));
        let verification_basis = if boundary_response_persisted {
            "the Cloudflare boundary response is durable, but local post-boundary recovery is required before verification can be trusted"
        } else {
            "Cloudflare returned a mutation response, but the boundary receipt is not durably validated; the one-time secret sink was still attempted and the mutation must not be replayed"
        };
        return Ok(ApiBoundaryResponseOutcome::Recovery(
            post_boundary_failure_envelope(
                plan,
                response_value,
                apply_evidence,
                lifecycle.lineage_evidence,
                &error,
                response.success,
                verification_basis,
            ),
        ));
    }
    let Some(apply_evidence) = apply_evidence else {
        return Err(CliError::Input(
            "post-boundary response handling lost its apply evidence without recording a recovery failure"
                .to_owned(),
        ));
    };
    Ok(ApiBoundaryResponseOutcome::Ready {
        response_value,
        apply_evidence,
        lineage_evidence: lifecycle.lineage_evidence,
    })
}

/// A transport error after `BoundaryAttemptPersisted` cannot prove that the
/// remote mutation did not happen. Persist as much local recovery state as
/// possible and return an operation-bound unknown-outcome envelope.
fn process_api_transport_failure(
    store: &StateStore,
    plan: &mut PlanV1,
    transport_error: &CliError,
    secrets: &dyn SecretStore,
) -> ResultEnvelopeV2 {
    plan.status = PlanStatus::RectificationRequired;
    let mut failures = vec![format!(
        "Cloudflare mutation outcome is unknown after the request crossed the boundary: {transport_error}"
    )];
    if let Err(error) = persist_transaction_stage_with_artifact(
        store,
        plan,
        TransactionStageV1::BoundaryResponsePersisted,
        boundary_failure_artifact("dynamic_api", "transport_error"),
    ) {
        failures.push(format!(
            "unknown-outcome boundary receipt persistence failed: {error}"
        ));
    }
    if let Err(error) = persist_secret_lifecycle(store, plan, false, None, secrets) {
        failures.push(format!(
            "unknown-outcome secret lifecycle persistence failed: {error}"
        ));
    }
    let error = CliError::Input(failures.join("; "));
    post_boundary_failure_envelope(
        plan,
        json!({
            "success": false,
            "outcome": "unknown",
            "receipt_available": false,
        }),
        None,
        None,
        &error,
        false,
        "the mutation request was sent, but no Cloudflare response was received; the remote outcome is unknown and must be rectified without replay",
    )
}

fn api_plan_result_envelope(
    plan: &PlanV1,
    mut result: Value,
    apply_evidence: EvidenceV1,
    lineage_evidence: Option<EvidenceV1>,
    verification: ApiVerificationOutcome,
    performed: bool,
    finalization_error: Option<&CliError>,
) -> ResultEnvelopeV2 {
    if let Some(resource_id) = verification.correlated_resource_id.as_ref()
        && let Some(object) = result.as_object_mut()
    {
        object.insert(
            "cfctl_correlated_resource_id".to_owned(),
            resource_id.clone(),
        );
    }
    if let Some(error) = finalization_error {
        let mut envelope = post_boundary_failure_envelope(
            plan,
            result,
            Some(apply_evidence),
            lineage_evidence,
            error,
            performed,
            "the Cloudflare boundary response is durable, but the final local checkpoint requires recovery",
        );
        envelope.verification.state = verification.state;
        envelope.verification.basis = Some(format!(
            "{}; the final plan checkpoint could not be persisted",
            verification.basis
        ));
        if let Some(evidence) = verification.evidence {
            envelope.evidence.push(evidence);
        }
        return envelope;
    }
    let mut envelope = ResultEnvelopeV2::success("plans run", result).with_evidence(apply_evidence);
    if let Some(evidence) = lineage_evidence {
        envelope.evidence.push(evidence);
    }
    if let Some(evidence) = verification.evidence {
        envelope.evidence.push(evidence);
    }
    envelope.ok = performed && plan.status == PlanStatus::Verified;
    envelope.performed = performed;
    envelope.operation_id = Some(plan.operation_id.clone());
    envelope.capability_id = Some(plan.capability.id.clone());
    envelope.profile_id = Some(plan.profile_id.clone());
    envelope.account_id = Some(plan.account_id.clone());
    envelope.policy_decision = Some(plan.policy.clone());
    envelope.verification.state = verification.state;
    envelope.verification.basis = Some(verification.basis);
    envelope.error = verification.error;
    envelope
}

struct ApiVerificationOutcome {
    state: VerificationState,
    basis: String,
    evidence: Option<EvidenceV1>,
    error: Option<ErrorV1>,
    correlated_resource_id: Option<Value>,
}

fn blocked_capability_envelope(
    command: &str,
    capability: &cfctl_core::CapabilityV1,
    reason: &str,
) -> ResultEnvelopeV2 {
    let next_step = format!(
        "Run `cfctl guide {} --json` and follow next_action; never bypass the blocker.",
        capability.id
    );
    let mut envelope = ResultEnvelopeV2::failure(
        command,
        "CFCTL_CAPABILITY_BLOCKED",
        &format!("capability is blocked: {reason}"),
        Some(&next_step),
    );
    envelope.capability_id = Some(capability.id.clone());
    envelope.result = json!({ "blocking_gaps": capability.mutation_contract_gaps() });
    envelope
}

fn post_boundary_failure_envelope(
    plan: &PlanV1,
    result: Value,
    apply_evidence: Option<EvidenceV1>,
    lineage_evidence: Option<EvidenceV1>,
    error: &CliError,
    performed: bool,
    verification_basis: &str,
) -> ResultEnvelopeV2 {
    let next_step = format!(
        "Do not replay the mutation; run `cfctl plans rectify {}`.",
        plan.operation_id
    );
    let mut envelope = ResultEnvelopeV2::failure(
        "plans run",
        "CFCTL_POST_BOUNDARY_RECOVERY_REQUIRED",
        &error.to_string(),
        Some(&next_step),
    );
    envelope.result = redact_json(&result);
    envelope.performed = performed;
    envelope.operation_id = Some(plan.operation_id.clone());
    envelope.capability_id = Some(plan.capability.id.clone());
    envelope.profile_id = Some(plan.profile_id.clone());
    envelope.account_id = Some(plan.account_id.clone());
    envelope.policy_decision = Some(plan.policy.clone());
    envelope.verification.state = VerificationState::Pending;
    envelope.verification.basis = Some(verification_basis.to_owned());
    if let Some(evidence) = apply_evidence {
        envelope.evidence.push(evidence);
    }
    if let Some(evidence) = lineage_evidence {
        envelope.evidence.push(evidence);
    }
    envelope
}

fn boundary_response_artifact(
    plan: &PlanV1,
    response: &CloudflareResponseV1,
    apply_evidence: Option<&EvidenceV1>,
) -> Value {
    let nested_resource_id = plan
        .capability
        .created_nested_resource
        .as_ref()
        .and_then(|target| {
            let correlation = plan
                .input
                .pointer(&format!("/body/{}", target.correlation_field))
                .and_then(Value::as_str)?;
            let items = response
                .result
                .pointer(&target.items_pointer)
                .and_then(Value::as_array)?;
            let matching = items
                .iter()
                .filter(|item| {
                    item.get(&target.correlation_field).and_then(Value::as_str) == Some(correlation)
                })
                .collect::<Vec<_>>();
            (matching.len() == 1)
                .then(|| {
                    matching[0]
                        .pointer(&target.response_item_identity_pointer)
                        .filter(|identity| {
                            identity.as_str().is_some_and(|value| !value.is_empty())
                                || identity.as_u64().is_some()
                                || identity.as_i64().is_some()
                        })
                        .cloned()
                })
                .flatten()
        });
    let identity_pointer = plan
        .capability
        .created_resource
        .as_ref()
        .map(|target| target.response_result_identity_pointer.as_str())
        .or_else(|| {
            plan.capability
                .created_collection_resource
                .as_ref()
                .map(|target| target.response_result_identity_pointer.as_str())
        })
        .unwrap_or("/id");
    // Fail closed: never lift a secret field into the journal's `resource_id`.
    // The core contract gate already refuses a secret-named identity pointer, so
    // this is belt-and-suspenders against a pointer that slipped through.
    let resource_id = if nested_resource_id.is_some() {
        nested_resource_id
    } else if cfctl_core::pointer_names_secret_field(identity_pointer) {
        None
    } else {
        response
            .result
            .pointer(identity_pointer)
            .filter(|identity| {
                identity.as_str().is_some_and(|value| !value.is_empty())
                    || identity.as_u64().is_some()
                    || identity.as_i64().is_some()
            })
            .cloned()
    };
    json!({
        "apply_evidence_hash": apply_evidence.map(|evidence| evidence.content_hash.as_str()),
        "http_status": response.status,
        "success": response.success,
        "resource_id": resource_id,
        "resource_status": response.result.get("status").and_then(Value::as_str),
        "etag": response.etag,
        "cf_ray": response.cf_ray,
    })
}

fn boundary_failure_artifact(adapter: &str, outcome: &str) -> Value {
    json!({
        "adapter": adapter,
        "outcome": outcome,
        "receipt_available": false,
        "success": false,
    })
}

fn oauth_client_secret_output_state(
    plan: &PlanV1,
    response_success: bool,
    response_result: Option<&Value>,
) -> Result<(bool, Option<bool>)> {
    if !is_oauth_client_create_operation_identity(&plan.capability) {
        return Ok((response_success && is_secret_output_plan(plan), None));
    }
    if !is_oauth_client_create_capability(&plan.capability) {
        return Err(CliError::Input(
            "OAuth client creation drifted from its governed identity, entitlement, verification, or secret-output contract"
                .to_owned(),
        ));
    }
    if !response_success {
        return Ok((false, None));
    }
    let result = response_result.ok_or_else(|| {
        CliError::Input(
            "Cloudflare reported OAuth client creation success without a response result"
                .to_owned(),
        )
    })?;
    let secret_returned = match result.get("client_secret") {
        None | Some(Value::Null) => false,
        Some(Value::String(secret)) if !secret.is_empty() => true,
        Some(_) => {
            return Err(CliError::Input(
                "Cloudflare returned a malformed OAuth client_secret; the operation requires rectification"
                    .to_owned(),
            ));
        }
    };
    let auth_method = plan
        .input
        .pointer("/body/token_endpoint_auth_method")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input(
                "OAuth client creation plan omitted token_endpoint_auth_method".to_owned(),
            )
        })?;
    let output_required = match auth_method {
        "none" => secret_returned,
        "client_secret_basic" | "client_secret_post" => true,
        _ => {
            return Err(CliError::Input(
                "OAuth client creation plan contains an unsupported token authentication method"
                    .to_owned(),
            ));
        }
    };
    Ok((output_required, Some(secret_returned)))
}

fn secret_sink_artifact(
    plan: &PlanV1,
    path: Option<&Path>,
    input_cleanup_required: bool,
    input_cleanup_completed: bool,
    output_required: bool,
    secret_returned: Option<bool>,
    failure: Option<&str>,
) -> Value {
    let output_completed = !output_required || path.is_some();
    let mut artifact = json!({
        "completed": input_cleanup_completed && output_completed && failure.is_none(),
        "failure": failure,
        "input_cleanup": {
            "required": input_cleanup_required,
            "completed": input_cleanup_completed,
        },
        "output_sink": {
            "required": output_required,
            "completed": output_completed,
            "create_new": output_required,
            "format": secret_sink_format(&plan.capability),
            "unix_mode": cfg!(unix).then_some("0600"),
        },
        "path": path.map(|path| path.display().to_string()),
    });
    if is_oauth_client_create_operation_identity(&plan.capability) {
        artifact["secret_returned"] = secret_returned.map_or(Value::Null, Value::Bool);
        artifact["output_sink"]["requested"] = Value::Bool(is_secret_output_plan(plan));
        artifact["path"] = Value::Null;
    }
    artifact
}

/// Persists the secret-sink outcome and then reconciles token lineage from the
/// already-durable boundary receipt regardless of whether the sink succeeded.
/// A post-boundary error always directs the operator to rectification; replay
/// is never an acceptable recovery path.
struct PostBoundaryLifecycleOutcome {
    lineage_evidence: Option<EvidenceV1>,
    error: Option<CliError>,
}

fn persist_secret_lifecycle_and_reconcile_lineage(
    store: &StateStore,
    plan: &mut PlanV1,
    response_success: bool,
    response_result: Option<&Value>,
    secrets: &dyn SecretStore,
    boundary_response_durable: bool,
) -> PostBoundaryLifecycleOutcome {
    let secret_sink_result =
        persist_secret_lifecycle(store, plan, response_success, response_result, secrets);
    let lineage_result = if boundary_response_durable {
        reconcile_standing_lineage_from_plan(store, plan)
    } else {
        Ok(None)
    };
    match (secret_sink_result, lineage_result) {
        (Ok(_sink_path), Ok(lineage_evidence)) => PostBoundaryLifecycleOutcome {
            lineage_evidence,
            error: None,
        },
        (Err(sink_error), Ok(lineage_evidence)) => PostBoundaryLifecycleOutcome {
            lineage_evidence,
            error: Some(CliError::Input(format!(
                "the Cloudflare boundary response was persisted, but the secret sink failed: {sink_error}. Do not replay the mutation; run `cfctl plans rectify {}`",
                plan.operation_id
            ))),
        },
        (Ok(_), Err(lineage_error)) => PostBoundaryLifecycleOutcome {
            lineage_evidence: None,
            error: Some(CliError::Input(format!(
                "the Cloudflare boundary response was persisted, but standing token lineage reconciliation failed: {lineage_error}. Do not replay the mutation; run `cfctl plans rectify {}`",
                plan.operation_id
            ))),
        },
        (Err(sink_error), Err(lineage_error)) => PostBoundaryLifecycleOutcome {
            lineage_evidence: None,
            error: Some(CliError::Input(format!(
                "the Cloudflare boundary response was persisted, but both the secret sink and standing token lineage reconciliation failed (sink: {sink_error}; lineage: {lineage_error}). Do not replay the mutation; run `cfctl plans rectify {}`",
                plan.operation_id
            ))),
        },
    }
}

fn persist_secret_lifecycle(
    store: &StateStore,
    plan: &mut PlanV1,
    response_success: bool,
    response_result: Option<&Value>,
    secrets: &dyn SecretStore,
) -> Result<Option<PathBuf>> {
    let input_cleanup_required = plan_secret_body_ref(plan).is_some();
    let (output_required, secret_returned) = initialize_secret_output_state(
        store,
        plan,
        response_success,
        response_result,
        input_cleanup_required,
    )?;
    let input_cleanup_completed = match delete_plan_secret(plan, secrets) {
        Ok(deleted) => !input_cleanup_required || deleted,
        Err(error) => {
            plan.status = PlanStatus::RectificationRequired;
            persist_transaction_stage_with_artifact(
                store,
                plan,
                TransactionStageV1::SecretSinkPersisted,
                secret_sink_artifact(
                    plan,
                    None,
                    input_cleanup_required,
                    false,
                    output_required,
                    secret_returned,
                    Some("input_cleanup_failed"),
                ),
            )?;
            return Err(error);
        }
    };
    let sink_path = if output_required {
        let Some(result) = response_result else {
            plan.status = PlanStatus::RectificationRequired;
            persist_transaction_stage_with_artifact(
                store,
                plan,
                TransactionStageV1::SecretSinkPersisted,
                secret_sink_artifact(
                    plan,
                    None,
                    input_cleanup_required,
                    input_cleanup_completed,
                    output_required,
                    secret_returned,
                    Some("output_missing"),
                ),
            )?;
            return Err(CliError::Input(
                "the adapter reported success without returning the required sink-only value; do not replay the mutation"
                    .to_owned(),
            ));
        };
        match sink_secret_result(plan, result) {
            Ok(path) => Some(path),
            Err(error) => {
                plan.status = PlanStatus::RectificationRequired;
                persist_transaction_stage_with_artifact(
                    store,
                    plan,
                    TransactionStageV1::SecretSinkPersisted,
                    secret_sink_artifact(
                        plan,
                        None,
                        input_cleanup_required,
                        input_cleanup_completed,
                        output_required,
                        secret_returned,
                        Some("output_sink_failed"),
                    ),
                )?;
                return Err(error);
            }
        }
    } else {
        None
    };
    persist_transaction_stage_with_artifact(
        store,
        plan,
        TransactionStageV1::SecretSinkPersisted,
        secret_sink_artifact(
            plan,
            sink_path.as_deref(),
            input_cleanup_required,
            input_cleanup_completed,
            output_required,
            secret_returned,
            None,
        ),
    )?;
    Ok(sink_path)
}

fn initialize_secret_output_state(
    store: &StateStore,
    plan: &mut PlanV1,
    response_success: bool,
    response_result: Option<&Value>,
    input_cleanup_required: bool,
) -> Result<(bool, Option<bool>)> {
    match oauth_client_secret_output_state(plan, response_success, response_result) {
        Ok(state) => Ok(state),
        Err(error) => {
            plan.status = PlanStatus::RectificationRequired;
            persist_transaction_stage_with_artifact(
                store,
                plan,
                TransactionStageV1::SecretSinkPersisted,
                secret_sink_artifact(
                    plan,
                    None,
                    input_cleanup_required,
                    !input_cleanup_required,
                    response_success && is_secret_output_plan(plan),
                    None,
                    Some("output_contract_invalid"),
                ),
            )?;
            Err(error)
        }
    }
}

fn verification_response_artifact(outcome: &ApiVerificationOutcome) -> Result<Value> {
    Ok(json!({
        "state": outcome.state.as_str(),
        "basis_hash": hash_value(&json!(outcome.basis))?,
        "evidence_hash": outcome.evidence.as_ref().map(|evidence| evidence.content_hash.as_str()),
        "resource_id":outcome.correlated_resource_id,
    }))
}

async fn verify_api_plan(
    store: &StateStore,
    executor: &Executor,
    plan: &mut PlanV1,
    response: &CloudflareResponseV1,
    execution_input: &CallInput,
    credential: &AuthCredential,
) -> Result<ApiVerificationOutcome> {
    if !response.success {
        plan.status = PlanStatus::Failed;
        return Ok(ApiVerificationOutcome {
            state: VerificationState::NotApplicable,
            basis: "Cloudflare rejected the mutation before verification".to_owned(),
            evidence: None,
            error: None,
            correlated_resource_id: None,
        });
    }
    persist_transaction_stage(
        store,
        plan,
        TransactionStageV1::VerificationAttemptPersisted,
    )?;
    if !plan.capability.verification.required {
        plan.status = PlanStatus::Verified;
        let outcome = ApiVerificationOutcome {
            state: VerificationState::Passed,
            basis: non_readback_verification_basis(&plan.capability),
            evidence: None,
            error: None,
            correlated_resource_id: None,
        };
        persist_transaction_stage_with_artifact(
            store,
            plan,
            TransactionStageV1::VerificationResponsePersisted,
            verification_response_artifact(&outcome)?,
        )?;
        return Ok(outcome);
    }
    let outcome = match executor
        .verify_plan_with_input(plan, response, execution_input, credential)
        .await
    {
        Ok(verification) => verification_outcome(store, plan, verification)?,
        Err(error) => verification_error_outcome(store, plan, &error)?,
    };
    persist_transaction_stage_with_artifact(
        store,
        plan,
        TransactionStageV1::VerificationResponsePersisted,
        verification_response_artifact(&outcome)?,
    )?;
    Ok(outcome)
}

fn non_readback_verification_basis(capability: &CapabilityV1) -> String {
    if capability.verification.strategy == "sink_write_and_source_response_status" {
        "Cloudflare returned success and the required sink-only secret output was durably persisted"
            .to_owned()
    } else {
        "operation declares no post-change verifier".to_owned()
    }
}

fn verification_outcome(
    store: &StateStore,
    plan: &mut PlanV1,
    verification: OperationVerificationV1,
) -> Result<ApiVerificationOutcome> {
    let state = if verification.passed {
        VerificationState::Passed
    } else {
        VerificationState::Failed
    };
    plan.status = if verification.passed {
        PlanStatus::Verified
    } else {
        PlanStatus::RectificationRequired
    };
    // Defense in depth: the verifier readback is the full Cloudflare response,
    // which for a secret-sensitive capability can carry secret material. Apply
    // the same secret-aware redaction the Apply receipt gets before this reaches
    // evidence — the storage-layer `redact_json` alone misses camelCase/bare
    // secret fields (e.g. `secretAccessKey`, `sessionToken`, `value`).
    let mut verification_value = serde_json::to_value(&verification)?;
    if should_redact_secret_response(&plan.capability)
        && let Some(readback) = verification_value.get("readback")
    {
        let redacted = redact_response_for_capability(&plan.capability, readback);
        if let Some(object) = verification_value.as_object_mut() {
            object.insert("readback".to_owned(), redacted);
        }
    }
    let evidence =
        Some(store.write_evidence(EvidenceClass::PostChangeVerification, &verification_value)?);
    let error = (!verification.passed).then(|| ErrorV1 {
        code: "CFCTL_VERIFICATION_FAILED".to_owned(),
        message: verification.basis.clone(),
        next_step: Some(format!(
            "Inspect live state with `cfctl plans rectify {}` before any compensation.",
            plan.operation_id
        )),
    });
    Ok(ApiVerificationOutcome {
        state,
        basis: verification.basis,
        evidence,
        error,
        correlated_resource_id: verification.correlated_resource_id,
    })
}

fn verification_error_outcome(
    store: &StateStore,
    plan: &mut PlanV1,
    verification_error: &CloudflareError,
) -> Result<ApiVerificationOutcome> {
    let basis = format!("operation-specific verifier failed: {verification_error}");
    plan.status = PlanStatus::RectificationRequired;
    let evidence = Some(store.write_evidence(
        EvidenceClass::PostChangeVerification,
        &json!({
            "strategy": plan.capability.verification.strategy,
            "passed": false,
            "error": verification_error.to_string(),
        }),
    )?);
    Ok(ApiVerificationOutcome {
        state: VerificationState::Failed,
        basis: basis.clone(),
        evidence,
        error: Some(ErrorV1 {
            code: "CFCTL_VERIFICATION_ERROR".to_owned(),
            message: basis,
            next_step: Some(format!(
                "Do not replay the mutation; run `cfctl plans rectify {}`.",
                plan.operation_id
            )),
        }),
        correlated_resource_id: None,
    })
}

async fn resume_plan(store: &StateStore, selector: &PlanSelector) -> Result<ResultEnvelopeV2> {
    let plan = load_validated_plan(store, &selector.operation_id)?;
    match plan.status {
        PlanStatus::Draft | PlanStatus::Approved => Box::pin(run_plan(store, selector)).await,
        PlanStatus::Consumed | PlanStatus::Running => Err(CliError::Input(
            "the operation may have crossed the Cloudflare boundary; replay is blocked until rectification proves current state"
                .to_owned(),
        )),
        PlanStatus::Verified | PlanStatus::Rectified => show_plan(store, selector),
        _ => Err(CliError::Input(format!(
            "operation is {:?}; use `cfctl plans rectify {}`",
            plan.status, plan.operation_id
        ))),
    }
}

struct CompensationRequest {
    capability_id: String,
    expected_method: String,
    expected_path: String,
    input: CallInput,
    requested_account: Option<String>,
    adapter_targets: Value,
}

struct CompensationTarget {
    capability_id: String,
    expected_method: String,
    expected_path: String,
    selectors: Value,
    body: Option<Value>,
}

fn validate_compensation_contract(capability: &CapabilityV1) -> Result<()> {
    if capability.rollback_contract_supported() {
        return Ok(());
    }
    Err(CliError::Input(format!(
        "rollback strategy `{}` is not implemented for capability `{}`; inspect live state before compensating",
        capability
            .rollback
            .strategy
            .as_deref()
            .unwrap_or("<missing>"),
        capability.id
    )))
}

