fn async_list_member_compensation_request(plan: &PlanV1) -> Result<CompensationRequest> {
    let member_id = plan
        .transaction_artifact(TransactionStageV1::VerificationResponsePersisted)
        .and_then(|artifact| artifact.get("resource_id"))
        .and_then(Value::as_str)
        .filter(|identity| identity.len() == 32)
        .ok_or_else(|| {
            CliError::Input(
                "the List add crossed the boundary, but no exact correlated member identity is present in its verification receipt; inspect live List state before compensating"
                    .to_owned(),
            )
        })?;
    let account_id = plan
        .targets
        .pointer("/selectors/account_id")
        .and_then(Value::as_str)
        .filter(|identity| !identity.is_empty())
        .ok_or_else(|| {
            CliError::Input("List compensation omitted its account selector".to_owned())
        })?;
    let list_id = plan
        .targets
        .pointer("/selectors/list_id")
        .and_then(Value::as_str)
        .filter(|identity| !identity.is_empty())
        .ok_or_else(|| CliError::Input("List compensation omitted its list selector".to_owned()))?;
    let source = plan
        .targets
        .pointer("/adapter/security_action")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            CliError::Input(
                "List compensation omitted its hash-bound security-action receipt".to_owned(),
            )
        })?;
    let security_action = json!({
        "schema_version":1,
        "kind":"remove_expired_list_member",
        "actor":source.get("actor").cloned().unwrap_or(Value::String("cfctl-compensation".to_owned())),
        "evidence_ref":source.get("evidence_ref").cloned().unwrap_or(Value::Null),
        "expires_at":source.get("expires_at").cloned().unwrap_or(Value::Null),
        "reason":"explicit rollback of the exact correlated List member",
        "source_operation_id":plan.operation_id,
        "member_id":member_id,
        "rollback_override":true,
        "anonymous_identity_inferred":false,
    });
    Ok(CompensationRequest {
        capability_id: SECURITY_LIST_MEMBER_REMOVE_ID.to_owned(),
        expected_method: "DELETE".to_owned(),
        expected_path: SECURITY_LIST_MEMBER_COLLECTION_PATH.to_owned(),
        input: CallInput {
            selectors: json!({"account_id":account_id,"list_id":list_id}),
            query: json!({}),
            body: Some(json!({"items":[{"id":member_id}]})),
            ..CallInput::default()
        },
        requested_account: Some(plan.account_id.clone()),
        adapter_targets: json!({"security_action":security_action}),
    })
}

fn compensation_resource_id(artifact: &Value) -> Result<&Value> {
    artifact
        .get("resource_id")
        .filter(|identity| {
            identity.as_str().is_some_and(|value| !value.is_empty())
                || identity.as_u64().is_some()
                || identity.as_i64().is_some()
        })
        .ok_or_else(|| {
            CliError::Input(
                "the creation response is recorded, but its hash-bound receipt has no string or integer resource id; inspect live resource state before compensating"
                    .to_owned(),
            )
        })
}

fn string_compensation_resource_id<'a>(plan: &PlanV1, resource_id: &'a Value) -> Result<&'a str> {
    resource_id.as_str().filter(|value| !value.is_empty()).ok_or_else(|| {
        CliError::Input(format!(
            "the `{}` compensation contract requires a string resource identity, but the hash-bound creation receipt has a different scalar type",
            plan.capability.id
        ))
    })
}

fn operation_specific_compensation_request(plan: &PlanV1) -> Result<Option<CompensationRequest>> {
    let request = if plan.capability.id == GLOBAL_WARP_OVERRIDE_MUTATION_CAPABILITY_ID {
        global_warp_override_compensation_request(plan)?
    } else if is_d1_read_replication_mutation(&plan.capability) {
        d1_read_replication_compensation_request(plan)?
    } else if is_cloudflare_tunnel_configuration_mutation(&plan.capability) {
        cloudflare_tunnel_configuration_compensation_request(plan)?
    } else if is_warp_connector_configuration_mutation(&plan.capability) {
        warp_connector_configuration_compensation_request(plan)?
    } else if is_web_analytics_rum_mutation(&plan.capability) {
        web_analytics_rum_compensation_request(plan)?
    } else if is_dns_record_update_mutation(&plan.capability) {
        dns_record_compensation_request(plan)?
    } else if should_bind_same_path_prior_state(&plan.capability) {
        same_path_prior_state_compensation_request(plan)?
    } else if plan.capability.id == SECURITY_LIST_MEMBER_CREATE_ID {
        async_list_member_compensation_request(plan)?
    } else {
        return Ok(None);
    };
    Ok(Some(request))
}

fn compensation_request(plan: &PlanV1) -> Result<Option<CompensationRequest>> {
    if !matches!(
        plan.status,
        PlanStatus::Consumed | PlanStatus::Running | PlanStatus::RectificationRequired
    ) || !plan.capability.rollback.supported
    {
        return Ok(None);
    }
    validate_compensation_contract(&plan.capability)?;
    let Some(artifact) = plan.transaction_artifact(TransactionStageV1::BoundaryResponsePersisted)
    else {
        return Ok(None);
    };
    if artifact.get("success").and_then(Value::as_bool) != Some(true) {
        return Ok(None);
    }
    if let Some(request) = operation_specific_compensation_request(plan)? {
        return Ok(Some(request));
    }
    let resource_id = compensation_resource_id(artifact)?;
    let Some(target) = created_resource_compensation_target(plan, resource_id)? else {
        return Ok(None);
    };
    Ok(Some(CompensationRequest {
        capability_id: target.capability_id,
        expected_method: target.expected_method,
        expected_path: target.expected_path,
        input: CallInput {
            selectors: target.selectors,
            query: json!({}),
            body: target.body,
            ..CallInput::default()
        },
        requested_account: Some(plan.account_id.clone()),
        adapter_targets: json!({}),
    }))
}

fn created_resource_compensation_target(
    plan: &PlanV1,
    resource_id: &Value,
) -> Result<Option<CompensationTarget>> {
    let (capability_id, expected_method, expected_path, selectors, body) = match plan
        .capability
        .id
        .as_str()
    {
        "account-api-tokens-create-token" => (
            "account-api-tokens-delete-token".to_owned(),
            "DELETE".to_owned(),
            "/accounts/{account_id}/tokens/{token_id}".to_owned(),
            json!({"account_id": plan.account_id, "token_id": string_compensation_resource_id(plan, resource_id)?}),
            None,
        ),
        "user-api-tokens-create-token" => (
            "user-api-tokens-delete-token".to_owned(),
            "DELETE".to_owned(),
            "/user/tokens/{token_id}".to_owned(),
            json!({"token_id": string_compensation_resource_id(plan, resource_id)?}),
            None,
        ),
        "dns-records-for-a-zone-create-dns-record" => {
            let resource_id = string_compensation_resource_id(plan, resource_id)?;
            let input: CallInput = serde_json::from_value(plan.input.clone())?;
            let zone_id = input
                .selectors
                .get("zone_id")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    CliError::Input(
                        "the DNS record creation receipt is valid, but its source plan has no zone_id selector; inspect live DNS state before compensating"
                            .to_owned(),
                    )
                })?;
            (
                "dns-records-for-a-zone-delete-dns-record".to_owned(),
                "DELETE".to_owned(),
                DNS_RECORD_DETAIL_PATH.to_owned(),
                json!({"zone_id": zone_id, "dns_record_id": resource_id}),
                None,
            )
        }
        D1_DATABASE_CREATE_CAPABILITY_ID => {
            if plan.capability.rollback.strategy.as_deref()
                != Some(D1_EMPTY_DATABASE_COMPENSATION_STRATEGY)
            {
                return Ok(None);
            }
            let (capability_id, expected_path, selectors) =
                generic_created_resource_compensation(plan, resource_id)?;
            (
                capability_id,
                "DELETE".to_owned(),
                expected_path,
                selectors,
                None,
            )
        }
        _ => {
            if plan.capability.rollback.strategy.as_deref()
                != Some("delete_created_resource_by_returned_id")
            {
                return Ok(None);
            }
            let (capability_id, expected_path, selectors) =
                generic_created_resource_compensation(plan, resource_id)?;
            (
                capability_id,
                "DELETE".to_owned(),
                expected_path,
                selectors,
                None,
            )
        }
    };
    Ok(Some(CompensationTarget {
        capability_id,
        expected_method,
        expected_path,
        selectors,
        body,
    }))
}

fn generic_created_resource_compensation(
    plan: &PlanV1,
    resource_id: &Value,
) -> Result<(String, String, Value)> {
    let input: CallInput = serde_json::from_value(plan.input.clone())?;
    let mut selectors = input.selectors.as_object().cloned().ok_or_else(|| {
        CliError::Input(
            "the creation receipt is valid, but its source selectors are not an object; inspect live resource state before compensating"
                .to_owned(),
        )
    })?;
    let (identity_selector, delete_capability_id, expected_path) = if let Some(target) =
        plan.capability.created_resource.as_ref()
    {
        (
            target.identity_selector.as_str(),
            target.delete_capability_id.clone(),
            target.detail_path.clone(),
        )
    } else if let Some(target) = plan.capability.created_collection_resource.as_ref() {
        (
            target.identity_selector.as_str(),
            target.delete_capability_id.clone(),
            format!(
                "{}/{{{}}}",
                target.collection_path.trim_end_matches('/'),
                target.identity_selector
            ),
        )
    } else if let Some(target) = plan.capability.created_nested_resource.as_ref() {
        (
            target.identity_selector.as_str(),
            target.delete_capability_id.clone(),
            target.delete_path.clone(),
        )
    } else {
        return Err(CliError::Input(
                "the rollback strategy names created-resource deletion, but the hash-bound resource target is absent"
                    .to_owned(),
            ));
    };
    selectors.insert(identity_selector.to_owned(), resource_id.clone());
    Ok((
        delete_capability_id,
        expected_path,
        Value::Object(selectors),
    ))
}

fn bind_required_empty_compensation_body(
    request: &mut CompensationRequest,
    capability: &cfctl_core::CapabilityV1,
) {
    if request.expected_method == "DELETE"
        && capability.method == request.expected_method
        && capability.path == request.expected_path
        && request.input.body.is_none()
        && capability.required_empty_request_body_contract()
    {
        request.input.body = Some(json!({}));
    }
}

#[expect(
    clippy::too_many_lines,
    reason = "rectification must keep transaction-journal, boundary, verification, compensation, and terminal-state decisions visible as one recovery state machine"
)]
async fn rectify_plan(store: &StateStore, selector: &PlanSelector) -> Result<ResultEnvelopeV2> {
    let _plan_lock = store.lock_plan(&selector.operation_id)?;
    let mut plan = load_validated_plan(store, &selector.operation_id)?;
    if plan.capability.d1_approved_mln_import.is_some() {
        return rectify_approved_mln_import(store, &mut plan);
    }
    let lineage_evidence = reconcile_standing_lineage_from_plan(store, &plan)?;
    if let Some(mut request) = compensation_request(&plan)? {
        let catalog = ensure_catalog(store).await?;
        let capability = catalog
            .get(&request.capability_id)
            .cloned()
            .ok_or_else(|| capability_missing(&request.capability_id))?;
        if capability.method != request.expected_method || capability.path != request.expected_path
        {
            return Err(CliError::Input(format!(
                "compensation target `{}` no longer resolves to the hash-bound {} path; inspect live resource state before creating a replacement plan",
                request.capability_id, request.expected_method
            )));
        }
        bind_required_empty_compensation_body(&mut request, &capability);
        let source_receipt_hash = plan
            .transaction_journal
            .iter()
            .find(|checkpoint| checkpoint.stage == TransactionStageV1::BoundaryResponsePersisted)
            .and_then(|checkpoint| checkpoint.artifact_hash.as_deref());
        let mut compensation_targets = request
            .adapter_targets
            .as_object()
            .cloned()
            .unwrap_or_default();
        compensation_targets.insert(
            "compensates_operation_id".to_owned(),
            Value::String(plan.operation_id.clone()),
        );
        compensation_targets.insert(
            "compensates_capability_id".to_owned(),
            Value::String(plan.capability.id.clone()),
        );
        compensation_targets.insert(
            "compensation_strategy".to_owned(),
            serde_json::to_value(&plan.capability.rollback.strategy)?,
        );
        compensation_targets.insert(
            "source_receipt_hash".to_owned(),
            serde_json::to_value(source_receipt_hash)?,
        );
        compensation_targets.insert(
            "source_precondition_hash".to_owned(),
            serde_json::to_value(
                plan.precondition_hashes
                    .get("global_warp_override_state")
                    .or_else(|| {
                        plan.precondition_hashes
                            .get(D1_READ_REPLICATION_PRECONDITION)
                    })
                    .or_else(|| plan.precondition_hashes.get(DNS_RECORD_STATE_PRECONDITION))
                    .or_else(|| {
                        plan.precondition_hashes
                            .get(SECURITY_ACTION_STATE_PRECONDITION)
                    }),
            )?,
        );
        let mut envelope = Box::pin(create_plan(
            store,
            &catalog,
            capability,
            request.input,
            Some(&plan.profile_id),
            request.requested_account.as_deref(),
            Value::Object(compensation_targets),
        ))
        .await?;
        "plans rectify".clone_into(&mut envelope.command);
        if let Some(result) = envelope.result.as_object_mut() {
            result.insert(
                "compensates_operation_id".to_owned(),
                Value::String(plan.operation_id.clone()),
            );
            result.insert(
                "message".to_owned(),
                Value::String(
                    "A separate hash-bound compensation plan was created from the source plan receipts. It has not run; review and explicitly approve its operation ID."
                        .to_owned(),
                ),
            );
        }
        if let Some(evidence) = lineage_evidence {
            envelope.evidence.push(evidence);
        }
        return Ok(envelope);
    }
    let mut envelope = ResultEnvelopeV2::success(
        "plans rectify",
        json!({
            "operation_id": plan.operation_id,
            "status": plan.status,
            "compensation_steps": plan.compensation_steps,
            "verification_steps": plan.verification_steps,
            "non_reversible_warnings": plan.non_reversible_warnings,
            "message": "No safe automatic compensation plan can be derived from the hash-bound receipts for this capability. Inspect live state with the catalog, then create a new hash-bound plan."
        }),
    );
    if let Some(evidence) = lineage_evidence {
        envelope.evidence.push(evidence);
    }
    Ok(envelope)
}

#[expect(
    clippy::too_many_lines,
    reason = "rectification is one no-replay verified-state transition"
)]
fn rectify_approved_mln_import(store: &StateStore, plan: &mut PlanV1) -> Result<ResultEnvelopeV2> {
    if plan.status == PlanStatus::RectificationRequired
        && plan.transaction_stage == TransactionStageV1::SecretSinkPersisted
    {
        let checkpoints = store.read_d1_import_checkpoints(&plan.operation_id)?;
        if checkpoints.len() != 1
            || checkpoints[0].1.get("step").and_then(Value::as_str) != Some("init_response")
        {
            return Err(CliError::Input(
                "init-only rectification requires exactly one durable init response and no upload, ingest, poll, or provider-complete checkpoint"
                    .to_owned(),
            ));
        }
        let (init_evidence, checkpoint) = exact_durable_init_response_failure(store, plan)?;
        let valid_abandoned_session = checkpoint
            .pointer("/receipt/success")
            .and_then(Value::as_bool)
            == Some(true)
            && checkpoint
                .pointer("/receipt/result/success")
                .and_then(Value::as_bool)
                == Some(true)
            && checkpoint
                .pointer("/receipt/result/upload_url_present")
                .and_then(Value::as_bool)
                == Some(true)
            && checkpoint
                .pointer("/receipt/result/filename_present")
                .and_then(Value::as_bool)
                == Some(true)
            && checkpoint
                .pointer("/receipt/provider_errors_present")
                .and_then(Value::as_bool)
                == Some(false)
            && checkpoint
                .pointer("/receipt/result/provider_error_present")
                .and_then(Value::as_bool)
                == Some(false)
            && checkpoint
                .pointer("/receipt/errors")
                .and_then(Value::as_array)
                .is_some_and(Vec::is_empty)
            && checkpoint
                .pointer("/receipt/result/type")
                .is_some_and(Value::is_null)
            && checkpoint
                .pointer("/receipt/result/status")
                .is_some_and(Value::is_null);
        if !valid_abandoned_session {
            return Err(CliError::Input(
                "init-only rectification requires one successful redacted upload-session receipt; provider rejection or uncertainty remains unresolved"
                    .to_owned(),
            ));
        }
        persist_transaction_stage(
            store,
            plan,
            TransactionStageV1::VerificationAttemptPersisted,
        )?;
        plan.status = PlanStatus::Rectified;
        let completion = json!({
            "schema_version":1,
            "state":"rectified",
            "operation_id":plan.operation_id,
            "init_response_evidence_hash":init_evidence.content_hash,
            "upload_performed":false,
            "database_write_performed":false,
            "disposition":"abandoned_unuploaded_provider_init_session",
        });
        let verification_evidence =
            store.write_evidence(EvidenceClass::PostChangeVerification, &completion)?;
        persist_transaction_stage_with_artifact(
            store,
            plan,
            TransactionStageV1::VerificationResponsePersisted,
            json!({
                "state":"passed",
                "evidence_hash":verification_evidence.content_hash,
                "init_response_evidence_hash":init_evidence.content_hash,
            }),
        )?;
        persist_transaction_stage(store, plan, TransactionStageV1::Closed)?;
        let mut envelope = ResultEnvelopeV2::success("plans rectify", completion)
            .with_evidence(verification_evidence);
        envelope.evidence.push(init_evidence);
        envelope.performed = false;
        envelope.operation_id = Some(plan.operation_id.clone());
        envelope.capability_id = Some(plan.capability.id.clone());
        envelope.profile_id = Some(plan.profile_id.clone());
        envelope.account_id = Some(plan.account_id.clone());
        envelope.policy_decision = Some(plan.policy.clone());
        envelope.verification.state = VerificationState::Passed;
        envelope.verification.basis = Some(
            "the operation has exactly one durable successful init-session receipt and no upload, ingest, poll, or provider-complete checkpoint; rectification abandoned that unuploaded session without replay or provider mutation"
                .to_owned(),
        );
        return Ok(envelope);
    }
    if plan.status != PlanStatus::Running
        || plan.transaction_stage != TransactionStageV1::SecretSinkPersisted
    {
        return Err(CliError::Input(
            "approved MLN import is not at the durable provider_complete boundary".to_owned(),
        ));
    }
    let staged = plan
        .targets
        .pointer("/adapter/approved_mln_import")
        .cloned()
        .ok_or_else(|| CliError::Input("import stage binding is missing".to_owned()))?;
    let source_sha256 = staged
        .get("sha256")
        .and_then(Value::as_str)
        .map(str::to_owned)
        .ok_or_else(|| CliError::Input("import source SHA-256 is missing".to_owned()))?;
    let provider_boundary =
        exact_durable_provider_complete_boundary(store, plan.operation_id.as_str())?;
    let provider_complete_hash = &provider_boundary.evidence_hash;
    let import_input: CallInput = serde_json::from_value(plan.input.clone())?;
    let migration_id = import_input
        .body
        .as_ref()
        .and_then(|body| body.get("migration_id"))
        .and_then(Value::as_str)
        .ok_or_else(|| CliError::Input("import migration identity is missing".to_owned()))?;
    let matching = store
        .list_operational_proofs()?
        .into_iter()
        .filter_map(|proof| {
            if migration_id == "0142" {
                let binding = proof.mln_0142_governed_execution()?;
                let final_bookmark_hash = provider_boundary
                    .checkpoint
                    .pointer("/receipt/final_bookmark")
                    .and_then(Value::as_str)
                    .and_then(|bookmark| hash_value(&Value::String(bookmark.to_owned())).ok())?;
                let exact = proof.capability_id == "mln-0142-post-import-schema"
                    && binding.completion_status == "completed"
                    && binding.import_operation_id == plan.operation_id
                    && binding.import_boundary_evidence_hash == *provider_complete_hash
                    && binding.import_source_sha256 == source_sha256
                    && binding.import_plan_hash == plan.content_hash
                    && binding.final_bookmark_hash == final_bookmark_hash
                    && binding.target_scope_hash == hash_value(staged.get("target")?).ok()?;
                return exact.then_some(proof);
            }
            let binding = proof.mln_0143_governed_execution()?;
            if proof.capability_id != "mln-0143-data-invariants"
                || binding.phase != "post_import"
                || binding.completion_status != "completed"
                || binding.cross_operation_lineage_hash.is_none()
            {
                return None;
            }
            let evidence = store
                .read_evidence_value(&proof.evidence.content_hash)
                .ok()?;
            let manifest = evidence.get("result").unwrap_or(&evidence);
            let lineage = manifest.get("lineage")?;
            let exact = lineage.get("import_operation_id").and_then(Value::as_str)
                == Some(plan.operation_id.as_str())
                && lineage
                    .get("import_boundary_evidence_hash")
                    .and_then(Value::as_str)
                    == Some(provider_complete_hash.as_str())
                && lineage.get("import_source_sha256").and_then(Value::as_str)
                    == Some(source_sha256.as_str())
                && lineage.get("import_plan_hash").and_then(Value::as_str)
                    == Some(plan.content_hash.as_str())
                && binding.cross_operation_lineage_hash.as_deref()
                    == hash_value(lineage).ok().as_deref();
            exact.then_some(proof)
        })
        .collect::<Vec<_>>();
    if matching.len() != 1 {
        return Err(CliError::Input(
            "import verification requires exactly one governed post_import proof bound to this plan, source, target, and provider boundary"
                .to_owned(),
        ));
    }
    let proof = &matching[0];
    persist_transaction_stage(
        store,
        plan,
        TransactionStageV1::VerificationAttemptPersisted,
    )?;
    plan.status = PlanStatus::Verified;
    let completion = json!({
        "schema_version":1,
        "state":"verified",
        "operation_id":plan.operation_id,
        "provider_complete_evidence_hash":provider_complete_hash,
        "post_import_operation_id":proof.mln_0143_governed_execution().map(|binding| binding.operation_id.as_str()).or_else(|| proof.mln_0142_governed_execution().map(|binding| binding.operation_id.as_str())),
        "post_import_evidence_hash":proof.evidence.content_hash,
        "source_sha256":source_sha256,
        "target":staged.get("target"),
    });
    let verification_evidence =
        store.write_evidence(EvidenceClass::PostChangeVerification, &completion)?;
    persist_transaction_stage_with_artifact(
        store,
        plan,
        TransactionStageV1::VerificationResponsePersisted,
        json!({
            "state":"passed",
            "evidence_hash":verification_evidence.content_hash,
            "provider_complete_evidence_hash":provider_complete_hash,
        }),
    )?;
    persist_transaction_stage(store, plan, TransactionStageV1::Closed)?;
    let mut envelope =
        ResultEnvelopeV2::success("plans rectify", completion).with_evidence(verification_evidence);
    envelope.performed = false;
    envelope.operation_id = Some(plan.operation_id.clone());
    envelope.capability_id = Some(plan.capability.id.clone());
    envelope.profile_id = Some(plan.profile_id.clone());
    envelope.account_id = Some(plan.account_id.clone());
    envelope.policy_decision = Some(plan.policy.clone());
    envelope.verification.state = VerificationState::Passed;
    envelope.verification.basis = Some(
        "the exact provider_complete import boundary is joined to one governed migration-specific post-import proof; this local transition performed no additional provider mutation"
            .to_owned(),
    );
    Ok(envelope)
}

async fn keys_command(store: &StateStore, command: KeysCommand) -> Result<ResultEnvelopeV2> {
    match command {
        KeysCommand::Permissions(arguments) => Box::pin(key_permissions(store, &arguments)).await,
        KeysCommand::Mint(arguments) => {
            preflight_standing_authority(store, arguments.under_policy.as_deref())?;
            let plan = Box::pin(key_mint(store, &arguments)).await?;
            Box::pin(finish_standing_run(
                store,
                plan,
                arguments.under_policy.as_deref(),
            ))
            .await
        }
        KeysCommand::Rotate(arguments) => Box::pin(key_rotate(store, &arguments)).await,
        KeysCommand::RenewAnalyticsProfile(arguments) => {
            Box::pin(key_renew_analytics_profile(store, &arguments)).await
        }
        KeysCommand::Revoke(arguments) => {
            preflight_standing_authority(store, arguments.under_policy.as_deref())?;
            let plan = Box::pin(key_revoke(store, &arguments)).await?;
            Box::pin(finish_standing_run(
                store,
                plan,
                arguments.under_policy.as_deref(),
            ))
            .await
        }
        KeysCommand::Policy(arguments) => Box::pin(key_policy(store, arguments.command)).await,
    }
}

/// Fails a standing run closed before any live read or plan creation when
/// the named authority is missing, unapproved, revoked, or expired.
fn preflight_standing_authority(store: &StateStore, under_policy: Option<&str>) -> Result<()> {
    if let Some(authority_id) = under_policy {
        recover_standing_lineage(store, authority_id)?;
        store.load_authority(authority_id)?.ensure_operational()?;
    }
    Ok(())
}

/// When `--under-policy` names a standing authority, the freshly created plan
/// is immediately validated against the authority's bounds and executed in
/// the same invocation; otherwise the plan envelope is returned for the
/// ordinary per-operation approval ceremony.
async fn finish_standing_run(
    store: &StateStore,
    plan_envelope: ResultEnvelopeV2,
    under_policy: Option<&str>,
) -> Result<ResultEnvelopeV2> {
    let Some(authority_id) = under_policy else {
        return Ok(plan_envelope);
    };
    let Some(operation_id) = plan_envelope.operation_id.clone() else {
        return Err(CliError::Input(
            "a standing run requires the plan envelope to carry an operation id".to_owned(),
        ));
    };
    Box::pin(run_plan_under_standing_authority(
        store,
        &operation_id,
        authority_id,
    ))
    .await
}

async fn key_policy(store: &StateStore, command: KeyPolicyCommand) -> Result<ResultEnvelopeV2> {
    match command {
        KeyPolicyCommand::Create(arguments) => Box::pin(key_policy_create(store, &arguments)).await,
        KeyPolicyCommand::List => key_policy_list(store),
        KeyPolicyCommand::Approve(arguments) => key_policy_approve(store, &arguments),
        KeyPolicyCommand::Revoke(selector) => key_policy_revoke(store, &selector),
    }
}

async fn key_policy_create(
    store: &StateStore,
    arguments: &KeyPolicyCreateArgs,
) -> Result<ResultEnvelopeV2> {
    if arguments.permissions.is_empty() {
        return Err(CliError::Input(
            "a standing authority requires at least one allowlisted permission group; use `cfctl keys permissions --account <id>`"
                .to_owned(),
        ));
    }
    if arguments.name_prefix.trim().is_empty() {
        return Err(CliError::Input(
            "a standing authority requires a non-empty `--name-prefix` lineage bound".to_owned(),
        ));
    }
    if arguments.max_child_ttl_hours == 0 || arguments.max_runs_per_day == 0 {
        return Err(CliError::Input(
            "`--max-child-ttl-hours` and `--max-runs-per-day` must both be at least 1".to_owned(),
        ));
    }
    let inventory = Box::pin(key_permissions(
        store,
        &KeyPermissionArgs {
            profile: arguments.profile.clone(),
            account: arguments.account.clone(),
            user: false,
        },
    ))
    .await?;
    if !inventory.ok
        || !inventory.performed
        || inventory.account_id.as_deref() != Some(arguments.account.as_str())
    {
        return Err(CliError::Input(
            "fresh account-bound permission inventory did not produce a live-read receipt"
                .to_owned(),
        ));
    }
    let selected_groups = validate_selected_permission_groups(
        &arguments.permissions,
        inventory.result.get("result").unwrap_or(&Value::Null),
    )?;
    let zone_id = arguments
        .zone
        .as_deref()
        .map(str::trim)
        .filter(|zone| !zone.is_empty());
    if let Some(zone_id) = zone_id {
        validate_zone_id(zone_id)?;
    }
    validate_standing_authority_group_scopes(&selected_groups, zone_id)?;
    let selected_group_ids = selected_groups
        .iter()
        .filter_map(|group| group.get("id").and_then(Value::as_str))
        .map(str::to_owned)
        .collect::<Vec<_>>();
    let selected_groups_hash = hash_value(&serde_json::to_value(&selected_groups)?)?;
    let expires_at = Utc::now() + ChronoDuration::days(i64::from(arguments.expires_days));
    let authority = StandingAuthorityV1::draft(
        &arguments.account,
        zone_id,
        vec![
            "account-api-tokens-create-token".to_owned(),
            "account-api-tokens-delete-token".to_owned(),
        ],
        selected_group_ids,
        &selected_groups_hash,
        arguments.max_child_ttl_hours,
        &arguments.name_prefix,
        arguments.max_runs_per_day,
        expires_at,
    )?;
    store.create_authority(&authority)?;
    let mut envelope = ResultEnvelopeV2::success(
        "keys policy create",
        json!({
            "authority_id": authority.authority_id,
            "status": authority.status.as_str(),
            "account_id": authority.account_id,
            "zone_id": authority.zone_id,
            "bound_resources": authority.allowed_token_resources(),
            "capability_ids": authority.capability_ids,
            "name_prefix": authority.name_prefix,
            "max_child_ttl_hours": authority.max_child_ttl_hours,
            "max_runs_per_day": authority.max_runs_per_day,
            "expires_at": authority.expires_at,
            "resolved_permission_groups": selected_groups,
            "permission_inventory_hash": authority.permission_inventory_hash,
            "approval_command": format!(
                "cfctl keys policy approve {} --yes",
                authority.authority_id
            ),
            "message": "Standing authority drafted from a fresh live permission inventory. Review the resolved groups and bounds, then approve the exact authority ID."
        }),
    );
    envelope.account_id = Some(arguments.account.clone());
    envelope.evidence = inventory.evidence;
    Ok(envelope)
}

fn key_policy_list(store: &StateStore) -> Result<ResultEnvelopeV2> {
    let now = Utc::now();
    let authorities: Vec<Value> = store
        .list_authorities()?
        .iter()
        .map(|authority| {
            let effective_status = authority.effective_status(now);
            let runs_last_24h = authority.runs_in_last_day(now);
            let runs_remaining_24h = usize::try_from(authority.max_runs_per_day)
                .unwrap_or(usize::MAX)
                .saturating_sub(runs_last_24h);
            let next_action = match effective_status {
                "pending_approval" => format!(
                    "Review the bounds, then run `cfctl keys policy approve {} --yes`.",
                    authority.authority_id
                ),
                "active" if runs_remaining_24h == 0 => format!(
                    "The rolling run budget is exhausted; wait for budget to age out or revoke with `cfctl keys policy revoke {}`.",
                    authority.authority_id
                ),
                "active" => format!(
                    "Use `--under-policy {}` only for a matching mint or lineage-bound revoke; list again to inspect the resulting budget and lineage.",
                    authority.authority_id
                ),
                "expired" => {
                    "This authority is effectively expired; create and explicitly approve a new policy if recurring work must continue."
                        .to_owned()
                }
                "revoked" => {
                    "This authority is revoked and cannot admit new runs; individually revoke any surviving child tokens when needed."
                        .to_owned()
                }
                _ => "Inspect the authority document before taking another action.".to_owned(),
            };
            json!({
                "authority_id": authority.authority_id,
                "status": effective_status,
                "account_id": authority.account_id,
                "zone_id": authority.zone_id,
                "bound_resources": authority.allowed_token_resources(),
                "capability_ids": authority.capability_ids,
                "name_prefix": authority.name_prefix,
                "permission_group_count": authority.permission_group_ids.len(),
                "max_child_ttl_hours": authority.max_child_ttl_hours,
                "max_runs_per_day": authority.max_runs_per_day,
                "runs_last_24h": runs_last_24h,
                "runs_remaining_24h": runs_remaining_24h,
                "minted_tokens": authority.minted_token_ids.len(),
                "minted_token_ids": authority.minted_token_ids,
                "created_at": authority.created_at,
                "expires_at": authority.expires_at,
                "next_action": next_action,
            })
        })
        .collect();
    Ok(ResultEnvelopeV2::success(
        "keys policy list",
        json!({"authorities": authorities}),
    ))
}

fn key_policy_approve(
    store: &StateStore,
    arguments: &KeyPolicyApproveArgs,
) -> Result<ResultEnvelopeV2> {
    let guard = store.lock_authority(&arguments.authority_id)?;
    let mut authority = store.load_authority(&arguments.authority_id)?;
    authority.approve(arguments.yes)?;
    store.save_authority_guarded(&authority, &guard)?;
    Ok(ResultEnvelopeV2::success(
        "keys policy approve",
        json!({
            "authority_id": authority.authority_id,
            "status": authority.status.as_str(),
            "approved_content_hash": authority.approval.as_ref().map(|approval| approval.approved_content_hash.clone()),
            "expires_at": authority.expires_at,
            "message": "Standing authority is active. Unattended runs under it are bounded, rate-limited, attributable, and revocable with `cfctl keys policy revoke`."
        }),
    ))
}

fn key_policy_revoke(store: &StateStore, selector: &KeyPolicySelector) -> Result<ResultEnvelopeV2> {
    let guard = store.lock_authority(&selector.authority_id)?;
    let mut authority = store.load_authority(&selector.authority_id)?;
    authority.revoke();
    store.save_authority_guarded(&authority, &guard)?;
    Ok(ResultEnvelopeV2::success(
        "keys policy revoke",
        json!({
            "authority_id": authority.authority_id,
            "status": authority.status.as_str(),
            "message": "Standing authority revoked. Runs not yet durably admitted fail closed; an already-admitted boundary attempt may finish, and later lineage reconciliation cannot reactivate the grant. Already-minted child tokens are unaffected and can be revoked individually."
        }),
    ))
}

async fn key_permissions(
    store: &StateStore,
    arguments: &KeyPermissionArgs,
) -> Result<ResultEnvelopeV2> {
    let envelope = Box::pin(call_command(store, permission_inventory_call(arguments))).await?;
    Ok(permission_inventory_envelope(envelope))
}

fn permission_inventory_call(arguments: &KeyPermissionArgs) -> CallArgs {
    let capability_id = if arguments.user {
        "permission-groups-list-permission-groups"
    } else {
        "account-api-tokens-list-permission-groups"
    };
    let mut selectors = Vec::new();
    if !arguments.user {
        selectors.push(("account_id".to_owned(), arguments.account.clone()));
    }
    CallArgs {
        capability_id: capability_id.to_owned(),
        selectors,
        query: Vec::new(),
        body_json: None,
        body_stdin: false,
        profile: arguments.profile.clone(),
        account: Some(arguments.account.clone()),
        if_match: None,
        if_none_match: None,
        value_out: None,
        credential_in: None,
        out: None,
        source_file: None,
    }
}

fn permission_inventory_envelope(mut envelope: ResultEnvelopeV2) -> ResultEnvelopeV2 {
    "keys permissions".clone_into(&mut envelope.command);
    let forbidden = serde_json::from_value::<CloudflareResponseV1>(envelope.result.clone())
        .is_ok_and(|response| {
            !response.success
                && (response.status == 403
                    || response.errors.iter().any(|error| error.code == Some(9109)))
        });
    if forbidden {
        envelope.ok = false;
        envelope.verification.state = VerificationState::Failed;
        envelope.error = Some(ErrorV1 {
            code: "CFCTL_PERMISSION_INVENTORY_FORBIDDEN".to_owned(),
            message: "Cloudflare denied the permission-group inventory. The selected API token requires the `Account API Tokens Read` or `Account API Tokens Write` grant for the explicit account."
                .to_owned(),
            next_step: Some(
                "Grant the selected token Account API Tokens Read or Write, then retry the same account-bound inventory command."
                    .to_owned(),
            ),
        });
    }
    envelope
}

async fn key_mint(store: &StateStore, arguments: &KeyMutationArgs) -> Result<ResultEnvelopeV2> {
    let account = arguments.account.as_deref().ok_or_else(|| {
        CliError::Input("token minting requires `--account` for explicit resource scope".to_owned())
    })?;
    let value_out = arguments.value_out.as_ref().ok_or_else(|| {
        CliError::Input("token minting requires the sink-only `--value-out <path>`".to_owned())
    })?;
    if arguments.permissions.is_empty() {
        return Err(CliError::Input(if arguments.user {
            "at least one permission group ID or exact name is required; use `cfctl keys permissions --user --account <id>`"
                    .to_owned()
        } else {
            "at least one permission group ID or exact name is required; use `cfctl keys permissions --account <id>`"
                    .to_owned()
        }));
    }
    // Resolve the requested scope before any network I/O. This is pure
    // argument validation, and running it after the inventory read reported a
    // contradiction like `--user --zone` as an inventory failure — naming the
    // wrong problem, after spending a live call to find it. The same resolution
    // runs again inside the binding partition below; it is idempotent.
    resolve_mint_token_scope(arguments, account)?;
    let inventory = Box::pin(key_permissions(
        store,
        &KeyPermissionArgs {
            profile: arguments.profile.clone(),
            account: account.to_owned(),
            user: arguments.user,
        },
    ))
    .await?;
    if !inventory.ok || !inventory.performed || inventory.account_id.as_deref() != Some(account) {
        return Err(CliError::Input(
            "fresh owner-specific permission inventory did not produce an account-bound live-read receipt"
                .to_owned(),
        ));
    }
    let selected_groups = validate_selected_permission_groups(
        &arguments.permissions,
        inventory.result.get("result").unwrap_or(&Value::Null),
    )?;
    let permission_bindings = resolve_mint_token_bindings(arguments, account, &selected_groups)?;
    let selected_groups_hash = hash_value(&serde_json::to_value(&selected_groups)?)?;
    let inventory_evidence_hashes = inventory
        .evidence
        .iter()
        .map(|evidence| evidence.content_hash.clone())
        .collect::<Vec<_>>();
    let body = build_mint_policy_body(&arguments.name, &permission_bindings, arguments.ttl_hours);
    let catalog = ensure_catalog(store).await?;
    let capability_id = if arguments.user {
        "user-api-tokens-create-token"
    } else {
        "account-api-tokens-create-token"
    };
    let inventory_contract = token_permission_inventory_contract(capability_id)
        .ok_or_else(|| capability_missing(capability_id))?;
    let capability = catalog
        .get(capability_id)
        .cloned()
        .ok_or_else(|| capability_missing(capability_id))?;
    let mut plan = Box::pin(create_plan(
        store,
        &catalog,
        capability,
        CallInput {
            selectors: if arguments.user {
                json!({})
            } else {
                json!({"account_id": account})
            },
            query: json!({}),
            body: Some(body),
            ..CallInput::default()
        },
        arguments.profile.as_deref(),
        Some(account),
        json!({
            "value_out": value_out,
            "permission_inventory": {
                "source_capability_id": inventory_contract.capability_id,
                "selected_groups": selected_groups,
                "selected_groups_hash": selected_groups_hash,
                "permission_bindings": permission_bindings.iter().map(TokenPolicyBinding::as_json).collect::<Vec<_>>(),
                "evidence_hashes": inventory_evidence_hashes,
            }
        }),
    ))
    .await?;
    plan.evidence.splice(0..0, inventory.evidence);
    Ok(plan)
}

fn validate_selected_permission_groups(
    requested_selectors: &[String],
    inventory: &Value,
) -> Result<Vec<Value>> {
    if requested_selectors.is_empty() {
        return Err(CliError::Input(
            "at least one permission group ID or exact name must be selected".to_owned(),
        ));
    }
    let groups = inventory.as_array().ok_or_else(|| {
        CliError::Input("live permission inventory result is not an array".to_owned())
    })?;
    let mut requested_selectors = requested_selectors.to_vec();
    requested_selectors.sort();
    requested_selectors.dedup();
    let mut resolved = BTreeMap::<String, &Value>::new();
    for requested_selector in requested_selectors {
        let matches = groups
            .iter()
            .filter(|group| {
                group.get("id").and_then(Value::as_str) == Some(&requested_selector)
                    || group.get("name").and_then(Value::as_str) == Some(&requested_selector)
            })
            .collect::<Vec<_>>();
        if matches.len() != 1 {
            return Err(CliError::Input(format!(
                "permission group selector `{requested_selector}` is not unique in the fresh account inventory (matched {})",
                matches.len()
            )));
        }
        let group = matches[0];
        let resolved_id = group
            .get("id")
            .and_then(Value::as_str)
            .filter(|id| !id.trim().is_empty())
            .ok_or_else(|| {
                CliError::Input(format!(
                    "permission group `{requested_selector}` has no auditable ID in the fresh account inventory"
                ))
            })?;
        let id_matches = groups
            .iter()
            .filter(|candidate| candidate.get("id").and_then(Value::as_str) == Some(resolved_id))
            .count();
        if id_matches != 1 {
            return Err(CliError::Input(format!(
                "permission group `{resolved_id}` is not unique in the fresh account inventory (matched {id_matches})"
            )));
        }
        resolved.insert(resolved_id.to_owned(), group);
    }
    let mut selected = Vec::with_capacity(resolved.len());
    for (resolved_id, group) in resolved {
        let name = group
            .get("name")
            .and_then(Value::as_str)
            .filter(|name| !name.trim().is_empty())
            .ok_or_else(|| {
                CliError::Input(format!(
                    "permission group `{resolved_id}` has no auditable name in the fresh account inventory"
                ))
            })?;
        let mut scopes = group
            .get("scopes")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                CliError::Input(format!(
                    "permission group `{resolved_id}` has no auditable scope list in the fresh account inventory"
                ))
            })?
            .iter()
            .map(|scope| {
                scope.as_str().map(str::to_owned).ok_or_else(|| {
                    CliError::Input(format!(
                        "permission group `{resolved_id}` contains a non-string scope"
                    ))
                })
            })
            .collect::<Result<Vec<_>>>()?;
        scopes.sort();
        scopes.dedup();
        if scopes.is_empty() {
            return Err(CliError::Input(format!(
                "permission group `{resolved_id}` has an empty scope list"
            )));
        }
        let mut normalized = Map::from_iter([
            ("id".to_owned(), Value::String(resolved_id)),
            ("name".to_owned(), Value::String(name.to_owned())),
            ("scopes".to_owned(), serde_json::to_value(scopes)?),
        ]);
        if let Some(category) = group.get("category").and_then(Value::as_str) {
            normalized.insert("category".to_owned(), Value::String(category.to_owned()));
        }
        selected.push(Value::Object(normalized));
    }
    Ok(selected)
}

async fn key_rotate(store: &StateStore, arguments: &KeyRotateArgs) -> Result<ResultEnvelopeV2> {
    let catalog = ensure_catalog(store).await?;
    let capability_id = if arguments.user {
        "user-api-tokens-roll-token"
    } else {
        "account-api-tokens-roll-token"
    };
    let capability = catalog
        .get(capability_id)
        .cloned()
        .ok_or_else(|| capability_missing(capability_id))?;
    Box::pin(create_plan(
        store,
        &catalog,
        capability,
        CallInput {
            selectors: if arguments.user {
                json!({"token_id": arguments.id})
            } else {
                json!({"account_id": arguments.account, "token_id": arguments.id})
            },
            query: json!({}),
            body: Some(json!({})),
            ..CallInput::default()
        },
        None,
        Some(&arguments.account),
        json!({"value_out": arguments.value_out}),
    ))
    .await
}

async fn analytics_rotation_reads(
    store: &StateStore,
    profile: &str,
    account: &str,
    zone: &str,
    hostname: &str,
) -> Result<Vec<ResultEnvelopeV2>> {
    let today = Utc::now().date_naive();
    let month_start = today.with_day(1).ok_or_else(|| {
        CliError::Input("could not derive the current UTC month boundary".to_owned())
    })?;
    let limit = i64::from(today.day());
    let calls = [
        CallArgs {
            capability_id: "graphql-analytics-account-rum-dataset-settings".to_owned(),
            selectors: vec![("account_id".to_owned(), account.to_owned())],
            query: Vec::new(),
            body_json: Some("{}".to_owned()),
            body_stdin: false,
            profile: Some(profile.to_owned()),
            account: Some(account.to_owned()),
            if_match: None,
            if_none_match: None,
            value_out: None,
            credential_in: None,
            out: None,
            source_file: None,
        },
        CallArgs {
            capability_id: "graphql-analytics-zone-dataset-settings".to_owned(),
            selectors: vec![("zone_id".to_owned(), zone.to_owned())],
            query: Vec::new(),
            body_json: Some("{}".to_owned()),
            body_stdin: false,
            profile: Some(profile.to_owned()),
            account: Some(account.to_owned()),
            if_match: None,
            if_none_match: None,
            value_out: None,
            credential_in: None,
            out: None,
            source_file: None,
        },
        CallArgs {
            capability_id: "graphql-analytics-account-rum-pageload-visits".to_owned(),
            selectors: vec![("account_id".to_owned(), account.to_owned())],
            query: Vec::new(),
            body_json: Some(
                json!({
                    "dataset":"rumPageloadEventsAdaptiveGroups",
                    "hostname":hostname,
                    "start":month_start.format("%Y-%m-%d").to_string(),
                    "end":today.format("%Y-%m-%d").to_string(),
                    "limit":limit,
                })
                .to_string(),
            ),
            body_stdin: false,
            profile: Some(profile.to_owned()),
            account: Some(account.to_owned()),
            if_match: None,
            if_none_match: None,
            value_out: None,
            credential_in: None,
            out: None,
            source_file: None,
        },
    ];
    let mut envelopes = Vec::with_capacity(calls.len());
    for call in calls {
        let envelope = Box::pin(call_command(store, call)).await?;
        let succeeded = envelope.ok && envelope.performed;
        envelopes.push(envelope);
        if !succeeded {
            break;
        }
    }
    Ok(envelopes)
}

fn analytics_reads_passed(envelopes: &[ResultEnvelopeV2]) -> bool {
    envelopes.len() == 3
        && envelopes
            .iter()
            .all(|envelope| envelope.ok && envelope.performed)
}

fn remove_staged_rotation_profile(
    store: &StateStore,
    secrets: &dyn SecretStore,
    staging_profile_id: &str,
    slot_id: &str,
) -> Result<()> {
    let mut profiles = ProfilesConfig::load(store)?;
    profiles.profiles.remove(staging_profile_id);
    profiles.save(store)?;
    secrets.delete_api_token_slot(slot_id)?;
    Ok(())
}

async fn revoke_rotation_child(
    store: &StateStore,
    minter_profile: &str,
    account: &str,
    token_id: &str,
    authority_id: &str,
) -> Result<ResultEnvelopeV2> {
    preflight_standing_authority(store, Some(authority_id))?;
    let plan = Box::pin(key_revoke(
        store,
        &KeyRevokeArgs {
            profile: Some(minter_profile.to_owned()),
            user: false,
            id: token_id.to_owned(),
            account: Some(account.to_owned()),
            under_policy: Some(authority_id.to_owned()),
        },
    ))
    .await?;
    Box::pin(finish_standing_run(store, plan, Some(authority_id))).await
}

fn rotation_failure(
    code: &str,
    message: impl Into<String>,
    next_step: impl Into<String>,
    evidence: Vec<EvidenceV1>,
    result: Value,
) -> ResultEnvelopeV2 {
    let mut envelope = ResultEnvelopeV2::success("keys renew-analytics-profile", result);
    envelope.ok = false;
    envelope.performed = true;
    envelope.verification.state = VerificationState::Failed;
    envelope.error = Some(ErrorV1 {
        code: code.to_owned(),
        message: message.into(),
        next_step: Some(next_step.into()),
    });
    envelope.evidence = evidence;
    envelope
}

#[expect(
    clippy::too_many_lines,
    reason = "the governed rotation keeps mint, staged reads, atomic activation, post-activation reads, rollback, and lineage-bound revocation in one fail-closed owner"
)]
async fn key_renew_analytics_profile(
    store: &StateStore,
    arguments: &KeyRenewAnalyticsProfileArgs,
) -> Result<ResultEnvelopeV2> {
    validate_zone_id(&arguments.zone)?;
    if arguments.permissions.is_empty() {
        return Err(CliError::Input(
            "analytics profile renewal requires explicit permission groups".to_owned(),
        ));
    }
    if arguments.ttl_hours == 0 || arguments.renew_before_hours >= arguments.ttl_hours {
        return Err(CliError::Input(
            "`--ttl-hours` must be positive and greater than `--renew-before-hours`".to_owned(),
        ));
    }
    if arguments.profile == arguments.minter_profile {
        return Err(CliError::Input(
            "the publisher and minter profiles must be distinct".to_owned(),
        ));
    }
    let authority = store.load_authority(&arguments.under_policy)?;
    authority.ensure_operational()?;
    if authority.account_id != arguments.account
        || authority.zone_id.as_deref() != Some(arguments.zone.as_str())
    {
        return Err(CliError::Input(
            "standing authority account or zone does not match the requested publisher rotation"
                .to_owned(),
        ));
    }
    let profiles = ProfilesConfig::load(store)?;
    let mut old_profile = profiles
        .profiles
        .get(&arguments.profile)
        .cloned()
        .ok_or_else(|| {
            CliError::Input(format!(
                "publisher profile `{}` does not exist",
                arguments.profile
            ))
        })?;
    if old_profile.kind != ProfileKind::ApiToken
        || old_profile.account_id.as_deref() != Some(arguments.account.as_str())
    {
        return Err(CliError::Input(
            "publisher profile must be an API token pinned to the requested account".to_owned(),
        ));
    }
    let minter = profiles
        .profiles
        .get(&arguments.minter_profile)
        .ok_or_else(|| {
            CliError::Input(format!(
                "minter profile `{}` does not exist",
                arguments.minter_profile
            ))
        })?;
    if minter.kind != ProfileKind::ApiToken
        || minter.account_id.as_deref() != Some(arguments.account.as_str())
    {
        return Err(CliError::Input(
            "minter profile must be an API token pinned to the requested account".to_owned(),
        ));
    }
    if let Some(pending_token_id) = old_profile.managed_api_token.as_ref().and_then(|managed| {
        (managed.pending_revoke_operation_id.is_none())
            .then(|| managed.pending_revoke_token_id.clone())
            .flatten()
    }) {
        let revoke_plan = match Box::pin(key_revoke(
            store,
            &KeyRevokeArgs {
                profile: Some(arguments.minter_profile.clone()),
                user: false,
                id: pending_token_id.clone(),
                account: Some(arguments.account.clone()),
                under_policy: None,
            },
        ))
        .await
        {
            Ok(plan) => plan,
            Err(error) => {
                let mut pending = rotation_failure(
                    "CFCTL_ANALYTICS_ROTATION_REVOKE_PLAN_FAILED",
                    format!(
                        "the active child remains healthy, but governed old-child revoke-plan creation is still failing: {error}"
                    ),
                    "Repair the explicit minter-profile planning failure; later hourly runs keep retrying only plan creation and refuse another mint.",
                    Vec::new(),
                    json!({
                        "profile":arguments.profile,
                        "state":"active_old_revoke_plan_pending",
                        "active_token_id":old_profile
                            .managed_api_token
                            .as_ref()
                            .map(|managed| managed.token_id.as_str()),
                        "old_token_id":pending_token_id,
                        "observable_failure_signal":"nonzero process exit with CFCTL_ANALYTICS_ROTATION_REVOKE_PLAN_FAILED",
                    }),
                );
                pending.profile_id = Some(arguments.profile.clone());
                pending.account_id = Some(arguments.account.clone());
                return Ok(pending);
            }
        };
        let revoke_operation_id = revoke_plan.operation_id.clone().ok_or_else(|| {
            CliError::Input("bootstrap revoke plan omitted its operation ID".to_owned())
        })?;
        let mut repaired_profile = old_profile.clone();
        let repaired_managed = repaired_profile
            .managed_api_token
            .as_mut()
            .ok_or_else(|| CliError::Input("managed profile binding disappeared".to_owned()))?;
        repaired_managed.pending_revoke_operation_id = Some(revoke_operation_id);
        let mut repaired_profiles = profiles.clone();
        repaired_profiles
            .profiles
            .insert(arguments.profile.clone(), repaired_profile.clone());
        repaired_profiles.save(store)?;
        old_profile = repaired_profile;
    }
    if let Some(managed) = old_profile.managed_api_token.as_ref()
        && let (Some(pending_token_id), Some(pending_operation_id)) = (
            managed.pending_revoke_token_id.as_deref(),
            managed.pending_revoke_operation_id.as_deref(),
        )
    {
        let pending_plan = load_validated_plan(store, pending_operation_id)?;
        let pending_matches = pending_plan.capability.id == "account-api-tokens-delete-token"
            && pending_plan.account_id == arguments.account
            && pending_plan
                .input
                .pointer("/selectors/token_id")
                .and_then(Value::as_str)
                == Some(pending_token_id);
        if !pending_matches || pending_plan.status != PlanStatus::Verified {
            let mut pending = rotation_failure(
                "CFCTL_ANALYTICS_ROTATION_OLD_REVOKE_PENDING",
                "a prior analytics rotation still has an unverified old-child revocation",
                format!(
                    "Approve and run operation `{pending_operation_id}`; the hourly renewal check stays failed until its exact not-found verification is durable."
                ),
                Vec::new(),
                json!({
                    "profile":arguments.profile,
                    "state":"active_old_revoke_pending",
                    "active_token_id":managed.token_id,
                    "old_token_id":pending_token_id,
                    "revoke_operation_id":pending_operation_id,
                    "observable_failure_signal":"nonzero process exit with CFCTL_ANALYTICS_ROTATION_OLD_REVOKE_PENDING",
                }),
            );
            pending.operation_id = Some(pending_operation_id.to_owned());
            pending.profile_id = Some(arguments.profile.clone());
            pending.account_id = Some(arguments.account.clone());
            return Ok(pending);
        }
        let retired_slot = managed.pending_revoke_slot_id.clone();
        let mut reconciled_profile = old_profile.clone();
        let reconciled_managed = reconciled_profile
            .managed_api_token
            .as_mut()
            .ok_or_else(|| CliError::Input("managed profile binding disappeared".to_owned()))?;
        reconciled_managed.pending_revoke_token_id = None;
        reconciled_managed.pending_revoke_operation_id = None;
        reconciled_managed.pending_revoke_slot_id = None;
        let mut reconciled_profiles = profiles.clone();
        reconciled_profiles
            .profiles
            .insert(arguments.profile.clone(), reconciled_profile.clone());
        reconciled_profiles.save(store)?;
        let secrets = platform_secrets(store);
        if let Some(slot_id) = retired_slot.as_deref() {
            secrets.delete_api_token_slot(slot_id)?;
        } else {
            secrets.delete_api_token(&arguments.profile)?;
        }
        old_profile = reconciled_profile;
    }
    let old_token_id = match (
        old_profile.managed_api_token.as_ref(),
        arguments.current_token_id.as_deref(),
    ) {
        (Some(managed), Some(provided)) if managed.token_id != provided => {
            return Err(CliError::Input(
                "`--current-token-id` conflicts with the profile's managed child identity"
                    .to_owned(),
            ));
        }
        (Some(managed), _) => managed.token_id.clone(),
        (None, Some(provided)) if !provided.trim().is_empty() => provided.to_owned(),
        (None, _) => {
            return Err(CliError::Input(
                "the first managed renewal requires `--current-token-id`; later runs use the profile's durable managed-child identity"
                    .to_owned(),
            ));
        }
    };
    if !arguments.force
        && let Some(managed) = old_profile.managed_api_token.as_ref()
    {
        let renew_at =
            managed.expires_at - ChronoDuration::hours(i64::from(arguments.renew_before_hours));
        if Utc::now() < renew_at {
            let active_reads = Box::pin(analytics_rotation_reads(
                store,
                &arguments.profile,
                &arguments.account,
                &arguments.zone,
                &arguments.hostname,
            ))
            .await?;
            if !analytics_reads_passed(&active_reads) {
                return Ok(rotation_failure(
                    "CFCTL_ANALYTICS_PROFILE_READ_FAILED",
                    "the active managed analytics profile failed its settings or hostname-bound RUM read",
                    "Inspect the redacted live-read receipts and restore credential-store access before the next scheduled attempt.",
                    active_reads
                        .into_iter()
                        .flat_map(|envelope| envelope.evidence)
                        .collect(),
                    json!({
                        "profile":arguments.profile,
                        "state":"active_read_failed",
                    }),
                ));
            }
            let secrets = platform_secrets(store);
            secrets.delete_api_token(&arguments.profile)?;
            let mut envelope = ResultEnvelopeV2::success(
                "keys renew-analytics-profile",
                json!({
                    "profile":arguments.profile,
                    "state":"healthy_not_due",
                    "active_token_id":managed.token_id,
                    "expires_at":managed.expires_at,
                    "renew_at":renew_at,
                    "legacy_profile_credential_cleanup":"completed_idempotently",
                    "observable_failure_signal":"nonzero process exit with ResultEnvelopeV2 error",
                    "message":"Managed analytics child is outside its renewal window and passed account settings, zone settings, and exact-hostname RUM reads."
                }),
            );
            envelope.profile_id = Some(arguments.profile.clone());
            envelope.account_id = Some(arguments.account.clone());
            envelope.evidence = active_reads
                .into_iter()
                .flat_map(|read| read.evidence)
                .collect();
            return Ok(envelope);
        }
    }

    preflight_standing_authority(store, Some(&arguments.under_policy))?;
    let rotation_id = Uuid::new_v4();
    let child_name = format!(
        "{}{}-{}",
        arguments.name_prefix,
        Utc::now().format("%Y%m%d%H%M%S"),
        &rotation_id.simple().to_string()[..8]
    );
    if !child_name.starts_with(&authority.name_prefix) {
        return Err(CliError::Input(
            "generated child name is outside the standing authority prefix".to_owned(),
        ));
    }
    let staging_root = store.paths().data_dir.join("credential-rotation-staging");
    fs::create_dir_all(&staging_root).map_err(|source| cli_io(&staging_root, source))?;
    #[cfg(unix)]
    fs::set_permissions(&staging_root, fs::Permissions::from_mode(0o700))
        .map_err(|source| cli_io(&staging_root, source))?;
    let sink_path = staging_root.join(format!("{rotation_id}.token"));
    let mint_plan = Box::pin(key_mint(
        store,
        &KeyMutationArgs {
            profile: Some(arguments.minter_profile.clone()),
            user: false,
            name: child_name,
            permissions: arguments.permissions.clone(),
            account: Some(arguments.account.clone()),
            zone: Some(arguments.zone.clone()),
            ttl_hours: Some(arguments.ttl_hours),
            value_out: Some(sink_path.clone()),
            under_policy: Some(arguments.under_policy.clone()),
        },
    ))
    .await?;
    let mint = Box::pin(finish_standing_run(
        store,
        mint_plan,
        Some(&arguments.under_policy),
    ))
    .await?;
    if !mint.ok || !mint.performed {
        return Ok(rotation_failure(
            "CFCTL_ANALYTICS_ROTATION_MINT_FAILED",
            "the standing-authority mint did not complete",
            "Inspect the mint operation receipt; do not retry if the boundary may have been crossed without lineage reconciliation.",
            mint.evidence,
            json!({"profile":arguments.profile,"state":"mint_failed"}),
        ));
    }
    let new_token_id = mint
        .result
        .pointer("/result/id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CliError::Input(
                "successful child mint omitted its non-secret token identity; do not replay"
                    .to_owned(),
            )
        })?
        .to_owned();
    let token = read_private_secret_file(&sink_path, "internal rotation sink")?;
    fs::remove_file(&sink_path).map_err(|source| cli_io(&sink_path, source))?;
    let expires_at = mint
        .result
        .pointer("/result/expires_on")
        .and_then(Value::as_str)
        .and_then(|raw| DateTime::parse_from_rfc3339(raw).ok())
        .map_or_else(
            || Utc::now() + ChronoDuration::hours(i64::from(arguments.ttl_hours)),
            |value| value.with_timezone(&Utc),
        );

    let secrets = platform_secrets(store);
    let slot_id = Uuid::new_v4().to_string();
    secrets.store_api_token_slot(&slot_id, token.trim())?;
    let staging_profile_id = format!("__cfctl_rotation_{rotation_id}");
    let mut staging_profile = ProfileMetadata::new(
        &staging_profile_id,
        ProfileKind::ApiToken,
        Some(&arguments.account),
    );
    staging_profile.api_token_slot_id = Some(slot_id.clone());
    let mut staged_profiles = ProfilesConfig::load(store)?;
    staged_profiles
        .profiles
        .insert(staging_profile_id.clone(), staging_profile.clone());
    if let Err(error) = staged_profiles.save(store) {
        let _ = secrets.delete_api_token_slot(&slot_id);
        return Err(error);
    }

    let staged_reads = Box::pin(analytics_rotation_reads(
        store,
        &staging_profile_id,
        &arguments.account,
        &arguments.zone,
        &arguments.hostname,
    ))
    .await?;
    if !analytics_reads_passed(&staged_reads) {
        let mut evidence = mint.evidence;
        evidence.extend(
            staged_reads
                .into_iter()
                .flat_map(|envelope| envelope.evidence),
        );
        let cleanup = Box::pin(revoke_rotation_child(
            store,
            &arguments.minter_profile,
            &arguments.account,
            &new_token_id,
            &arguments.under_policy,
        ))
        .await?;
        evidence.extend(cleanup.evidence);
        remove_staged_rotation_profile(store, &secrets, &staging_profile_id, &slot_id)?;
        return Ok(rotation_failure(
            "CFCTL_ANALYTICS_ROTATION_STAGED_READ_FAILED",
            "the fresh child failed its staged settings or hostname-bound RUM read",
            "The prior publisher profile remains active. Inspect the redacted live-read and cleanup receipts before the next scheduled attempt.",
            evidence,
            json!({
                "profile":arguments.profile,
                "state":"staged_read_failed",
                "new_child_revoked":cleanup.ok,
            }),
        ));
    }

    let mut activation_profiles = ProfilesConfig::load(store)?;
    let current = activation_profiles
        .profiles
        .get(&arguments.profile)
        .ok_or_else(|| {
            CliError::Input("publisher profile disappeared during rotation".to_owned())
        })?;
    if current.credential_generation_id != old_profile.credential_generation_id
        || current.api_token_slot_id != old_profile.api_token_slot_id
    {
        let _ = revoke_rotation_child(
            store,
            &arguments.minter_profile,
            &arguments.account,
            &new_token_id,
            &arguments.under_policy,
        )
        .await;
        remove_staged_rotation_profile(store, &secrets, &staging_profile_id, &slot_id)?;
        return Err(CliError::Input(
            "publisher credential generation changed during rotation; the fresh child was not activated"
                .to_owned(),
        ));
    }
    let mut activated_profile = old_profile.clone();
    activated_profile.credential_generation_id = staging_profile.credential_generation_id.clone();
    activated_profile.api_token_slot_id = Some(slot_id.clone());
    activated_profile.managed_api_token = Some(ManagedApiTokenV1 {
        schema_version: 1,
        token_id: new_token_id.clone(),
        expires_at,
        standing_authority_id: arguments.under_policy.clone(),
        pending_revoke_token_id: None,
        pending_revoke_operation_id: None,
        pending_revoke_slot_id: None,
    });
    activation_profiles.profiles.remove(&staging_profile_id);
    activation_profiles
        .profiles
        .insert(arguments.profile.clone(), activated_profile.clone());
    activation_profiles.save(store)?;
    let activation_evidence = store.write_evidence(
        EvidenceClass::PostChangeVerification,
        &json!({
            "profile":arguments.profile,
            "account_id":arguments.account,
            "zone_id":arguments.zone,
            "old_credential_generation_id":old_profile.credential_generation_id,
            "new_credential_generation_id":activated_profile.credential_generation_id,
            "new_token_id":new_token_id,
            "expires_at":expires_at,
            "activation":"atomic_profile_metadata_switch",
            "secret_material_recorded":false,
        }),
    )?;

    let active_reads = Box::pin(analytics_rotation_reads(
        store,
        &arguments.profile,
        &arguments.account,
        &arguments.zone,
        &arguments.hostname,
    ))
    .await?;
    if !analytics_reads_passed(&active_reads) {
        let mut rollback_profiles = ProfilesConfig::load(store)?;
        rollback_profiles
            .profiles
            .insert(arguments.profile.clone(), old_profile.clone());
        rollback_profiles.save(store)?;
        let cleanup = Box::pin(revoke_rotation_child(
            store,
            &arguments.minter_profile,
            &arguments.account,
            &new_token_id,
            &arguments.under_policy,
        ))
        .await?;
        secrets.delete_api_token_slot(&slot_id)?;
        let mut evidence = mint.evidence;
        evidence.push(activation_evidence);
        evidence.extend(
            active_reads
                .into_iter()
                .flat_map(|envelope| envelope.evidence),
        );
        evidence.extend(cleanup.evidence);
        return Ok(rotation_failure(
            "CFCTL_ANALYTICS_ROTATION_ACTIVE_READ_FAILED",
            "the atomically activated profile failed its live read and was rolled back",
            "The prior profile generation is active again. Inspect the redacted read, rollback, and fresh-child revocation receipts.",
            evidence,
            json!({
                "profile":arguments.profile,
                "state":"rolled_back",
                "new_child_revoked":cleanup.ok,
            }),
        ));
    }

    let refreshed_authority = store.load_authority(&arguments.under_policy)?;
    let old_is_lineage_bound = refreshed_authority
        .minted_token_ids
        .iter()
        .any(|token_id| token_id == &old_token_id);
    let mut evidence = mint.evidence;
    evidence.push(activation_evidence);
    evidence.extend(
        staged_reads
            .into_iter()
            .chain(active_reads)
            .flat_map(|envelope| envelope.evidence),
    );
    if !old_is_lineage_bound {
        let revoke_plan = match Box::pin(key_revoke(
            store,
            &KeyRevokeArgs {
                profile: Some(arguments.minter_profile.clone()),
                user: false,
                id: old_token_id.clone(),
                account: Some(arguments.account.clone()),
                under_policy: None,
            },
        ))
        .await
        {
            Ok(plan) => plan,
            Err(error) => {
                let mut pending_profiles = ProfilesConfig::load(store)?;
                let pending_profile = pending_profiles
                    .profiles
                    .get_mut(&arguments.profile)
                    .ok_or_else(|| {
                        CliError::Input("activated publisher profile disappeared".to_owned())
                    })?;
                let managed = pending_profile.managed_api_token.as_mut().ok_or_else(|| {
                    CliError::Input(
                        "activated publisher profile lost its managed binding".to_owned(),
                    )
                })?;
                managed.pending_revoke_token_id = Some(old_token_id.clone());
                managed.pending_revoke_operation_id = None;
                managed
                    .pending_revoke_slot_id
                    .clone_from(&old_profile.api_token_slot_id);
                pending_profiles.save(store)?;
                return Ok(rotation_failure(
                    "CFCTL_ANALYTICS_ROTATION_REVOKE_PLAN_FAILED",
                    format!(
                        "the fresh child is active and verified, but the old-child revoke plan could not be prepared: {error}"
                    ),
                    "The overlap is durably pending. A later hourly run retries only governed revoke-plan creation before permitting another mint.",
                    evidence,
                    json!({
                        "profile":arguments.profile,
                        "state":"active_old_revoke_plan_pending",
                        "active_token_id":new_token_id,
                        "old_token_id":old_token_id,
                        "observable_failure_signal":"nonzero process exit with CFCTL_ANALYTICS_ROTATION_REVOKE_PLAN_FAILED",
                    }),
                ));
            }
        };
        evidence.extend(revoke_plan.evidence.clone());
        let revoke_operation_id = revoke_plan.operation_id.clone().ok_or_else(|| {
            CliError::Input("bootstrap revoke plan omitted its operation ID".to_owned())
        })?;
        let mut pending_profiles = ProfilesConfig::load(store)?;
        let pending_profile = pending_profiles
            .profiles
            .get_mut(&arguments.profile)
            .ok_or_else(|| CliError::Input("activated publisher profile disappeared".to_owned()))?;
        let managed = pending_profile.managed_api_token.as_mut().ok_or_else(|| {
            CliError::Input("activated publisher profile lost its managed binding".to_owned())
        })?;
        managed.pending_revoke_token_id = Some(old_token_id.clone());
        managed.pending_revoke_operation_id = Some(revoke_operation_id.clone());
        managed
            .pending_revoke_slot_id
            .clone_from(&old_profile.api_token_slot_id);
        pending_profiles.save(store)?;
        let mut pending = rotation_failure(
            "CFCTL_ANALYTICS_ROTATION_BOOTSTRAP_REVOKE_APPROVAL_REQUIRED",
            "the fresh child is active and verified, but the pre-existing child is outside standing-authority lineage",
            format!(
                "Approve and run operation `{}` once. Future renewals revoke their lineage-bound prior child automatically.",
                revoke_plan.operation_id.as_deref().unwrap_or("missing")
            ),
            evidence,
            json!({
                "profile":arguments.profile,
                "state":"active_old_revoke_pending",
                "active_token_id":new_token_id,
                "expires_at":expires_at,
                "old_token_id":old_token_id,
                "revoke_operation_id":revoke_operation_id.clone(),
                "observable_failure_signal":"nonzero process exit with CFCTL_ANALYTICS_ROTATION_BOOTSTRAP_REVOKE_APPROVAL_REQUIRED",
            }),
        );
        pending.operation_id = Some(revoke_operation_id);
        pending.profile_id = Some(arguments.profile.clone());
        pending.account_id = Some(arguments.account.clone());
        return Ok(pending);
    }

    let revoke = Box::pin(revoke_rotation_child(
        store,
        &arguments.minter_profile,
        &arguments.account,
        &old_token_id,
        &arguments.under_policy,
    ))
    .await?;
    evidence.extend(revoke.evidence);
    if !revoke.ok || revoke.verification.state != VerificationState::Passed {
        let revoke_operation_id = revoke.operation_id.clone().ok_or_else(|| {
            CliError::Input(
                "failed old-child revocation omitted its operation ID; the active profile remains cut over but requires manual overlap reconciliation"
                    .to_owned(),
            )
        })?;
        let mut pending_profiles = ProfilesConfig::load(store)?;
        let pending_profile = pending_profiles
            .profiles
            .get_mut(&arguments.profile)
            .ok_or_else(|| CliError::Input("activated publisher profile disappeared".to_owned()))?;
        let managed = pending_profile.managed_api_token.as_mut().ok_or_else(|| {
            CliError::Input("activated publisher profile lost its managed binding".to_owned())
        })?;
        managed.pending_revoke_token_id = Some(old_token_id.clone());
        managed.pending_revoke_operation_id = Some(revoke_operation_id.clone());
        managed
            .pending_revoke_slot_id
            .clone_from(&old_profile.api_token_slot_id);
        pending_profiles.save(store)?;
        return Ok(rotation_failure(
            "CFCTL_ANALYTICS_ROTATION_OLD_REVOKE_FAILED",
            "the fresh child is active and verified, but old-child revocation was not proven",
            format!(
                "Reconcile operation `{revoke_operation_id}` to Verified. Every later hourly check stays failed and refuses another mint until this overlap is closed."
            ),
            evidence,
            json!({
                "profile":arguments.profile,
                "state":"active_old_revoke_failed",
                "active_token_id":new_token_id,
                "old_token_id":old_token_id,
                "revoke_operation_id":revoke_operation_id,
                "observable_failure_signal":"nonzero process exit with CFCTL_ANALYTICS_ROTATION_OLD_REVOKE_PENDING",
            }),
        ));
    }
    if let Some(old_slot_id) = old_profile.api_token_slot_id.as_deref() {
        secrets.delete_api_token_slot(old_slot_id)?;
    } else {
        secrets.delete_api_token(&arguments.profile)?;
    }
    let mut envelope = ResultEnvelopeV2::success(
        "keys renew-analytics-profile",
        json!({
            "profile":arguments.profile,
            "state":"rotated",
            "active_token_id":new_token_id,
            "revoked_token_id":old_token_id,
            "expires_at":expires_at,
            "renew_at":expires_at - ChronoDuration::hours(i64::from(arguments.renew_before_hours)),
            "verification_capabilities":[
                "graphql-analytics-account-rum-dataset-settings",
                "graphql-analytics-zone-dataset-settings",
                "graphql-analytics-account-rum-pageload-visits",
            ],
            "observable_failure_signal":"nonzero process exit with ResultEnvelopeV2 error",
            "message":"Fresh analytics child was staged, verified, atomically activated, re-verified through the publisher profile, and the lineage-bound prior child was revoked."
        }),
    );
    envelope.performed = true;
    envelope.profile_id = Some(arguments.profile.clone());
    envelope.account_id = Some(arguments.account.clone());
    envelope.verification.state = VerificationState::Passed;
    envelope.verification.basis = Some(
        "staged and active account RUM settings, zone settings, and exact-host RUM reads passed before lineage-bound old-child revocation"
            .to_owned(),
    );
    envelope.evidence = evidence;
    Ok(envelope)
}

async fn key_revoke(store: &StateStore, arguments: &KeyRevokeArgs) -> Result<ResultEnvelopeV2> {
    let account = arguments.account.as_deref().ok_or_else(|| {
        CliError::Input("token revocation requires `--account` for explicit ownership".to_owned())
    })?;
    let catalog = ensure_catalog(store).await?;
    let capability_id = if arguments.user {
        "user-api-tokens-delete-token"
    } else {
        "account-api-tokens-delete-token"
    };
    let capability = catalog
        .get(capability_id)
        .cloned()
        .ok_or_else(|| capability_missing(capability_id))?;
    Box::pin(create_plan(
        store,
        &catalog,
        capability,
        CallInput {
            selectors: if arguments.user {
                json!({"token_id": arguments.id})
            } else {
                json!({"account_id": account, "token_id": arguments.id})
            },
            query: json!({}),
            body: None,
            ..CallInput::default()
        },
        arguments.profile.as_deref(),
        Some(account),
        Value::Null,
    ))
    .await
}

#[derive(Debug, Deserialize)]
struct AdmissionPolicyStageInput {
    name: String,
    rules: Vec<AdmissionPolicyRuleV1>,
}

fn policy_command(store: &StateStore, command: PolicyCommand) -> Result<ResultEnvelopeV2> {
    match command {
        PolicyCommand::Admission(command) => admission_policy_command(store, command.command),
        PolicyCommand::Cloudflare(command) => cloudflare_policy_command(store, command.command),
    }
}

fn admission_policy_command(
    store: &StateStore,
    command: AdmissionPolicyCommand,
) -> Result<ResultEnvelopeV2> {
    match command {
        AdmissionPolicyCommand::Stage(arguments) => {
            let value: Value = serde_json::from_slice(
                &fs::read(&arguments.file).map_err(|source| cli_io(&arguments.file, source))?,
            )?;
            let bundle = if value.get("schema_version").is_some() {
                serde_json::from_value::<AdmissionPolicyBundleV1>(value)?
            } else {
                let input: AdmissionPolicyStageInput = serde_json::from_value(value)?;
                AdmissionPolicyBundleV1::pending(input.name, input.rules)?
            };
            if bundle.status != AdmissionPolicyBundleStatusV1::Pending {
                return Err(CliError::Input(
                    "only a pending admission bundle may be staged".to_owned(),
                ));
            }
            bundle.validate()?;
            store.create_admission_bundle(&bundle)?;
            Ok(ResultEnvelopeV2::success(
                "policy admission stage",
                json!({
                    "bundle": bundle,
                    "approval_command": format!("cfctl policy admission approve {} --yes", bundle.bundle_id),
                    "message": "Admission bundle staged. It has no effect until separately approved and atomically activated."
                }),
            ))
        }
        AdmissionPolicyCommand::List => Ok(ResultEnvelopeV2::success(
            "policy admission list",
            json!({
                "bundles": store.list_admission_bundles()?,
                "active_bundle_id": store.active_admission_bundle_id()?,
            }),
        )),
        AdmissionPolicyCommand::Show(arguments) => {
            let bundle = store.load_admission_bundle(&arguments.bundle_id)?;
            Ok(ResultEnvelopeV2::success(
                "policy admission show",
                serde_json::to_value(bundle)?,
            ))
        }
        AdmissionPolicyCommand::Diff(arguments) => {
            let candidate = store.load_admission_bundle(&arguments.bundle_id)?;
            let active = active_admission_policy(store)?;
            Ok(ResultEnvelopeV2::success(
                "policy admission diff",
                json!({
                    "candidate": candidate,
                    "active": active,
                    "rules_changed": active.as_ref().is_none_or(|active| active.rules != candidate.rules),
                    "safety_floor": "Compiled ambiguity, incomplete-contract, cost, secret, stale-observation, and drift blockers remain non-overridable."
                }),
            ))
        }
        AdmissionPolicyCommand::Approve(arguments) => {
            let bundle = store.approve_admission_bundle(&arguments.bundle_id, arguments.yes)?;
            Ok(ResultEnvelopeV2::success(
                "policy admission approve",
                json!({
                    "bundle_id": bundle.bundle_id,
                    "content_hash": bundle.content_hash,
                    "status": bundle.status,
                    "activate_command": format!("cfctl policy admission activate {}", bundle.bundle_id),
                    "message": "The exact bundle is approved but is not active."
                }),
            ))
        }
        AdmissionPolicyCommand::Activate(arguments) => {
            activate_admission_bundle(store, &arguments.bundle_id, false)
        }
        AdmissionPolicyCommand::Rollback(arguments) => {
            activate_admission_bundle(store, &arguments.bundle_id, true)
        }
    }
}

fn cloudflare_policy_command(
    store: &StateStore,
    command: CloudflarePolicyCommand,
) -> Result<ResultEnvelopeV2> {
    let registry = Registry::open(&store.paths().data_dir)?;
    match command {
        CloudflarePolicyCommand::List => {
            let policies = registry
                .list_resources(None)?
                .into_iter()
                .filter(|resource| is_policy_resource_kind(&resource.kind))
                .collect::<Vec<_>>();
            Ok(ResultEnvelopeV2::success(
                "policy cloudflare list",
                json!({"resources": policies, "coverage": registry.coverage()?}),
            ))
        }
        CloudflarePolicyCommand::Get(arguments) => {
            let resource = registry.get_resource(&arguments.resource)?;
            Ok(ResultEnvelopeV2::success(
                "policy cloudflare get",
                json!({
                    "resource": resource,
                    "observations": registry.observation_history(&arguments.resource)?,
                    "found": resource.is_some(),
                }),
            ))
        }
        CloudflarePolicyCommand::Diff(arguments) => registry_diff_envelope(
            &registry,
            "policy cloudflare diff",
            arguments.resource.as_deref(),
            false,
        ),
        CloudflarePolicyCommand::Plan(arguments) => registry_diff_envelope(
            &registry,
            "policy cloudflare plan",
            arguments.resource.as_deref(),
            true,
        ),
    }
}

fn is_policy_resource_kind(kind: &str) -> bool {
    let kind = kind.to_ascii_lowercase();
    [
        "access",
        "gateway",
        "notification",
        "policy",
        "ruleset",
        "waf",
    ]
    .iter()
    .any(|term| kind.contains(term))
}

fn active_admission_policy(store: &StateStore) -> Result<Option<AdmissionPolicyBundleV1>> {
    store.active_admission_policy().map_err(CliError::from)
}

fn activate_admission_bundle(
    store: &StateStore,
    bundle_id: &str,
    rollback: bool,
) -> Result<ResultEnvelopeV2> {
    let activation = store.activate_admission_bundle(bundle_id)?;
    let target = activation.bundle;
    let previous_id = activation.previous_bundle_id;
    Ok(ResultEnvelopeV2::success(
        if rollback {
            "policy admission rollback"
        } else {
            "policy admission activate"
        },
        json!({
            "bundle": target,
            "previous_bundle_id": previous_id,
            "message": if rollback {
                "Previously approved bundle atomically selected as active; compiled safety floor remains authoritative."
            } else {
                "Approved bundle atomically selected as active; compiled safety floor remains authoritative."
            }
        }),
    ))
}

const EVENT_SCHEMA_REFERENCE: &str =
    "https://developers.cloudflare.com/queues/event-subscriptions/events-schemas/";
const QUEUE_PULL_REFERENCE: &str =
    "https://developers.cloudflare.com/queues/configuration/pull-consumers/";
const REALTIMEKIT_WEBHOOK_REFERENCE: &str =
    "https://developers.cloudflare.com/realtime/realtimekit/webhooks/";
const EVENT_BRIDGE_WORKER_SOURCE: &str = include_str!("../../../bridge/event-ingress/src/index.ts");
const EVENT_BRIDGE_WRANGLER_SOURCE: &str =
    include_str!("../../../bridge/event-ingress/wrangler.jsonc");

fn events_command(store: &StateStore, command: EventsCommand) -> Result<ResultEnvelopeV2> {
    let mut registry = Registry::open(&store.paths().data_dir)?;
    match command {
        EventsCommand::Sources => Ok(ResultEnvelopeV2::success(
            "events sources",
            json!({
                "schema_version": 1,
                "verified_at": "2026-07-22",
                "documentation_last_updated": "2026-07-15",
                "documentation": EVENT_SCHEMA_REFERENCE,
                "sources": [
                    {"family":"Access","source_ids":["access"]},
                    {"family":"Artifacts","source_ids":["artifacts","artifacts.repo"]},
                    {"family":"Email Sending","source_ids":["email.sending"]},
                    {"family":"R2","source_ids":["r2"]},
                    {"family":"Super Slurper","source_ids":["superSlurper","superSlurper.job"]},
                    {"family":"Vectorize","source_ids":["vectorize"]},
                    {"family":"Workers AI","source_ids":["workersAi.model"]},
                    {"family":"Workers Builds","source_ids":["workersBuilds.worker"]},
                    {"family":"Workers KV","source_ids":["kv"]},
                    {"family":"Workflows","source_ids":["workflows.workflow"]}
                ],
                "truth_boundary": "This is a versioned local documentation snapshot. Use catalog/docs drift checks before changing Event Subscription request schemas."
            }),
        )),
        EventsCommand::Status => Ok(ResultEnvelopeV2::success(
            "events status",
            json!({
                "ledger": registry.event_status()?,
                "reconciliation_jobs": registry.reconciliation_jobs()?,
                "queue_pull_contract": QUEUE_PULL_REFERENCE,
                "truth_boundary": "Events and queued reconciliation jobs are durable local evidence. They are not observed Cloudflare resource state."
            }),
        )),
        EventsCommand::History(EventHistoryArgs { limit }) => Ok(ResultEnvelopeV2::success(
            "events history",
            json!({"events": registry.event_history(limit)?, "limit": limit}),
        )),
        EventsCommand::Reconcile(EventReconcileArgs { resource }) => {
            let resource_ref = registry.get_resource(&resource)?.ok_or_else(|| {
                CliError::Input(format!(
                    "registry resource `{resource}` was not found; run `cfctl registry sync` and inspect `cfctl registry list --json`"
                ))
            })?;
            let job = registry.enqueue_reconciliation(resource_ref)?;
            Ok(ResultEnvelopeV2::success(
                "events reconcile",
                json!({
                    "job": job,
                    "live_read_executed": false,
                    "next_action": "Resolve the resource kind to its registered inventory provider and execute the bounded live read; only a successful evidence-backed read may record an observation."
                }),
            ))
        }
        EventsCommand::Bridge(arguments) => event_bridge_command(store, arguments.command),
    }
}

fn event_bridge_command(
    store: &StateStore,
    command: EventBridgeCommand,
) -> Result<ResultEnvelopeV2> {
    let manifest_path = store
        .paths()
        .config_dir
        .join("events/bridge/event-ingress.json");
    let template = json!({
        "schema_version": 1,
        "worker_name": "cfctl-event-ingress",
        "worker_source_hash": hash_value(&json!(EVENT_BRIDGE_WORKER_SOURCE))?,
        "wrangler_source_hash": hash_value(&json!(EVENT_BRIDGE_WRANGLER_SOURCE))?,
        "queue_binding": "EVENT_QUEUE",
        "realtimekit": {
            "signature_header": "rtk-signature",
            "delivery_id_header": "rtk-uuid",
            "webhook_id_header": "rtk-webhook-id",
            "algorithm": "RSA-SHA256",
            "public_key_url": "https://api.realtime.cloudflare.com/.well-known/webhooks.json",
            "documentation": REALTIMEKIT_WEBHOOK_REFERENCE
        },
        "deployment_state": "not_applied"
    });
    match command {
        EventBridgeCommand::Inspect => Ok(ResultEnvelopeV2::success(
            "events bridge inspect",
            json!({"template": template, "manifest_path": manifest_path}),
        )),
        EventBridgeCommand::Prepare => {
            let parent = manifest_path.parent().ok_or_else(|| {
                CliError::Input("event bridge manifest has no parent directory".to_owned())
            })?;
            fs::create_dir_all(parent).map_err(|source| cli_io(parent, source))?;
            store.write_json(&manifest_path, &template)?;
            Ok(ResultEnvelopeV2::success(
                "events bridge prepare",
                json!({
                    "manifest_path": manifest_path,
                    "manifest": template,
                    "cloudflare_applied": false,
                    "next_action": "Resolve and plan the exact Worker, Queue, and Event Subscription capabilities separately. This command stages local configuration only and grants no Cloudflare mutation authority."
                }),
            ))
        }
        EventBridgeCommand::Status => {
            let manifest: Option<Value> = manifest_path
                .is_file()
                .then(|| store.read_json(&manifest_path))
                .transpose()?;
            Ok(ResultEnvelopeV2::success(
                "events bridge status",
                json!({
                    "prepared": manifest.is_some(),
                    "manifest_path": manifest_path,
                    "manifest": manifest,
                    "cloudflare_apply_proven": false
                }),
            ))
        }
    }
}

#[expect(
    clippy::too_many_lines,
    reason = "the public registry subcommand dispatcher keeps every read-only projection and local declaration action explicit"
)]
fn registry_command(store: &StateStore, command: RegistryCommand) -> Result<ResultEnvelopeV2> {
    let mut registry = Registry::open(&store.paths().data_dir)?;
    match command {
        RegistryCommand::Scopes(arguments) => match arguments.command {
            RegistryScopesCommand::List => Ok(ResultEnvelopeV2::success(
                "registry scopes list",
                json!({"scopes": registry.list_scopes()?}),
            )),
            RegistryScopesCommand::Discover => {
                let profiles = ProfilesConfig::load(store)?;
                let scopes = profiles
                    .profiles
                    .values()
                    .filter_map(|profile| profile.account_id.as_deref())
                    .map(|account| ScopeRefV1::new(ScopeKindV1::Account, account, None))
                    .collect::<BTreeSet<_>>();
                Ok(ResultEnvelopeV2::success(
                    "registry scopes discover",
                    json!({
                        "scopes": scopes,
                        "source": "configured credential profile metadata",
                        "adopted": false,
                        "next_action": "Review each scope, then use `cfctl registry scopes adopt --kind account --id <account-id>` or run `cfctl registry sync` to adopt configured account scopes."
                    }),
                ))
            }
            RegistryScopesCommand::Adopt(arguments) => {
                let scope = registry_scope(&arguments);
                registry.adopt_scope(&scope)?;
                Ok(ResultEnvelopeV2::success(
                    "registry scopes adopt",
                    json!({"scope": scope, "message": "Scope adopted for local registry synchronization; no Cloudflare boundary was crossed."}),
                ))
            }
            RegistryScopesCommand::Remove(arguments) => {
                let scope = registry_scope(&arguments);
                let removed = registry.remove_scope(&scope)?;
                Ok(ResultEnvelopeV2::success(
                    "registry scopes remove",
                    json!({"scope": scope, "removed": removed, "message": "Scope retired from future registry synchronization; immutable evidence remains authoritative."}),
                ))
            }
        },
        RegistryCommand::Sync => registry_sync(store, &mut registry),
        RegistryCommand::Status => Ok(ResultEnvelopeV2::success(
            "registry status",
            serde_json::to_value(registry.status()?)?,
        )),
        RegistryCommand::Coverage => Ok(ResultEnvelopeV2::success(
            "registry coverage",
            serde_json::to_value(registry.coverage()?)?,
        )),
        RegistryCommand::List(arguments) => Ok(ResultEnvelopeV2::success(
            "registry list",
            json!({"resources": registry.list_resources(arguments.kind.as_deref())?}),
        )),
        RegistryCommand::Get(arguments) => {
            let resource = registry.get_resource(&arguments.resource)?;
            let desired = registry
                .list_desired_resources()?
                .into_iter()
                .find(|candidate| candidate.resource.key() == arguments.resource);
            let ownership = registry
                .list_ownership()?
                .into_iter()
                .find(|candidate| candidate.resource.key() == arguments.resource);
            let observation = registry
                .observation_history(&arguments.resource)?
                .into_iter()
                .next();
            Ok(ResultEnvelopeV2::success(
                "registry get",
                json!({
                    "resource": resource,
                    "latest_observation": observation,
                    "desired": desired,
                    "ownership": ownership,
                    "found": resource.is_some(),
                }),
            ))
        }
        RegistryCommand::Graph => Ok(ResultEnvelopeV2::success(
            "registry graph",
            json!({
                "scopes": registry.list_scopes()?,
                "resources": registry.list_resources(None)?,
                "ownership": registry.list_ownership()?,
                "truth_boundary": "Scope and relationship rows are a rebuildable projection; desired declarations, live-read evidence, and Cloudflare state retain separate authority."
            }),
        )),
        RegistryCommand::Diff(arguments) => registry_diff_envelope(
            &registry,
            "registry diff",
            arguments.resource.as_deref(),
            false,
        ),
        RegistryCommand::History(arguments) => Ok(ResultEnvelopeV2::success(
            "registry history",
            json!({
                "resource": arguments.resource,
                "observations": registry.observation_history(&arguments.resource)?,
            }),
        )),
        RegistryCommand::Export => Ok(ResultEnvelopeV2::success(
            "registry export",
            serde_json::to_value(registry.export()?)?,
        )),
        RegistryCommand::Rebuild => {
            let backup = registry.rebuild_projection()?;
            let sync = registry_sync_result(store, &mut registry)?;
            Ok(ResultEnvelopeV2::success(
                "registry rebuild",
                json!({
                    "backup": backup,
                    "sync": sync,
                    "message": "The rebuildable projection was backed up, cleared, reconstructed from configured sources, and integrity-checked."
                }),
            ))
        }
        RegistryCommand::Declarations(arguments) => match arguments.command {
            RegistryDeclarationsCommand::Validate => {
                let declarations = load_registry_declarations(store)?;
                Ok(ResultEnvelopeV2::success(
                    "registry declarations validate",
                    json!({
                        "valid": true,
                        "declaration_count": declarations.len(),
                        "declarations": declarations,
                    }),
                ))
            }
            RegistryDeclarationsCommand::Diff(arguments) => registry_diff_envelope(
                &registry,
                "registry declarations diff",
                arguments.resource.as_deref(),
                false,
            ),
            RegistryDeclarationsCommand::Plan(arguments) => registry_diff_envelope(
                &registry,
                "registry declarations plan",
                arguments.resource.as_deref(),
                true,
            ),
        },
        RegistryCommand::Ownership(arguments) => match arguments.command {
            RegistryOwnershipCommand::List => Ok(ResultEnvelopeV2::success(
                "registry ownership list",
                json!({"ownership": registry.list_ownership()?}),
            )),
            RegistryOwnershipCommand::Get(arguments) => {
                let ownership = registry
                    .list_ownership()?
                    .into_iter()
                    .find(|candidate| candidate.resource.key() == arguments.resource);
                Ok(ResultEnvelopeV2::success(
                    "registry ownership get",
                    json!({"resource": arguments.resource, "ownership": ownership, "found": ownership.is_some()}),
                ))
            }
            RegistryOwnershipCommand::Check => {
                let desired = registry.list_desired_resources()?;
                let ownership = registry.list_ownership()?;
                let missing = desired
                    .iter()
                    .filter(|item| {
                        !ownership
                            .iter()
                            .any(|owner| owner.resource.key() == item.resource.key())
                    })
                    .map(|item| item.resource.key())
                    .collect::<Vec<_>>();
                Ok(ResultEnvelopeV2::success(
                    "registry ownership check",
                    json!({
                        "valid": missing.is_empty(),
                        "missing_ownership": missing,
                        "duplicate_owners": [],
                        "note": "The SQLite uniqueness constraint rejects duplicate resource owners at import time."
                    }),
                ))
            }
        },
    }
}

fn registry_scope(arguments: &RegistryScopeArgs) -> ScopeRefV1 {
    let parent = arguments
        .parent_kind
        .zip(arguments.parent_id.as_deref())
        .map(|(kind, id)| ScopeRefV1::new(registry_scope_kind(kind), id, None));
    ScopeRefV1::new(
        registry_scope_kind(arguments.kind),
        arguments.id.clone(),
        parent,
    )
}

const fn registry_scope_kind(kind: RegistryScopeKindArg) -> ScopeKindV1 {
    match kind {
        RegistryScopeKindArg::Organization => ScopeKindV1::Organization,
        RegistryScopeKindArg::Account => ScopeKindV1::Account,
        RegistryScopeKindArg::Zone => ScopeKindV1::Zone,
        RegistryScopeKindArg::Resource => ScopeKindV1::Resource,
    }
}

fn registry_sync(store: &StateStore, registry: &mut Registry) -> Result<ResultEnvelopeV2> {
    Ok(ResultEnvelopeV2::success(
        "registry sync",
        registry_sync_result(store, registry)?,
    ))
}

#[expect(
    clippy::too_many_lines,
    reason = "registry rebuild, provider coverage, source-config separation, and historical evidence indexing form one deterministic sync projection"
)]
fn registry_sync_result(store: &StateStore, registry: &mut Registry) -> Result<Value> {
    let profiles = ProfilesConfig::load(store)?;
    let mut adopted_accounts = BTreeSet::new();
    for account in profiles
        .profiles
        .values()
        .filter_map(|profile| profile.account_id.as_deref())
    {
        registry.adopt_scope(&ScopeRefV1::new(ScopeKindV1::Account, account, None))?;
        adopted_accounts.insert(account.to_owned());
    }

    let mut operation_count = 0_usize;
    let mut catalog_hash = None;
    if store.paths().catalog_file().is_file() {
        let catalog = CatalogSnapshot::load(&store.paths().catalog_file())?;
        catalog_hash = Some(catalog.schema_hash.clone());
        for capability in catalog.capabilities.values() {
            let gaps = capability.mutation_contract_gaps();
            let blocker = capability
                .blocked_reason
                .clone()
                .or_else(|| (!gaps.is_empty()).then(|| gaps.join("; ")));
            registry.upsert_operation(&OperationIndexRecordV1 {
                schema_version: 1,
                capability_id: capability.id.clone(),
                product: capability.product.clone(),
                method: capability.method.clone(),
                path: capability.path.clone(),
                adapter_status: adapter_status_label(capability.adapter_status).to_owned(),
                maturity: operation_maturity(capability, &gaps).to_owned(),
                blocker,
                catalog_hash: catalog.schema_hash.clone(),
            })?;
            operation_count += 1;
        }
    }

    let declarations = load_registry_declarations(store)?;
    for desired in &declarations {
        registry.upsert_desired_resource(desired)?;
        let repository = Path::new(&desired.source_path)
            .parent()
            .unwrap_or_else(|| Path::new(&desired.source_path))
            .display()
            .to_string();
        registry.upsert_ownership(&OwnershipRecordV1 {
            schema_version: 1,
            resource: desired.resource.clone(),
            owner: desired.owner.clone(),
            repository,
            deploy_lane: desired.deploy_lane.clone(),
            verifier: desired.verifier.clone(),
            allowed_change_path: desired.allowed_change_path.clone(),
        })?;
    }

    let account_pins = store.workspace_manifest()?.account_pins();
    let graph = discover_registered(store)?;
    let mut source_resources = 0_usize;
    let mut unscoped_source_resources = Vec::new();
    let mut source_kinds = BTreeSet::new();
    for resource in &graph.resources {
        let accounts = graph
            .links
            .get(&resource.key)
            .into_iter()
            .flatten()
            .filter_map(|repository| {
                let repository = Path::new(repository);
                account_pins
                    .iter()
                    .filter(|(root, _)| repository.starts_with(root))
                    .max_by_key(|(root, _)| root.components().count())
                    .map(|(_, account)| account.clone())
            })
            .collect::<BTreeSet<_>>();
        if accounts.len() != 1 {
            unscoped_source_resources.push(resource.key.clone());
            continue;
        }
        let account = accounts.into_iter().next().ok_or_else(|| {
            CliError::Input("account scope selection unexpectedly became empty".to_owned())
        })?;
        let id = resource
            .key
            .split_once(':')
            .map_or_else(|| resource.key.clone(), |(_, id)| id.to_owned());
        registry.upsert_resource(
            &ResourceRefV1::new(
                ScopeRefV1::new(ScopeKindV1::Account, account, None),
                resource.kind.clone(),
                id,
            ),
            "source_config",
        )?;
        source_kinds.insert(resource.kind.clone());
        source_resources += 1;
    }
    for kind in source_kinds {
        registry.upsert_provider(&InventoryProviderV1 {
            schema_version: 1,
            resource_kind: kind.clone(),
            scope_kind: "account_or_zone".to_owned(),
            list_capability_id: String::new(),
            detail_capability_id: None,
            pagination: "unbound".to_owned(),
            normalization_rule: format!(
                "source-config kind `{kind}` requires an explicit live response identity mapping"
            ),
            freshness_seconds: 0,
            permissions: Vec::new(),
            status: "blocked".to_owned(),
            blocker: Some(format!(
                "{kind} source configuration is indexed, but no live normalization provider is bound"
            )),
        })?;
    }
    let proof_page = store.list_recent_operational_proofs(OPERATIONAL_PROOF_PROJECTION_LIMIT)?;
    for proof in &proof_page.proofs {
        registry.record_unindexable_evidence(
            &proof.evidence.content_hash,
            "operational proof receipt has no normalized resource-state payload",
        )?;
    }
    registry.mark_sync_complete()?;
    Ok(json!({
        "catalog_hash": catalog_hash,
        "operation_count": operation_count,
        "adopted_accounts": adopted_accounts,
        "desired_resource_count": declarations.len(),
        "source_config_resource_count": source_resources,
        "unscoped_source_resources": unscoped_source_resources,
        "unindexable_evidence": registry.unindexable_evidence()?,
        "unindexable_evidence_projection_truncated": proof_page.truncated,
        "coverage": registry.coverage()?,
        "truth_boundary": "This sync indexes catalog and local source/desired state. Only successful, evidence-backed inventory-provider reads may create live observations; events and source config never do so."
    }))
}

fn operation_maturity(capability: &CapabilityV1, gaps: &[String]) -> &'static str {
    if capability.adapter_status == AdapterStatus::Blocked {
        "indexed"
    } else if !capability.mutating {
        "observable"
    } else if gaps.is_empty() {
        "verifiable"
    } else {
        "typed"
    }
}

const fn adapter_status_label(status: AdapterStatus) -> &'static str {
    match status {
        AdapterStatus::Native => "native",
        AdapterStatus::DynamicApi => "dynamic_api",
        AdapterStatus::DelegatedCli => "delegated_cli",
        AdapterStatus::GovernedUi => "governed_ui",
        AdapterStatus::Blocked => "blocked",
    }
}

fn load_registry_declarations(store: &StateStore) -> Result<Vec<DesiredResourceV1>> {
    let directory = store.paths().config_dir.join("registry/declarations");
    if !directory.is_dir() {
        return Ok(Vec::new());
    }
    let mut paths = fs::read_dir(&directory)
        .map_err(|source| cli_io(&directory, source))?
        .map(|entry| {
            entry
                .map(|entry| entry.path())
                .map_err(|source| cli_io(&directory, source))
        })
        .collect::<Result<Vec<_>>>()?;
    paths.retain(|path| {
        path.extension()
            .is_some_and(|extension| extension == "json")
    });
    paths.sort();
    let mut declarations = Vec::new();
    for path in paths {
        let value: Value = store.read_json(&path)?;
        if value.is_array() {
            declarations.extend(serde_json::from_value::<Vec<DesiredResourceV1>>(value)?);
        } else {
            declarations.push(serde_json::from_value::<DesiredResourceV1>(value)?);
        }
    }
    if let Some(invalid) = declarations
        .iter()
        .find(|declaration| declaration.schema_version != 1)
    {
        return Err(CliError::Input(format!(
            "desired resource `{}` uses unsupported schema version {}",
            invalid.resource.key(),
            invalid.schema_version
        )));
    }
    Ok(declarations)
}

fn registry_diff_envelope(
    registry: &Registry,
    command: &'static str,
    selected_resource: Option<&str>,
    planning: bool,
) -> Result<ResultEnvelopeV2> {
    let diffs = registry
        .list_desired_resources()?
        .into_iter()
        .filter(|desired| {
            selected_resource.is_none_or(|selected| desired.resource.key() == selected)
        })
        .map(|desired| {
            let resource_key = desired.resource.key();
            let observation = registry
                .observation_history(&resource_key)?
                .into_iter()
                .next();
            let state = observation.as_ref().map_or("unobserved", |observed| {
                if observed.state_hash == desired.manifest_hash {
                    "converged"
                } else {
                    "drifted"
                }
            });
            Ok(json!({
                "resource": desired.resource,
                "state": state,
                "desired_hash": desired.manifest_hash,
                "observed_hash": observation.as_ref().map(|item| &item.state_hash),
                "observation": observation,
                "next_action": if state == "converged" {
                    Value::Null
                } else {
                    json!(format!("cfctl resolve \"reconcile {}\" --json", resource_key))
                },
            }))
        })
        .collect::<Result<Vec<_>>>()?;
    Ok(ResultEnvelopeV2::success(
        command,
        json!({
            "diffs": diffs,
            "aggregate_plan_created": false,
            "planning_requested": planning,
            "message": if planning {
                "Registry planning never aggregates mutation approvals. Resolve and create one governed child plan per drifted resource after a fresh live read."
            } else {
                "Desired declarations were compared only with the latest successful live observations; unobserved resources remain unknown."
            }
        }),
    ))
}

fn workspace_command(store: &StateStore, command: WorkspaceCommand) -> Result<ResultEnvelopeV2> {
    match command {
        WorkspaceCommand::Add(arguments) => {
            store.register_workspace(&arguments.path, arguments.account)?;
            Ok(ResultEnvelopeV2::success(
                "workspace add",
                json!({"path": arguments.path, "message": "Workspace root registered; discovery remains bounded to registered roots."}),
            ))
        }
        WorkspaceCommand::Remove(arguments) => {
            let (path, removed, account_pin_removed) =
                store.unregister_workspace(&arguments.path)?;
            Ok(ResultEnvelopeV2::success(
                "workspace remove",
                json!({
                    "path": path,
                    "removed": removed,
                    "account_pin_removed": account_pin_removed,
                    "message": "Workspace root retired from future discovery; historical graphs and evidence were preserved."
                }),
            ))
        }
        WorkspaceCommand::Discover => {
            let graph = discover_registered(store)?;
            store.write_json(&workspace_graph_file(store), &graph)?;
            Ok(ResultEnvelopeV2::success(
                "workspace discover",
                serde_json::to_value(graph)?,
            ))
        }
        WorkspaceCommand::Graph => {
            let graph = discover_registered(store)?;
            Ok(ResultEnvelopeV2::success(
                "workspace graph",
                serde_json::to_value(graph)?,
            ))
        }
        WorkspaceCommand::Audit => {
            let graph = discover_registered(store)?;
            let account_pins = store.workspace_manifest()?.account_pins();
            let proof_page =
                store.list_recent_operational_proofs(OPERATIONAL_PROOF_PROJECTION_LIMIT)?;
            let proofs = &proof_page.proofs;
            let profiles = ProfilesConfig::load(store)?;
            let current_catalog_hash = store
                .paths()
                .catalog_file()
                .is_file()
                .then(|| CatalogSnapshot::load(&store.paths().catalog_file()))
                .transpose()?
                .map(|catalog| catalog.schema_hash);
            let mut repositories = Vec::new();
            for repository in &graph.repositories {
                let output = std::process::Command::new("git")
                    .args([
                        "-C",
                        &repository.path.display().to_string(),
                        "status",
                        "--porcelain",
                    ])
                    .output()
                    .map_err(|source| cli_io(&repository.path, source))?;
                let account_id = account_pins
                    .iter()
                    .filter(|(root, _)| repository.path.starts_with(root))
                    .max_by_key(|(root, _)| root.components().count())
                    .map(|(_, account)| account.as_str());
                repositories.push(json!({
                    "name": repository.name,
                    "path": repository.path,
                    "dirty": !output.stdout.is_empty(),
                    "cloudflare_configs": repository.cloudflare_configs,
                    "account_id": account_id,
                    "operational_proof": workspace_operational_proof_posture(
                        proofs,
                        &profiles,
                        account_id,
                        current_catalog_hash.as_deref(),
                    ),
                }));
            }
            Ok(ResultEnvelopeV2::success(
                "workspace audit",
                json!({
                    "repositories": repositories,
                    "resource_count": graph.resources.len(),
                    "operational_proof_projection": operational_proof_projection_json(&proof_page),
                    "truth_boundary": "Repository configuration is source-config evidence. The operational-proof overlay contains account-scoped live-read receipts and remains separate from edge verification or desired-state convergence."
                }),
            ))
        }
    }
}

fn workspace_operational_proof_posture(
    proofs: &[OperationalProofV1],
    profiles: &ProfilesConfig,
    account_id: Option<&str>,
    current_catalog_hash: Option<&str>,
) -> Value {
    let Some(account_id) = account_id else {
        return json!({
            "state": "unscoped",
            "proof_count": 0,
            "next_action": "Register the root with an explicit account pin before joining local configuration to operational proof."
        });
    };
    let scoped = proofs
        .iter()
        .filter(|proof| proof.account_id.as_deref() == Some(account_id))
        .collect::<Vec<_>>();
    let capabilities = scoped
        .iter()
        .map(|proof| proof.capability_id.as_str())
        .collect::<BTreeSet<_>>();
    let current_catalog_successes = current_catalog_hash.map_or(0, |catalog_hash| {
        scoped
            .iter()
            .filter(|proof| {
                proof.catalog_hash == catalog_hash
                    && proof
                        .profile_id
                        .as_deref()
                        .and_then(|profile_id| profiles.profiles.get(profile_id))
                        .and_then(|profile| profile.credential_generation_id.as_deref())
                        == proof.credential_generation_id.as_deref()
                    && proof.credential_generation_id.is_some()
                    && proof.outcome == OperationalProofOutcomeV1::Succeeded
            })
            .count()
    });
    let current_catalog_failures = current_catalog_hash.map_or(0, |catalog_hash| {
        scoped
            .iter()
            .filter(|proof| {
                proof.catalog_hash == catalog_hash
                    && proof
                        .profile_id
                        .as_deref()
                        .and_then(|profile_id| profiles.profiles.get(profile_id))
                        .and_then(|profile| profile.credential_generation_id.as_deref())
                        == proof.credential_generation_id.as_deref()
                    && proof.credential_generation_id.is_some()
                    && proof.outcome == OperationalProofOutcomeV1::Failed
            })
            .count()
    });
    json!({
        "state": if scoped.is_empty() { "not_recorded" } else { "recorded" },
        "account_id": account_id,
        "proof_count": scoped.len(),
        "capabilities_observed": capabilities,
        "latest_observed_at": scoped.iter().map(|proof| proof.observed_at).max(),
        "current_catalog_hash": current_catalog_hash,
        "current_catalog_successes": current_catalog_successes,
        "current_catalog_failures": current_catalog_failures,
        "catalog_drifted_or_unclassified": scoped.len().saturating_sub(current_catalog_successes + current_catalog_failures),
        "credential_unbound_or_drifted": scoped.iter().filter(|proof| {
            proof.credential_generation_id.is_none()
                || proof.profile_id.as_deref()
                    .and_then(|profile_id| profiles.profiles.get(profile_id))
                    .and_then(|profile| profile.credential_generation_id.as_deref())
                    != proof.credential_generation_id.as_deref()
        }).count(),
        "freshness_policy": "Select a governed workflow to evaluate time freshness; workspace audit does not invent a universal window."
    })
}

fn agents_command(store: &StateStore, command: AgentsCommand) -> Result<ResultEnvelopeV2> {
    let home = home_directory()?;
    match command {
        AgentsCommand::Install(arguments) => {
            let selected: Vec<AgentKind> = if arguments.all_detected {
                AgentKind::all()
                    .into_iter()
                    .filter(|agent| which::which(agent.program()).is_ok())
                    .collect()
            } else {
                vec![configured_agent()?]
            };
            let receipts = selected
                .into_iter()
                .map(|agent| install_agent_skill(&home, agent, InstallMode::Install))
                .collect::<std::result::Result<Vec<_>, _>>()?;
            let evidence = store
                .write_evidence(EvidenceClass::LocalProof, &serde_json::to_value(&receipts)?)?;
            Ok(ResultEnvelopeV2::success(
                "agents install",
                json!({"receipts": receipts, "message": "Managed cfctl discovery instructions installed for detected agents."}),
            )
            .with_evidence(evidence))
        }
        AgentsCommand::Sync => {
            // Sync replaces what is already installed; creating a missing
            // integration is `agents install`. Naming the agents it passed over
            // matters because the silent case is the confusing one: an operator
            // who runs sync to fix a missing skill would otherwise read
            // "synchronized" and believe it was done.
            let (present, skipped): (Vec<_>, Vec<_>) =
                AgentKind::all().into_iter().partition(|agent| {
                    inspect_agent(&home, *agent, which::which(agent.program()).is_ok())
                        .skill_present
                });
            let receipts = present
                .into_iter()
                .map(|agent| install_agent_skill(&home, agent, InstallMode::Sync))
                .collect::<std::result::Result<Vec<_>, _>>()?;
            let skipped: Vec<_> = skipped.into_iter().map(AgentKind::label).collect();
            let message = if skipped.is_empty() {
                "Existing managed integrations synchronized.".to_owned()
            } else {
                format!(
                    "Existing managed integrations synchronized. No managed instructions are installed for {}; run `cfctl agents install` to add them.",
                    skipped.join(", ")
                )
            };
            Ok(ResultEnvelopeV2::success(
                "agents sync",
                json!({"receipts": receipts, "skipped_agents": skipped, "message": message}),
            ))
        }
        AgentsCommand::Doctor => {
            let status: Vec<_> = AgentKind::all()
                .into_iter()
                .map(|agent| inspect_agent(&home, agent, which::which(agent.program()).is_ok()))
                .collect();
            let configured = configured_agent()?;
            let running_build = current_build_info();
            let build_identity_healthy = build_identity_is_healthy(&running_build);
            let path_build = inspect_path_build(&running_build);
            let instruction_drift = status
                .iter()
                .filter(|agent| agent.skill_present && !agent.skill_current)
                .count();
            let healthy = build_identity_healthy && path_build.healthy && instruction_drift == 0;
            Ok(health_envelope(
                "agents doctor",
                json!({
                    "running_build": running_build,
                    "build_identity_healthy": build_identity_healthy,
                    "path_build": path_build,
                    "configured_default_agent": configured,
                    "platform": env::consts::OS,
                    "platform_secret_store": platform_secret_store_health(store)?,
                    "instruction_drift": instruction_drift,
                    "agents": status,
                }),
                healthy,
                "CFCTL_AGENT_OR_BUILD_DRIFT",
                "The source identity, PATH build, or managed agent instructions are not current.",
            ))
        }
    }
}

async fn docs_command(store: &StateStore, command: DocsCommand) -> Result<ResultEnvelopeV2> {
    let _catalog = ensure_catalog(store).await?;
    let mut feeds: OfficialTextFeedsV1 = store.read_json(&docs_file(store))?;
    if feeds.product_indexes.is_empty() {
        feeds = fetch_official_text_feeds(&http_client()?).await?;
        store.write_json(&docs_file(store), &feeds)?;
    }
    match command {
        DocsCommand::Search(SearchArgs { query, limit }) => {
            let matches = search_docs(&http_client()?, &feeds, &query, limit.min(100)).await;
            Ok(ResultEnvelopeV2::success(
                "docs search",
                json!({
                    "query": query,
                    "matches": matches,
                    "fetched_at": feeds.fetched_at,
                    "result_limit": limit.min(100),
                    "limit_capped": limit > 100,
                }),
            ))
        }
        DocsCommand::Changes => Ok(ResultEnvelopeV2::success(
            "docs changes",
            json!({"source": feeds.changelog_url, "fetched_at": feeds.fetched_at, "text": feeds.changelog}),
        )),
        DocsCommand::Coverage => {
            let linked_pages = feeds
                .product_indexes
                .values()
                .flat_map(|index| index.lines())
                .filter_map(cfctl_catalog::markdown_link)
                .filter(|url| url.ends_with("/index.md"))
                .count();
            Ok(ResultEnvelopeV2::success(
                "docs coverage",
                json!({
                    "official_index": feeds.docs_index_url,
                    "official_changelog": feeds.changelog_url,
                    "linked_pages": linked_pages,
                    "product_indexes": feeds.product_indexes.len(),
                    "unread_product_indexes": feeds.unread_product_indexes,
                    "fetched_at": feeds.fetched_at,
                    "note": "Coverage indexes official product feeds; matching page bodies are fetched from Cloudflare on demand and returned with per-page fetch status."
                }),
            ))
        }
    }
}

async fn search_docs(
    client: &reqwest::Client,
    feeds: &OfficialTextFeedsV1,
    query: &str,
    limit: usize,
) -> Vec<Value> {
    let terms: Vec<String> = query
        .split_whitespace()
        .map(str::to_ascii_lowercase)
        .collect();
    let candidates: Vec<String> = feeds
        .docs_index
        .lines()
        .chain(
            feeds
                .product_indexes
                .values()
                .flat_map(|index| index.lines()),
        )
        .chain(feeds.changelog.lines())
        .filter(|line| {
            let line = line.to_ascii_lowercase();
            terms.iter().all(|term| line.contains(term))
        })
        .take(limit)
        .map(str::to_owned)
        .collect();
    let mut matches = stream::iter(candidates.into_iter().enumerate())
        .map(|(position, index_entry)| {
            let client = client.clone();
            let terms = terms.clone();
            async move {
                let Some(url) = cfctl_catalog::markdown_link(&index_entry).map(str::to_owned) else {
                    return (
                        position,
                        json!({"index_entry": index_entry, "body_status": "not_a_page_link"}),
                    );
                };
                let response = client
                    .get(&url)
                    .header(reqwest::header::ACCEPT, "text/markdown")
                    .send()
                    .await
                    .and_then(reqwest::Response::error_for_status);
                match response {
                    Ok(response) => match response.text().await {
                        Ok(body) => (
                            position,
                            json!({
                                "index_entry": index_entry,
                                "url": url,
                                "body_status": "fetched",
                                "excerpt": docs_excerpt(&body, &terms),
                            }),
                        ),
                        Err(error) => (
                            position,
                            json!({"index_entry": index_entry, "url": url, "body_status": "unread", "reason": error.to_string()}),
                        ),
                    },
                    Err(error) => (
                        position,
                        json!({"index_entry": index_entry, "url": url, "body_status": "unread", "reason": error.to_string()}),
                    ),
                }
            }
        })
        .buffer_unordered(8)
        .collect::<Vec<_>>()
        .await;
    matches.sort_by_key(|(position, _)| *position);
    matches.into_iter().map(|(_, value)| value).collect()
}

fn docs_excerpt(body: &str, terms: &[String]) -> String {
    let matching: Vec<&str> = body
        .lines()
        .filter(|line| {
            let line = line.to_ascii_lowercase();
            terms.iter().all(|term| line.contains(term))
        })
        .filter(|line| !line.trim().is_empty())
        .take(6)
        .collect();
    let lines = if matching.is_empty() {
        body.lines()
            .filter(|line| !line.trim().is_empty())
            .take(6)
            .collect()
    } else {
        matching
    };
    lines.join("\n").chars().take(2_000).collect()
}

fn doctor_command(store: &StateStore) -> Result<ResultEnvelopeV2> {
    let profiles = ProfilesConfig::load(store)?;
    let inventory_hash = oauth_scope_inventory_hash(store)?;
    let unsupported_legacy_profiles: Vec<Value> = profiles
        .profiles
        .values()
        .filter(|profile| profile.kind == ProfileKind::LegacyWranglerSession)
        .map(|profile| {
            json!({
                "profile": profile.id,
                "kind": "wrangler_session",
                "supported": false,
                "credential_store_accessed": false,
                "remove_argv": ["cfctl", "auth", "logout", profile.id, "--json"],
                "next_step": format!(
                    "Remove this metadata-only legacy profile with `cfctl auth logout {}` and create a supported OAuth or API-token profile; Wrangler authentication is not a cfctl credential lane.",
                    profile.id
                ),
            })
        })
        .collect();
    let oauth_reconsent: Vec<Value> = profiles
        .profiles
        .values()
        .filter(|profile| profile.kind == ProfileKind::OAuth)
        .map(|profile| {
            let reconsent_required = inventory_hash.is_some()
                && profile.oauth_scope_inventory_hash.as_ref() != inventory_hash.as_ref();
            json!({
                "profile": profile.id,
                "granted_scope_count": profile.oauth_scopes.len(),
                "scope_inventory_hash": profile.oauth_scope_inventory_hash,
                "reconsent_required": reconsent_required,
            })
        })
        .collect();
    let catalog = if store.paths().catalog_file().is_file() {
        let catalog = CatalogSnapshot::load(&store.paths().catalog_file())?;
        json!({
            "present": true,
            "schema_hash": catalog.schema_hash,
            "capabilities": catalog.capabilities.len(),
            "stale": catalog_is_stale(store),
        })
    } else {
        json!({"present": false})
    };
    let home = home_directory()?;
    let agents: Vec<_> = AgentKind::all()
        .into_iter()
        .map(|agent| inspect_agent(&home, agent, which::which(agent.program()).is_ok()))
        .collect();
    let running_build = current_build_info();
    let build_identity_healthy = build_identity_is_healthy(&running_build);
    let path_build = inspect_path_build(&running_build);
    let instruction_drift = agents
        .iter()
        .filter(|agent| agent.skill_present && !agent.skill_current)
        .count();
    let healthy = build_identity_healthy && path_build.healthy && instruction_drift == 0;
    Ok(health_envelope(
        "doctor",
        json!({
            "running_build": running_build,
            "build_identity_healthy": build_identity_healthy,
            "path_build": path_build,
            "platform": env::consts::OS,
            "config_dir": store.paths().config_dir,
            "data_dir": store.paths().data_dir,
            "cache_dir": store.paths().cache_dir,
            "delegated_cli_environment": governed_cli_environment_contract(
                &store.paths().cache_dir
            ),
            "catalog": catalog,
            "profile_count": profiles.profiles.len(),
            "current_profile": profiles.current_profile,
            "unsupported_legacy_profiles": unsupported_legacy_profiles,
            "oauth_scope_inventory_hash": inventory_hash,
            "oauth_profiles": oauth_reconsent,
            "platform_secret_store": platform_secret_store_health(store)?,
            "standing_authorities": standing_authorities_health(store)?,
            "instruction_drift": instruction_drift,
            "agents": agents,
            "public_oauth": "unconfigured until cfctl.io ownership, site publication, domain verification, and permanent promotion are explicitly completed; use `cfctl auth import-api-token --account <id> --stdin` for the scoped day-to-day lane",
        }),
        healthy,
        "CFCTL_RUNTIME_DRIFT",
        "The source identity, PATH build, or managed agent instructions are not current.",
    ))
}

fn version_command() -> Result<ResultEnvelopeV2> {
    Ok(ResultEnvelopeV2::success(
        "version",
        serde_json::to_value(current_build_info())?,
    ))
}

fn health_envelope(
    command: &str,
    result: Value,
    healthy: bool,
    code: &str,
    message: &str,
) -> ResultEnvelopeV2 {
    let mut envelope = ResultEnvelopeV2::success(command, result);
    if !healthy {
        envelope.ok = false;
        envelope.verification.state = VerificationState::Failed;
        envelope.error = Some(ErrorV1 {
            code: code.to_owned(),
            message: message.to_owned(),
            next_step: Some(
                "Run ./bootstrap.sh from a tracked-clean checkout, then synchronize managed agents."
                    .to_owned(),
            ),
        });
    }
    envelope
}

async fn update_command(check: bool) -> Result<ResultEnvelopeV2> {
    if !check {
        return Err(CliError::Input(
            "self-update is disabled until a release has signed checksums and attestations; use `cfctl update --check`"
                .to_owned(),
        ));
    }
    let response = http_client()?
        .get("https://api.github.com/repos/rogu3bear/cfctl/releases/latest")
        .header(reqwest::header::USER_AGENT, "cfctl")
        .send()
        .await?;
    if response.status() == reqwest::StatusCode::NOT_FOUND {
        return Ok(ResultEnvelopeV2::success(
            "update",
            json!({"current": env!("CARGO_PKG_VERSION"), "published_release": null, "message": "No public GitHub release exists yet."}),
        ));
    }
    let release = response.error_for_status()?.json::<Value>().await?;
    Ok(ResultEnvelopeV2::success(
        "update",
        json!({"current": env!("CARGO_PKG_VERSION"), "latest": release.get("tag_name"), "release_url": release.get("html_url")}),
    ))
}

fn migrate_command(store: &StateStore, command: MigrateCommand) -> Result<ResultEnvelopeV2> {
    match command {
        MigrateCommand::V1 => {
            let cwd = env::current_dir().map_err(|source| cli_io(Path::new("."), source))?;
            let mut imported = Vec::new();
            let mut skipped = Vec::new();
            let retained_repo_state = "compat/v1/state";
            let state_source = if cwd.join(retained_repo_state).is_dir() {
                retained_repo_state
            } else {
                "state"
            };
            for (source_root, import_label) in
                [(state_source, "state"), ("var/inventory", "var/inventory")]
            {
                let root = cwd.join(source_root);
                if !root.is_dir() {
                    continue;
                }
                for entry in walkdir::WalkDir::new(&root)
                    .follow_links(false)
                    .into_iter()
                    .filter_map(std::result::Result::ok)
                    .filter(|entry| entry.file_type().is_file())
                {
                    let path = entry.path();
                    if is_secret_path(path) {
                        skipped.push(json!({"source_path": path, "reason": "secret-shaped path"}));
                        continue;
                    }
                    let content =
                        fs::read_to_string(path).map_err(|source| cli_io(path, source))?;
                    if contains_sensitive_content(&content) {
                        skipped
                            .push(json!({"source_path": path, "reason": "secret-shaped content"}));
                        continue;
                    }
                    let content_hash = hash_value(&Value::String(content.clone()))?;
                    let digest = content_hash
                        .strip_prefix("sha256:")
                        .unwrap_or(&content_hash);
                    let Ok(source_relative) = path.strip_prefix(&root) else {
                        skipped.push(
                            json!({"source_path": path, "reason": "path escaped source root"}),
                        );
                        continue;
                    };
                    let destination = store.write_import(
                        &Path::new("v1")
                            .join(digest)
                            .join(import_label)
                            .join(source_relative),
                        content.as_bytes(),
                    )?;
                    let evidence = store.write_evidence(
                        EvidenceClass::SourceConfig,
                        &json!({
                            "source_path": path,
                            "destination": destination,
                            "source_content_hash": content_hash,
                        }),
                    )?;
                    imported.push(json!({
                        "source_path": path,
                        "destination": destination,
                        "source_content_hash": content_hash,
                        "evidence": evidence,
                    }));
                }
            }
            Ok(ResultEnvelopeV2::success(
                "migrate v1",
                json!({
                    "imported": imported,
                    "skipped": skipped,
                    "credentials_imported": false,
                    "message": "V1 desired state and evidence were copied into content-addressed imports; secret-shaped files and credentials were not imported."
                }),
            ))
        }
    }
}

async fn ensure_catalog(store: &StateStore) -> Result<CatalogSnapshot> {
    if !store.paths().catalog_file().is_file() || catalog_is_stale(store) {
        let _receipt = sync_catalog(store).await?;
    }
    Ok(CatalogSnapshot::load(&store.paths().catalog_file())?)
}

async fn resolve_login_scopes(
    store: &StateStore,
    profiles: &ProfilesConfig,
    secrets: &dyn SecretStore,
    requested: &[String],
) -> Result<Vec<String>> {
    if !requested.is_empty() {
        let mut scopes = requested.to_vec();
        scopes.sort();
        scopes.dedup();
        return Ok(scopes);
    }
    let snapshot = if oauth_scope_inventory_file(store).is_file() {
        store.read_json::<Value>(&oauth_scope_inventory_file(store))?
    } else {
        let profile = profiles.selected(None).map_err(|_| {
            CliError::Input(
                "default all-scope login needs a cached authenticated `/oauth/scopes` inventory; first pass explicit --scope IDs or refresh with an active profile"
                    .to_owned(),
            )
        })?;
        let credential = fresh_credential(profile, secrets).await?;
        fetch_oauth_scope_snapshot(&credential).await?
    };
    let scopes = oauth_scope_ids(&snapshot)?;
    store.write_json(&oauth_scope_inventory_file(store), &snapshot)?;
    if scopes.is_empty() {
        return Err(CliError::Input(
            "Cloudflare returned an empty OAuth scope inventory; pass explicit --scope IDs"
                .to_owned(),
        ));
    }
    Ok(scopes)
}

async fn fresh_credential(
    profile: &ProfileMetadata,
    secrets: &dyn SecretStore,
) -> Result<AuthCredential> {
    if profile.kind != ProfileKind::OAuth {
        return Ok(secrets.load_profile_credential(profile)?);
    }
    let tokens = secrets.load_profile_oauth_tokens(profile)?;
    if !tokens.needs_refresh() {
        return Ok(AuthCredential::Bearer {
            token: tokens.access_token().to_owned(),
        });
    }
    let refresh_token = tokens.refresh_token().ok_or_else(|| {
        CliError::Input(format!(
            "OAuth profile `{}` expired and has no refresh token; log in again",
            profile.id
        ))
    })?;
    let client_id = profile.oauth_client_id.as_deref().ok_or_else(|| {
        CliError::Input(format!(
            "OAuth profile `{}` is missing its client ID; log in again",
            profile.id
        ))
    })?;
    let refreshed = refresh_oauth_tokens(
        &http_client()?,
        &OAuthClientConfig::cfctl_public(client_id),
        refresh_token,
    )
    .await?;
    let credential = AuthCredential::Bearer {
        token: refreshed.access_token().to_owned(),
    };
    secrets.store_oauth_tokens(&profile.id, &refreshed)?;
    Ok(credential)
}

async fn refresh_oauth_scopes_if_authenticated(store: &StateStore) -> Result<Option<Value>> {
    let profiles = ProfilesConfig::load(store)?;
    let Ok(profile) = profiles.selected(None) else {
        return Ok(None);
    };
    let credential = fresh_credential(profile, &platform_secrets(store)).await?;
    let snapshot = fetch_oauth_scope_snapshot(&credential).await?;
    store.write_json(&oauth_scope_inventory_file(store), &snapshot)?;
    Ok(Some(snapshot))
}

async fn fetch_oauth_scope_snapshot(credential: &AuthCredential) -> Result<Value> {
    let client = http_client()?;
    let request = client.get(format!("{API_BASE_URL}/oauth/scopes"));
    let request = match credential {
        AuthCredential::Bearer { token } => request.bearer_auth(token),
        AuthCredential::GlobalKey { email, key } => request
            .header("X-Auth-Email", email)
            .header("X-Auth-Key", key),
    };
    let envelope = request
        .send()
        .await?
        .error_for_status()?
        .json::<Value>()
        .await?;
    if !envelope
        .get("success")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Err(CliError::Input(format!(
            "Cloudflare rejected OAuth scope inventory: {}",
            envelope
                .get("errors")
                .cloned()
                .unwrap_or(Value::String("unknown error".to_owned()))
        )));
    }
    let scopes = envelope
        .get("result")
        .and_then(Value::as_array)
        .ok_or_else(|| CliError::Input("OAuth scope inventory result is not an array".to_owned()))?
        .clone();
    let ids = oauth_scope_ids(&json!({"scopes": scopes.clone()}))?;
    let schema_hash = hash_value(&serde_json::to_value(&ids)?)?;
    Ok(json!({
        "schema_version": 1,
        "fetched_at": Utc::now(),
        "source": "/oauth/scopes",
        "schema_hash": schema_hash,
        "scopes": scopes,
    }))
}

fn oauth_scope_ids(snapshot: &Value) -> Result<Vec<String>> {
    let mut ids: Vec<String> = snapshot
        .get("scopes")
        .and_then(Value::as_array)
        .ok_or_else(|| CliError::Input("cached OAuth scope inventory is malformed".to_owned()))?
        .iter()
        .filter_map(|scope| scope.get("id").and_then(Value::as_str))
        .map(str::to_owned)
        .collect();
    ids.sort();
    ids.dedup();
    Ok(ids)
}

fn oauth_scope_inventory_hash(store: &StateStore) -> Result<Option<String>> {
    let path = oauth_scope_inventory_file(store);
    if !path.is_file() {
        return Ok(None);
    }
    let snapshot: Value = store.read_json(&path)?;
    Ok(snapshot
        .get("schema_hash")
        .and_then(Value::as_str)
        .map(str::to_owned))
}

fn oauth_scope_inventory_file(store: &StateStore) -> PathBuf {
    store.paths().data_dir.join("auth/oauth-scopes-v1.json")
}

fn discover_registered(store: &StateStore) -> Result<WorkspaceGraph> {
    let roots: Vec<RegisteredRoot> = store
        .workspace_roots()?
        .iter()
        .map(|path| RegisteredRoot::new(path))
        .collect();
    Ok(WorkspaceGraph::discover(&roots)?)
}

fn workspace_precondition_hashes_for_scope(
    store: &StateStore,
    affected_repositories: &[String],
    local_artifact_paths: &[PathBuf],
) -> Result<BTreeMap<String, String>> {
    let graph = discover_registered(store)?;
    let repository_ids = affected_repositories
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let repositories = graph
        .repositories
        .iter()
        .filter(|repository| repository_ids.contains(&repository.path.display().to_string()))
        .collect::<Vec<_>>();
    if repositories.len() != repository_ids.len() {
        return Err(CliError::Input(
            "an affected repository is no longer present in the registered workspace graph"
                .to_owned(),
        ));
    }
    let resources = graph
        .resources
        .iter()
        .filter(|resource| {
            graph.links.get(&resource.key).is_some_and(|linked| {
                linked
                    .iter()
                    .any(|repository| repository_ids.contains(repository))
            })
        })
        .collect::<Vec<_>>();
    let links = graph
        .links
        .iter()
        .filter_map(|(resource, linked)| {
            let scoped = linked
                .iter()
                .filter(|repository| repository_ids.contains(*repository))
                .cloned()
                .collect::<BTreeSet<_>>();
            (!scoped.is_empty()).then_some((resource.clone(), scoped))
        })
        .collect::<BTreeMap<_, _>>();
    let mut hashes = BTreeMap::new();
    hashes.insert(
        "workspace_graph".to_owned(),
        hash_value(&json!({
            "repositories": repositories,
            "resources": resources,
            "links": links,
        }))?,
    );
    for path in repositories
        .into_iter()
        .flat_map(|repository| &repository.cloudflare_configs)
    {
        let content = fs::read_to_string(path).map_err(|source| cli_io(path, source))?;
        hashes.insert(
            format!("source_config:{}", path.display()),
            hash_value(&Value::String(content))?,
        );
    }
    for path in local_artifact_paths {
        hashes.insert(
            format!("source_artifact:{}", path.display()),
            hash_directory_artifact(path)?,
        );
    }
    Ok(hashes)
}

fn hash_directory_artifact(root: &Path) -> Result<String> {
    let canonical = fs::canonicalize(root).map_err(|source| cli_io(root, source))?;
    if !canonical.is_dir() {
        return Err(CliError::Input(format!(
            "deployment artifact `{}` is not a directory",
            canonical.display()
        )));
    }
    let mut manifest = Vec::new();
    for entry in WalkDir::new(&canonical).follow_links(false) {
        let entry = entry.map_err(|source| {
            CliError::Input(format!(
                "failed to inspect deployment artifact `{}`: {source}",
                canonical.display()
            ))
        })?;
        if entry.path() == canonical || entry.file_type().is_dir() {
            continue;
        }
        if !entry.file_type().is_file() {
            return Err(CliError::Input(format!(
                "deployment artifact contains unsupported non-file entry `{}`",
                entry.path().display()
            )));
        }
        let relative = entry.path().strip_prefix(&canonical).map_err(|_| {
            CliError::Input(format!(
                "deployment artifact entry `{}` escaped its root",
                entry.path().display()
            ))
        })?;
        let bytes = fs::read(entry.path()).map_err(|source| cli_io(entry.path(), source))?;
        manifest.push(json!({
            "path": relative.to_string_lossy(),
            "sha256": hex::encode(Sha256::digest(&bytes)),
        }));
    }
    manifest.sort_by_key(|entry| entry["path"].as_str().unwrap_or_default().to_owned());
    Ok(hash_value(&Value::Array(manifest))?)
}

fn validate_pages_source_remote_receipt(plan: &PlanV1, receipt: &Value) -> Result<()> {
    let input: CallInput = serde_json::from_value(plan.input.clone())?;
    let (owner, repository, branch) = pages_github_source(&input)?;
    let owner = owner.to_ascii_lowercase();
    let repository = repository.to_ascii_lowercase();
    let remote_ref = format!("refs/heads/{branch}");
    let commit = receipt.get("remote_commit").and_then(Value::as_str);
    let exact = receipt.as_object().is_some_and(|object| object.len() == 7)
        && receipt.get("schema_version").and_then(Value::as_u64) == Some(1)
        && receipt.get("provider").and_then(Value::as_str) == Some("github")
        && receipt.get("owner").and_then(Value::as_str) == Some(owner.as_str())
        && receipt.get("repository").and_then(Value::as_str) == Some(repository.as_str())
        && receipt.get("branch").and_then(Value::as_str) == Some(branch)
        && receipt.get("remote_ref").and_then(Value::as_str) == Some(remote_ref.as_str())
        && commit.is_some_and(|commit| {
            commit.len() == 40
                && commit
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        });
    if !exact {
        return Err(CliError::Input(
            "Pages source remote receipt has an invalid repository, branch, or commit shape; create a new plan"
                .to_owned(),
        ));
    }
    Ok(())
}

fn current_pages_source_remote_precondition(
    store: &StateStore,
    plan: &PlanV1,
) -> Result<Option<String>> {
    if !should_bind_pages_project_absence(&plan.capability) {
        return Ok(None);
    }
    let expected = plan
        .precondition_hashes
        .get(PAGES_SOURCE_REMOTE_PRECONDITION)
        .ok_or_else(|| {
            CliError::Input(
                "Pages project creation plan predates the exact source-remote contract; create a new plan"
                    .to_owned(),
            )
        })?;
    let receipt = plan
        .targets
        .pointer(&format!(
            "/source_preconditions/{PAGES_SOURCE_REMOTE_PRECONDITION}"
        ))
        .ok_or_else(|| {
            CliError::Input(
                "Pages project creation plan omitted its source-remote receipt; create a new plan"
                    .to_owned(),
            )
        })?;
    validate_pages_source_remote_receipt(plan, receipt)?;
    if &hash_value(receipt)? != expected {
        return Err(CliError::Input(
            "Pages source-remote receipt does not match its precondition hash; create a new plan"
                .to_owned(),
        ));
    }
    let input: CallInput = serde_json::from_value(plan.input.clone())?;
    let current = prepare_pages_source_remote_precondition(store, &plan.capability, &input)?
        .ok_or_else(|| {
            CliError::Input(
                "Pages source-remote precondition could not be recomputed; create a new plan"
                    .to_owned(),
            )
        })?;
    Ok(Some(hash_value(&current)?))
}

fn validate_plan_preconditions(store: &StateStore, plan: &PlanV1) -> Result<()> {
    let local_artifact_paths = plan
        .precondition_hashes
        .keys()
        .filter_map(|name| name.strip_prefix("source_artifact:"))
        .map(PathBuf::from)
        .collect::<Vec<_>>();
    let mut current = workspace_precondition_hashes_for_scope(
        store,
        &plan.affected_repositories,
        &local_artifact_paths,
    )?;
    if let Some(source_remote) = current_pages_source_remote_precondition(store, plan)? {
        current.insert(PAGES_SOURCE_REMOTE_PRECONDITION.to_owned(), source_remote);
    }
    for (name, expected) in &plan.precondition_hashes {
        if is_live_plan_precondition_hash(name) {
            continue;
        }
        if current.get(name) != Some(expected) {
            return Err(CliError::Input(format!(
                "precondition `{name}` drifted after planning; create a new plan"
            )));
        }
    }
    Ok(())
}

fn validate_worker_deployment_local_authority(
    store: &StateStore,
    plan: &PlanV1,
    input: &CallInput,
) -> Result<()> {
    let adapter = plan.targets.get("adapter").unwrap_or(&Value::Null);
    if !worker_deployment::binds_live_state(&plan.capability)
        && worker_deployment::target(adapter).is_none()
    {
        return Ok(());
    }
    let graph = discover_registered(store)?;
    worker_deployment::validate_current_target(&graph, &plan.capability, input, adapter)
}

fn is_live_plan_precondition_hash(name: &str) -> bool {
    matches!(
        name,
        "catalog"
            | "request_input"
            | "entitlement"
            | "zone_account"
            | PAGES_PROJECT_ABSENCE_PRECONDITION
            | "global_warp_override_state"
            | D1_READ_REPLICATION_PRECONDITION
            | D1_EMPTY_DATABASE_PRECONDITION
            | CLOUDFLARE_TUNNEL_CONFIGURATION_STATE_PRECONDITION
            | WARP_CONNECTOR_CONFIGURATION_STATE_PRECONDITION
            | WEB_ANALYTICS_RUM_STATE_PRECONDITION
            | DNS_RECORD_STATE_PRECONDITION
            | SAME_PATH_PRIOR_STATE_PRECONDITION
            | SECURITY_ACTION_STATE_PRECONDITION
            | OAUTH_CLIENT_KEY_OVERLAP_PRECONDITION
            | OAUTH_CLIENT_UPDATE_STATE_PRECONDITION
            | worker_custom_domain::WORKER_CUSTOM_DOMAIN_STATE_PRECONDITION
            | worker_deployment::STATE_PRECONDITION
            | R2_PARENT_TOKEN_PRECONDITION
    )
}

fn resolve_account_id(
    store: &StateStore,
    profile: &ProfileMetadata,
    requested: Option<&str>,
    input: &CallInput,
) -> Result<Option<String>> {
    let selector = input.selectors.get("account_id").and_then(Value::as_str);
    if let (Some(argument), Some(selector)) = (requested, selector)
        && argument != selector
    {
        return Err(CliError::Input(format!(
            "account selection is ambiguous: --account `{argument}` differs from selector `{selector}`"
        )));
    }
    if let Some(explicit) = requested.or(selector) {
        return Ok(Some(explicit.to_owned()));
    }

    let pins = store.workspace_manifest()?.account_pins();
    let cwd = env::current_dir().map_err(|source| cli_io(Path::new("."), source))?;
    let workspace_pin = pins
        .into_iter()
        .filter(|(root, _)| cwd.starts_with(root))
        .max_by_key(|(root, _)| root.components().count())
        .map(|(_, account)| account);
    if let (Some(workspace), Some(profile_account)) =
        (workspace_pin.as_deref(), profile.account_id.as_deref())
        && workspace != profile_account
    {
        return Err(CliError::Input(format!(
            "account selection is ambiguous: workspace pins `{workspace}` but profile `{}` pins `{profile_account}`; pass --account explicitly",
            profile.id
        )));
    }
    Ok(workspace_pin.or_else(|| profile.account_id.clone()))
}

struct PreparedCallInput {
    input: CallInput,
    secret_body: Option<Value>,
}

fn call_input(capability: &CapabilityV1, arguments: &CallArgs) -> Result<PreparedCallInput> {
    let selectors = object_from_pairs(&arguments.selectors);
    let query = query_object_from_pairs(capability, &arguments.query)?;
    validate_wrangler_worker_versions_input(capability, &query)?;
    let body = if arguments.body_stdin {
        Some(serde_json::from_str(&read_stdin()?)?)
    } else {
        arguments
            .body_json
            .as_deref()
            .map(serde_json::from_str)
            .transpose()?
    };
    let contains_secret = body
        .as_ref()
        .is_some_and(|value| request_body_contains_secret(capability, value));
    if contains_secret && !arguments.body_stdin {
        return Err(CliError::Input(
            "secret-shaped request fields are accepted only through `--body-stdin`, never command arguments"
                .to_owned(),
        ));
    }
    Ok(PreparedCallInput {
        input: CallInput {
            selectors,
            query,
            body: if contains_secret { None } else { body.clone() },
            if_match: arguments.if_match.clone(),
            if_none_match: arguments.if_none_match.clone(),
        },
        secret_body: contains_secret.then_some(body).flatten(),
    })
}

fn validate_wrangler_worker_versions_input(capability: &CapabilityV1, query: &Value) -> Result<()> {
    if !matches!(
        capability.id.as_str(),
        "wrangler.versions-upload" | "wrangler.versions-deploy"
    ) {
        return Ok(());
    }
    let config = query.get("config").and_then(Value::as_str).ok_or_else(|| {
        CliError::Input("Worker Versions plans require a config selector".to_owned())
    })?;
    if !Path::new(config).is_absolute() {
        return Err(CliError::Input(
            "Worker Versions plans require an absolute Wrangler config path".to_owned(),
        ));
    }
    if capability.id == "wrangler.versions-deploy" {
        let spec = query
            .get("argument")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                CliError::Input(
                    "Worker Versions deployment requires exactly one UUID@100 target".to_owned(),
                )
            })?;
        if wrangler_versions_deploy_version_id(spec).is_none() {
            return Err(CliError::Input(
                "Worker Versions deployment target must be exactly one UUID@100 value".to_owned(),
            ));
        }
    }
    Ok(())
}

fn request_body_contains_secret(capability: &CapabilityV1, body: &Value) -> bool {
    redact_json(body) != *body
        || body.as_object().is_some_and(|fields| {
            fields
                .keys()
                .any(|field| capability.request_object_field_is_write_only(field))
        })
}

fn query_object_from_pairs(capability: &CapabilityV1, pairs: &[(String, String)]) -> Result<Value> {
    let mut grouped = BTreeMap::<String, Vec<String>>::new();
    for (name, value) in pairs {
        grouped.entry(name.clone()).or_default().push(value.clone());
    }
    let mut query = Map::new();
    for (name, values) in grouped {
        let array_typed = capability.selectors.iter().any(|selector| {
            selector.location == "query" && selector.name == name && selector.value_type == "array"
        });
        if array_typed {
            query.insert(
                name,
                Value::Array(values.into_iter().map(Value::String).collect()),
            );
        } else if values.len() == 1 {
            query.insert(name, Value::String(values[0].clone()));
        } else {
            return Err(CliError::Input(format!(
                "query control `{name}` is repeated but its catalog type is not an array"
            )));
        }
    }
    Ok(Value::Object(query))
}

fn object_from_pairs(pairs: &[(String, String)]) -> Value {
    Value::Object(
        pairs
            .iter()
            .map(|(key, value)| (key.clone(), Value::String(value.clone())))
            .collect::<Map<String, Value>>(),
    )
}

fn parse_callback(value: &str) -> Result<(String, String)> {
    if let Ok(document) = serde_json::from_str::<Value>(value) {
        let state = document.get("state").and_then(Value::as_str);
        let code = document.get("code").and_then(Value::as_str);
        if let (Some(state), Some(code)) = (state, code) {
            return Ok((state.to_owned(), code.to_owned()));
        }
    }
    let mut parts = value.split_whitespace();
    let state = parts.next();
    let code = parts.next();
    if let (Some(state), Some(code), None) = (state, code, parts.next()) {
        return Ok((state.to_owned(), code.to_owned()));
    }
    Err(CliError::Input(
        "callback stdin must be JSON with `state` and `code`, or exactly `STATE CODE`".to_owned(),
    ))
}

fn parse_money(value: &str) -> Result<MoneyV1> {
    let (currency, amount) = value
        .split_once(':')
        .ok_or_else(|| CliError::Input("cost ceiling must be CURRENCY:AMOUNT".to_owned()))?;
    if currency.len() != 3
        || !currency
            .chars()
            .all(|character| character.is_ascii_alphabetic())
    {
        return Err(CliError::Input(
            "currency must be a three-letter code".to_owned(),
        ));
    }
    let amount = amount
        .parse::<f64>()
        .map_err(|_| CliError::Input("cost amount is not a number".to_owned()))?;
    if !amount.is_finite() || amount < 0.0 {
        return Err(CliError::Input(
            "cost amount must be finite and non-negative".to_owned(),
        ));
    }
    Ok(MoneyV1 {
        currency: currency.to_ascii_uppercase(),
        amount,
    })
}

pub(crate) fn verification_for_status(status: PlanStatus) -> VerificationState {
    match status {
        PlanStatus::Verified | PlanStatus::Rectified => VerificationState::Passed,
        PlanStatus::Failed => VerificationState::Failed,
        PlanStatus::RectificationRequired => VerificationState::Unsupported,
        _ => VerificationState::Pending,
    }
}

fn stage_required(stage: cfctl_core::GuideStage, capability: &cfctl_core::CapabilityV1) -> bool {
    use cfctl_core::GuideStage;
    if capability.workflow.is_some() {
        return matches!(
            stage,
            GuideStage::Discover
                | GuideStage::InspectCurrentState
                | GuideStage::LoadStandards
                | GuideStage::Execute
                | GuideStage::CloseWithEvidence
        );
    }
    match stage {
        GuideStage::RequestApproval | GuideStage::Rectify => capability.mutating,
        GuideStage::CalculateCost => capability.cost.incremental || !capability.cost.known,
        GuideStage::Verify => capability.verification.required,
        _ => true,
    }
}

fn guide_document(capability: &CapabilityV1) -> CapabilityGuideV1 {
    let blocking_gaps = capability.mutation_contract_gaps();
    let contract_ready =
        capability.adapter_status != AdapterStatus::Blocked && blocking_gaps.is_empty();
    let post_resolution_call_argv = capability_call_argv(capability);
    let call_argv = contract_ready.then(|| post_resolution_call_argv.clone());
    let stages = guide_stages()
        .iter()
        .enumerate()
        .map(|(index, stage)| {
            guide_stage_document(
                index + 1,
                *stage,
                capability,
                contract_ready,
                &blocking_gaps,
                Some(&post_resolution_call_argv),
            )
        })
        .collect::<Vec<_>>();
    let blocked_reason = capability.blocked_reason.clone();
    let next_action =
        guide_next_action(capability, contract_ready, Some(&post_resolution_call_argv));
    let capability = caller_facing_capability(capability);

    CapabilityGuideV1 {
        capability,
        contract_state: if contract_ready {
            GuideContractStateV1::Available
        } else {
            GuideContractStateV1::Blocked
        },
        blocking_gaps,
        blocked_reason,
        call_argv,
        post_resolution_call_argv: post_resolution_call_argv.clone(),
        next_action,
        stages,
    }
}

/// Minimum top score for the resolver to commit to a single capability.
/// A hit below this is a description-only near-miss; the resolver reports
/// candidates but refuses to emit a call string.
const RESOLVE_MIN_CONFIDENT_SCORE: usize = 6;

/// Deterministically map a natural-language intent to a capability and the exact
/// governed commands to run. Read-only: it never mutates Cloudflare and never
/// launches an agent (that is `execute_natural_language`). It fails closed —
/// emitting only disambiguation guidance — when nothing matches confidently or
/// the top match does not clearly beat the runner-up.
async fn resolve_command(store: &StateStore, arguments: ResolveArgs) -> Result<ResultEnvelopeV2> {
    let intent = arguments.intent.trim();
    if intent.is_empty() {
        return Err(CliError::guided(
            "CFCTL_RESOLVE_EMPTY",
            "resolve needs a natural-language intent",
            "Describe the goal, e.g. `cfctl resolve \"enable email routing on example.com\"`.",
        ));
    }
    let catalog = ensure_catalog(store).await?;
    let ranked = catalog.search_scored(intent);
    let (result, error) = resolve_result(
        intent,
        &ranked,
        arguments.account.as_deref(),
        arguments.limit,
    );
    let mut envelope = ResultEnvelopeV2::success("resolve", result);
    // `error: Some` is a fail-closed resolve: mark it not-ok and surface the
    // recovery hint at the canonical envelope level, matching every other
    // failure surface. `None` means a capability was actionably resolved.
    envelope.ok = error.is_none();
    if envelope.ok {
        envelope.capability_id = envelope
            .result
            .pointer("/resolved/capability_id")
            .and_then(Value::as_str)
            .map(str::to_owned);
    }
    envelope.error = error;
    Ok(envelope)
}

/// Pure decision core for `resolve`: given the ranked catalog hits, produce the
/// result JSON and an optional `ErrorV1`. `Some(error)` means the resolve failed
/// closed (not actionable) and carries the canonical envelope-level `next_step`;
/// `None` means an actionable capability was resolved. Deterministic and
/// side-effect-free so the fail-closed gating is unit-testable without a store.
#[expect(
    clippy::too_many_lines,
    reason = "resolution keeps ambiguity, broad telemetry overviews, selector discrimination, and dangerous-mutation fail-closed behavior in one deterministic decision boundary"
)]
fn resolve_result(
    intent: &str,
    ranked: &[(&CapabilityV1, usize)],
    account: Option<&str>,
    limit: usize,
) -> (Value, Option<ErrorV1>) {
    let limit = limit.clamp(1, 25);
    let candidates: Vec<Value> = ranked
        .iter()
        .take(limit)
        .map(|(capability, score)| resolve_candidate_json(capability, *score))
        .collect();

    if is_broad_telemetry_intent(intent) {
        let telemetry_ranked = rank_telemetry_overview(intent, ranked);
        let reads = telemetry_ranked
            .iter()
            .filter(|(capability, _)| !capability.mutating && capability.workflow.is_none())
            .take(limit)
            .map(|(capability, score)| resolve_candidate_json(capability, *score))
            .collect::<Vec<_>>();
        let workflows = telemetry_ranked
            .iter()
            .filter(|(capability, _)| capability.workflow.is_some())
            .take(limit)
            .map(|(capability, score)| resolve_candidate_json(capability, *score))
            .collect::<Vec<_>>();
        let mutations = telemetry_ranked
            .iter()
            .filter(|(capability, _)| {
                capability.mutating
                    && capability.adapter_status != AdapterStatus::Blocked
                    && capability.mutation_contract_gaps().is_empty()
            })
            .take(limit)
            .map(|(capability, score)| resolve_candidate_json(capability, *score))
            .collect::<Vec<_>>();
        let blocked_gaps = telemetry_ranked
            .iter()
            .filter(|(capability, _)| {
                capability.mutating
                    && (capability.adapter_status == AdapterStatus::Blocked
                        || !capability.mutation_contract_gaps().is_empty())
            })
            .take(limit)
            .map(|(capability, score)| resolve_candidate_json(capability, *score))
            .collect::<Vec<_>>();
        return (
            json!({
                "intent": intent,
                "matched": candidates,
                "resolved": {
                    "kind": "telemetry_domain_overview",
                    "domains": ["analytics", "logs_observability", "security_response", "data_governance"],
                    "ranked_reads": reads,
                    "governed_workflows": workflows,
                    "mutation_candidates": mutations,
                    "blocked_or_unclassified_gaps": blocked_gaps,
                    "mutation_selection": "withheld_until_a_specific_capability_is_resolved_and_guided",
                    "discovery_argv": {
                        "coverage": ["cfctl", "catalog", "coverage", "--json"],
                        "search": ["cfctl", "catalog", "search", intent, "--json"]
                    }
                },
                "ambiguous": false,
                "guidance": "Broad telemetry language returns workflow-first, domain-aware discovery. Choose and inspect one typed capability; cfctl never selects an enforcement or configuration mutation from this overview, and blocked mutations remain labeled contract gaps.",
            }),
            None,
        );
    }

    // No positive-scoring capability: fail closed with discovery guidance.
    let Some((top_capability, top_score)) = ranked.first().map(|(cap, score)| (*cap, *score))
    else {
        let next_step = "Broaden the query, or run `cfctl catalog search \"<keywords>\" --json`. If the catalog is stale, run `cfctl catalog sync`.";
        let result = json!({
            "intent": intent,
            "matched": [],
            "resolved": Value::Null,
            "ambiguous": true,
            "reason": "no catalog capability matched the intent terms",
            "next_step": next_step,
            "disambiguation": {
                "search_argv": ["cfctl", "catalog", "search", intent, "--json"],
                "coverage_argv": ["cfctl", "catalog", "coverage", "--json"],
            },
        });
        let error = ErrorV1 {
            code: "CFCTL_RESOLVE_NO_MATCH".to_owned(),
            message: "no catalog capability matched the intent terms".to_owned(),
            next_step: Some(next_step.to_owned()),
        };
        return (result, Some(error));
    };

    let runner_up = ranked.get(1).map_or(0, |(_, score)| *score);
    // Commit only to a confident, unambiguous top match: score above the floor
    // and at least 1.2x the runner-up (or a sole match). Integer test avoids
    // float rounding: top/runner >= 6/5. The 1.2x margin is evidence-backed: a
    // 28-intent live-catalog study showed the top candidate is correct in ~93%
    // of cases, yet a 1.5x gate committed only 7% because near-duplicate
    // capabilities cluster; 1.2x commits clearly-dominant matches while exact
    // and near ties (below 1.2x) still fail closed.
    let confident = top_score >= RESOLVE_MIN_CONFIDENT_SCORE
        && (runner_up == 0 || top_score * 5 >= runner_up * 6);

    if !confident {
        let reason = if top_score < RESOLVE_MIN_CONFIDENT_SCORE {
            format!(
                "top match `{}` scored only {top_score}; too weak to commit",
                top_capability.id
            )
        } else {
            format!(
                "top match `{}` (score {top_score}) does not clearly beat `{}` (score {runner_up})",
                top_capability.id, ranked[1].0.id,
            )
        };
        let next_step = "Pick a candidate and inspect it: `cfctl catalog show <capability-id> --json`, then `cfctl guide <capability-id>`.";
        let result = json!({
            "intent": intent,
            "matched": candidates,
            "resolved": Value::Null,
            "ambiguous": true,
            "reason": reason.clone(),
            "next_step": next_step,
        });
        let error = ErrorV1 {
            code: "CFCTL_RESOLVE_AMBIGUOUS".to_owned(),
            message: reason,
            next_step: Some(next_step.to_owned()),
        };
        return (result, Some(error));
    }

    let (resolved, guidance) = resolve_actionable(top_capability, intent, account);
    let result = json!({
        "intent": intent,
        "matched": candidates,
        "resolved": resolved,
        "ambiguous": false,
        "guidance": guidance,
    });
    (result, None)
}

fn rank_telemetry_overview<'a>(
    intent: &str,
    ranked: &[(&'a CapabilityV1, usize)],
) -> Vec<(&'a CapabilityV1, usize)> {
    let terms = intent
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|term| !term.is_empty())
        .map(str::to_ascii_lowercase)
        .collect::<BTreeSet<_>>();
    let asks_for_audit = ["audit", "coverage", "overview", "discover"]
        .iter()
        .any(|term| terms.contains(*term));
    let mut reranked = ranked
        .iter()
        .map(|(capability, score)| {
            let mut adjusted = *score;
            if capability.workflow.is_some() {
                adjusted += 24;
            }
            if asks_for_audit {
                adjusted += match capability.id.as_str() {
                    "workflow.telemetry.audit-account" => 64,
                    "workflow.telemetry.audit-governance" => 56,
                    "workflow.telemetry.export-evidence-packet" => 48,
                    "workflow.telemetry.verify-freshness" => 40,
                    _ => 0,
                };
            }
            if capability.adapter_status == AdapterStatus::Blocked {
                adjusted = adjusted.saturating_sub(8);
            }
            (*capability, adjusted)
        })
        .collect::<Vec<_>>();
    reranked.sort_by(|(left, left_score), (right, right_score)| {
        right_score
            .cmp(left_score)
            .then_with(|| left.id.cmp(&right.id))
    });
    reranked
}

fn is_broad_telemetry_intent(intent: &str) -> bool {
    let terms = intent
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|term| !term.is_empty())
        .map(str::to_ascii_lowercase)
        .collect::<BTreeSet<_>>();
    let has_domain = ["telemetry", "analytics", "observability", "logs"]
        .iter()
        .any(|term| terms.contains(*term));
    let has_specific_discriminator = [
        "access", "bot", "browser", "cache", "ddos", "dns", "engine", "firewall", "graphql",
        "hostname", "ip", "logpull", "logpush", "pages", "rate", "rum", "security", "tail",
        "trace", "waf", "web", "worker", "zero",
    ]
    .iter()
    .any(|term| terms.contains(*term));
    let asks_for_overview = ["audit", "coverage", "discover", "overview"]
        .iter()
        .any(|term| terms.contains(*term));
    has_domain && !has_specific_discriminator && (asks_for_overview || terms.len() <= 4)
}

/// Build the `resolved` object for a confident top match: capability metadata,
/// the governed command set, and (when applicable) the zone hint and account.
/// Returns the resolved JSON and the human-facing guidance summary.
fn resolve_actionable(
    capability: &CapabilityV1,
    intent: &str,
    account: Option<&str>,
) -> (Value, String) {
    let gaps = capability.mutation_contract_gaps();
    let contract_ready = capability.adapter_status != AdapterStatus::Blocked && gaps.is_empty();
    let call_argv = capability_call_argv(capability);
    let next_action = guide_next_action(capability, contract_ready, Some(&call_argv));

    // Contract-ready: emit the exact governed command sequence. Blocked or
    // gap-incomplete: reuse guide_next_action's fail-closed guidance instead of
    // fabricating a call the agent must not run.
    let commands = if contract_ready {
        let mut commands = json!({ "draft_argv": call_argv });
        if capability.mutating {
            commands["approve_argv"] = json!(approval_command_argv(capability, "<operation-id>"));
            commands["run_argv"] = json!(["cfctl", "plans", "run", "<operation-id>", "--json"]);
            commands["status_argv"] =
                json!(["cfctl", "plans", "status", "<operation-id>", "--json"]);
        }
        commands
    } else {
        json!({
            "blocked": true,
            "blocking_gaps": gaps,
            "next_action": next_action.clone(),
        })
    };

    let mut resolved = json!({
        "capability_id": capability.id,
        "title": capability.title,
        "product": capability.product,
        "mutating": capability.mutating,
        "contract_ready": contract_ready,
        "adapter_status": capability.adapter_status,
        "required_selectors": required_selectors_json(capability),
        "needs_request_body": capability_has_meaningful_request_body(capability),
        "permission_lane": capability.permissions,
        "commands": commands,
    });
    if let Some(hint) = resolve_zone_hint(capability, intent) {
        resolved["zone_resolution_hint"] = hint;
    }
    if let Some(account) = account {
        resolved["account"] = json!(account);
    }
    (resolved, next_action.summary)
}

fn resolve_candidate_json(capability: &CapabilityV1, score: usize) -> Value {
    let contract_ready = capability.adapter_status != AdapterStatus::Blocked
        && capability.mutation_contract_gaps().is_empty();
    json!({
        "capability_id": capability.id,
        "score": score,
        "title": capability.title,
        "product": capability.product,
        "mutating": capability.mutating,
        "adapter_status": capability.adapter_status,
        "contract_ready": contract_ready,
        "show_argv": catalog_show_argv(&capability.id),
        "guide_argv": ["cfctl", "guide", capability.id.as_str(), "--json"],
    })
}

pub(crate) fn required_selectors_json(capability: &CapabilityV1) -> Vec<Value> {
    capability
        .selectors
        .iter()
        .filter(|selector| selector.required)
        .map(|selector| {
            json!({
                "name": selector.name,
                "location": selector.location,
                "value_type": selector.value_type,
                "description": selector.description,
            })
        })
        .collect()
}

/// When a capability requires a zone path selector, emit a resolve-first hint:
/// cfctl has no inline domain->zone_id resolver, so an agent must read the zone
/// id from a `/zones` list before calling. Never guesses a zone id.
fn resolve_zone_hint(capability: &CapabilityV1, intent: &str) -> Option<Value> {
    let needs_zone = capability.selectors.iter().any(|selector| {
        selector.required
            && selector.location == "path"
            && selector.name.to_ascii_lowercase().contains("zone")
    });
    if !needs_zone {
        return None;
    }
    let domain = extract_domain(intent);
    let domain_token = domain.as_deref().unwrap_or("<domain>");
    Some(json!({
        "reason": "This capability needs a 32-hex Cloudflare zone id, not a domain name.",
        "resolve_first": "Find the zone-list capability, then read the zone id from its result.",
        "search_argv": ["cfctl", "catalog", "search", "list zones", "--json"],
        "example_read_argv": [
            "cfctl", "call", "<zone-list-capability-id>", "--query", format!("name={domain_token}"), "--json"
        ],
        "use_field": "result[0].id",
    }))
}

/// Extract the first domain-like token from an intent, for zone-hint examples.
/// Deliberately conservative: no dependency on the regex crate.
fn extract_domain(intent: &str) -> Option<String> {
    intent
        .split(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '(' | ')' | ','))
        .map(|token| token.trim_matches(|c: char| !c.is_ascii_alphanumeric()))
        .find(|token| is_domain_like(token))
        .map(str::to_ascii_lowercase)
}

fn is_domain_like(token: &str) -> bool {
    if token.len() < 3 || !token.contains('.') {
        return false;
    }
    let labels: Vec<&str> = token.split('.').collect();
    if labels.len() < 2 {
        return false;
    }
    let last = labels.last().copied().unwrap_or_default();
    if last.len() < 2 || !last.chars().all(|c| c.is_ascii_alphabetic()) {
        return false;
    }
    labels.iter().all(|label| {
        !label.is_empty() && label.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
    })
}

pub(crate) fn capability_call_argv(capability: &CapabilityV1) -> Vec<String> {
    if matches!(
        capability.id.as_str(),
        "account-api-tokens-create-token" | "user-api-tokens-create-token"
    ) {
        let mut argv = vec!["cfctl", "keys", "mint"];
        if capability.id == "user-api-tokens-create-token" {
            argv.push("--user");
        }
        argv.extend([
            "--name",
            "<token-name>",
            "--permission",
            "<permission-group-id>",
            "--account",
            "<account_id>",
            "--value-out",
            "<new-mode-0600-path>",
            "--json",
        ]);
        return argv.into_iter().map(str::to_owned).collect();
    }

    let mut argv = vec!["cfctl".to_owned(), "call".to_owned(), capability.id.clone()];
    for selector in capability
        .selectors
        .iter()
        .filter(|selector| selector.required)
    {
        argv.push(
            if selector.location == "query" {
                "--query"
            } else {
                "--selector"
            }
            .to_owned(),
        );
        argv.push(format!("{}=<{}>", selector.name, selector.name));
    }
    if capability_has_meaningful_request_body(capability) {
        argv.push("--body-stdin".to_owned());
    }
    if is_secret_output_capability(capability) {
        let sink = if is_access_service_token_create_capability(capability)
            || is_r2_temporary_credentials_operation_identity(capability)
            || is_worker_tail_create_capability(capability)
        {
            "<new-mode-0600-json-path>"
        } else {
            "<new-mode-0600-path>"
        };
        argv.extend(["--value-out".to_owned(), sink.to_owned()]);
    }
    if capability.d1_full_export.is_some() {
        argv.extend(["--out".to_owned(), "<new-mode-0600-sql-path>".to_owned()]);
    }
    argv.push("--json".to_owned());
    argv
}

pub(crate) fn capability_has_meaningful_request_body(capability: &CapabilityV1) -> bool {
    let Some(schema) = capability.request_schema.as_ref() else {
        return false;
    };
    if schema.get("x-cfctl-body-required").and_then(Value::as_bool) == Some(true) {
        return true;
    }
    if capability
        .request_object_fields()
        .is_some_and(|fields| !fields.is_empty())
    {
        return true;
    }
    schema
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|value_type| value_type != "object")
}

fn guide_next_action(
    capability: &CapabilityV1,
    contract_ready: bool,
    call_argv: Option<&[String]>,
) -> GuideActionV1 {
    if contract_ready {
        let summary = if capability.mutating {
            "Create the preview plan with the exact generated argv; no Cloudflare mutation occurs until the resulting operation is run."
        } else {
            "Run the exact generated argv to produce a redacted live-read receipt."
        };
        return GuideActionV1 {
            summary: summary.to_owned(),
            argv: call_argv.unwrap_or_default().to_vec(),
        };
    }

    let gaps = capability.mutation_contract_gaps();
    let blocked_text = format!(
        "{} {}",
        capability.blocked_reason.as_deref().unwrap_or_default(),
        gaps.join(" ")
    )
    .to_ascii_lowercase();
    let (summary, argv) = if should_resolve_entitlement_probe(capability) {
        (
            "Run the exact call to perform the declared read-only product probe. A successful read is hash-bound and rechecked before execution; a rejected read leaves authorization, plan entitlement, and account configuration explicitly unresolved.",
            call_argv.unwrap_or_default().to_vec(),
        )
    } else if should_resolve_zone_entitlement(capability) {
        (
            "Run the exact call to perform the governed live zone-subscription read. cfctl creates a plan only when the active plan is allowed by the official matrix, then binds and rechecks that entitlement before execution.",
            call_argv.unwrap_or_default().to_vec(),
        )
    } else if blocked_text.contains("product-scoped subscription join key") {
        (
            "cfctl cannot safely map the account's product-scoped subscriptions to this operation's generic plan matrix because the official schema supplies no product-scoped subscription join key. Keep the operation blocked; do not treat any active account subscription as proof of entitlement.",
            vec![
                "cfctl".to_owned(),
                "docs".to_owned(),
                "search".to_owned(),
                format!("{} plans subscriptions", capability.product),
                "--json".to_owned(),
            ],
        )
    } else if blocked_text.contains("cost") {
        (
            "Resolve and bind the operation's official pricing contract before planning it.",
            vec![
                "cfctl".to_owned(),
                "docs".to_owned(),
                "search".to_owned(),
                format!("{} pricing", capability.product),
                "--json".to_owned(),
            ],
        )
    } else if blocked_text.contains("entitlement") {
        (
            "Review the official plan gate, then obtain an account-backed entitlement result before planning. Documentation identifies requirements but does not prove the selected account is entitled.",
            vec![
                "cfctl".to_owned(),
                "docs".to_owned(),
                "search".to_owned(),
                format!("{} plans", capability.product),
                "--json".to_owned(),
            ],
        )
    } else if blocked_text.contains("permission inventory")
        || blocked_text.contains("permission lane")
    {
        (
            "Inspect the fresh account permission inventory. Inventory alone does not prove that a permission group authorizes this operation; token creation must use the governed keys workflow.",
            [
                "cfctl",
                "keys",
                "permissions",
                "--account",
                "<account_id>",
                "--json",
            ]
            .map(str::to_owned)
            .to_vec(),
        )
    } else {
        (
            "Inspect the exact blocked adapter and contract metadata; do not attempt execution until every named gap is resolved.",
            vec![
                "cfctl".to_owned(),
                "catalog".to_owned(),
                "show".to_owned(),
                capability.id.clone(),
                "--json".to_owned(),
            ],
        )
    };
    GuideActionV1 {
        summary: summary.to_owned(),
        argv,
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum GuideLiveRead {
    ZoneAccount,
    ZoneEntitlement,
    ProductEntitlementProbe,
    GlobalWarpOverrideState,
    D1ReadReplicationState,
    CloudflareTunnelConfigurationState,
    WarpConnectorConfigurationState,
    WebAnalyticsRumState,
    DnsRecordState,
    OAuthClientSecretState,
    WorkerCustomDomainState,
}

fn guide_live_reads(capability: &CapabilityV1) -> Vec<GuideLiveRead> {
    [
        (
            should_bind_zone_account(capability),
            GuideLiveRead::ZoneAccount,
        ),
        (
            should_resolve_zone_entitlement(capability),
            GuideLiveRead::ZoneEntitlement,
        ),
        (
            should_resolve_entitlement_probe(capability),
            GuideLiveRead::ProductEntitlementProbe,
        ),
        (
            should_bind_global_warp_override_state(capability),
            GuideLiveRead::GlobalWarpOverrideState,
        ),
        (
            should_bind_d1_read_replication_state(capability),
            GuideLiveRead::D1ReadReplicationState,
        ),
        (
            should_bind_cloudflare_tunnel_configuration_state(capability),
            GuideLiveRead::CloudflareTunnelConfigurationState,
        ),
        (
            should_bind_warp_connector_configuration_state(capability),
            GuideLiveRead::WarpConnectorConfigurationState,
        ),
        (
            should_bind_web_analytics_rum_state(capability),
            GuideLiveRead::WebAnalyticsRumState,
        ),
        (
            should_bind_dns_record_state(capability),
            GuideLiveRead::DnsRecordState,
        ),
        (
            should_bind_oauth_client_secret_state(capability),
            GuideLiveRead::OAuthClientSecretState,
        ),
        (
            worker_custom_domain::should_bind_state(capability),
            GuideLiveRead::WorkerCustomDomainState,
        ),
    ]
    .into_iter()
    .filter_map(|(required, read)| required.then_some(read))
    .collect()
}

fn guide_stage_contract_state(
    stage: cfctl_core::GuideStage,
    capability: &CapabilityV1,
    contract_ready: bool,
    blocking_gaps: &[String],
    live_reads: &[GuideLiveRead],
) -> GuideContractStateV1 {
    use cfctl_core::GuideStage;

    if capability.workflow.is_some() {
        return if matches!(
            stage,
            GuideStage::Discover
                | GuideStage::InspectCurrentState
                | GuideStage::LoadStandards
                | GuideStage::Execute
                | GuideStage::CloseWithEvidence
        ) {
            GuideContractStateV1::Available
        } else {
            GuideContractStateV1::NotApplicable
        };
    }

    let entitlement_blocked = capability.entitlement.available == Some(false)
        || blocking_gaps.iter().any(|gap| gap.contains("entitlement"));
    let entitlement_unresolved = capability.mutating
        && capability.entitlement.available != Some(true)
        && capability.entitlement.plans.is_empty();
    match stage {
        GuideStage::SelectAccount if live_reads.contains(&GuideLiveRead::ZoneAccount) => {
            GuideContractStateV1::LiveReadRequired
        }
        GuideStage::CheckEntitlement
            if live_reads.contains(&GuideLiveRead::ZoneEntitlement)
                || live_reads.contains(&GuideLiveRead::ProductEntitlementProbe) =>
        {
            GuideContractStateV1::LiveReadRequired
        }
        GuideStage::InspectCurrentState
            if live_reads.iter().any(|read| {
                matches!(
                    read,
                    GuideLiveRead::GlobalWarpOverrideState
                        | GuideLiveRead::D1ReadReplicationState
                        | GuideLiveRead::CloudflareTunnelConfigurationState
                        | GuideLiveRead::WarpConnectorConfigurationState
                        | GuideLiveRead::WebAnalyticsRumState
                        | GuideLiveRead::DnsRecordState
                        | GuideLiveRead::OAuthClientSecretState
                        | GuideLiveRead::WorkerCustomDomainState
                )
            }) =>
        {
            GuideContractStateV1::LiveReadRequired
        }
        GuideStage::CheckEntitlement if entitlement_blocked => GuideContractStateV1::Blocked,
        GuideStage::CheckEntitlement if entitlement_unresolved => {
            GuideContractStateV1::ManualReview
        }
        GuideStage::CalculateCost if capability.mutating && !capability.cost.known => {
            GuideContractStateV1::Blocked
        }
        GuideStage::CalculateCost
        | GuideStage::BuildPlan
        | GuideStage::RequestApproval
        | GuideStage::AcquireLocks
        | GuideStage::Rectify
            if !capability.mutating =>
        {
            GuideContractStateV1::NotApplicable
        }
        GuideStage::BuildPlan
        | GuideStage::RequestApproval
        | GuideStage::AcquireLocks
        | GuideStage::Execute
            if !contract_ready =>
        {
            GuideContractStateV1::Blocked
        }
        GuideStage::Verify
            if !capability.verification_contract_declared()
                || !capability.verification_contract_supported() =>
        {
            GuideContractStateV1::Blocked
        }
        GuideStage::Verify if !capability.verification.required => {
            GuideContractStateV1::NotApplicable
        }
        GuideStage::Rectify
            if !capability.rollback_contract_declared()
                || !capability.rollback_contract_supported() =>
        {
            GuideContractStateV1::Blocked
        }
        GuideStage::CloseWithEvidence if capability.mutating && !contract_ready => {
            GuideContractStateV1::Blocked
        }
        _ => GuideContractStateV1::Available,
    }
}

fn guide_live_read_summary(
    stage: cfctl_core::GuideStage,
    live_reads: &[GuideLiveRead],
) -> Option<&'static str> {
    use cfctl_core::GuideStage;

    match stage {
        GuideStage::SelectAccount if live_reads.contains(&GuideLiveRead::ZoneAccount) => Some(
            "Read the exact live zone details and require its account ID to match the selected account.",
        ),
        GuideStage::CheckEntitlement if live_reads.contains(&GuideLiveRead::ZoneEntitlement) => {
            Some(
                "Read the exact live zone subscription and evaluate its active plan against the official availability matrix.",
            )
        }
        GuideStage::CheckEntitlement
            if live_reads.contains(&GuideLiveRead::ProductEntitlementProbe) =>
        {
            Some(
                "Run the declared read-only product capability. A successful response proves present API access; a rejection remains ambiguous between token permission, plan entitlement, and account configuration.",
            )
        }
        GuideStage::InspectCurrentState
            if live_reads.contains(&GuideLiveRead::GlobalWarpOverrideState) =>
        {
            Some(
                "Read and bind the exact live account-wide disconnect state; execution repeats this read and rejects drift before crossing the mutation boundary.",
            )
        }
        GuideStage::InspectCurrentState
            if live_reads.contains(&GuideLiveRead::D1ReadReplicationState) =>
        {
            Some(
                "Read and bind the exact live database read-replication mode; execution repeats this read and rejects drift before crossing the mutation boundary.",
            )
        }
        GuideStage::InspectCurrentState
            if live_reads.contains(&GuideLiveRead::CloudflareTunnelConfigurationState) =>
        {
            Some(
                "Read and bind the exact live remotely managed Tunnel routing configuration; execution repeats this read and rejects drift before replacing any ingress rule.",
            )
        }
        GuideStage::InspectCurrentState
            if live_reads.contains(&GuideLiveRead::WarpConnectorConfigurationState) =>
        {
            Some(
                "Read and bind the exact live WARP Connector high-availability mode and provider configuration; execution repeats this read and rejects drift before changing Cloudflare Mesh failover behavior.",
            )
        }
        GuideStage::InspectCurrentState
            if live_reads.contains(&GuideLiveRead::WebAnalyticsRumState) =>
        {
            Some(
                "Read and bind the exact live editable Web Analytics RUM on/off value; execution repeats this read and rejects manual state or drift before changing zone-wide data collection.",
            )
        }
        GuideStage::InspectCurrentState if live_reads.contains(&GuideLiveRead::DnsRecordState) => {
            Some(
                "Read and bind the exact live writable DNS record state; execution repeats this read and rejects drift before crossing the mutation boundary.",
            )
        }
        GuideStage::InspectCurrentState
            if live_reads.contains(&GuideLiveRead::WorkerCustomDomainState) =>
        {
            Some(
                "Read and bind the active zone and exact Worker settings, then require the hostname to be absent from both Worker custom domains and DNS records; execution repeats all four reads and rejects drift before attachment.",
            )
        }
        _ => None,
    }
}

fn guide_stage_uses_live_read(stage: cfctl_core::GuideStage, live_reads: &[GuideLiveRead]) -> bool {
    use cfctl_core::GuideStage;

    match stage {
        GuideStage::SelectAccount => live_reads.contains(&GuideLiveRead::ZoneAccount),
        GuideStage::CheckEntitlement => {
            live_reads.contains(&GuideLiveRead::ZoneEntitlement)
                || live_reads.contains(&GuideLiveRead::ProductEntitlementProbe)
        }
        GuideStage::InspectCurrentState => live_reads.iter().any(|read| {
            matches!(
                read,
                GuideLiveRead::GlobalWarpOverrideState
                    | GuideLiveRead::D1ReadReplicationState
                    | GuideLiveRead::CloudflareTunnelConfigurationState
                    | GuideLiveRead::WarpConnectorConfigurationState
                    | GuideLiveRead::WebAnalyticsRumState
                    | GuideLiveRead::DnsRecordState
                    | GuideLiveRead::WorkerCustomDomainState
            )
        }),
        _ => false,
    }
}

fn guide_stage_document(
    number: usize,
    stage: cfctl_core::GuideStage,
    capability: &CapabilityV1,
    contract_ready: bool,
    blocking_gaps: &[String],
    call_argv: Option<&[String]>,
) -> CapabilityGuideStageV1 {
    let live_reads = guide_live_reads(capability);
    let contract_state = guide_stage_contract_state(
        stage,
        capability,
        contract_ready,
        blocking_gaps,
        &live_reads,
    );
    let summary = guide_live_read_summary(stage, &live_reads)
        .unwrap_or_else(|| guide_stage_summary(stage, capability));
    let evidence_class = if capability.workflow.is_some() {
        if matches!(
            stage,
            cfctl_core::GuideStage::Discover | cfctl_core::GuideStage::LoadStandards
        ) {
            EvidenceClass::SourceConfig
        } else {
            EvidenceClass::AgentAction
        }
    } else if guide_stage_uses_live_read(stage, &live_reads) {
        EvidenceClass::LiveRead
    } else {
        guide_stage_evidence_class(stage, capability.mutating)
    };
    CapabilityGuideStageV1 {
        stage: number,
        name: stage,
        capability_id: capability.id.clone(),
        required: stage_required(stage, capability),
        contract_state,
        summary: summary.to_owned(),
        evidence_class,
        commands: guide_stage_commands(stage, capability, contract_state, call_argv),
    }
}

fn guide_stage_summary(stage: cfctl_core::GuideStage, capability: &CapabilityV1) -> &'static str {
    use cfctl_core::GuideStage;

    if capability.workflow.is_some() {
        return match stage {
            GuideStage::Discover => {
                "Inspect the workflow outcome, component graph, selector handoffs, and component approval boundaries."
            }
            GuideStage::InspectCurrentState => {
                "Preview the workflow against the local operational-proof index; no Cloudflare boundary is crossed."
            }
            GuideStage::LoadStandards => {
                "Load current official product documentation for the workflow's component capabilities."
            }
            GuideStage::Execute => {
                "Generate the workflow preview and exact component commands. Run bounded reads individually; mutations remain separate plans."
            }
            GuideStage::CloseWithEvidence => {
                "Use the preview receipt and any exported receipt-only manifest without treating artifact presence as verification."
            }
            _ => "This generic capability stage does not apply to a preview-only native workflow.",
        };
    }

    let mutating = capability.mutating;

    match stage {
        GuideStage::Discover => {
            "Inspect the catalog contract and adapter classification selected for this capability."
        }
        GuideStage::Authenticate => {
            "Confirm that the selected profile has a usable credential without exposing its value."
        }
        GuideStage::SelectAccount => {
            "Reconcile the explicit account, profile pin, and registered workspace pin; ambiguity fails closed."
        }
        GuideStage::CheckEntitlement => {
            "Inspect the official plan matrix. When live resolution is required, catalog metadata alone does not prove the selected account's entitlement."
        }
        GuideStage::InspectCurrentState if mutating => {
            "Audit registered-workspace state before deriving impact; use an operation-specific Cloudflare read or verifier rather than infer live state from local configuration."
        }
        GuideStage::InspectCurrentState => {
            "Run the capability as a redacted live read to inspect current Cloudflare state."
        }
        GuideStage::LoadStandards => {
            "Load current official product documentation and changelog context."
        }
        GuideStage::MapDependencies => {
            "Map exact local IaC references and affected registered repositories."
        }
        GuideStage::CalculateCost => {
            "Use the bound cost model and official pricing references; unknown or unbounded cost remains blocked."
        }
        GuideStage::BuildPlan => {
            "Create a hash-bound preview plan from the exact selectors, request body, workspace impact, and safety contracts."
        }
        GuideStage::RequestApproval => {
            "Review the plan, then bind approval and any cost ceiling to its exact operation ID."
        }
        GuideStage::AcquireLocks => {
            "Revalidate catalog, account, request, and workspace hashes before acquiring execution locks."
        }
        GuideStage::Execute if mutating => {
            "Cross the Cloudflare write boundary only through the exact durable operation ID."
        }
        GuideStage::Execute => {
            "Perform the redacted live read through the catalog-selected adapter."
        }
        GuideStage::Verify
            if capability.verification.strategy == "sink_write_and_source_response_status" =>
        {
            "Treat Cloudflare success plus the durable sink-only secret receipt as the terminal verification; no readback can prove the new credential value."
        }
        GuideStage::Verify => {
            "Require operation-specific post-change verification before declaring success."
        }
        GuideStage::Rectify => {
            "Use only the declared compensation contract and hash-bound boundary receipts."
        }
        GuideStage::CloseWithEvidence => {
            "Close only with final durable status and content-addressed evidence."
        }
    }
}

fn guide_stage_evidence_class(stage: cfctl_core::GuideStage, mutating: bool) -> EvidenceClass {
    use cfctl_core::GuideStage;

    match stage {
        GuideStage::Discover
        | GuideStage::CheckEntitlement
        | GuideStage::LoadStandards
        | GuideStage::MapDependencies
        | GuideStage::CalculateCost => EvidenceClass::SourceConfig,
        GuideStage::InspectCurrentState | GuideStage::Execute if !mutating => {
            EvidenceClass::LiveRead
        }
        GuideStage::Authenticate
        | GuideStage::SelectAccount
        | GuideStage::InspectCurrentState
        | GuideStage::AcquireLocks
        | GuideStage::CloseWithEvidence => EvidenceClass::LocalProof,
        GuideStage::BuildPlan | GuideStage::RequestApproval => EvidenceClass::Preview,
        GuideStage::Execute | GuideStage::Rectify => EvidenceClass::Apply,
        GuideStage::Verify => EvidenceClass::PostChangeVerification,
    }
}

fn operation_specific_current_state_command(capability: &CapabilityV1) -> Option<Vec<String>> {
    if worker_custom_domain::should_bind_state(capability) {
        return Some(worker_custom_domain::current_state_command());
    }
    if should_bind_global_warp_override_state(capability) {
        return Some(vec![
            "cfctl".to_owned(),
            "call".to_owned(),
            GLOBAL_WARP_OVERRIDE_READ_CAPABILITY_ID.to_owned(),
            "--selector".to_owned(),
            "account_id=<account_id>".to_owned(),
            "--json".to_owned(),
        ]);
    }
    if should_bind_d1_read_replication_state(capability) {
        return Some(vec![
            "cfctl".to_owned(),
            "call".to_owned(),
            D1_READ_REPLICATION_READ_CAPABILITY_ID.to_owned(),
            "--selector".to_owned(),
            "account_id=<account_id>".to_owned(),
            "--selector".to_owned(),
            "database_id=<database_id>".to_owned(),
            "--json".to_owned(),
        ]);
    }
    if should_bind_cloudflare_tunnel_configuration_state(capability) {
        return Some(vec![
            "cfctl".to_owned(),
            "call".to_owned(),
            CLOUDFLARE_TUNNEL_CONFIGURATION_READ_CAPABILITY_ID.to_owned(),
            "--selector".to_owned(),
            "account_id=<account_id>".to_owned(),
            "--selector".to_owned(),
            "tunnel_id=<tunnel_id>".to_owned(),
            "--json".to_owned(),
        ]);
    }
    if should_bind_warp_connector_configuration_state(capability) {
        return Some(vec![
            "cfctl".to_owned(),
            "call".to_owned(),
            WARP_CONNECTOR_CONFIGURATION_READ_CAPABILITY_ID.to_owned(),
            "--selector".to_owned(),
            "account_id=<account_id>".to_owned(),
            "--selector".to_owned(),
            "tunnel_id=<tunnel_id>".to_owned(),
            "--json".to_owned(),
        ]);
    }
    if should_bind_web_analytics_rum_state(capability) {
        return Some(vec![
            "cfctl".to_owned(),
            "call".to_owned(),
            WEB_ANALYTICS_RUM_READ_CAPABILITY_ID.to_owned(),
            "--selector".to_owned(),
            "zone_id=<zone_id>".to_owned(),
            "--json".to_owned(),
        ]);
    }
    if should_bind_dns_record_state(capability) {
        return Some(vec![
            "cfctl".to_owned(),
            "call".to_owned(),
            DNS_RECORD_DETAIL_READ_CAPABILITY_ID.to_owned(),
            "--selector".to_owned(),
            "zone_id=<zone_id>".to_owned(),
            "--selector".to_owned(),
            "dns_record_id=<dns_record_id>".to_owned(),
            "--json".to_owned(),
        ]);
    }
    (should_bind_oauth_client_secret_state(capability)
        || should_bind_oauth_client_update_state(capability))
    .then(|| {
        vec![
            "cfctl".to_owned(),
            "call".to_owned(),
            OAUTH_CLIENT_DETAIL_READ_CAPABILITY_ID.to_owned(),
            "--selector".to_owned(),
            "account_id=<account_id>".to_owned(),
            "--selector".to_owned(),
            "oauth_client_id=<oauth_client_id>".to_owned(),
            "--json".to_owned(),
        ]
    })
}

fn guide_stage_commands(
    stage: cfctl_core::GuideStage,
    capability: &CapabilityV1,
    contract_state: GuideContractStateV1,
    call_argv: Option<&[String]>,
) -> Vec<Vec<String>> {
    use cfctl_core::GuideStage;

    let available = contract_state == GuideContractStateV1::Available;
    let conditional =
        |command: Option<Vec<String>>| available.then_some(command).flatten().into_iter().collect();
    if capability.workflow.is_some() {
        return match stage {
            GuideStage::Discover => vec![catalog_show_argv(&capability.id)],
            GuideStage::InspectCurrentState | GuideStage::Execute => {
                conditional(call_argv.map(<[String]>::to_vec))
            }
            GuideStage::LoadStandards => vec![vec![
                "cfctl".to_owned(),
                "docs".to_owned(),
                "search".to_owned(),
                capability.product.clone(),
                "--json".to_owned(),
            ]],
            _ => Vec::new(),
        };
    }
    match stage {
        GuideStage::SelectAccount | GuideStage::CheckEntitlement
            if contract_state == GuideContractStateV1::LiveReadRequired =>
        {
            call_argv.map(<[String]>::to_vec).into_iter().collect()
        }
        GuideStage::Discover | GuideStage::CheckEntitlement | GuideStage::CalculateCost => {
            vec![catalog_show_argv(&capability.id)]
        }
        GuideStage::Authenticate => vec![argv(&["cfctl", "auth", "status", "default", "--json"])],
        GuideStage::SelectAccount => vec![
            argv(&["cfctl", "auth", "profiles", "--json"]),
            argv(&["cfctl", "workspace", "graph", "--json"]),
        ],
        GuideStage::InspectCurrentState if !capability.mutating => {
            conditional(call_argv.map(<[String]>::to_vec))
        }
        GuideStage::InspectCurrentState => operation_specific_current_state_command(capability)
            .map_or_else(
                || vec![argv(&["cfctl", "workspace", "audit", "--json"])],
                |command| vec![command],
            ),
        GuideStage::LoadStandards => vec![vec![
            "cfctl".to_owned(),
            "docs".to_owned(),
            "search".to_owned(),
            capability.product.clone(),
            "--json".to_owned(),
        ]],
        GuideStage::MapDependencies => {
            vec![argv(&["cfctl", "workspace", "graph", "--json"])]
        }
        GuideStage::RequestApproval => {
            conditional(Some(approval_command_argv(capability, "<operation-id>")))
        }
        GuideStage::AcquireLocks => conditional(Some(argv(&[
            "cfctl",
            "plans",
            "show",
            "<operation-id>",
            "--json",
        ]))),
        GuideStage::Execute if capability.mutating => conditional(Some(argv(&[
            "cfctl",
            "plans",
            "run",
            "<operation-id>",
            "--json",
        ]))),
        GuideStage::BuildPlan | GuideStage::Execute => {
            conditional(call_argv.map(<[String]>::to_vec))
        }
        GuideStage::Verify => conditional(Some(argv(&[
            "cfctl",
            "plans",
            "status",
            "<operation-id>",
            "--json",
        ]))),
        GuideStage::Rectify => conditional(Some(argv(&[
            "cfctl",
            "plans",
            "rectify",
            "<operation-id>",
            "--json",
        ]))),
        GuideStage::CloseWithEvidence if capability.mutating => conditional(Some(argv(&[
            "cfctl",
            "plans",
            "status",
            "<operation-id>",
            "--json",
        ]))),
        GuideStage::CloseWithEvidence => Vec::new(),
    }
}

fn approval_command_argv(capability: &CapabilityV1, operation_id: &str) -> Vec<String> {
    let mut command = ["cfctl", "plans", "approve"].map(str::to_owned).to_vec();
    command.extend([operation_id.to_owned(), "--yes".to_owned()]);
    if capability.cost.incremental
        && capability.cost.known
        && let (Some(currency), Some(maximum)) =
            (&capability.cost.currency, capability.cost.maximum)
    {
        command.extend([
            "--max-cost".to_owned(),
            format!("{}:{maximum}", currency.to_ascii_uppercase()),
        ]);
    }
    command.push("--json".to_owned());
    command
}

fn argv(parts: &[&str]) -> Vec<String> {
    parts.iter().map(|part| (*part).to_owned()).collect()
}

fn catalog_show_argv(capability_id: &str) -> Vec<String> {
    vec![
        "cfctl".to_owned(),
        "catalog".to_owned(),
        "show".to_owned(),
        capability_id.to_owned(),
        "--json".to_owned(),
    ]
}

fn preflight_secret_sink(plan: &PlanV1) -> Result<()> {
    if !is_secret_output_plan(plan) {
        return Ok(());
    }
    let path = secret_sink_path(plan)?;
    if path.exists() {
        return Err(CliError::Input(format!(
            "secret sink already exists and will not be overwritten: {}",
            path.display()
        )));
    }
    let parent = path
        .parent()
        .ok_or_else(|| CliError::Input("secret sink has no parent directory".to_owned()))?;
    if !is_oauth_client_create_operation_identity(&plan.capability) {
        return fs::create_dir_all(parent).map_err(|source| cli_io(parent, source));
    }
    if !path.is_absolute() {
        return Err(CliError::Input(
            "OAuth client --value-out must be an absolute path under a pre-existing mode-0700 operator-secret directory outside every Git repository"
                .to_owned(),
        ));
    }
    let canonical_parent = fs::canonicalize(parent).map_err(|source| cli_io(parent, source))?;
    if canonical_parent
        .ancestors()
        .any(|ancestor| ancestor.join(".git").exists())
    {
        return Err(CliError::Input(
            "OAuth client secret output is forbidden inside a Git repository".to_owned(),
        ));
    }
    let metadata =
        fs::metadata(&canonical_parent).map_err(|source| cli_io(&canonical_parent, source))?;
    if !metadata.is_dir() {
        return Err(CliError::Input(
            "OAuth client secret output parent is not a directory".to_owned(),
        ));
    }
    #[cfg(unix)]
    if metadata.permissions().mode() & 0o777 != 0o700 {
        return Err(CliError::Input(format!(
            "OAuth client secret output parent {} must have mode 0700",
            canonical_parent.display()
        )));
    }
    #[cfg(not(unix))]
    return Err(CliError::Input(
        "OAuth client creation requires a platform where cfctl can prove a mode-0700 operator-secret directory"
            .to_owned(),
    ));
    #[cfg(unix)]
    Ok(())
}

fn resolved_plan_input(plan: &PlanV1, secrets: &dyn SecretStore) -> Result<CallInput> {
    let mut input: CallInput = serde_json::from_value(plan.input.clone())?;
    let Some(reference) = plan_secret_body_ref(plan) else {
        return Ok(input);
    };
    let encoded = secrets.get(reference)?.ok_or_else(|| {
        CliError::Input(
            "the plan's secret request body is missing from the platform credential store"
                .to_owned(),
        )
    })?;
    let body: Value = serde_json::from_str(&encoded)?;
    let expected_hash = plan
        .targets
        .pointer("/adapter/secret_body_hash")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("secret request body hash is missing from the plan".to_owned())
        })?;
    if hash_value(&body)? != expected_hash {
        return Err(CliError::Input(
            "the secret request body drifted after planning; approval is invalid".to_owned(),
        ));
    }
    input.body = Some(body);
    Ok(input)
}

fn plan_secret_body_ref(plan: &PlanV1) -> Option<&str> {
    plan.targets
        .pointer("/adapter/secret_body_ref")
        .and_then(Value::as_str)
}

fn sink_secret_result(plan: &PlanV1, result: &Value) -> Result<PathBuf> {
    let payload = secret_sink_payload(&plan.capability, result)?;
    let path = secret_sink_path(plan)?;
    let mut options = fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let mut file = options
        .open(&path)
        .map_err(|source| cli_io(&path, source))?;
    file.write_all(&payload)
        .map_err(|source| cli_io(&path, source))?;
    file.sync_all().map_err(|source| cli_io(&path, source))?;
    Ok(path)
}

fn secret_sink_payload(capability: &CapabilityV1, result: &Value) -> Result<Vec<u8>> {
    if is_worker_tail_create_capability(capability) {
        let required = |field: &'static str| {
            result
                .get(field)
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    CliError::Input(format!(
                        "Cloudflare reported Worker tail creation success without non-empty `{field}`; no lease sink was created and the operation requires rectification"
                    ))
                })
        };
        return Ok(serde_json::to_vec(&json!({
            "expires_at": required("expires_at")?,
            "id": required("id")?,
            "url": required("url")?,
        }))?);
    }
    if is_r2_temporary_credentials_operation_identity(capability) {
        let required = |field: &'static str| {
            result
                .get(field)
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    CliError::Input(format!(
                        "Cloudflare reported R2 temporary-credential success without non-empty `{field}`; no credential sink was created and the operation requires rectification"
                    ))
                })
        };
        let access_key_id = required("accessKeyId")?;
        let secret_access_key = required("secretAccessKey")?;
        let session_token = required("sessionToken")?;
        return Ok(serde_json::to_vec(&json!({
            "accessKeyId": access_key_id,
            "secretAccessKey": secret_access_key,
            "sessionToken": session_token,
        }))?);
    }
    if is_access_service_token_create_capability(capability) {
        let client_id = result
            .get("client_id")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| {
                CliError::Input(
                    "Cloudflare reported Access service-token creation success without a non-empty client_id; no credential sink was created and the operation requires rectification"
                        .to_owned(),
                )
            })?;
        let client_secret = result
            .get("client_secret")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| {
                CliError::Input(
                    "Cloudflare reported Access service-token creation success without a non-empty client_secret; no credential sink was created and the operation requires rectification"
                        .to_owned(),
                )
            })?;
        return Ok(serde_json::to_vec(&json!({
            "client_id": client_id,
            "client_secret": client_secret,
        }))?);
    }
    if is_oauth_client_create_operation_identity(capability) {
        let client_id = result
            .get("client_id")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| {
                CliError::Input(
                    "Cloudflare reported OAuth client creation success without a non-empty client_id; no credential sink was created and the operation requires rectification"
                        .to_owned(),
                )
            })?;
        let client_secret = result
            .get("client_secret")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| {
                CliError::Input(
                    "Cloudflare omitted the required OAuth client secret; no credential sink was created and the operation requires rectification"
                        .to_owned(),
                )
            })?;
        return Ok(serde_json::to_vec(&json!({
            "client_id":client_id,
            "client_secret":client_secret,
        }))?);
    }

    let Some(secret) = find_secret_value(result) else {
        return Err(CliError::Input(
            "Cloudflare reported success but no one-time credential value was present; the operation requires rectification"
                .to_owned(),
        ));
    };
    Ok(secret.as_bytes().to_vec())
}

fn is_access_service_token_create_capability(capability: &CapabilityV1) -> bool {
    let exact_operation = matches!(
        (
            capability.id.as_str(),
            capability.path.as_str(),
            capability.product.as_str(),
            capability.account_scope.as_str(),
        ),
        (
            "access-service-tokens-create-a-service-token",
            "/accounts/{account_id}/access/service_tokens",
            "Access service tokens",
            "account",
        ) | (
            "zone-level-access-service-tokens-create-a-service-token",
            "/zones/{zone_id}/access/service_tokens",
            "Zone-Level Access service tokens",
            "zone",
        )
    );
    exact_operation
        && capability.method == "POST"
        && capability.permissions == ["Access: Service Tokens Write"]
}

fn secret_sink_format(capability: &CapabilityV1) -> Option<&'static str> {
    if !is_secret_output_capability(capability) {
        None
    } else if is_worker_tail_create_capability(capability) {
        Some("worker_tail_lease_json")
    } else if is_r2_temporary_credentials_operation_identity(capability) {
        Some("r2_temporary_credentials_json")
    } else if is_access_service_token_create_capability(capability) {
        Some("access_service_token_json")
    } else if is_oauth_client_create_operation_identity(capability) {
        Some("oauth_client_json")
    } else {
        Some("opaque_text")
    }
}

fn secret_sink_path(plan: &PlanV1) -> Result<PathBuf> {
    plan.targets
        .pointer("/adapter/value_out")
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .ok_or_else(|| CliError::Input("secret-producing plan has no value_out sink".to_owned()))
}

fn is_secret_output_plan(plan: &PlanV1) -> bool {
    is_secret_output_capability(&plan.capability)
}

fn is_secret_output_capability(capability: &CapabilityV1) -> bool {
    (capability.risk == RiskClass::SecretSensitive
        && !is_worker_script_secret_input_only_capability(capability))
        || is_access_service_token_create_capability(capability)
        || is_r2_temporary_credentials_operation_identity(capability)
        || is_oauth_client_create_operation_identity(capability)
}

fn should_redact_secret_response(capability: &CapabilityV1) -> bool {
    capability.risk == RiskClass::SecretSensitive
        || is_access_service_token_create_capability(capability)
        || is_r2_temporary_credentials_operation_identity(capability)
        || is_oauth_client_create_operation_identity(capability)
}

fn is_worker_tail_create_capability(capability: &CapabilityV1) -> bool {
    capability.id == "worker-tail-logs-start-tail"
        && capability.method == "POST"
        && capability.path == "/accounts/{account_id}/workers/scripts/{script_name}/tails"
        && capability.product == "Worker Tail Logs"
        && capability.account_scope == "account"
        && capability.permissions == ["Workers Tail Read", "Workers Scripts Write"]
        && capability.verification.strategy == "worker_tail_collection_contains_created_lease_id"
}

fn is_worker_tail_response_capability(capability: &CapabilityV1) -> bool {
    is_worker_tail_create_capability(capability)
        || (capability.id == "worker-tail-logs-list-tails"
            && capability.method == "GET"
            && capability.path == "/accounts/{account_id}/workers/scripts/{script_name}/tails"
            && capability.product == "Worker Tail Logs"
            && capability.account_scope == "account"
            && capability.permissions == ["Workers Tail Read"])
}

fn is_worker_script_secret_input_only_capability(capability: &CapabilityV1) -> bool {
    capability.id == "worker-put-script-secret"
        && capability.method == "PUT"
        && capability.path == "/accounts/{account_id}/workers/scripts/{script_name}/secrets"
        && capability.product == "Worker Script"
        && capability.permissions == ["Workers Scripts Write"]
        && capability.verification.strategy
            == "worker_script_secret_reports_planned_name_and_type_after_put"
        && capability.request_object_field_is_write_only("text")
        && capability.request_object_field_is_write_only("key_base64")
        && capability.request_object_field_is_write_only("key_jwk")
}

fn find_secret_value(value: &Value) -> Option<&str> {
    if let Some(value) = value.as_str() {
        return Some(value);
    }
    if let Some(object) = value.as_object() {
        for key in cfctl_core::SECRET_SINK_VALUE_KEYS.iter().copied() {
            if let Some(candidate) = object.get(key) {
                if let Some(value) = candidate.as_str() {
                    return Some(value);
                }
                if (candidate.is_object() || candidate.is_array())
                    && let Some(value) = find_secret_value(candidate)
                {
                    return Some(value);
                }
            }
        }
        return object
            .values()
            .filter(|candidate| candidate.is_object() || candidate.is_array())
            .find_map(find_secret_value);
    }
    value.as_array()?.iter().find_map(find_secret_value)
}

fn redact_secret_result(value: &Value) -> Value {
    if let Value::Object(object) = value {
        let mut redacted = object.clone();
        if let Some(result) = object.get("result") {
            redacted.insert("result".to_owned(), redact_secret_payload(result, true));
        }
        return Value::Object(redacted);
    }
    redact_secret_payload(value, true)
}

fn redact_response_for_capability(capability: &CapabilityV1, value: &Value) -> Value {
    let redacted = if should_redact_secret_response(capability) {
        redact_secret_result(value)
    } else {
        value.clone()
    };
    if is_worker_tail_response_capability(capability) {
        redact_field_recursively(&redacted, "url")
    } else {
        redacted
    }
}

fn redact_field_recursively(value: &Value, field: &str) -> Value {
    match value {
        Value::Object(object) => Value::Object(
            object
                .iter()
                .map(|(key, item)| {
                    if key == field {
                        (key.clone(), Value::String("[SUNK]".to_owned()))
                    } else {
                        (key.clone(), redact_field_recursively(item, field))
                    }
                })
                .collect(),
        ),
        Value::Array(values) => Value::Array(
            values
                .iter()
                .map(|item| redact_field_recursively(item, field))
                .collect(),
        ),
        _ => value.clone(),
    }
}

fn redact_secret_payload(value: &Value, root: bool) -> Value {
    match value {
        Value::Object(object) => Value::Object(
            object
                .iter()
                .map(|(key, item)| {
                    // Single-sourced against `cfctl_core::SECRET_FIELD_NAMES`;
                    // the `secret_payload_redaction_mirrors_the_core_set` test
                    // binds the two so this arm set cannot drift.
                    if cfctl_core::SECRET_FIELD_NAMES.contains(&key.as_str()) {
                        (key.clone(), Value::String("[SUNK]".to_owned()))
                    } else {
                        (key.clone(), redact_secret_payload(item, false))
                    }
                })
                .collect(),
        ),
        Value::Array(values) => Value::Array(
            values
                .iter()
                .map(|item| redact_secret_payload(item, true))
                .collect(),
        ),
        Value::String(_) if root => Value::String("[SUNK]".to_owned()),
        _ => value.clone(),
    }
}

fn catalog_is_stale(store: &StateStore) -> bool {
    fs::metadata(store.paths().catalog_file())
        .ok()
        .and_then(|metadata| metadata.modified().ok())
        .and_then(|modified| modified.elapsed().ok())
        .is_none_or(|age| age > Duration::from_hours(24))
}

fn http_client() -> Result<reqwest::Client> {
    let mut builder = reqwest::Client::builder()
        .connect_timeout(Duration::from_secs(10))
        .timeout(Duration::from_mins(2))
        .user_agent(concat!("cfctl/", env!("CARGO_PKG_VERSION")));
    // IP-allowlisted API tokens (e.g. a laptop-pinned minter) are usually
    // scoped to the machine's IPv4. When the host default-routes over IPv6,
    // Cloudflare rejects the call with error 9109 ("Cannot use the access
    // token from location: <IPv6>"). `CFCTL_FORCE_IPV4=1` binds egress to an
    // IPv4 source so those tokens work — including unattended (launchd) runs
    // that can't fall back to an interactive `curl -4`.
    if force_ipv4_egress() {
        builder = builder.local_address(std::net::IpAddr::V4(std::net::Ipv4Addr::UNSPECIFIED));
    }
    Ok(builder.build()?)
}

/// True when `CFCTL_FORCE_IPV4` is set to an affirmative value. Off by default
/// so IPv6-only hosts and non-allowlisted tokens are unaffected.
fn force_ipv4_egress() -> bool {
    force_ipv4_from(std::env::var("CFCTL_FORCE_IPV4").ok().as_deref())
}

fn force_ipv4_from(value: Option<&str>) -> bool {
    matches!(value, Some("1" | "true" | "yes" | "on"))
}

fn configured_agent() -> Result<AgentKind> {
    match env::var("CFCTL_AGENT")
        .unwrap_or_else(|_| "codex".to_owned())
        .to_ascii_lowercase()
        .as_str()
    {
        "codex" => Ok(AgentKind::Codex),
        "claude" | "claude-code" => Ok(AgentKind::Claude),
        "cursor" => Ok(AgentKind::Cursor),
        "gemini" => Ok(AgentKind::Gemini),
        value => Err(CliError::Input(format!(
            "unsupported configured agent `{value}`"
        ))),
    }
}

fn home_directory() -> Result<PathBuf> {
    env::var_os("HOME")
        .map(PathBuf::from)
        .ok_or_else(|| CliError::Input("HOME is unavailable".to_owned()))
}

fn read_stdin() -> Result<String> {
    let mut value = String::new();
    std::io::stdin()
        .read_to_string(&mut value)
        .map_err(|source| cli_io(Path::new("stdin"), source))?;
    Ok(value)
}

/// Read an out-of-band secret from exactly one source. `--value-in <path>`
/// exists so callers can hand cfctl a secret without piping it through a build
/// wrapper such as `./cfctl`, which routes stdin through `cargo` and can consume
/// it before the binary reads it. Exactly one of stdin or a file is required.
fn read_import_secret(from_stdin: bool, value_in: Option<&Path>, label: &str) -> Result<String> {
    match (from_stdin, value_in) {
        (true, Some(_)) => Err(CliError::Input(format!(
            "choose one {label} source: either `--stdin` or `--value-in <path>`, not both"
        ))),
        (false, None) => Err(CliError::Input(format!(
            "the {label} must be supplied out-of-band: add `--stdin` or `--value-in <mode-0600 path>`; values in command arguments are forbidden"
        ))),
        (true, None) => read_stdin(),
        (false, Some(path)) => read_secret_file(path),
    }
}

/// Read a secret from a file that no other user can read. On Unix any group or
/// other permission bit fails closed, mirroring the mode-0600 sink that
/// `--value-out` writes.
fn read_secret_file(path: &Path) -> Result<String> {
    read_private_secret_file(path, "--value-in")
}

fn read_private_secret_file(path: &Path, option: &str) -> Result<String> {
    let metadata = fs::metadata(path).map_err(|source| cli_io(path, source))?;
    if !metadata.is_file() {
        return Err(CliError::Input(format!(
            "`{option}` path is not a regular file: {}",
            path.display()
        )));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mode = metadata.permissions().mode();
        if mode & 0o077 != 0 {
            return Err(CliError::Input(format!(
                "`{option}` file {} must not be readable by group or others; run `chmod 600 {}` (current mode {:04o})",
                path.display(),
                path.display(),
                mode & 0o7777
            )));
        }
    }
    fs::read_to_string(path).map_err(|source| cli_io(path, source))
}

fn read_r2_log_retrieval_credentials(path: &Path) -> Result<R2LogRetrievalCredentials> {
    let content = read_private_secret_file(path, "--credential-in")?;
    let value: Value = serde_json::from_str(&content).map_err(|_| {
        CliError::Input(
            "`--credential-in` must contain one valid JSON object; credential contents were not logged"
                .to_owned(),
        )
    })?;
    let object = value.as_object().ok_or_else(|| {
        CliError::Input("`--credential-in` must contain one JSON object".to_owned())
    })?;
    let expected = BTreeSet::from(["access_key_id", "secret_access_key"]);
    let actual = object.keys().map(String::as_str).collect::<BTreeSet<_>>();
    if actual != expected {
        return Err(CliError::Input(
            "`--credential-in` must contain exactly `access_key_id` and `secret_access_key`; unknown or missing fields are rejected"
                .to_owned(),
        ));
    }
    let access_key_id = object
        .get("access_key_id")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("credential field `access_key_id` must be a string".to_owned())
        })?;
    let secret_access_key = object
        .get("secret_access_key")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            CliError::Input("credential field `secret_access_key` must be a string".to_owned())
        })?;
    R2LogRetrievalCredentials::new(access_key_id.to_owned(), secret_access_key.to_owned())
        .map_err(CliError::from)
}

fn docs_file(store: &StateStore) -> PathBuf {
    store
        .paths()
        .data_dir
        .join("catalog/official-text-feeds-v1.json")
}

fn catalog_index_file(store: &StateStore) -> PathBuf {
    store.paths().data_dir.join("catalog/catalog-v1.sqlite3")
}

fn workspace_graph_file(store: &StateStore) -> PathBuf {
    store.paths().data_dir.join("workspace-graph-v1.json")
}

fn capability_missing(id: &str) -> CliError {
    CliError::guided(
        "CFCTL_UNKNOWN_CAPABILITY",
        format!("capability `{id}` is not in the current catalog"),
        format!(
            "Find the correct id: `cfctl catalog search \"{id}\" --json` (or `cfctl resolve \"<what you want to do>\"`)."
        ),
    )
}

fn is_secret_path(path: &Path) -> bool {
    let normalized = path.display().to_string().to_ascii_lowercase();
    [".env", "secret", "credential", "token", "private_key"]
        .iter()
        .any(|needle| normalized.contains(needle))
}

fn contains_sensitive_content(content: &str) -> bool {
    if let Ok(value) = serde_json::from_str::<Value>(content)
        && redact_json(&value) != value
    {
        return true;
    }
    content.lines().any(|line| {
        let normalized = line.trim().to_ascii_lowercase();
        !normalized.contains("[redacted]")
            && [
                "access_token",
                "refresh_token",
                "api_token",
                "api_key",
                "global_key",
                "client_secret",
                "private_key",
                "password",
            ]
            .iter()
            .any(|marker| {
                normalized.starts_with(marker)
                    && (normalized.contains('=') || normalized.contains(':'))
            })
    })
}

fn cli_io(path: &Path, source: std::io::Error) -> CliError {
    CliError::Io {
        path: path.display().to_string(),
        source,
    }
}

